  str_skill_href_desc_desc_30066 = "Se estiver do lado de fora de um <color=#00F6FF>matriz deslumbrante</color> depois de usar um Chain Combo, um novo array deslumbrante será criado abrangendo o intervalo do Chain Combo atual. Só pode haver <color=#00F6FF>2</color> matrizes deslumbrantes no campo a qualquer momento. A criação de uma nova matriz deslumbrante depois que o máximo for atingido removerá a que estiver em campo por mais tempo.",
  str_skill_href_desc_name_30067 = "Matriz deslumbrante",
  str_skill_href_desc_desc_30067 = "Se estiver do lado de fora de um <color=#00F6FF>matriz deslumbrante</color> depois de usar um Chain Combo, uma nova matriz deslumbrante será criada abrangendo o intervalo do Chain Combo atual. Só pode haver <color=#00F6FF>3</color> matrizes deslumbrantes no campo a qualquer momento. Criar uma nova matriz deslumbrante depois que o máximo for atingido removerá a que estiver em campo por mais tempo.",
  str_skill_href_desc_name_30068 = "Matriz deslumbrante",
  str_skill_href_desc_desc_30068 = "Se estiver do lado de fora de um <color=#00F6FF>matriz deslumbrante</color> depois de usar um Chain Combo, um novo array deslumbrante será criado abrangendo o intervalo do Chain Combo atual. Só pode haver <color=#00F6FF>3</color> matrizes deslumbrantes no campo a qualquer momento. A criação de uma nova matriz deslumbrante depois que o máximo for atingido removerá a que estiver em campo por mais tempo. No início da batalha, um conjunto deslumbrante que é <color=#00F6FF>12 telhas em forma de diamante</color> será gerado no local inicial.",
  str_skill_href_desc_name_30069 = "energia cúbica",
  str_skill_href_desc_desc_30069 = "Ganhos <color=#00F6FF>1</color> ponto por rodada, até <color=#00F6FF>9</color> pontos.",
  str_skill_href_desc_name_30070 = "energia cúbica",
  str_skill_href_desc_desc_30070 = "Axelia entra na batalha com <color=#00F6FF>2</color> pontos e ganhos <color=#00F6FF>1</color> ponto a cada rodada, até <color=#00F6FF>9</color> pontos.",
  str_skill_href_desc_name_30071 = "Módulo de autoridade",
  str_skill_href_desc_desc_30071 = "O efeito da Habilidade Ativa pode ser alterado no Módulo de Autoridade. O Módulo de Autoridade mantém um registro de <color=#00F6FF>todos os objetos convocáveis de certos Thunder Aurorians que são convocados nesta batalha</color>.\nSelecionável <color=#00F6FF>ladrilhos especiais</color>: Ladrilhos Escuros, Ladrilhos de Prisma, Ladrilhos de Prisma em forma de Cruz.\nOs objetos convocáveis dos seguintes <color=#00F6FF>aurorianos</color> podem ser selecionados: Amemori, Reinhardt, Bopper, Roy, Ciel, Nadine e Amy.",
  str_skill_href_desc_name_30072 = "Orbe de Cura",
  str_skill_href_desc_desc_30072 = "Quando está em campo há <color=#00F6FF>0/1/2</color> rodadas, os aurorianos que passarem pelo orbe ou o absorverem usando a Habilidade Ativa de Axelia recuperarão HP igual a <color=#00F6FF>40%/100%/200%</color> do ATK de Axelia.",
  str_skill_href_desc_name_30073 = "Orbe de Cura",
  str_skill_href_desc_desc_30073 = "Quando está em campo há <color=#00F6FF>0/1/2</color> rodadas, os aurorianos que passarem pelo orbe recuperarão HP igual a <color=#00F6FF>40%/100%/250%</color> do ATK de Axelia. Se o orbe for absorvido com a habilidade ativa de Axelia, a quantidade de cura aumenta para <color=#00F6FF>80%/180%/400%</color>.",
  str_skill_href_desc_name_30074 = "Chama da Serpente",
  str_skill_href_desc_desc_30074 = "Usar nível <color=#00F6FF>2|3|4</color> Chain Combo para acender o Serpent Flare correspondente. A habilidade ativa estará pronta quando <color=#00F6FF>3</color> Serpent Flares são acesos e todos os Serpent Flares serão extintos após o uso da Habilidade Ativa.",
  str_skill_href_desc_name_30075 = "Pontos de percepção",
  str_skill_href_desc_desc_30075 = "Obter <color=#00F6FF>1</color> ponto para cada 1 ladrilho vermelho percorrido.",
  str_skill_href_desc_name_30076 = "Pontos de percepção",
  str_skill_href_desc_desc_30076 = "Obter <color=#00F6FF>1</color> ponto para cada 1 ladrilho vermelho percorrido. Ganho <color=#00F6FF>5</color> pontos ao entrar em batalha, e <color=#00F6FF>5</color> pontos no início de cada onda.",
  str_skill_href_desc_name_30077 = "Pontos de percepção",
  str_skill_href_desc_desc_30077 = "Obter <color=#00F6FF>1</color> ponto para cada 1 ladrilho percorrido. Ganho <color=#00F6FF>5</color> pontos ao entrar em batalha, e <color=#00F6FF>5</color> pontos no início de cada onda.",
  str_skill_href_desc_name_30078 = "Zelo",
  str_skill_href_desc_desc_30078 = "Cada Ataque Normal concede <color=#00F6FF>5</color> pontos, até <color=#00F6FF>100</color> pontos.",
  str_skill_href_desc_name_30079 = "Munição Reserva",
  str_skill_href_desc_desc_30079 = "1 bala pode ser reservada no início de cada rodada. 5 balas podem ser reservadas ao usar a habilidade ativa. 1 bala pode ser reservada quando qualquer auroriano usar sua Habilidade Ativa.",
  str_skill_href_desc_name_30080 = "Azulejo de prisma em forma de cruz",
  str_skill_href_desc_desc_30080 = "Ao conectar ladrilhos, converte 4 ladrilhos em forma de cruz em torno de ladrilhos de prisma em forma de cruz no mesmo elemento que os ladrilhos de prisma em forma de cruz.",
  str_skill_href_desc_name_30081 = "Avançar",
  str_skill_href_desc_desc_30081 = "Só tem efeito em alvos que podem ser puxados e prioriza alvos que estão mais próximos do centro da área.",
  str_skill_href_desc_name_30082 = "Agrupado",
  str_skill_href_desc_desc_30082 = "Existem outros alvos dentro de 1 cluster ao redor do alvo.",
  str_skill_href_desc_name_30083 = "Sabedoria",
  str_skill_href_desc_desc_30083 = "Um alvo sem Máx. PV não pode receber Sabedoria.",
  str_skill_href_desc_name_30084 = "Convergir",
  str_skill_href_desc_desc_30084 = "Reorganiza a cor das casas para que as casas azuis na coluna/linha se concentrem ao redor da casa selecionada, sem alterar as posições dos inimigos, objetos invocáveis ou casas especiais.",
  str_skill_href_desc_name_30085 = "Ripple",
  str_skill_href_desc_desc_30085 = "Acumula até 99 vezes. Um múltiplo de 7 pilhas é consumido a cada vez. Nenhuma pilha é consumida quando estiver com PV completo.",
  str_skill_href_desc_name_30086 = "Ripple",
  str_skill_href_desc_desc_30086 = "Acumula até 99 vezes. Um múltiplo de 5 pilhas é consumido a cada vez. Nenhuma pilha é consumida quando estiver com PV completo.",
  str_skill_href_desc_name_30087 = "Lagarto de Ferro",
  str_skill_href_desc_desc_30087 = "O Lagarto de Ferro pode existir por até 2 rodadas e apenas 1 pode estar no campo por vez.",
  str_skill_href_desc_name_30088 = "Lagarto de Ferro",
  str_skill_href_desc_desc_30088 = "Você pode tocar no Lagarto de Ferro para lançar habilidades a cada rodada. O Lagarto de Ferro pode existir por até 2 rodadas e apenas 1 pode estar no campo por vez.",
  str_skill_href_desc_name_30089 = "Magnetix",
  str_skill_href_desc_desc_30089 = "Quando lançado, ele puxa os inimigos dentro de 2 grupos ao redor em 1 ladrilho e depois desaparece.",
  str_skill_href_desc_name_30090 = "Whirlpool",
  str_skill_href_desc_desc_30090 = "Após o lançamento, o Chain Combo de Bopper será alterado para enfrentar o Iron Lizard diretamente, estendendo-se até a borda do campo nesta rodada.",
  str_skill_href_desc_name_30091 = "Toque",
  str_skill_href_desc_desc_30091 = "Quando cristais são gerados sob os pés do inimigo ou quando o inimigo pisa ou se move sobre um ladrilho com cristais, causa dano. O dano pode ser acionado repetidamente se vários cristais forem gerados sob o inimigo.",
  str_skill_href_desc_name_30092 = "Movimento",
  str_skill_href_desc_desc_30092 = "Inclui teletransporte através de Habilidades Ativas de aliados Aurorian, repulsão/atração causada por habilidades inimigas, o uso de um Vórtice Transportador e muito mais.",
  str_skill_href_desc_name_30093 = "Casa Escura",
  str_skill_href_desc_desc_30093 = "The next tile at this location is guaranteed to be the same element as the current tile.",
  str_skill_href_desc_name_30094 = "Imersão",
  str_skill_href_desc_desc_30094 = "Máx. 40 pilhas. Cada pilha dura por 3 rodadas.",
  str_skill_href_desc_name_30095 = "Peça Sobressalente",
  str_skill_href_desc_desc_30095 = "Ganha 3 Peças Sobressalentes no início da batalha e 1 no começo de cada rodada seguinte.",
  str_skill_href_desc_name_30096 = "Doação Sombria",
  str_skill_href_desc_desc_30096 = "Ganha 1 ponto no início de cada rodada e 1 ponto ao passar por cada Ladrilho Escuro.",
  str_skill_href_desc_name_30097 = "Doação Sombria",
  str_skill_href_desc_desc_30097 = "Ganha 5 pontos ao entrar na batalha, 1 ponto no início de cada rodada, e 1 ponto ao passar por cada Ladrilho Escuro.",
  str_skill_href_desc_name_30098 = "Doação Sombria",
  str_skill_href_desc_desc_30098 = "Ganha 5 pontos ao entrar na batalha, 1 ponto no início de cada rodada, 2 pontos no início de cada onda, e 1 ponto ao passar por cada Ladrilho Escuro.",
  str_skill_href_desc_name_30099 = "Doação Sombria",
  str_skill_href_desc_desc_30099 = "Ganha 1 ponto no início de cada rodada, 2 pontos no início de cada onda, e 1 ponto ao passar por cada Ladrilho Escuro.",
  str_skill_href_desc_name_510218 = "Estratégia de Investimento",
  str_skill_href_desc_desc_510218 = "Sheol ganha 1 Capital para cada 5 casas Azuis ou 1 casa Escura que ela atravessa.\nApós acumular 2/5/8 Capital, 3 novos grupos de habilidades de combate correspondentes à Habilidade Ativa, Combo em Cadeia e Ataque Normal serão desbloqueados em ordem na Estratégia de Investimento, e apenas 1 das 2 opções dentro de cada grupo pode ser selecionada cada vez. As habilidades de combate que podem ser obtidas são as seguintes:\nEmaranhamento da Serpente Sombria: Expande o alcance da Habilidade Ativa para 13 ladrilhos em formato de diamante.\nImpulsionado pela Névoa: Aumenta o dano da Habilidade Ativa em 50%.\nRico e Poderoso: O Combo em Cadeia causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo.\nRiqueza Esmagadora: Para cada Escuro Casa passada ao conectar as casas desta vez, aumenta o dano do Chain Combo uma vez.\nExpansão Capital: Ataques podem ser lançados na diagonal.\nAtaque Capital: Para cada Casa Escura passada ao conectar as casas desta vez, aumenta o dano dos Ataques Normais em 20%, até o dobro do dano.",
  str_skill_href_desc_name_513218 = "Estratégia de Investimento",
  str_skill_href_desc_desc_513218 = "Sheol ganha 1 Capital para cada 5 ladrilhos Azuis ou 1 ladrilho Escuro que ela passa. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos. (desbloqueia na Ascensão III)Após acumular 2/5/8 Capital, 3 novos grupos de habilidades de combate correspondentes à Habilidade Ativa, Combo em Cadeia e Ataque Normal serão desbloqueados em ordem na Estratégia de Investimento, e apenas 1 das 2 opções dentro de cada grupo pode ser selecionada cada vez. As habilidades de combate que podem ser obtidas são as seguintes:\nEmaranhado de Cobra Sombria: Expande o alcance da Habilidade Ativa para 13 peças em forma de diamante.Impulsionado pela Névoa: Aumenta o dano da Habilidade Ativa em 50%.\nRico e Poderoso: O Chain Combo causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo.\nRiqueza Esmagadora: Para cada Bloco Escuro passado ao conectar blocos desta vez, aumenta o dano do Chain Combo uma vez.\nExpansão Capital: Ataques podem ser lançados na diagonal.\nGolpe Capital: Para cada Escuro O ladrilho passado ao conectar ladrilhos desta vez, aumenta o dano dos Ataques Normais em 20%, até o dobro do dano.",
  str_skill_href_desc_name_516218 = "Estratégia de Investimento",
  str_skill_href_desc_desc_516218 = "Sheol começa a batalha com 5 Capital e ganha 1 Capital para cada 5 casas Azuis ou 1 casa Escura que ela passa. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos. (desbloqueia na Ascensão III)Após acumular 2/5/8 Capital, 3 novos grupos de habilidades de combate correspondentes à Habilidade Ativa, Combo em Cadeia e Ataque Normal serão desbloqueados em ordem na Estratégia de Investimento, e apenas 1 das 2 opções dentro de cada grupo pode ser selecionada cada vez. As habilidades de combate que podem ser obtidas são as seguintes:\nEmaranhado de Cobra Sombria: Expande o alcance da Habilidade Ativa para 13 peças em forma de diamante.Impulsionado pela Névoa: Aumenta o dano da Habilidade Ativa em 50%.\nRico e Poderoso: O Chain Combo causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo.\nEsmagando Riqueza: Para cada Ladrilho Escuro passado ao conectar ladrilhos desta vez, aumenta o dano do Chain Combo uma vez.\nExpansão Capital: Ataques podem ser lançados na diagonal.\nGolpe Capital: Para cada Escuro O ladrilho passado ao conectar ladrilhos desta vez, aumenta o dano dos Ataques Normais em 20%, até o dobro do dano.",
  str_skill_href_desc_name_530218 = "Estratégia de Investimento",
  str_skill_href_desc_desc_530218 = "Sheol ganha 1 Capital para cada 5 casas Azuis ou 1 casa Escura que ela atravessa.\nApós acumular 2/5/8 Capital, 3 novos grupos de habilidades de combate correspondentes à Habilidade Ativa, Combo em Cadeia e Ataque Normal serão desbloqueados em ordem na Estratégia de Investimento, e apenas 1 das 2 opções dentro de cada grupo pode ser selecionada cada vez. Após completar a primeira rodada de investimento, ela pode fazer uma segunda rodada de investimento para obter uma habilidade de combate que não tinha na primeira rodada de investimento. As habilidades de combate que podem ser obtidas são as seguintes:\nEmaranhado de Cobra Sombria: Expande o alcance da Habilidade Ativa para 13 peças em forma de diamante.\nImpulsionada pela Névoa: Aumenta o dano da Habilidade Ativa em 50%.\nRica e Poderosa: O Combo em Cadeia causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo.\nRiqueza Esmagadora: Para cada Bloco Escuro passado ao conectar blocos desta vez, aumenta o dano do Combo uma vez.\nExpansão de Capital: Os ataques podem ser lançados na diagonal.\nGolpe de Capital: Para cada Bloco Escuro passado ao conectar blocos desta vez, aumenta o dano dos Ataques Normais em 20%, até o dobro do dano.",
  str_skill_href_desc_name_533218 = "Estratégia de Investimento",
  str_skill_href_desc_desc_533218 = "Sheol ganha 1 Capital para cada 5 casas Azuis ou 1 casa Escura que ela passa. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos.Após acumular 2/5/8 de Capital, 3 novos grupos de habilidades de combate correspondentes à Habilidade Ativa, Combo e Ataque Normal serão desbloqueados em ordem na Estratégia de Investimento, e apenas 1 das 2 opções dentro de cada grupo pode ser selecionada cada vez. Após completar a primeira rodada de investimento, ela pode fazer uma segunda rodada de investimento para obter uma habilidade de combate que não tinha na primeira rodada de investimento. As habilidades de combate que podem ser obtidas são as seguintes:\nEmaranhado de Cobra Sombria: Expande o alcance da Habilidade Ativa para 13 ladrilhos em formato de diamante.\nImpulsionado pela Névoa: Aumenta o dano da Habilidade Ativa em 50%.\nRico e Poderoso: O Combo em Cadeia causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo.\nRiqueza Esmagadora: Para cada Escuro Casa passada ao conectar as casas desta vez, aumenta o dano do Chain Combo uma vez.\nExpansão Capital: Ataques podem ser lançados na diagonal.\nAtaque Capital: Para cada Casa Escura passada ao conectar as casas desta vez, aumenta o dano dos Ataques Normais em 20%, até o dobro do dano.",
  str_skill_href_desc_name_536218 = "Estratégia de Investimento",
  str_skill_href_desc_desc_536218 = "Sheol começa a batalha com 5 Capitais e ganha 1 Capital para cada 5 casas Azuis ou 1 casa Escura que ela passa. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATQ de Sheol em 1%, até 40 pontos.Após acumular 2/5/8 de Capital, 3 novos grupos de habilidades de combate correspondentes à Habilidade Ativa, Combo e Ataque Normal serão desbloqueados em ordem na Estratégia de Investimento, e apenas 1 das 2 opções dentro de cada grupo pode ser selecionada cada vez. Após completar a primeira rodada de investimento, ela pode fazer uma segunda rodada de investimento para obter uma habilidade de combate que não tinha na primeira rodada de investimento. As habilidades de combate que podem ser obtidas são as seguintes:\nEmaranhado de Cobra Sombria: Expande o alcance da Habilidade Ativa para 13 ladrilhos em formato de diamante.\nImpulsionado pela Névoa: Aumenta o dano da Habilidade Ativa em 50%.\nRico e Poderoso: O Combo em Cadeia causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo.\nRiqueza Esmagadora: Para cada Escuro Casa passada ao conectar as casas desta vez, aumenta o dano do Chain Combo uma vez.\nExpansão Capital: Ataques podem ser lançados na diagonal.\nAtaque Capital: Para cada Casa Escura passada ao conectar as casas desta vez, aumenta o dano dos Ataques Normais em 20%, até o dobro do dano.",
  str_skill_href_desc_name_30100 = "Quadro de Cor",
  str_skill_href_desc_desc_30100 = "Zeta pode preencher seu Quadro de Cores com as seguintes cores. Uma vez preenchido, ela poderá lançar sua Habilidade Ativa Secreta Razzle Dazzle.\n1. Sua Habilidade Ativa Variety Blitz registra as cores dos ladrilhos selecionados antes de redefini-los.\n2. Ao se mover para atacar um alvo, Conan, invocado pela Habilidade Ativa Secreta Razzle Dazzle, registrará as cores dos ladrilhos que ele atravessa.",
  str_skill_href_desc_name_30110 = "Próxima Fila",
  str_skill_href_desc_desc_30110 = "A próxima fila exibe um dos sete tipos de blocos que representam o alcance de ladrilhos que a Habilidade Ativa da Batia pode converter.\nO bloco mudará aleatoriamente cada vez que Batia usar sua Habilidade Ativa.",
  str_skill_href_desc_name_30111 = "Next Queue",
  str_skill_href_desc_desc_30111 = "A próxima fila exibe um dos sete tipos de blocos que representam o alcance de peças que a Habilidade Ativa da Batia pode converter.\nO bloco mudará aleatoriamente cada vez que Batia usar sua Habilidade Ativa.\nCada peça Vermelha percorrida concede 1 Energia. Consuma 5 Energias para randomizar o bloco. Cada tentativa de randomização custará 5 Energias adicionais até o próximo uso de sua Habilidade Ativa.",
  str_skill_href_desc_name_30112 = "Next Queue",
  str_skill_href_desc_desc_30112 = "A Próxima Fila exibe um dos sete tipos de blocos que representam a gama de peças que a Habilidade Ativa da Batia pode converter.\nO bloco mudará aleatoriamente cada vez que Batia usar sua Habilidade Ativa.\nA Próxima Fila começa com 10 de Energia, e cada peça Vermelha percorrida concede 1 de Energia. Consuma 5 de Energia para randomizar o bloco. Cada tentativa de randomização custará 5 de Energia adicional até o próximo uso de sua Habilidade Ativa.",
  str_skill_href_desc_name_30113 = "Next Queue",
  str_skill_href_desc_desc_30113 = "A Próxima Fila exibe um dos sete tipos de blocos que representam o alcance de peças que a Habilidade Ativa da Batia pode converter.\nO bloco mudará aleatoriamente cada vez que Batia usar sua Habilidade Ativa.\nA Próxima Fila começa com 10 de Energia, e cada peça Vermelha percorrida concede 1 de Energia. Consuma 5 de Energia para randomizar o bloco.",
  str_skill_href_desc_name_30114 = "Next Queue",
  str_skill_href_desc_desc_30114 = "A próxima fila exibe um dos sete tipos de blocos que representam a gama de peças que a Habilidade Ativa da Batia pode converter.\nO bloco mudará aleatoriamente cada vez que Batia usar sua Habilidade Ativa.\nCada peça Vermelha percorrida concede 1 Energia. Consuma 5 Energias para randomizar o bloco. Cada tentativa de randomização custará 5 Energias adicionais até o próximo uso de sua Habilidade Ativa.Bloqueie o bloco na Próxima Fila para impedir que ele seja randomizado. Enquanto estiver bloqueado, cada randomização aprimora o bloco atual. Para cada aprimoramento, a Habilidade Ativa também gerará um Bloco Escuro em um local aleatório.",
  str_skill_href_desc_name_30115 = "Next Queue",
  str_skill_href_desc_desc_30115 = "A Próxima Fila exibe um dos sete tipos de blocos que representam o alcance de peças que a Habilidade Ativa da Batia pode converter.\nSempre que Batia libera sua Habilidade Ativa, um bloco aparecerá aleatoriamente.\nA Próxima Fila começa com 10 de Energia, e cada peça Vermelha percorrida concede 1 de Energia. Consuma 5 de Energia para randomizar o bloco. Cada tentativa de randomização custará 5 de Energia adicional até o próximo uso de sua Habilidade Ativa.Bloqueie o bloco na Próxima Fila para impedir que ele seja randomizado. Enquanto estiver bloqueado, cada randomização aprimora o bloco atual em vez disso. Para cada aprimoramento, a Habilidade Ativa também gerará um Bloco Escuro em um local aleatório.",
  str_skill_href_desc_name_30116 = "Next Queue",
  str_skill_href_desc_desc_30116 = "A Próxima Fila exibe um dos sete tipos de blocos que representam o alcance de peças que a Habilidade Ativa da Batia pode converter.\nO bloco mudará aleatoriamente cada vez que Batia usar sua Habilidade Ativa.\nA Próxima Fila começa com 10 de Energia, e cada peça Vermelha percorrida concede 1 de Energia. Consuma 5 de Energia para randomizar o bloco.Bloqueie o bloco na Próxima Fila para impedir que ele seja randomizado. Enquanto estiver bloqueado, cada randomização aprimora o bloco atual. Para cada aprimoramento, a Habilidade Ativa também gerará um Bloco Escuro em um local aleatório.",
  str_skill_href_desc_name_30117 = "Marca: Requiem",
  str_skill_href_desc_desc_30117 = "Ganha 1 acúmulo cada vez que um Combo em Cadeia ou Ataque Normal desencadeia um golpe de relâmpago em um inimigo.",
  str_skill_href_desc_name_30118 = "Pacto do Senhor",
  str_skill_href_desc_desc_30118 = "Apenas um alvo no campo pode ter o Pacto do Senhor de cada vez.",
  str_skill_href_desc_name_30119 = "AP",
  str_skill_href_desc_desc_30119 = "Os personagens da colaboração do Atelier Ryza 2 compartilham AP. Cada personagem pode usar uma Habilidade Ativa uma vez por turno. Eles ganham 10 AP no final de um turno se nenhuma Habilidade Ativa for usada.",
  str_skill_href_desc_name_30120 = "AP",
  str_skill_href_desc_desc_30120 = "Personagens de colaboração do Atelier Ryza 2 compartilham AP. Cada personagem pode usar uma Habilidade Ativa uma vez por turno. Eles ganham 20 AP ao entrar na batalha e 10 AP no final de um turno se nenhuma Habilidade Ativa for usada.",
  str_skill_href_desc_name_30121 = "AP",
  str_skill_href_desc_desc_30121 = "Personagens de colaboração do Atelier Ryza 2 compartilham AP. Cada personagem pode usar uma Habilidade Ativa uma vez por turno. Eles ganham 20 AP ao entrar na batalha e 10 AP no final de cada rodada.",
  str_skill_href_desc_name_30122 = "Sistema de Táticas",
  str_skill_href_desc_desc_30122 = "Obtenha Pontos Táticos através de várias ações em batalha e acione efeitos correspondentes ao atingir certas quantidades.\n10 TP - Nível 1: Aumenta o dano final da Combinação em Cadeia dos personagens da colaboração Atelier Ryza 2 em 15%.\n40 TP - Nível 2: Gera 1 Ladrilho Escuro em uma localização aleatória no início de cada rodada.70 TP - Nv. 3: Ryza e Patricia infligem 1 acúmulo de Queimar com seus Combos. O Combo de Klaudia inflige 1 acúmulo de Veneno ao atingir.\n100 TP - Nv. 4: Aumenta o dano final da Habil. Ativa dos personagens da colaboração Atelier Ryza 2 em 50%.\n130 TP - Nv. 5: Gera 1 Azulejo Escuro extra em uma localização aleatória no início de cada rodada.",
  str_skill_href_desc_name_30123 = "Sistema de Táticas",
  str_skill_href_desc_desc_30123 = "Obtenha Pontos Táticos através de várias ações em batalha e acione efeitos correspondentes ao atingir certas quantidades. O limite de nível padrão é 5, que aumenta em 1 ao entrar na batalha.\n10 TP - Nv. 1: Aumenta o dano final do Combo em Cadeia dos personagens da colaboração Atelier Ryza 2 em 15%.40 TP - Nv. 2: Gera 1 Casa Escura em uma localização aleatória no início de cada rodada.\n70 TP - Nv. 3: Ryza e Patricia's Combos aplicam 1 acúmulo de Queimar ao acertar. O Combo de Klaudia aplica 1 acúmulo de Veneno ao acertar.100 TP - Nv. 4: Aumenta o dano final da Habilidade Ativa dos personagens da colaboração Atelier Ryza 2 em 50%.\n130 TP - Nv. 5: Gera 1 Casa Escura extra em uma localização aleatória no início de cada turno.\n160 TP - Nv. 6: Aumenta o ATQ básico dos personagens da colaboração Atelier Ryza 2 em 10%.\n200 TP - Nv. 7: Gera 1 Casa Escura extra em uma localização aleatória no início de cada turno.",
  str_skill_href_desc_name_30124 = "Absorção",
  str_skill_href_desc_desc_30124 = "O efeito é acionado ao passar pelos ladrilhos. Os efeitos correspondentes dos Aurorianos relevantes podem ser acionados.",
  str_skill_href_desc_name_30125 = "Vis",
  str_skill_href_desc_desc_30125 = "A equipe ganha 1 Vis para cada 2 ladrilhos conectados.",
  str_skill_href_desc_name_30126 = "Vis",
  str_skill_href_desc_desc_30126 = "A equipe ganha 1 Vis para cada 2 ladrilhos conectados e ganha 5 Vis no início de cada rodada.",
  str_skill_href_desc_name_30127 = "Conexão de Ladrilhos",
  str_skill_href_desc_desc_30127 = "Ignora o elemento do ladrilho ao conectá-los. Consome 1 Vis para cada ladrilho conectado.",
  str_skill_href_desc_name_30128 = "Estado da Equipe-Desl.",
  str_skill_href_desc_desc_30128 = "Quando Claymore não está na equipe, ele não pode ser Capitão e não atacará com a equipe.",
