  str_skill_desc_505106 = "Forosão ataca da Lumiwall, causando dano e reiniciando o elemento das casas ao longo da fileira ou coluna do alvo.",
  str_skill_name_505109 = "Corrente Negra",
  str_skill_desc_505109 = "Forosão lança um ataque a distância em alvos na área de ataque após mover-se e invoca 1 Ilusão no campo a cada rodada.",
  str_skill_name_504901 = "Golpe Sombrio",
  str_skill_desc_504901 = "A Ilusão ataca e causa dano a alvos na área de ataque.",
  str_skill_name_505121 = "Lumiwall",
  str_skill_desc_505121 = "Um objeto no qual Forosão se transforma. Forosão esconde-se na Lumiwall mais longe do inimigo (a Lumiwall pode ser atacada). Uma Ilusão é invocada para atacar o inimigo quando a Lumiwall é destruída. Após 2 Lumiwalls serem destruídas, todas elas desaparecem e Forosão se revela.",
  str_skill_name_500251 = "Furacão Veloz",
  str_skill_desc_500251 = "Usa a Pena de Wendy para teletransportar um aliado até a localização da pena.",
  str_skill_name_500252 = "Lança",
  str_skill_desc_500252 = "Ataca alvos na área de ataque 1 vez.",
  str_skill_name_1002811 = "Eclipsitas de Transporte",
  str_skill_desc_1002811 = "Eclipsitas responsáveis pelo transporte. Derrote-as para obter o Noitium que elas estão carregando.",
  str_skill_name_515121 = "Lumiwall",
  str_skill_desc_515121 = "Um objeto no qual Forosão se transforma. Forosão esconde-se na Lumiwall mais longe do inimigo (a Lumiwall pode ser atacada). Uma Ilusão é invocada para atacar o inimigo quando a Lumiwall é destruída. Após 3 Lumiwalls serem destruídas, todas elas desaparecem e Forosão se revela.",
  str_skill_name_1003401 = "Ímpeto de Luta",
  str_skill_desc_1003401 = "O Lurker se fixa a um Eclipsita em 1 círculo ao redor de si, concedendo um Escudo e aumentando o ATQ.",
  str_skill_name_1003421 = "Delírio",
  str_skill_desc_1003421 = "O Delirium Lurker se liga a um Aurorian dentro de 1 aglomerado ao redor de si mesmo, reduzindo o ponto de Sanidade do Aurorian continuamente.",
  str_skill_name_1003501 = "Regenerar",
  str_skill_desc_1003501 = "Quando em 1 círculo ao redor de Dawn, une-se a ela para recuperar seu PV.",
  str_skill_name_1003502 = "Regeneração Aprimorada",
  str_skill_desc_1003502 = "Quando em 1 círculo ao redor de Dawn, une-se a ela para recuperar seu PV e conceder um escudo.",
  str_skill_name_1003601 = "Golpe Radiante",
  str_skill_desc_1003601 = "Causa dano massivo a alvos em 2 círculos ao redor.",
  str_skill_name_1003611 = "Furacão de Floresta",
  str_skill_desc_1003611 = "Cria um furacão que causa dano forte a todos os inimigos. Quanto mais Fadas Dawn houver no tabuleiro, mais dano ele causará.",
  str_skill_name_1003621 = "Invocar Fada Dawn",
  str_skill_desc_1003621 = "Dawn invoca uma Fada Dawn que possui poderes curativos, recuperando o PV de Dawn em 1 círculo ao redor dela.",
  str_skill_name_1003622 = "Invocar Fada Dawn Melhorada",
  str_skill_desc_1003622 = "Dawn invoca uma Fada Dawn que possui poderes curativos, recuperando o PV dela e concedendo um escudo, se estiver em 1 círculo ao redor dela.",
  str_skill_name_1003800 = "Peão Isolado",
  str_skill_desc_1003800 = "Após se mover, causa dano em 4 casas em uma área em forma de cruz a seu redor.",
  str_skill_name_1003901 = "Ameaça Direta",
  str_skill_desc_1003901 = "Move-se horizontal ou verticalmente em uma área em forma de cruz. Após se mover, causa dano a alvos dentro de 1 círculo ao redor. Ao colidir com um alvo enquanto se move, causa mais dano a esse alvo e o empurra para a borda do tabuleiro.",
  str_skill_name_1003902 = "Linha de Ataque",
  str_skill_desc_1003902 = "Move-se horizontal ou verticalmente em uma área em forma de cruz. Após se mover, causa dano a alvos dentro de 2 círculo ao redor. Ao colidir com um alvo enquanto se move, causa mais dano a esse alvo e o empurra para a borda do tabuleiro.",
  str_skill_name_1003912 = "Solidificar",
  str_skill_desc_1003912 = "Parece estar fixo no lugar, incapaz de se mover, atacar, ou levar dano. Vai ativar e agir na próxima onda.",
  str_skill_name_1004001 = "Salto",
  str_skill_desc_1004001 = "Após pousar, causa dano em 4 casas ao redor em uma forma de cruz. Se houver um alvo na casa em que pousar, causa dano forte ao alvo e o atordoa, jogando-o para trás.",
  str_skill_name_1004002 = "A Saltos Largos",
  str_skill_desc_1004002 = "Após pousar, causa dano em 1 círculo ao redor. Se houver um alvo na casa em que pousar, causa dano forte ao alvo e o atordoa, jogando-o para trás.",
  str_skill_desc_1104002 = "Após o pouso, causa dano a 1 aglomerado ao redor e cria um Spikepest naquela área. Se houver um alvo no ponto de pouso, causa dano severo ao alvo e o atordoa, enquanto o repele.",
  str_skill_name_1004101 = "Ataque Angular",
  str_skill_desc_1004101 = "Move diagonalmente. Após se mover, causa dano a alvos em uma forma de cruz até a extensão máxima do alcance, centralizado na unidade.",
  str_skill_name_1004102 = "Assassinato Angular",
  str_skill_desc_1004102 = "Move diagonalmente. Após se mover, causa dano a alvos em uma forma de cruz até a extensão máxima do alcance, centralizado na unidade, e reduz a DEF de alvos acertados.",
  str_skill_desc_1104102 = "Move-se na diagonal. Depois de se mover, causa dano aos alvos em forma de cruz na extensão máxima de seu alcance, centrado na unidade, e reduz a DEF dos alvos atingidos.",
  str_skill_name_1004201 = "Do Lado da Rainha",
  str_skill_desc_1004201 = "Causa dano equivalente a uma porcentagem do PV máximo do alvo, em alvos em formato radial até o alcance máximo. O centro é a unidade.",
  str_skill_name_1004202 = "Defesa Robusta",
  str_skill_desc_1004202 = "Causa dano equivalente a uma porcentagem do PV máximo do alvo, em alvos em formato radial até o alcance máximo. O centro é a unidade. Se não houver alvos nas 8 direções ao redor da unidade, ganha uma barreira defensiva e restaura PV de unidades aliadas.",
  str_skill_desc_1104202 = "Causa dano igual a uma porcentagem do HP máximo do alvo a alvos em forma radial até o alcance máximo centrado na unidade. Se não houver alvos nas 8 direções ao redor da unidade, ganha uma barreira defensiva, reduz a Sanidade do jogador e restaura HP para unidades aliadas.",
  str_skill_name_1004301 = "Comando Real",
  str_skill_desc_1004301 = "Manda os peões causarem dano a alvos em 1 círculo ao redor.",
  str_skill_name_1004302 = "Dissuasão",
  str_skill_desc_1004302 = "Empurra alvos ao alcance, até que estejam fora do alcance do ataque.",
  str_skill_name_1004303 = "Reino Soberano",
  str_skill_desc_1004303 = "Causa dano a todos os inimigos no tabuleiro.",
  str_skill_name_1006511 = "Aríete",
  str_skill_desc_1006511 = "Causa dano a alvos ao alcance.",
  str_skill_name_1006521 = "Abismo",
  str_skill_desc_1006521 = "Detona a energia em seu corpo, causando dano a alvos ao alcance e destruindo a casa na qual está localizado.",
  str_skill_name_1007001 = "Toca",
  str_skill_desc_1007001 = "Quando há casas quebradas ao alcance do alvo, Burrow emerge de uma casa quebrada ao lado do alvo e causa dano, enquanto também quebra uma casa adjacente. Quando Aurorians passam por casas quebradas, seu contador de combo não aumenta.",
  str_skill_name_1007011 = "Avassalador",
  str_skill_desc_1007011 = "Quando não houver casas quebradas ao alcance do alvo, move-se para um local a 2 casas de distância e quebra 8 casas dentro de 1 círculo ao redor. Quando Aurorians passam por casas quebradas, seu contador de combo não aumenta.",
  str_skill_name_29010011 = "Berro",
  str_skill_desc_29010011 = "Quando o alvo estiver adjacente a uma casa quebrada, move-se para a casa quebrada e causa dano ao alvo enquanto o empurra para trás.",
  str_skill_name_29010012 = "Ameaça",
  str_skill_desc_29010012 = "Quando o alvo está dentro de um alcance em forma radial, move-se adjacente a ele e causa dano ao alvo enquanto o empurra para trás, quebrando casas em uma linha reta entre o alvo e o conjurador.",
  str_skill_name_1007102 = "Açoite",
  str_skill_desc_1007102 = "Causa dano a alvos ao alcance.",
  str_skill_desc_10071021 = "Mata instantaneamente todos os alvos dentro do alcance.",
  str_skill_desc_220091202 = "Quebras casas e causa dano aos alvos dentro do alcance.",
  str_skill_name_1007103 = "Choque Mortal",
  str_skill_desc_1007103 = "Lança uma onda de choque em direção ao local do alvo na última rodada e 1 círculo ao redor. Se o alvo estiver no alcance da onda de choque, receberá muito dano.",
  str_skill_desc_1107103 = "Lança um ataque na localização do alvo na última rodada e em 1 círculo ao redor, instantaneamente vencendo os inimigos em alcance.",
  str_skill_desc_220091201 = "Lança um ataque na localização do alvo na última rodada e em 1 círculo ao redor. Quebra casas e instantaneamente vence os inimigos em alcance.",
  str_skill_name_1007104 = "Barragem Sônico",
  str_skill_desc_1007104 = "Causa dano a alvos ao alcance e os empurra.",
  str_skill_desc_10071041 = "Causa dano a alvos no alcance e os repele, e invoca várias Tentaclaws que reduzem a Sanidade Auroriana ao mesmo tempo.",
  str_skill_name_1007112 = "Raio Impactante",
  str_skill_desc_1007112 = "Lança um raio impactante em direção ao local do alvo na última rodada, causando dano a alvos no caminho do raio e no local alvo. (O monstro reviverá nesse local 2 rodadas após morrer.)",
  str_skill_desc_10071121 = "Lança um raio impactante em direção ao local do alvo na última rodada, causando dano aos alvos no caminho do raio e no local do alvo.",
  str_skill_name_1007113 = "Ímpeto dos Ventos",
  str_skill_desc_1007113 = "Empurra alvos ao alcance para o meio do campo de batalha. (O monstro reviverá nesse local 2 rodadas após ser derrotado.)",
  str_skill_name_39004511 = "Corrente Negra",
