  str_skill_desc_200024231 = "Invoca Dreadblades e Vinesmark para a batalha a cada rodada.",
  str_skill_name_10000021 = "Invocar Magicanino",
  str_skill_desc_10000021 = "Invoca um Magicanino para a batalha a cada rodada.",
  str_skill_name_28002411 = "Opressão",
  str_skill_desc_28002411 = "Forsakin empurra você a cada rodada.",
  str_skill_name_390041101 = "Avassalador Perverso",
  str_skill_desc_390041101 = "Gertzurde ataca alvos dentro de sua área de ataque 2 vezes e aplica 2 acúmulos de Marca de Vulnerabilidade. Quanto mais essas marcas se acumulam, mais o ATK da equipe é reduzido. Gertzurde então convoca 4 Servos de Gertzurde para o local selecionado.",
  str_skill_name_390041102 = "Avassalador Perverso",
  str_skill_desc_390041102 = "Gertzurde ataca alvos dentro de sua área de ataque 2 vezes e aplica 2 acúmulos de Marca de Vulnerabilidade. Quanto mais essas marcas se acumulam, mais o ATK da equipe é reduzido. Gertzurde então convoca 4 Servos de Gertzurde para o local selecionado.",
  str_skill_name_390041103 = "Urro Furioso Melhorado Perverso",
  str_skill_desc_390041103 = "O último rugido de Gertzurde aplica 3 acúmulos de Marca de Vulnerabilidade aos alvos dentro da área de ataque. Quanto mais pilhas houver, menor será o DEF do alvo.",
  str_skill_name_390041104 = "Detonação Perversa",
  str_skill_desc_390041104 = "Gertzurde detona Marcas de Vulnerabilidade nos alvos para causar dano pesado. O dano escala com o número de marcas nos alvos. Marcas de vulnerabilidade não são apagadas após a detonação.",
  str_skill_name_300045101 = "Urro Furioso Perverso",
