  str_skill_name_391028103 = "Incorporalidade",
  str_skill_desc_391028103 = "O Invocador Escuro detona sua energia acumulada, causando dano a todo o campo de batalha.",
  str_skill_name_391028104 = "Cruz da Escuridão",
  str_skill_desc_391028104 = "O Invocador Escuro causa dano a alvos em uma forma de cruz até o alcance máximo e invoca 2 balizas no local selecionado.",
  str_skill_name_300040101 = "Sobrecarga de Energia",
  str_skill_desc_300040101 = "Balizas fornecem energia para Invocadores Escuros por meio de um Vínculo de Energia. Cada baliza aumenta o ATQ do Invocador Escuro em 5%.",
  str_skill_name_390026401 = "Golpe Radiante Perverso",
