  str_skill_name_390026402 = "Golpe Radiante Perverso",
  str_skill_desc_390026402 = "Após se mover, causa muito dano aos alvos dentro de 2 grupos ao redor e invoca 2 Fadas Dawn no local selecionado.",
  str_skill_name_390026403 = "Furacão de Floresta Perverso",
  str_skill_desc_390026403 = "Cria um furacão que causa dano forte a todos os inimigos. Quanto mais Fadas Dawn houver no campo de batalha, mais dano ele causará.",
  str_skill_name_300060201 = "Parasita Perverso",
  str_skill_desc_300060201 = "Move-se gradualmente em direção ao inimigo. Ao se mover para o alcance de 1 círculo do inimigo, causa dano a ele.",
  str_skill_name_390064101 = "Luar Perverso",
  str_skill_desc_390064101 = "Após Caracalune se mover, causa dano aos alvos ao seu alcance.",
  str_skill_name_390064102 = "Caracalune Perverso",
