  str_skill_name_390064103 = "Lúmem Perverso",
  str_skill_desc_390064103 = "O Caracalune torna-se um Plenalune, colidindo diretamente com o alvo e causando dano.",
  str_skill_name_390066101 = "Pancada Perversa",
  str_skill_desc_390066101 = "Causa dano a alvos ao alcance.",
  str_skill_name_390066102 = "Surto de Energia Perverso",
  str_skill_desc_390066102 = "Causa dano a alvos em 2 colunas e linhas e destrói a casa em que está localizado.",
