  str_skill_desc_390025102 = "O Fantasma causa dano elemental em forma de cruz.",
  str_skill_name_390025103 = "Invoca Ilusão",
  str_skill_desc_390025103 = "Invoca 1 Fantasma Furioso e o manda causar dano a todos os inimigos no campo de batalha. Quanto menor o PV do alvo, maior será o dano causado.",
  str_skill_name_1007211 = "Fluxo Escuro Solus",
  str_skill_desc_1007211 = "Maude lança ondas de choque 2 casas para frente em formato retangular, que viajam ao alcance máximo possível, causando dano aos alvos atingidos.",
  str_skill_name_1007221 = "Fantoche Solus",
  str_skill_desc_1007221 = "Maude invoca certos Eclipsitas para ajudá-lo a restringir as ações de seus Aurorians.",
  str_skill_name_290120101 = "A Noite Mais Escura",
  str_skill_desc_290120101 = "Se Claymore não puder se mover até o alvo ao conectar casas, age como um Eclipsita. Depois de se mover, golpeia os alvos em alcance e causa dano enquanto gera uma barreira que resiste até 1 ataque.",
  str_skill_name_290120102 = "Luz do Farsante",
  str_skill_desc_290120102 = "Se Claymore puder se mover até o alvo ao conectar casas, Claymore age como um Aurorian, causando muito dano ao alvo após conectar casas e se mover até ele.",
  str_skill_name_290120103 = "Perseguidor Umbral",
  str_skill_desc_290120103 = "Claymore se teleporta para o meio do mapa e desfere um golpe assustador que destrói casas em formato de cruz a partir do centro. Ao mesmo tempo, usa Fluxo Escuro para cobrir três áreas do mapa, absorvendo temporariamente toda a Lúmina dessas áreas.",
  str_skill_name_290130101 = "Retirada",
  str_skill_desc_290130101 = "Aterrorizador ataca todos os alvos inimigos ao alcance da habilidade, causando dano e os empurrando.",
  str_skill_name_290130102 = "Pesadelo",
  str_skill_desc_290130102 = "Aterrorizador causa dano a todos os alvos em todas as áreas.",
  str_skill_name_290130103 = "Corrupção",
  str_skill_desc_290130103 = "Fearmonger causa dano a alvos dentro de 2 aglomerados ao redor e converte as cores nos ladrilhos dentro do alcance da habilidade. Também está bloqueando algumas peças dentro do mesmo intervalo. Depois disso, Fearmonger invoca 3 lacaios.",
  str_skill_desc_290130113 = "Fearmonger causa dano a alvos dentro de 2 aglomerados ao redor e converte as cores nos ladrilhos dentro do alcance da habilidade. Também está bloqueando algumas peças dentro do mesmo intervalo. Depois disso, Fearmonger invoca 2 lacaios.",
  str_skill_desc_290130123 = "Fearmonger causa dano a alvos dentro de 2 grupos ao redor e converte as cores nos ladrilhos enquanto também bloqueia os ladrilhos dentro do alcance. Depois disso, Fearmonger invoca 4 lacaios.",
  str_skill_name_290134101 = "Retirada",
  str_skill_desc_290134101 = "Fearmonger ataca todos os alvos inimigos dentro do alcance da habilidade, causando dano e repelindo-os, então invoca Fearmonger Minions para o campo.",
  str_skill_name_290134102 = "Pesadelo",
  str_skill_desc_290134102 = "Fearmonger causa dano a todos os alvos em todas as áreas e gera ladrilhos enfraquecidos no campo.",
  str_skill_name_290134103 = "Corrupção",
  str_skill_desc_290134103 = "Fearmonger converte as cores de todas as peças dentro de 2 aglomerados ao redor e bloqueia algumas peças dentro de seu alcance de habilidade.",
  str_skill_desc_290130104 = "??? ataca todos os alvos inimigos ao alcance, causando dano e os empurrando.",
  str_skill_desc_290130105 = "??? causa dano a todos os alvos em todas as áreas.",
  str_skill_desc_290130106 = "??? causa dano a alvos dentro de 2 círculos ao redor e converte as cores das casas, também bloqueando as casas dentro do alcance.",
  str_skill_name_200130101 = "Ataque Furtivo",
  str_skill_desc_200130101 = "Causa muito dano a um único inimigo alvo uma vez.",
  str_skill_name_200134101 = "Ataque Furtivo",
  str_skill_desc_200134101 = "Causa alto dano uma vez a alvos inimigos dentro da área de ataque.",
  str_skill_name_200134105 = "Ataque Furtivo",
  str_skill_desc_200134105 = "Causa muito dano a um único inimigo alvo uma vez.",
  str_skill_desc_200130102 = "Causa alto dano a um alvo inimigo no campo uma vez e aplica uma Marca: Aterrorizador no alvo. Cada acúmulo desta marca reduz a DEF do alvo (quanto mais acúmulos, menor a DEF do alvo). Entrar na Hora da Aurora vai limpar toda a Marca: Aterrorizador.",
  str_skill_name_290180101 = "Ordem - Banir",
