  str_skill_upgrade_desc_17010816 = "Aprimoramento de Habilidade Ativa: Aumenta o ATK básico em <color=#FFFF00>3%</color> na batalha atual para cada habilidade lançada.",
  str_skill_upgrade_desc_16011213 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate.\nExpande o alcance de seleção da Habilidade Ativa para todo o campo de batalha.",
  str_skill_upgrade_desc_16011216 = "Aprimoramento de habilidade ativa: converte 1 ou mais peças inimigas em peças vermelhas.",
  str_skill_upgrade_desc_15011312 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_15011315 = "Melhoria de Habilidade Ativa: Reduz a recarga em <color=#FFFF00>1</color> rodada.",
  str_skill_upgrade_desc_15011412 = "Melhoria de Habilidade Ativa: Após usar uma Habilidade Ativa, os Combos são efetivos contra todos os inimigos ao alcance nessa rodada.",
  str_skill_upgrade_desc_15011415 = "Melhoria de Habilidade Ativa: Usa a Habilidade Ativa mais uma vez depois de atingir apenas 1 inimigo (pode ser ativada uma vez por turno).",
  str_skill_upgrade_desc_14012714 = "Melhoria de Habilidade Ativa: As casas selecionadas tornam-se Casas Verdes <link=\"20001\"><#FFAE07><u>Melhoradas</u></color></link>.",
  str_skill_upgrade_desc_16011713 = "Melhoria de Habilidade Ativa: Aumenta o dano da Habil. Ativa em <color=#FFFF00>30%</color>.",
  str_skill_upgrade_desc_16011716 = "Melhoria de Habilidade Ativa: Se a Habilidade Ativa já estava pronta na última rodada, o alcance de deslocamento se torna <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_upgrade_desc_16011913 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16011916 = "Melhoria de Habilidade Ativa: Após cada onda de trovão atingir um alvo, o dano da próxima onda de trovão é reduzido em <color=#00F6FF>20%</color>. Pode atingir até <color=#00F6FF>5</color> vezes.",
  str_skill_upgrade_desc_16012212 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16012215 = "Melhoria de Habilidade Ativa: Limpa o efeito <color=#00F6FF>casa danificada</color> de casas dentro do alcance da habilidade.",
  str_skill_upgrade_desc_16012113 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>, ficando disponível no início do combate.",
  str_skill_upgrade_desc_16012116 = "Melhoria de Habilidade Ativa: as primeiras <color=#00F6FF>3</color> casas ao alcance do dano tornam-se <link=\"20001\"><#FFAE07><u> Casas Melhoradas </u></color></link>. Para cada casa melhorada, o dano aumenta em <color=#FFFF00>15%</color>.",
  str_skill_upgrade_desc_16011512 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>, ficando disponível no início do combate.",
  str_skill_upgrade_desc_16011515 = "Melhoria de Habilidade Ativa: 1 casa adicional dentro da área de purificação é convertida em <link=\"20001\"><#FFAE07><u>Casa Melhorada</u></color></link>.",
  str_skill_upgrade_desc_13006514 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>, ficando disponível no início do combate.",
  str_skill_upgrade_desc_16012613 = "Melhoria de Habilidade Ativa: Aumenta o dano da Habil. Ativa em <color=#FFFF00>120%</color>.",
  str_skill_upgrade_desc_16012616 = "Melhoria de Habilidade Ativa: pode usar mais 1 vez após entrar na Hora da Aurora (ativado 1 vez por onda).",
  str_skill_upgrade_desc_16012913 = "Melhoria de Habilidade Ativa: cada <link=\"30022\"><#FFAE07><u> Prole</u></color></link> causa um dano adicional de <color=#00F6FF>10%</color>. Pode acumular até <color=#00F6FF>12</color> Proles.",
  str_skill_upgrade_desc_16012916 = "Melhoria de Habilidade Ativa: ganha 2 <link=\"30023\"><u><#FFAE07> Proles</u></color></link> no começo de cada onda.",
  str_skill_upgrade_desc_16012013 = "Melhoria de Habilidade Ativa: Reduz a recarga em <color=#FFFF00>1</color> rodada.",
  str_skill_upgrade_desc_16012016 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16012312 = "Melhoria de Habilidade Ativa: Aumenta o dano da Habil. Ativa em <color=#FFFF00>40%</color>.",
  str_skill_upgrade_desc_16012315 = "Melhoria de Habilidade Ativa: Quando atinge o alvo pela primeira vez, ele fica atordoado por 1 rodada.",
  str_skill_upgrade_desc_15001514 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16013113 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16013116 = "Melhoria de Habilidade Ativa: Aumenta o escudo da Habil. Ativa em <color=#FFFF00>30%</color>.",
  str_skill_upgrade_desc_15013212 = "Melhoria de Habilidade Ativa: se o dano causado ao inimigo foi recuperado, a recarga da Habilidade Ativa será reduzida em <color=#00F6FF>1</color> rodada.",
  str_skill_upgrade_desc_15013215 = "Melhoria de Habilidade Ativa: Aumenta o dano da Habil. Ativa em <color=#FFFF00>150%</color>.",
  str_skill_upgrade_desc_16013313 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16013316 = "Melhoria de Combo: Causa <color=#00F6FF>30%</color> de dano <link=\"30015\"><#FFAE07><u>ao redor</u></color></link> a todos os alvos em <color=#00F6FF>4 casas em forma de cruz</color> ao redor do inimigo.",
  str_skill_upgrade_desc_14013714 = "Melhoria de Habilidade Ativa: aumenta o máximo de casas convertidas em <color=#FFFF00>1</color>.",
  str_skill_upgrade_desc_15013512 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_15013515 = "Melhoria de Habilidade Ativa: A redução de dano da habilidade ativa é limitada a <color=#FFFF00>40%</color> do valor inicial.",
  str_skill_upgrade_desc_16013413 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16013416 = "Melhoria de Habilidade de Equip.: Kanna ganha <color=#FFFF00>2</color> acúmulos de carga quando a onda começa. (Válida para Ascensão I)",
  str_skill_upgrade_desc_15013612 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
