  str_skill_desc_313022 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 aglomerado ao redor</color> e um <color=#00F6FF>forma cruzada para o alcance máximo</color> e repele os inimigos.",
