  str_skill_desc_320049 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> e converte todas as casas Vermelhas ao alcance do ataque para outros elementos.",
  str_skill_desc_323049 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> e converte todas as casas Vermelhas ao alcance do ataque para outros elementos.",
  str_skill_desc_300051 = "Ataca em qualquer direção selecionada. Causa <color=#00F6FF>240%</color> de dano ao primeiro inimigo atingido e a inimigos em <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_310051 = "Ataca em qualquer direção selecionada. Causa <color=#00F6FF>240%</color> de dano ao primeiro inimigo atingido e a inimigos em <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_320051 = "Ataca em qualquer direção selecionada. Causa <color=#00F6FF>240%</color> de dano ao primeiro inimigo atingido e a inimigos em <color=#00F6FF>1 círculo ao redor</color> e aplica <link=\"10002\"><#FFAE07><u>Queimar</u></color></link> (2 acúmulos no primeiro inimigo, 1 no restante) por 2 rodadas.",
  str_skill_desc_300052 = "Teletransporta para um local a 3 casas de distância. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>4 casas em forma de cruz</color> daquela localização.",
  str_skill_desc_310052 = "Teletransporta para um local a 3 casas de distância. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>4 casas em forma de cruz</color> daquela localização.",
  str_skill_desc_320052 = "Teletransporta para um local a 3 casas de distância. Causa <color=#00F6FF>{1}%</color> de dano em casas dentro de <color=#00F6FF>1 círculo ao redor</color> daquela localização.",
  str_skill_desc_300007 = "Ofertas <color=#00F6FF>{1}%</color> dano <color=#00F6FF>em forma de cruz para o alcance máximo</color>.",
  str_skill_desc_320007 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>uma área em forma de cruz até o alcance máximo</color>. Dobra os acúmulos de Veneno, se o alvo está Envenenado. Quando o alvo sofrer o máximo de 5 acúmulos de Veneno, a Habilidade Ativa causará +<color=#00F6FF>50%</color> de dano.",
  str_skill_desc_300008 = "Converte 1 casa atravessável para uma <link=\"30001\"><#FFAE07><u>Casa de Prisma</u></color></link> Vermelha.",
  str_skill_desc_310008 = "Converte 1 casa atravessável para uma <link=\"30001\"><#FFAE07><u>Casa de Prisma</u></color></link> Vermelha.",
  str_skill_desc_300032 = "Ofertas <color=#00F6FF>100%</color> dano <color=#00F6FF>6-10</color> vezes aleatoriamente para os inimigos no campo. Quando um alvo recebe dano mais de uma vez, o dano da segunda vez é reduzido pela metade.",
  str_skill_desc_310032 = "Ofertas <color=#00F6FF>100%</color> dano <color=#00F6FF>6-10</color> vezes aleatoriamente para os inimigos no campo. Quando um alvo recebe dano mais de uma vez, o dano da segunda vez é reduzido pela metade.",
  str_skill_desc_300035 = "Teletransporta para qualquer casa em <color=#00F6FF>2 círculos ao redor</color> da unidade.",
  str_skill_desc_310035 = "Teletransporta para qualquer casa em <color=#00F6FF>2 círculos ao redor</color> da unidade.",
  str_skill_desc_320035 = "Teletransporta para qualquer casa em <color=#00F6FF>2 círculos ao redor</color> da unidade.",
  str_skill_desc_300058 = "Coloca o estandarte em 1 casa selecionada. Quanto mais perto Amy estiver do estandarte, mais sua DEF aumentará (até <color=#00F6FF>100%</color>). O estandarte desaparece quando tocado por um inimigo.",
  str_skill_desc_303058 = "Coloca o estandarte em 1 casa selecionada. Quanto mais perto Amy estiver do estandarte, mais sua DEF aumentará (até <color=#00F6FF>100%</color>). O estandarte desaparece quando tocado por um inimigo.",
  str_skill_desc_310058 = "Coloca o estandarte em 1 casa selecionada. Quanto mais perto Amy estiver do estandarte, mais sua DEF aumentará (até <color=#00F6FF>100%</color>). O estandarte desaparece quando tocado por um inimigo.",
  str_skill_desc_313058 = "Coloca o estandarte em 1 casa selecionada. Quanto mais perto Amy estiver do estandarte, mais sua DEF aumentará (até <color=#00F6FF>100%</color>). O estandarte desaparece quando tocado por um inimigo.",
  str_skill_desc_300053 = "Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>. O dano aumentará para <color=#00F6FF>150%</color>, se houver apenas 1 inimigo.",
  str_skill_desc_303053 = "Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>. O dano aumentará para <color=#00F6FF>150%</color>, se houver apenas 1 inimigo. Remove a recarga da Habil. Ativa, se o alvo for morto pela habilidade.",
  str_skill_desc_310053 = "Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>. O dano aumentará para <color=#00F6FF>150%</color>, se houver apenas 1 inimigo.",
  str_skill_desc_313053 = "Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>. O dano aumentará para <color=#00F6FF>150%</color>, se houver apenas 1 inimigo. Remove a recarga da Habil. Ativa, se o alvo for morto pela habilidade.",
  str_skill_desc_320053 = "Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>. O dano aumentará para <color=#00F6FF>200%</color>, se houver apenas 1 inimigo.",
  str_skill_desc_323053 = "Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>. O dano aumentará para <color=#00F6FF>200%</color>, se houver apenas 1 inimigo. Remove a recarga da Habil. Ativa, se o alvo for morto pela habilidade.",
  str_skill_desc_300074 = "Ofertas <color=#00F6FF>{1}%</color> dano a um <color=#00F6FF>forma cruzada para o alcance máximo</color> e os agride à unidade.",
  str_skill_desc_310074 = "Ofertas <color=#00F6FF>{1}%</color> dano a um <color=#00F6FF>forma cruzada para o alcance máximo</color> e os agride à unidade.",
  str_skill_desc_320074 = "Ofertas <color=#00F6FF>{1}%</color> dano a um <color=#00F6FF>forma cruzada para o alcance máximo</color> e os agride à unidade. Para cada <color=#00F6FF>1</color> tile agredido, o inimigo leva <color=#00F6FF>10%</color> mais danos finais.",
  str_skill_desc_300017 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>4 casas em forma de cruz</color> e empurra inimigos.",
  str_skill_desc_320017 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> e empurra inimigos.",
