  str_skill_desc_303001 = "Conv. as <color=#00F6FF>4</color> casas Vermelhas ou Amarelas mais próx. em Verdes. Se a habil. já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>1</color> nessa rodada.",
  str_skill_desc_306001 = "Conv. as <color=#00F6FF>5</color> casas Vermelhas ou Amarelas mais próx. em Verdes. Se a habil. já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>1</color> nessa rodada.",
  str_skill_desc_330001 = "Converte as <color=#00F6FF>4</color> casas Vermelhas ou Amarelas mais próximas em Verdes (tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>).",
  str_skill_desc_333001 = "Converte as <color=#00F6FF>4</color> casas Vermelhas ou Amarelas mais próximas em Verdes (tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>). Se a Habil já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_336001 = "Converte as <color=#00F6FF>5</color> casas Vermelhas ou Amarelas mais próximas em Verdes (tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>). Se a Habil já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_300011 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_320011 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>2 círculos ao redor</color> e aplica <color=#00F6FF>2</color> acúmulos de Marca: Dracodente (aplica o máximo de acúmulos de Marcas: Dracodente a inimigos dentro da área ao matar um inimigo).",
  str_skill_desc_330011 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>2 círculos ao redor</color> e aplica <color=#00F6FF>2</color> acúmulos de Marca: Dracodente (aplica o máximo de acúmulos de Marcas: Dracodente a inimigos dentro da área ao matar um inimigo).",
  str_skill_desc_300019 = "Causa <color=#00F6FF>250%</color> de dano em até 3 inimigos em <color=#00F6FF>3 círculos ao redor</color>. Causa <color=#00F6FF>250%</color> de dano quando há apenas 1 inimigo em alcance (esse dano ignora DEF). Restaura PV igual a 25% do dano causado.",
  str_skill_desc_303019 = "Causa <color=#00F6FF>250%</color> de dano em até 3 inimigos em <color=#00F6FF>3 círculos ao redor</color>. Causa <color=#00F6FF>250%</color> de dano quando há apenas 1 inimigo em alcance (esse dano ignora DEF). Restaura PV igual a 35% do dano causado.",
  str_skill_desc_306019 = "Causa <color=#00F6FF>250%</color> de dano aos 3 inimigos mais próximos. Causa <color=#00F6FF>250%</color> de dano quando há apenas 1 inimigo no alcance (esse dano ignora DEF). Restaura PV igual a 35% do dano causado.",
  str_skill_desc_320019 = "Causa <color=#00F6FF>250%</color> de dano em até 3 inimigos em <color=#00F6FF>3 círculos ao redor</color>. Causa <color=#00F6FF>250%</color> de dano quando há apenas 1 inimigo em alcance (esse dano ignora DEF). Restaura PV igual a 25% do dano causado. Aumenta o dano final causado a alvos em 10% para cada acúmulo de Sangrar que eles têm.",
  str_skill_desc_323019 = "Causa <color=#00F6FF>250%</color> de dano em até 3 inimigos em <color=#00F6FF>3 círculos ao redor</color>. Causa <color=#00F6FF>250%</color> de dano quando há apenas 1 inimigo em alcance (esse dano ignora DEF). Restaura PV igual a 35% do dano causado. Aumenta o dano final causado a alvos em 10% para cada acúmulo de Sangrar que eles têm.",
  str_skill_desc_326019 = "Causa <color=#00F6FF>250%</color> de dano aos 3 inimigos mais próximos. Causa <color=#00F6FF>250%</color> de dano quando há apenas 1 inimigo em alcance (esse dano ignora DEF). Restaura PV igual a 35% do dano causado. Aumenta o dano final causado a alvos em 10% para cada acúmulo de Sangrar que eles têm.",
  str_skill_desc_300023 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela.",
  str_skill_desc_303023 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela.",
  str_skill_desc_306023 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela.",
  str_skill_desc_300002 = "Converte qualquer <color=#00F6FF>2</color> telhas selecionadas para <link=\"20001\"><#FFAE07><u>telhas verdes aprimoradas</u></color></link> e ofertas <color=#00F6FF>200%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> centralizado em cada ladrilho selecionado.",
  str_skill_desc_303002 = "Converte qualquer <color=#00F6FF>2</color> telhas selecionadas para <link=\"20001\"><#FFAE07><u>telhas verdes aprimoradas</u></color></link> e ofertas <color=#00F6FF>240%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> centralizado em cada ladrilho selecionado.",
  str_skill_desc_306002 = "Converte qualquer <color=#00F6FF>2</color> telhas selecionadas para <link=\"20001\"><#FFAE07><u>telhas verdes aprimoradas</u></color></link> e ofertas <color=#00F6FF>240%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> centralizado em cada ladrilho selecionado.",
  str_skill_desc_320002 = "Converte qualquer <color=#00F6FF>2</color> telhas selecionadas para <link=\"20001\"><#FFAE07><u>telhas verdes aprimoradas</u></color></link> e ofertas <color=#00F6FF>200%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> centralizado em cada ladrilho selecionado.",
  str_skill_desc_323002 = "Converte qualquer <color=#00F6FF>2</color> telhas selecionadas para <link=\"20001\"><#FFAE07><u>telhas verdes aprimoradas</u></color></link> e ofertas <color=#00F6FF>240%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> centralizado em cada ladrilho selecionado.",
  str_skill_desc_326002 = "Converte qualquer <color=#00F6FF>2</color> telhas selecionadas para <link=\"20001\"><#FFAE07><u>telhas verdes aprimoradas</u></color></link> e ofertas <color=#00F6FF>240%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> centralizado em cada ladrilho selecionado.",
  str_skill_desc_16000213 = "Converte quaisquer 2 peças selecionadas em peças verdes aprimoradas e causa dano em forma de cruz ao alcance máximo centralizado em cada peça selecionada.",
  str_skill_desc_300005 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor o PV do inimigo, maior o dano (dano aumentado até 100%).",
  str_skill_desc_306005 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor o PV do inimigo, maior o dano (dano aumentado até 100%).",
  str_skill_desc_310005 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor o PV do inimigo, maior o dano (dano aumentado até 100%).",
  str_skill_desc_316005 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor o PV do inimigo, maior o dano (dano aumentado até 100%).",
  str_skill_desc_330005 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor o PV do inimigo, maior o dano (dano aumentado até 100%).",
  str_skill_desc_336005 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor o PV do inimigo, maior o dano (dano aumentado até 100%).",
  str_skill_desc_300006 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>1 coluna</color> e empurra os inimigos. Converte casas na área de ataque em Azuis.",
  str_skill_desc_303006 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>1 coluna</color> e empurra os inimigos. Converte casas na área de ataque em Azuis.",
  str_skill_desc_300025 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>3 colunas</color> ou <color=#00F6FF>3 filas selecionadas</color> e empurra os inimigos. Restaura todas as casas <color=#00F6FF>não vermelhas</color> dentro da área de ataque.",
  str_skill_desc_306025 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>3 colunas</color> ou <color=#00F6FF>3 filas</color> selecionadas e empurra os inimigos. Restaura todas as casas <color=#00F6FF>não vermelhas</color> dentro da área de ataque e tem uma <color=#00F6FF>chance pequena</color> de gerar casas Vermelhas.",
  str_skill_desc_320025 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>3 colunas</color> ou <color=#00F6FF>3 filas selecionadas</color> e empurra os inimigos. O dano causado à fila ou coluna do meio será de 1,5x o dano causado aos dois lados. Restaura todas as casas <color=#00F6FF>não Vermelhas</color> dentro da área de ataque.",
  str_skill_desc_326025 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>3 colunas</color> ou <color=#00F6FF>3 filas selecionadas</color> e empurra os inimigos. O dano causado à fila ou coluna do meio será de 1,5x o dano causado aos dois lados. Restaura todas as casas <color=#00F6FF>não Vermelhas</color> dentro da área de ataque, e tem uma <color=#00F6FF>chance pequena</color> de gerar casas Vermelhas.",
  str_skill_desc_300026 = "Rest. <color=#00F6FF>todas as casas não Vermelhas</color> e há uma <color=#00F6FF>chance pequena</color> de gerar casas Verm. Conv. 1 ou mais casas inimigas em Verm.",
  str_skill_desc_306026 = "Rest. <color=#00F6FF>todas as casas não Vermelhas</color> e há uma <color=#00F6FF>chance pequena</color> de gerar casas Verm. Conv. 1 ou mais casas inimigas em Verm.",
  str_skill_desc_300028 = "Recupera o PV da equipe em <color=#00F6FF>200%</color> do ATQ de Raphaela. Restaura as <color=#00F6FF>casas não Azuis em 3 círculos ao redor</color>.",
  str_skill_desc_306028 = "Recupera o PV da equipe em <color=#00F6FF>200%</color> do ATQ de Raphaela. Restaura as <color=#00F6FF>casas não Azuis em 3 círculos ao redor</color>. Possui uma <color=#00F6FF>chance pequena</color> de gerar casas Azuis.",
  str_skill_desc_330028 = "Recupera o PV da equipe em <color=#00F6FF>200%</color> do ATQ de Raphaela. Restaura <color=#00F6FF>as casas não Azuis</color> em 3 círculos ao redor.",
  str_skill_desc_336028 = "Recupera o PV da equipe em <color=#00F6FF>200%</color> do ATQ de Raphaela. Restaura as <color=#00F6FF>casas não Azuis</color>. Possui uma <color=#00F6FF>chance pequena</color> de gerar casas Azuis.",
  str_skill_desc_300029 = "Converte casas com <color=#00F6FF>1</color> elemento selecionado entre Azul, Vermelha e Amarela para outro elemento e mantém os status melhorados da casa.",
  str_skill_desc_306029 = "Converte casas com <color=#00F6FF>1</color> elemento selecionado entre Azul, Vermelha e Amarela para outro elemento e mantém os status melhorados da casa.",
  str_skill_desc_320029 = "Converte casas com <color=#00F6FF>1</color> elemento selecionado entre Azul, Vermelha e Amarela para outro elemento e mantém os status melhorados da casa. 1 <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link> será gerada a cada <color=#00F6FF>10</color> casas convertidas.",
  str_skill_desc_326029 = "Converte casas com <color=#00F6FF>1</color> elemento selecionado entre Azul, Vermelha e Amarela para outro elemento e mantém os status melhorados da casa. 1 <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link> será gerada a cada <color=#00F6FF>10</color> casas convertidas.",
  str_skill_desc_300038 = "Conv. as <color=#00F6FF>4</color> casas Azuis e Verm. mais próx. em Amar.",
  str_skill_desc_303038 = "Converte as <color=#00F6FF>4</color> casas Azuis e Vermelhas mais próximas em Amarelas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>1</color> nessa rodada.",
  str_skill_desc_306038 = "Converte as <color=#00F6FF>5</color> casas Azuis e Vermelhas mais próximas em Amarelas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>1</color> nessa rodada.",
  str_skill_desc_300077 = "Converte <color=#00F6FF>4</color> casa selecionadas em Azuis.",
  str_skill_desc_303077 = "Converte quaisquer <color=#00F6FF>5</color> casas selecionadas em Azuis.",
  str_skill_desc_306077 = "Converte quaisquer <color=#00F6FF>5</color> casas selecionadas em Azuis.",
  str_skill_desc_300092 = "Conv. as <color=#00F6FF>4</color> casas Vermelhas mais próx. em Verdes.",
  str_skill_desc_302092 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Verdes. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_305092 = "Converte as <color=#00F6FF>5</color> casas Vermelhas mais próximas em Verdes. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_330092 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Verdes e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>.",
  str_skill_desc_332092 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Verdes e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_335092 = "Converte as <color=#00F6FF>5</color> casas Vermelhas mais próximas em Verdes e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_300075 = "Causa {1}% de dano a inimigos em <color=#00F6FF>3 círculos ao redor</color> e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> por 2 rodadas.",
  str_skill_desc_302075 = "Causa {1}% de dano a inimigos em <color=#00F6FF>3 círculos ao redor</color> e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> por 2 rodadas.",
  str_skill_desc_305075 = "Causa {1}% de dano a <color=#00F6FF>todos</color> os inimigos, aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> por 2 rodadas.",
  str_skill_desc_320075 = "Causa {1}% de dano a inimigos em <color=#00F6FF>3 círculos ao redor.</color> e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> por 2 rodadas e 2 acúmulos de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_desc_322075 = "Causa {1}% de dano a inimigos em <color=#00F6FF>3 círculos ao redor.</color> e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> por 2 rodadas e 2 acúmulos de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_desc_325075 = "Causa {1}% de dano a <color=#00F6FF>todos</color> os inimigos e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> por 2 rodadas e 2 acúmulos de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_desc_300086 = "Recupera o PV da equipe em <color=#00F6FF>60%</color> do PV Máx de Uriah. Se houver cura em excesso, a casa Verde mais próxima é convertida em uma <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link>.",
  str_skill_desc_304086 = "Recupera o PV da equipe em <color=#00F6FF>70%</color> do PV Máx de Uriah. Se houver cura em excesso, a casa Verde mais próxima é convertida em uma <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link>.",
  str_skill_desc_330086 = "Recupera o PV da equipe em <color=#00F6FF>60%</color> do PV Máx de Uriah. Se houver cura em excesso, a casa Verde mais próxima é convertida em uma<link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link>. Se <link=\"30010\"><#FFAE07><u>Hora da Aurora</u></color></link> estiver ativa, a Habilidade Ativa pode ser usada de novo.",
  str_skill_desc_334086 = "Recupera o PV da equipe em <color=#00F6FF>70%</color> do PV Máx de Uriah. Se houver cura em excesso, a casa Verde mais próxima é convertida em uma<link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link>. Se <link=\"30010\"><#FFAE07><u>Hora da Aurora</u></color></link> estiver ativa, a Habilidade Ativa pode ser usada de novo.",
  str_skill_desc_300068 = "Transporta para qualquer lugar e gera 1 Pena de Wendy no local. Toque em Pena de Wendy para retornar ao local de origem. Só pode existir 1 Pena de Wendy no campo de batalha.",
  str_skill_desc_320068 = "Gera 1 Pena de Wendy no campo de batalha no início da batalha. Gera 1 Pena de Wendy no local, após usar uma Habilidade Ativa. Toque em Pena de Wendy para retornar ao local de origem. Só pode existir 1 Pena de Wendy no campo de batalha.",
  str_skill_desc_300082 = "Troca os elementos entre <color=#00F6FF>2</color> casas.",
  str_skill_desc_320082 = "Troca os elementos entre <color=#00F6FF>2</color> casas. Casas de Floresta selecionadas são convertidas em <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>.",
  str_skill_desc_300057 = "Teletransporta para qualquer local e regenera o PV da equipe em uma quantidade igual a <color=#00F6FF>250%</color> do ATQ de Philyshy. Aumenta o Fator de Cura em <color=#00F6FF>10%</color> para cada inimigo em <color=#00F6FF>2 círculos ao redor</color> do local alvo.",
  str_skill_desc_305057 = "Teletransporta para qualquer local e regenera o PV da equipe em uma quantidade igual a <color=#00F6FF>250%</color> do ATQ de Philyshy. Aumenta o Fator de Cura em <color=#00F6FF>15%</color> para cada inimigo em <color=#00F6FF>3 círculos ao redor</color> do local alvo.",
  str_skill_desc_320057 = "Teletransporta para qualquer local e regenera o HP da equipe por um valor igual a <color=#00F6FF>250%</color> do ATK de Philyshy. Subsídios Philyshy um escudo igual a <color=#00F6FF>30%</color> de seu HP máximo e aumenta o Fator de Cura em <color=#00F6FF>10%</color> para cada inimigo dentro <color=#00F6FF>2 aglomerados circundantes</color> do local de destino.",
  str_skill_desc_325057 = "Teletransporta para qualquer local e regenera o HP da equipe por um valor igual a <color=#00F6FF>250%</color> do ATK de Philyshy. Subsídios Philyshy um escudo igual a <color=#00F6FF>30%</color> de seu HP máximo e aumenta o Fator de Cura em <color=#00F6FF>15%</color> para cada inimigo dentro <color=#00F6FF>3 aglomerados circundantes</color> do local de destino.",
  str_skill_desc_300091 = "Ao conjurar, cada casa Azul no campo de batalha concede a todos os membros lançados um ATQ bônus igual a <color=#00F6FF>0,5%</color> do ATQ de Chloe por 2 rodadas.",
  str_skill_desc_320091 = "Concede uma <link=\"30006\"><#FFAE07><u>Marca: Concerto</u></color></link>. Ao conjurar, cada casa Azul no campo de batalha concede a todos os membros lançados um ATQ bônus igual a <color=#00F6FF>0,5%</color> do ATQ de Chloe por 2 rodadas.",
  str_skill_desc_300079 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>2 círculos ao redor</color> e restaura todas as casas na área de ataque.",
  str_skill_desc_330079 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>2 círculos ao redor</color> e restaura todas as casas <color=#00F6FF>não Azuis</color> na área de ataque. Possui uma <color=#00F6FF>chance pequena</color> de gerar casas Azuis.",
  str_skill_desc_300085 = "Causa <color=#00F6FF>{1}%</color> de dano ao inimigo com a <color=#00F6FF>menor porcentagem de PV</color>.",
  str_skill_desc_320085 = "Causa <color=#00F6FF>{1}%</color> de dano ao inimigo com a <color=#00F6FF>menor porcentagem de PV</color>. Remove a recarga da Habil. Ativa, se o alvo for derrotado pela habilidade.",
  str_skill_desc_330085 = "Causa <color=#00F6FF>{1}%</color> de dano ao inimigo com a <color=#00F6FF>menor porcentagem de PV</color>. Concede uma <link=\"30005\"><#FFAE07><u>Marca: Testemunha</u></color></link>. Cada acúmulo de Marca: Testemunha aumenta o ATQ de Aurorians de Água em <color=#00F6FF>1%</color>. Remove a recarga da Habil. Ativa, se o alvo for derrotado pela habilidade.",
  str_skill_desc_300089 = "Converte <color=#00F6FF>2</color> casas selecionadas em <link=\"30001\"><#FFAE07><u>Casas de Prisma</u></color></link> Amarelas.",
  str_skill_desc_16008901 = "Converte quaisquer 2 peças selecionadas em peças de Prisma Amarelo.",
  str_skill_desc_303089 = "Conv. <color=#00F6FF>2</color> casas selecionadas em Casas de Prisma Amarelas <link=\"20001\"><#FFAE07><u>Melhoradas</u></color></link>.",
  str_skill_desc_300027 = "Avança ao local selecionado, causando <color=#00F6FF>{1}%</color> de dano a inimigos pelo caminho e em casas adjacentes.",
  str_skill_desc_303027 = "Avança ao local selecionado, causando <color=#00F6FF>{1}%</color> de dano a inimigos pelo caminho e em casas adjacentes. Lança instantaneamente um Combo no local selecionado de acordo com a distância viajada.",
  str_skill_desc_330027 = "Avança ao local selecionado, causando <color=#00F6FF>{1}%</color> de dano e dano extra igual a <color=#00F6FF>5%</color> de seus PV atuais a inimigos pelo caminho e em casas adjacentes.",
  str_skill_desc_333027 = "Avança ao local selecionado, causando <color=#00F6FF>{1}%</color> de dano e dano extra igual a <color=#00F6FF>5%</color> de seus PV atuais a inimigos pelo caminho e em casas adjacentes. Lança instantaneamente um Combo no local selecionado de acordo com a distância viajada.",
  str_skill_desc_300060 = "Entra no estado Meio-Dia, aumentando o ataque de Jona em <color=#00F6FF>10%</color> e dano do Combo em <color=#00F6FF>30%</color> por 2 rodadas.",
  str_skill_desc_303060 = "Entra no estado Meio-Dia, aumentando o ataque de Jona em <color=#00F6FF>10%</color> e dano do Combo em <color=#00F6FF>30%</color> por 2 rodadas.",
  str_skill_desc_306060 = "Entra no estado Meio-Dia, aumentando o ataque de Jona em <color=#00F6FF>15%</color> e dano do Combo em <color=#00F6FF>30%</color> por 2 rodadas.",
  str_skill_desc_330060 = "Entra no estado Meio-Dia, aumentando o ataque de Jona em <color=#00F6FF>10%</color> e dano do Combo em <color=#00F6FF>30%</color>, assim como reduz as casas para ativar o combo de Aurorians de Fogo em <color=#00F6FF>2</color> por 2 rodadas.",
  str_skill_desc_333060 = "Entra no estado Meio-Dia, aumentando o ataque de Jona em <color=#00F6FF>10%</color> e dano do Combo em <color=#00F6FF>30%</color>, assim como reduz as casas para ativar o combo de Aurorians de Fogo em <color=#00F6FF>2</color> por 2 rodadas.",
  str_skill_desc_336060 = "Entra no estado Meio-Dia, aumentando o ataque de Jona em <color=#00F6FF>15%</color> e dano do Combo em <color=#00F6FF>30%</color>, assim como reduz as casas para ativar o combo de Aurorians de Fogo em <color=#00F6FF>2</color> por 2 rodadas.",
  str_skill_desc_300064 = "Entra no estado Sobrecarga, no qual o Combo de Wrath aumenta em <color=#00F6FF>50%</color> e causa dano ao inimigo mais próximo 2 vezes por 2 rodadas.",
  str_skill_desc_303064 = "Entra no estado Sobrecarga, no qual o Combo de Wrath aumenta em <color=#00F6FF>50%</color> e causa dano ao inimigo mais próximo 2 vezes por 2 rodadas.",
  str_skill_desc_306064 = "Entra no estado Sobrecarga, no qual o Combo de Wrath aumenta em <color=#00F6FF>50%</color> e causa dano ao inimigo mais próximo 2 vezes por 2 rodadas.",
  str_skill_desc_320064 = "Entra no estado Sobrecarga, no qual o Combo de Wrath aumenta em <color=#00F6FF>50%</color> e causa dano ao inimigo mais próximo 2 vezes por 2 rodadas.",
  str_skill_desc_323064 = "Entra no estado Sobrecarga, no qual o Combo de Wrath aumenta em <color=#00F6FF>50%</color> e causa dano ao inimigo mais próximo 2 vezes por 2 rodadas.",
  str_skill_desc_326064 = "Entra no estado Sobrecarga, no qual o Combo de Wrath aumenta em <color=#00F6FF>50%</color> e causa dano ao inimigo mais próximo 2 vezes por 2 rodadas.",
  str_skill_desc_300070 = "Causa <color=#00F6FF>90%</color> de dano <color=#00F6FF>5</color> vezes a inimigos aleatórios no campo. Lança 1 ataque adicional para cada casa de Fogo dentro de <color=#00F6FF>1 círculo ao redor</color> da unidade.",
  str_skill_desc_302070 = "Causa <color=#00F6FF>90%</color> de dano <color=#00F6FF>5</color> vezes a inimigos aleatórios no campo. Lança 1 ataque adicional para cada casa de Fogo dentro de <color=#00F6FF>1 círculo ao redor</color> da unidade.",
  str_skill_desc_305070 = "Causa <color=#00F6FF>90%</color> de dano <color=#00F6FF>6</color> vezes a inimigos aleatórios no campo. Lança 1 ataque adicional para cada casa de Fogo dentro de <color=#00F6FF>12 casas adjacentes</color>.",
  str_skill_desc_300088 = "Ofertas <color=#00F6FF>{1}%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> e repele os inimigos. Converte as peças na área de ataque em Vermelho.",
  str_skill_desc_302088 = "Ofertas <color=#00F6FF>{1}%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> e repele os inimigos. Converte as peças na área de ataque em Vermelho.",
  str_skill_desc_305088 = "Ofertas <color=#00F6FF>{1}%</color> dano em um <color=#00F6FF>forma cruzada para o alcance máximo</color> e repele os inimigos. Converte as peças na área de ataque em Vermelho.",
  str_skill_desc_300084 = "Quando usada, o Combo de um Aurorian de Fogo será ativado <color=#00F6FF>2</color> vezes nessa rodada. No <color=#00F6FF>segundo</color> Combo, o ATQ de todos os Aurorians de Fogo é igual a <color=#00F6FF>70%</color> do ATQ de Istvan.",
  str_skill_desc_302084 = "Quando usada, o Combo de um Aurorian de Fogo será ativado <color=#00F6FF>2</color> vezes nessa rodada. No <color=#00F6FF>segundo</color> Combo, o ATQ de todos os Aurorians de Fogo é igual a <color=#00F6FF>70%</color> do ATQ de Istvan.",
  str_skill_desc_305084 = "Quando usada, o Combo de um Aurorian de Fogo será ativado <color=#00F6FF>2</color> vezes nessa rodada. No <color=#00F6FF>segundo</color> Combo, o ATQ de todos os Aurorians de Fogo é igual a <color=#00F6FF>70%</color> do ATQ de Istvan.",
  str_skill_desc_330084 = "Quando usada, o Combo de um Aurorian de Fogo será ativado <color=#00F6FF>2</color> vezes nessa rodada. No <color=#00F6FF>segundo</color> Combo, o ATQ de todos os Aurorians de Fogo é igual a <color=#00F6FF>85%</color> do ATQ de Istvan.",
  str_skill_desc_332084 = "Quando usada, o Combo de um Aurorian de Fogo será ativado <color=#00F6FF>2</color> vezes nessa rodada. No <color=#00F6FF>segundo</color> Combo, o ATQ de todos os Aurorians de Fogo é igual a <color=#00F6FF>85%</color> do ATQ de Istvan.",
  str_skill_desc_335084 = "Quando usada, o Combo de um Aurorian de Fogo será ativado <color=#00F6FF>2</color> vezes nessa rodada. No <color=#00F6FF>segundo</color> Combo, o ATQ de todos os Aurorians de Fogo é igual a <color=#00F6FF>85%</color> do ATQ de Istvan.",
  str_skill_desc_300090 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>todos</color> os inimigos e os atordoa em casas Vermelhas.",
  str_skill_desc_302090 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>todos</color> os inimigos e os atordoa em casas Vermelhas.",
  str_skill_desc_320090 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>todos</color> os inimigos em casas Vermelhas. Inimigos em outras casas têm <color=#00F6FF>35%</color> de chance de serem atordoados.",
  str_skill_desc_322090 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>todos</color> os inimigos em casas Vermelhas. Inimigos em outras casas têm <color=#00F6FF>35%</color> de chance de serem atordoados.",
  str_skill_desc_300045 = "Escolhe 1 casa como alvo, sacrifica <color=#00F6FF>15%</color> do PV atual para causar uma quantidade igual de dano a inimigos em <color=#00F6FF>9 casas quadradas</color>(esse dano ignora DEF) e aplica 1 acúmulo de <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> que dura 2 rodadas.",
  str_skill_desc_320045 = "Escolhe 1 casa como alvo, sacrifica <color=#00F6FF>15%</color> do PV atual para causar uma quantidade igual de dano a inimigos em <color=#00F6FF>9 casas quadradas</color>(esse dano ignora DEF) e aplica <link=\"30004\"><#FFAE07><u>1 acúmulo</u></color></link> de Sangrar que dura 2 rodadas.",
  str_skill_desc_330045 = "Escolhe 1 casa como alvo, sacrifica <color=#00F6FF>15%</color> do PV atual para causar uma quantidade igual de dano a inimigos em <color=#00F6FF>9 casas quadradas</color>(esse dano ignora DEF) e aplica <link=\"30004\"><#FFAE07><u>1 acúmulo</u></color></link> de Sangrar que dura 2 rodadas. O PV Máx. básico de Nails aumenta em <color=#00F6FF>50%</color>.",
  str_skill_desc_300081 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>todos</color> os inimigos e os atrai até a unidade.",
  str_skill_desc_320081 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos e os atrai até a unidade. O dano final aumenta em <color=#00F6FF>10%</color> para cada casa que os inimigos passam.",
  str_skill_desc_300083 = "Seleciona 1 casa, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>4 casas em forma de cruz</color> e empurra inimigos.",
  str_skill_desc_320083 = "Seleciona 1 casa, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> e empurra inimigos.",
  str_skill_desc_330083 = "Seleciona 1 casa, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> e empurra inimigos, assim como reduz suas DEF em proporção à porcentagem de dano causado por 2 rodadas.",
  str_skill_desc_300059 = "Move-se para qualquer casa em <color=#00F6FF>1 círculo ao redor</color> da unidade.",
  str_skill_desc_3000591 = "Move-se para qualquer casa em <color=#00F6FF>1 círculo ao redor</color> da unidade.",
  str_skill_desc_3000592 = "Move-se para qualquer casa em <color=#00F6FF>2 círculos ao redor</color> da unidade.",
  str_skill_desc_3000593 = "Move-se para qualquer casa em <color=#00F6FF>3 círculos ao redor</color> da unidade.",
  str_skill_desc_3000594 = "Move-se para qualquer casa em <color=#00F6FF>4 círculos ao redor</color> da unidade.",
  str_skill_desc_3000595 = "Move-se para qualquer casa em <color=#00F6FF>5 círculos ao redor</color> da unidade.",
  str_skill_desc_300080 = "Arremessa um recipiente na casa selecionada, trocando a casa para Amarelo. Um Cristal de Raio, Cristal de Meteorito, Curativo, Ataque ou Defesa é gerado aleatoriamente na casa.",
  str_skill_desc_320080 = "Arremessa um recipiente na casa selecionada, trocando a casa para uma <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link> Amarela. Um Cristal de Raio, Cristal de Meteorito, Curativo, Ataque ou Defesa é gerado aleatoriamente na casa.",
  str_skill_desc_300093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque.",
  str_skill_desc_306093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. Remove a recarga da Habil. Ativa se o alvo for derrotado pela habilidade (uma vez por rodada).",
  str_skill_desc_310093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque.",
  str_skill_desc_316093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. Remove a recarga da Habil. Ativa se o alvo for derrotado pela habilidade (uma vez por rodada).",
  str_skill_desc_320093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. O dano final aumenta em <color=#00F6FF>15%</color> para cada inimigo derrotado. Acumula até 10 vezes.",
  str_skill_desc_326093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. O dano final aumenta em <color=#00F6FF>15%</color> para cada inimigo derrotado. Acumula até 10 vezes. Remove a recarga da Habil. Ativa, se o alvo for morto pela habilidade (uma vez por rodada).",
  str_skill_desc_330093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. O dano final aumenta em <color=#00F6FF>15%</color> para cada inimigo derrotado. Acumula até 10 vezes.",
  str_skill_desc_336093 = "Teletransporta para qualquer local em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> dano em inimigos em <color=#00F6FF>1 círculo ao redor</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. O dano final aumenta em <color=#00F6FF>15%</color> para cada inimigo derrotado. Acumula até 10 vezes. Remove a recarga da Habil. Ativa, se o alvo for morto pela habilidade (uma vez por rodada).",
  str_skill_desc_300097 = "Teletransporta para qualquer local e causa dano a inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor o retângulo, maior o dano causado, até <color=#00F6FF>480%</color> de dano.",
  str_skill_desc_302097 = "Teletransporta para qualquer local e causa dano a inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor o retângulo, maior o dano causado, até <color=#00F6FF>600%</color> de dano.",
  str_skill_desc_300095 = "Seleciona 1 casa e coloca 1 mina nela e em <color=#00F6FF>4 casas em forma de X</color> adjacentes. Cada mina causa <color=#00F6FF>190%</color> de dano quando ativada e aplica 1 acúmulo de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_desc_320095 = "Seleciona 1 casa e coloca 1 mina nela e em <color=#00F6FF>4 casas em forma de X</color> adjacentes. Cada mina causa <color=#00F6FF>190%</color> de dano (dobrado na casa selecionada) quando ativada e aplica 1 acúmulo de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_desc_330095 = "Seleciona 1 casa e coloca 1 mina nela e em <color=#00F6FF>4 casas em forma de X</color> adjacentes. Cada mina causa <color=#00F6FF>190%</color> de dano (dobrado na casa selecionada) quando ativada e aplica 1 acúmulo de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_desc_300062 = "Seleciona uma das casas mais distantes ao redor da unidade em todas as <color=#00F6FF>8</color> direções e avança até o local selecionado, causando <color=#00F6FF>{1}%</color> de dano a inimigos pelo caminho e em casas adjacentes.",
  str_skill_desc_320062 = "Seleciona uma das casas no limite do campo de batalha e avança até o local selecionado, causando <color=#00F6FF>{1}%</color> de dano a inimigos pelo caminho e em casas adjacentes.",
  str_skill_desc_300024 = "Marca 1 casa. Quando o número de casas conectadas alcançar <color=#00F6FF>2</color> vezes o número de casas necessárias para ativar um Combo, lança um Combo novamente no local marcado.",
  str_skill_desc_305024 = "Marca 1 casa. Quando o número de casas conectadas alcançar <color=#00F6FF>2</color> vezes o número de casas necessárias para ativar um Combo, lança um Combo novamente no local marcado.",
  str_skill_desc_320024 = "Marca 1 casa. Quando o número de casas conectadas alcançar <color=#00F6FF>2</color> vezes o número de casas necessárias para ativar um Combo, lança um Combo novamente no local marcado (aumenta o dano final dos dois Combos em <color=#00F6FF>30%</color>).",
  str_skill_desc_325024 = "Marca 1 casa. Quando o número de casas conectadas alcançar <color=#00F6FF>2</color> vezes o número de casas necessárias para ativar um Combo, lança um Combo novamente no local marcado (aumenta o dano final dos dois Combos em <color=#00F6FF>30%</color>).",
  str_skill_desc_330024 = "Marca 1 casa. Quando o número de casas conectadas alcançar <color=#00F6FF>1,5</color> vezes o número de casas necessárias para ativar um Combo, lança um Combo novamente no local marcado (aumenta o dano final dos dois Combos em <color=#00F6FF>30%</color>).",
  str_skill_desc_335024 = "Marca 1 casa. Quando o número de casas conectadas alcançar <color=#00F6FF>1,5</color> vezes o número de casas necessárias para ativar um Combo, lança um Combo novamente no local marcado (aumenta o dano final dos dois Combos em <color=#00F6FF>30%</color>).",
  str_skill_desc_300087 = "Conv. as <color=#00F6FF>4</color> casas Vermelhas mais próx. em Amarelas.",
  str_skill_desc_302087 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Amarelas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_305087 = "Converte as <color=#00F6FF>5</color> casas Vermelhas mais próximas em Amarelas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_330087 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Amarelas e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>.",
  str_skill_desc_332087 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Amarelas e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_335087 = "Converte as <color=#00F6FF>5</color> casas Vermelhas mais próximas em Amarelas e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3020871 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Amarelas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3050871 = "Converte as <color=#00F6FF>5</color> casas Vermelhas mais próximas em Amarelas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3320871 = "Converte as <color=#00F6FF>4</color> casas Vermelhas mais próximas em Amarelas e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3350871 = "Converte as <color=#00F6FF>5</color> casas Vermelhas mais próximas em Amarelas e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_300101 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color> e restaura todas as casas na área de ataque.",
  str_skill_desc_330101 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color> e restaura todas as casas <color=#00F6FF>não Amarelas</color> na área de ataque. Há uma <color=#00F6FF>chance pequena</color> de gerar casas Amarelas.",
  str_skill_desc_300102 = "Seleciona 1 de <color=#00F6FF>4</color> direções ao redor da unidade e puxa todos os inimigos na direção selecionada e fileiras e colunas adjacentes a unidade, causando <color=#00F6FF>{1}%</color> de dano a inimigos puxados.",
  str_skill_desc_300099 = "Controla uma espada mágica, aumentando o ATQ da unidade em <color=#00F6FF>20%</color> nessa rodada. Depois disso, reduz o ATQ e a DEF em <color=#00F6FF>50%</color> por 1 rodada.",
  str_skill_desc_305099 = "Controla uma espada mágica, aumentando o ATQ da unidade em <color=#00F6FF>25%</color> nessa rodada. Depois disso, reduz o ATQ e a DEF em <color=#00F6FF>50%</color> por 1 rodada.",
  str_skill_desc_330099 = "Controla uma espada mágica, aumentando o ATQ da unidade em <color=#00F6FF>20%</color> nessa rodada. Depois disso, reduz o ATQ e a DEF em <color=#00F6FF>50%</color> por 1 rodada. A unidade fica imune a efeitos que reduzem o ATQ e a DEF, enquanto a unidade estiver controlando a espada mágica para derrotar inimigos.",
  str_skill_desc_335099 = "Controla uma espada mágica, aumentando o ATQ da unidade em <color=#00F6FF>25%</color> nessa rodada. Depois disso, reduz o ATQ e a DEF em <color=#00F6FF>50%</color> por 1 rodada. A unidade fica imune a efeitos que reduzem o ATQ e a DEF, enquanto a unidade estiver controlando a espada mágica para derrotar inimigos.",
  str_skill_desc_300100 = "Ofertas <color=#00F6FF>{1}%</color> dano a uma forma cruzada ao alcance máximo e repele os inimigos. Converte as peças na área de ataque em Verde.",
  str_skill_desc_302100 = "Ofertas <color=#00F6FF>{1}%</color> dano em forma de cruz ao alcance máximo e repele os inimigos. Converte as peças na área de ataque em Verde.",
  str_skill_desc_300098 = "Seleciona 1 inimigo em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> de dano a ele. Se o inimigo ocupa uma única casa e pode ser empurrado, ele se move para a posição selecionada no alcance do ataque.",
  str_skill_desc_305098 = "Seleciona 1 inimigo e causa <color=#00F6FF>{1}%</color> de dano a ele. Se o inimigo ocupa uma única casa e pode ser empurrado, ele se move para a posição selecionada no alcance do ataque.",
  str_skill_desc_330098 = "Seleciona 1 inimigo em <color=#00F6FF>3 círculos ao redor</color> e causa <color=#00F6FF>{1}%</color> de dano a ele. Se o inimigo ocupa uma única casa e pode ser empurrado, ele se move para a posição selecionada ao alcance do ataque. Se um alvo marcado é derrotado, causa dano igual a <color=#00F6FF>40%</color> do ATQ de Cuscuta a inimigos em <color=#00F6FF>1 círculo ao redor</color>. (Esse dano ignora a DEF.)",
  str_skill_desc_335098 = "Seleciona 1 inimigo e causa <color=#00F6FF>{1}%</color> de dano a ele. Se o inimigo ocupa uma única casa e pode ser empurrado, ele se move para a posição selecionada ao alcance do ataque. Se um alvo marcado é derrotado, causa dano igual a <color=#00F6FF>40%</color> do ATQ de Cuscuta a inimigos em <color=#00F6FF>1 círculo ao redor</color>. (Esse dano ignora a DEF.)",
  str_skill_desc_300094 = "Registra o local alvo. A unidade retorna ao local registrado após lançar um Combo Aurorian ou se mover.",
  str_skill_desc_300096 = "Conv. as <color=#00F6FF>4</color> casas Verm. ou Verdes mais próx. em Azuis.",
  str_skill_desc_303096 = "Converte as <color=#00F6FF>4</color> casas Vermelhas ou Verdes mais próximas em Azuis. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_306096 = "Converte as <color=#00F6FF>5</color> casas Vermelhas ou Verdes mais próximas em Azuis. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_330096 = "Converte as <color=#00F6FF>4</color> casas Vermelhas ou Verdes mais próximas em Azuis e tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>.",
  str_skill_desc_333096 = "Converte as <color=#00F6FF>4</color> casas Vermelhas ou Verdes mais próximas em Azuis (tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>). Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_336096 = "Converte as <color=#00F6FF>5</color> casas Vermelhas ou Verdes mais próximas em Azuis (tem chance de gerar até 2 <link=\"20001\"><#FFAE07><u>casas melhoradas</u></color></link>). Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3030961 = "Converte as <color=#00F6FF>4</color> casas Vermelhas ou Verdes mais próximas em Azuis. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3060961 = "Converte as <color=#00F6FF>5</color> casas Vermelhas ou Verdes mais próximas em Azuis. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3330961 = "Converte as <color=#00F6FF>4</color> casas Vermelhas ou Verdes mais próximas em Azuis. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3360961 = "Converte as <color=#00F6FF>5</color> casas Vermelhas ou Verdes mais próximas em Azuis. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_300056 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo em <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_desc_320056 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo entre <color=#00F6FF>todos</color> os inimigos na tela.",
  str_skill_desc_300103 = "Conv. as <color=#00F6FF>4</color> casas Azuis ou Verdes mais próx. em Verm.",
  str_skill_desc_303103 = "Converte as <color=#00F6FF>4</color> casas Azuis ou Verdes mais próximas em Vermelhas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_306103 = "Converte as <color=#00F6FF>5</color> casas Azuis ou Verdes mais próximas em Vermelhas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3031031 = "Converte as <color=#00F6FF>4</color> casas Azuis ou Verdes mais próximas em Vermelhas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3061031 = "Converte as <color=#00F6FF>5</color> casas Azuis ou Verdes mais próximas em Vermelhas. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_300067 = "Reduz o próximo dano recebido nessa rodada em <color=#00F6FF>30%</color>, até <color=#00F6FF>2</color> vezes o PV Máx. de Alice.",
  str_skill_desc_304067 = "Reduz o próximo dano recebido nessa rodada em <color=#00F6FF>40%</color>, até <color=#00F6FF>2</color> vezes o PV Máx. de Alice.",
  str_skill_desc_320067 = "Reduz o próximo dano recebido nessa rodada em <color=#00F6FF>30%</color> e recupera imediatamente <color=#00F6FF>10%</color> do PV perdido pela equipe ao receber dano. A redução de dano e o PV recuperado não podem exceder <color=#00F6FF>2</color> vezes o PV Máx. de Alice.",
  str_skill_desc_324067 = "Reduz o próximo dano recebido nessa rodada em <color=#00F6FF>40%</color> e recupera imediatamente <color=#00F6FF>10%</color> do PV perdido pela equipe ao receber dano. A redução de dano e o PV recuperado não podem exceder <color=#00F6FF>2</color> vezes o PV Máx. de Alice.",
  str_skill_desc_300104 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inim.",
  str_skill_desc_310104 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inim.",
  str_skill_desc_320104 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inim. Se o número de inim. atingidos for 2 ou menos, a habilidade será lançada mais 1 vez nessa rodada.",
  str_skill_desc_300030 = "Seleciona 1 casa de <color=#00F6FF>4 casas em forma de cruz</color> ao redor e causa <color=#00F6FF>{1}%</color> de dano em uma área em forma de leque nessa direção .(quanto mais próximo o inimigo está, maior o dano. Pode causar até 2,5x o dano).",
  str_skill_desc_306030 = "Seleciona 1 casa de <color=#00F6FF>4 casas em forma de cruz</color> e causa <color=#00F6FF>{1}%</color> de dano em uma área em forma de leque nessa direção .(quanto mais próximo o inimigo está, maior o dano. Pode causar até 2,5x o dano).",
  str_skill_desc_320030 = "Seleciona 1 casa de <color=#00F6FF>8 casas em forma de cruz</color> na área ao redor e causa <color=#00F6FF>{1}%</color> de dano em uma área em forma de leque nessa direção (quanto mais próximo o inimigo está de Sinsa, maior o dano. Pode causar até 2,5x o dano). Se uma casa da parte exterior for selecionada, Sinsa se moverá 1 casa para usar essa habilidade.",
  str_skill_desc_326030 = "Seleciona 1 casa de <color=#00F6FF>8 casas em forma de cruz</color> ao redor e causa <color=#00F6FF>{1}%</color> de dano em uma área em forma de leque nessa direção (quanto mais próximo o inimigo está de Sinsa, maior o dano. Pode causar até 3x o dano). Se uma casa da parte exterior for selecionada, Sinsa se moverá 1 casa para usar essa habilidade.",
  str_skill_desc_330030 = "Seleciona 1 casa de <color=#00F6FF>8 casas em forma de cruz</color> na área ao redor e causa <color=#00F6FF>{1}%</color> de dano em uma área em forma de leque nessa direção (quanto mais próximo o inimigo está de Sinsa, maior o dano. Pode causar até 2,5x o dano). Se uma casa da parte exterior for selecionada, Sinsa se moverá 1 casa para usar essa habilidade.",
  str_skill_desc_336030 = "Seleciona 1 casa de <color=#00F6FF>8 casas em forma de cruz</color> ao redor e causa <color=#00F6FF>{1}%</color> de dano em uma área em forma de leque nessa direção (quanto mais próximo o inimigo está de Sinsa, maior o dano. Pode causar até 3x o dano). Se uma casa da parte exterior for selecionada, Sinsa se moverá 1 casa para usar essa habilidade.",
  str_skill_desc_300071 = "Seleciona qualquer bloco em um <color=#00F6FF>forma de cruz</color>, converte esta peça em uma peça Red Enhanced e lança Dragonscorch para lidar <color=#00F6FF>{1}%</color> danos às telhas ao longo do caminho. Depois de chegar ao ladrilho selecionado, o Dragonscorch se espalha para o <color=#00F6FF>lado esquerdo e direito</color> desta telha até a distância máxima, causando 80% de dano.",
  str_skill_desc_305071 = "Seleciona qualquer bloco em um <color=#00F6FF>forma de cruz</color>, converte esta peça em uma peça Red Enhanced e lança Dragonscorch para lidar <color=#00F6FF>{1}%</color> danos às telhas ao longo do caminho. Depois de chegar ao ladrilho selecionado, o Dragonscorch se espalha para o <color=#00F6FF>lado esquerdo e direito</color> deste ladrilho até a distância máxima, causando 80% de dano e convertendo o ladrilho mais distante de cada lado em um ladrilho Vermelho.",
  str_skill_desc_320071 = "Seleciona qualquer bloco em um <color=#00F6FF>forma de cruz</color>, converte esta peça em uma peça Red Enhanced e lança Dragonscorch para lidar <color=#00F6FF>{1}%</color> danos às telhas ao longo do caminho. Depois de chegar ao ladrilho selecionado, o Dragonscorch se espalha para o <color=#00F6FF>lado esquerdo e direito</color> desta telha até a distância máxima, causando 80% de dano. Dragonscorch inflige o alvo com uma Burn Mark antes de causar dano.",
  str_skill_desc_325071 = "Seleciona qualquer bloco em um <color=#00F6FF>forma de cruz</color>, converte esta peça em uma peça Red Enhanced e lança Dragonscorch para lidar <color=#00F6FF>{1}%</color> danos às telhas ao longo do caminho. Depois de chegar ao ladrilho selecionado, o Dragonscorch se espalha para o <color=#00F6FF>lado esquerdo e direito</color> deste ladrilho até a distância máxima, causando 80% de dano e convertendo o ladrilho mais distante de cada lado em um ladrilho vermelho. Dragonscorch inflige o alvo com uma Burn Mark antes de causar dano.",
  str_skill_desc_300105 = "Seleciona 1 casa onde um inimigo está e causa <color=#00F6FF>40%</color> de dano 20 vezes ao inimigo. Seleciona novamente um alvo após eliminar o inimigo atual. A Habilidade Ativa causa dano 1 vez adicional para cada casa Amarela dentro de <color=#00F6FF>1 grupo ao redor</color> da sua localização atual.",
  str_skill_desc_306105 = "Seleciona 1 casa onde um inimigo está e causa <color=#00F6FF>40%</color> de dano 20 vezes ao inimigo. Seleciona novamente um alvo após eliminar o inimigo atual. A Habilidade Ativa causa dano 1 vez adicional para cada casa Amarela dentro de <color=#00F6FF>2 grupos adjacentes</color> à sua localização atual.",
  str_skill_desc_330105 = "Seleciona 1 casa onde um inimigo está e causa <color=#00F6FF>40%</color> de dano 20 vezes ao inimigo, com o fator de dano aumentando em <color=#00F6FF>0,8%</color> a cada vez. Seleciona um novo alvo após eliminar o inimigo atual. O alvo final do seu ataque tem sua DEF reduzida em 10% por 1 rodada. A Habilidade Ativa causa dano 1 vez adicional para cada casa Amarela dentro de <color=#00F6FF>1 grupo ao redor</color> da sua localização atual.",
  str_skill_desc_336105 = "Seleciona 1 casa onde um inimigo está e causa <color=#00F6FF>40%</color> de dano 20 vezes ao inimigo, com o fator de dano aumentando em <color=#00F6FF>0,8%</color> a cada vez. Seleciona um novo alvo após eliminar o inimigo atual. O alvo final do seu ataque tem sua DEF reduzida em 10% por 1 rodada. A Habilidade Ativa causa dano 1 vez adicional para cada casa Amarela dentro de <color=#00F6FF>2 grupos adjacentes</color> à sua localização atual.",
  str_skill_desc_330109 = "Custa <color=#00F6FF>10</color> Vis e limpa o Vis restante para causar <color=#00F6FF><color=#00F6FF>150%</color></color> de dano a todos os inimigos em uma direção escolhida e as casas adjacentes. O dano final aumenta em +<color=#00F6FF>8%</color> para cada 1 Vis limpo.",
  str_skill_desc_330110 = "Custa <color=#00F6FF>10</color> Vis e limpa o Vis restante para causar <color=#00F6FF>150%</color> de dano a todos os inimigos. O dano aumenta em +<color=#00F6FF>15%</color> para cada 1 Vis limpo.",
  str_skill_desc_336110 = "Custa <color=#00F6FF>10</color> Vis e limpa o Vis restante para causar <color=#00F6FF>150%</color> de dano a todos os inimigos. Para cada 1 Vis limpo, o dano aumenta em <color=#00F6FF>15%</color> e ignora <color=#00F6FF>1%</color> da defesa.",
  str_skill_desc_330107 = "Custa <color=#00F6FF>10</color> Vis para entrar em um estado aumentado nessa rodada: ataques normais podem ser lançados diagonalmente e aumenta o dano do ataque normal e do combo em <color=#00F6FF>20%</color> (pode acumular ao ser usado mais de uma vez).",
  str_skill_desc_333107 = "Custa <color=#00F6FF>10</color> Vis para entrar em um estado aumentado nessa rodada: ataques normais podem ser lançados diagonalmente e aumenta o dano do ataque normal e do combo em <color=#00F6FF>20%</color> (pode acumular ao ser usado mais de uma vez). Ganha 2 Vis a cada 1 inimigo derrotado, durante um estado aumentado.",
  str_skill_desc_336107 = "Custa <color=#00F6FF>10</color> Vis para entrar em um estado aumentado nessa rodada: ataques normais podem ser lançados diagonalmente e aumenta o dano do ataque normal e do combo em <color=#00F6FF>20%</color> (pode acumular ao ser usado mais de uma vez). Ganha 2 Vis a cada 1 inimigo derrotado, durante um estado aumentado.",
  str_skill_desc_330108 = "Custa <color=#00F6FF>10</color> Vis para causar <color=#00F6FF>{1}%</color> de dano a 1 casa selecionada e causa 50% de dano <link=\"30015\"><#FFAE07><u>de sobra</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor. Pode ser lançada múltiplas vezes por rodada.",
  str_skill_desc_333108 = "Custa <color=#00F6FF>10</color> Vis para causar <color=#00F6FF>{1}%</color> de dano a 1 casa selecionada e causa 50% de dano <link=\"30015\"><#FFAE07><u>de sobra</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor. Pode ser lançada múltiplas vezes por rodada.",
  str_skill_desc_336108 = "Custos <color=#00F6FF>10</color> Vis para negociar <color=#00F6FF>{1}%</color> dano a 1 ladrilho selecionado e causa 50% <link=\"30015\"><#FFAE07><u>Splash</u></color></link> danos a <color=#00F6FF>4 azulejos em forma de cruz</color> em torno dele. Cada lançamento aumenta o ATK básico em <color=#00F6FF>3%</color>. Pode ser lançado várias vezes a cada rodada.",
  str_skill_desc_300112 = "Teleporta para qualquer ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color>, lidando <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> do local de destino e redefine todos </color>não vermelho<color=#00F6FF> telhas dentro da área de ataque.",
  str_skill_desc_301112 = "Teletransporta para qualquer casa, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color> do local do alvo e restaura todas as casas </color>não Vermelhas<color=#00F6FF> na área de ataque.",
  str_skill_desc_303112 = "Teleporta para qualquer ladrilho, lidando <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> do local de destino e redefine todos </color>não vermelho<color=#00F6FF> telhas dentro da área de ataque. Converte 1 ou mais peças inimigas em peças vermelhas.",
  str_skill_desc_320112 = "Teleporta para qualquer ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color>, lidando <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> do local de destino e redefine todos </color>não vermelho<color=#00F6FF> telhas dentro da área de ataque.",
  str_skill_desc_321112 = "Teletransporta para qualquer casa, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color> do local do alvo e restaura todas as casas </color>não Vermelhas<color=#00F6FF> na área de ataque.",
  str_skill_desc_323112 = "Teleporta para qualquer ladrilho, lidando <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> do local de destino e redefine todos </color>não vermelho<color=#00F6FF> telhas dentro da área de ataque. Converte 1 ou mais peças inimigas em peças vermelhas.",
  str_skill_desc_330112 = "Teleporta para qualquer ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color>, lidando <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> do local de destino e redefine todos </color>não vermelho<color=#00F6FF> telhas dentro da área de ataque. Depois de acionar <color=#00F6FF>Beijo de Manticora</color>, os stacks de Manticore's Mark do alvo são apagados.",
  str_skill_desc_331112 = "Teleporta para qualquer ladrilho, lidando <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> do local de destino e redefine todos </color>não vermelho<color=#00F6FF> telhas dentro da área de ataque. Depois de acionar <color=#00F6FF>Beijo de Manticora</color>, os stacks de Manticore's Mark do alvo são apagados.",
  str_skill_desc_333112 = "Teleporta para qualquer ladrilho, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 aglomerados circundantes</color> do local de destino e redefinir todos </color>não vermelho<color=#00F6FF> telhas dentro da área de ataque. Depois de acionar <color=#00F6FF>Beijo de Manticora</color>, as Marcas da Manticora do alvo são apagadas. Pelo menos 1 ladrilho inimigo será convertido em Vermelho.",
  str_skill_desc_300113 = "Seleciona 1 de <color=#00F6FF>4</color> direções ao redor da unidade e desloca todos os inimigos que não são chefes e ocupam uma única casa na direção selecionada, causando <color=#00F6FF>{1}%</color> de dano a todos os inimigos no tabuleiro.",
  str_skill_desc_305113 = "Seleciona 1 de <color=#00F6FF>4</color> direções ao redor da unidade e desloca todos os inimigos que não são chefes e ocupam uma única casa na direção selecionada, causando <color=#00F6FF>{1}%</color> de dano a todos os inimigos no tabuleiro.",
  str_skill_desc_330113 = "Seleciona 1 de <color=#00F6FF>4</color> direções ao redor da unidade e desloca todos os inimigos que não são chefes e ocupam uma única casa na direção selecionada, causando <color=#00F6FF>{1}%</color> de dano a todos os inimigos no tabuleiro. Se o número de inimigos atingidos for 2 ou menos, essa habilidade será lançada mais uma vez nessa rodada.",
  str_skill_desc_335113 = "Seleciona 1 de <color=#00F6FF>4</color> direções ao redor da unidade e desloca todos os inimigos que não são chefes e ocupam uma única casa na direção selecionada, causando <color=#00F6FF>{1}%</color> de dano a todos os inimigos no tabuleiro. Se o número de inimigos atingidos for 2 ou menos, essa habilidade será lançada mais uma vez nessa rodada.",
  str_skill_desc_300114 = "Teletransporta para qualquer local em forma de L de sua posição atual (1 casa horizontalmente e 2 casas verticalmente ou 1 casa verticalmente e 2 casas horizontalmente), causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> do local alvo.",
  str_skill_desc_302114 = "Teletransporta para qualquer local em forma de L de sua posição atual (1 casa horizontalmente e 2 casas verticalmente ou 1 casa verticalmente e 2 casas horizontalmente), causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> do local alvo. Após usar uma Habilidade Ativa, os Combos são efetivos contra todos os inimigos ao alcance nessa rodada.",
  str_skill_desc_305114 = "Teletransporta para qualquer local em forma de L de sua posição atual (1 casa horizontalmente e 2 casas verticalmente ou 1 casa verticalmente e 2 casas horizontalmente), causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> do local alvo. Após usar uma Habilidade Ativa, os Combos são efetivos contra todos os inimigos ao alcance nessa rodada. Ao atingir apenas 1 inimigo, essa habilidade pode ser lançada mais 1 vez nessa rodada.",
  str_skill_desc_320114 = "Teletransporta para qualquer local em forma de L de sua posição atual (1 casa horizontalmente e 2 casas verticalmente ou 1 casa verticalmente e 2 casas horizontalmente), causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> do local alvo. Após usar uma Habilidade Ativa, o alcance do Combo é aumentando em 1 círculo nessa rodada.",
  str_skill_desc_322114 = "Teletransporta para qualquer local em forma de L de sua posição atual (1 casa horizontalmente e 2 casas verticalmente ou 1 casa verticalmente e 2 casas horizontalmente), causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> do local alvo. Após usar uma Habilidade Ativa, o alcance dos Combos aumenta em 1 círculo nessa rodada e são efetivos contra todos os inimigos ao alcance.",
  str_skill_desc_325114 = "Teletransporta para qualquer local em forma de L de sua posição atual (1 casa horizontalmente e 2 casas verticalmente ou 1 casa verticalmente e 2 casas horizontalmente), causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> do local alvo. Após usar uma Habilidade Ativa, o alcance dos Combos aumenta em 1 círculo nessa rodada e são efetivos contra todos os inimigos ao alcance. Ao atingir apenas 1 inimigo, essa habilidade pode ser usada mais 1 vez nessa rodada.",
  str_skill_desc_300127 = "Seleciona 1 casa (incluindo Casas Abismais) e coloca 1 Garça de Papel nela ao convertê-la para Verde. A Garça de Papel desaparecerá após os membros da equipe atravessarem.",
  str_skill_desc_304127 = "Seleciona 1 casa (incluindo Casas Abismais) e coloca 1 Garça de Papel nela ao convertê-la para uma <link=\"20001\"><#FFAE07><u>Casa Verde Melhorada</u></color></link>. Quando os membros da equipe atravessarem, a Garça de Papel desaparecerá.",
  str_skill_desc_320127 = "Seleciona 1 casa (incluindo Casas Abismais) e coloca 1 Garça de Papel nela ao convertê-la para Verde. A Garça de Papel desaparecerá após os membros da equipe atravessarem, e converterá 1 casa não Abismal abaixo dela para Verde.",
  str_skill_desc_324127 = "Seleciona 1 casa (incluindo Casas Abismais) e coloca 1 Garça de Papel nela ao convertê-la para uma <link=\"20001\"><#FFAE07><u>Casa Verde Melhorada</u></color></link>. A Garça de Papel desaparecerá após os membros da equipe atravessarem, e converterá 1 casa não Abismal abaixo dela para Verde.",
  str_skill_desc_300117 = "Teletransporta para qualquer casa dentro de <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor</color> do local alvo.",
  str_skill_desc_303117 = "Teletransporta para qualquer casa dentro de <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor</color> do local alvo.",
  str_skill_desc_306117 = "Teletransporta para qualquer casa em <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 círculos ao redor</color> do local alvo. Se a Habilidade Ativa estava pronta na última rodada, o alcance do teleporte nessa rodada se torna <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_3061171 = "Teletransporta para qualquer casa em <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 círculos ao redor</color> do local alvo. Se a Habilidade Ativa estava pronta na última rodada, o alcance do teleporte nessa rodada se torna <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_320117 = "Teletransporta para qualquer casa dentro de <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo.",
  str_skill_desc_323117 = "Teletransporta para qualquer casa dentro de <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo.",
  str_skill_desc_326117 = "Teletransporta para qualquer casa em <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo. Se a Habilidade Ativa estava pronta na última rodada, o alcance do teleporte nessa rodada se torna <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_3261171 = "Teletransporta para qualquer casa em <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo. Se a Habilidade Ativa estava pronta na última rodada, o alcance do teleporte nessa rodada se torna <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_330117 = "Teletransporta para qualquer casa dentro de <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo.",
  str_skill_desc_333117 = "Teletransporta para qualquer casa dentro de <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo.",
  str_skill_desc_336117 = "Teletransporta para qualquer casa em <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo. Se a Habilidade Ativa estava pronta na última rodada, o alcance do teleporte nessa rodada se torna <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_3361171 = "Teletransporta para qualquer casa em <color=#00F6FF>12 casas ao redor, em forma de diamante</color>, causando <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>20 casas ao redor do local alvo</color>. Causa 1,5x de dano ao círculo externo. Se a Habilidade Ativa estava pronta na última rodada, o alcance do teleporte nessa rodada se torna <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_300119 = "Seleciona 1 das <color=#00F6FF>4</color> direções ao redor da unidade e lança 3 ondas de trovão à frente em um alcance de 3 colunas, causando <color=#00F6FF>250%</color> de dano. Após cada onda de trovão acertar um alvo, a onda de trovão seguinte é reduzida em <color=#00F6FF>40%</color>. Pode acertar até <color=#00F6FF>3</color> vezes.",
  str_skill_desc_306119 = "Seleciona 1 das <color=#00F6FF>4</color> direções ao redor da unidade e lança 3 ondas de trovão à frente em um alcance de 3 colunas, causando <color=#00F6FF>250%</color> de dano. Após cada onda de trovão acertar um alvo, a onda de trovão seguinte é reduzida em <color=#00F6FF>20%</color>. Pode acertar até <color=#00F6FF>3</color> vezes.",
  str_skill_desc_300122 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>17 casas em forma radial</color> centradas na casa selecionada.",
  str_skill_desc_305122 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>17 casas em forma radial</color>, centradas na casa selecionada. Limpa o efeito <color=#00F6FF>casa danificada</color> de casas nesse alcance.",
  str_skill_desc_320122 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>17 casas em formato radial</color> centrado na casa selecionada. Dano causado à casa selecionada ignora DEF.",
  str_skill_desc_325122 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>17 casas em formato radial</color>, centrado na casa selecionada. Dano causado à casa selecionada ignora DEF. Limpa o efeito <color=#00F6FF>casa danificada</color> de casas nesse alcance.",
  str_skill_desc_330122 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>17 casas em formato radial</color> centrado na casa selecionada. Dano causado à casa selecionada ignora DEF. Quando Bênção chegar a 10 acúmulos, o alcance da Habilidade Ativa se torna o <color=#00F6FF>limite máximo da forma radial</color>.",
  str_skill_desc_3301221 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>17 casas em formato radial</color> centrado na casa selecionada. Dano causado à casa selecionada ignora DEF. Quando Bênção chegar a 10 acúmulos, o alcance da Habilidade Ativa se torna o <color=#00F6FF>limite máximo da forma radial</color>.",
  str_skill_desc_335122 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>17 casas em formato radial</color> centrado na casa selecionada. Dano causado à casa selecionada ignora DEF. Limpa o efeito <color=#00F6FF>casa danificada</color> de casas ao alcance. Quando Bênção chegar a 10 acúmulos, o alcance da Habilidade Ativa se torna o <color=#00F6FF>limite máximo da forma radial</color>.",
  str_skill_desc_300121 = "Selecione 1 casa, então com essa casa como centro, selecione 1 direção para estender a videira que espreita até a ponta do campo de batalha e causa <color=#00F6FF>360%</color> de dano dentro desse alcance, enquanto converte as <color=#00F6FF>2</color> casas frontais para <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>. Para cada 1 casa que a videira se estender, o dano aumenta em <color=#00F6FF>10%</color>.",
  str_skill_desc_306121 = "Selecione 1 casa, então com essa casa como centro, selecione 1 direção para estender a videira que espreita até a ponta do campo de batalha e causa <color=#00F6FF>360%</color> de dano dentro desse alcance, enquanto converte as <color=#00F6FF>3</color> casas frontais para <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>. Para cada 1 casa que a videira se estender, o dano aumenta em <color=#00F6FF>15%</color>.",
  str_skill_desc_320121 = "Selecione 1 casa, então com essa casa como centro, selecione 1 direção para estender a videira que espreita até a ponta do campo de batalha e causa <color=#00F6FF>360%</color> de dano dentro desse alcance, enquanto converte as <color=#00F6FF>3</color> casas frontais para <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>. As videiras se estendem <color=#00F6FF>3</color> casas em forma de cruz depois de causar dano. Esse efeito de extensão pode ser ativado apenas 1 vez para cada inimigo atingido. Para cada 1 casa que a videira se estender, o dano aumenta em <color=#00F6FF>10%</color>.",
  str_skill_desc_326121 = "Selecione 1 casa, então com essa casa como centro, selecione 1 direção para estender a videira que espreita até a ponta do campo de batalha e causa <color=#00F6FF>360%</color> de dano dentro desse alcance, enquanto converte as <color=#00F6FF>3</color> casas frontais para <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>. As videiras se estendem <color=#00F6FF>3</color> casas em forma de cruz depois de causar dano. Esse efeito de extensão pode ser ativado apenas 1 vez para cada inimigo atingido. Para cada 1 casa que a videira se estender, o dano aumenta em <color=#00F6FF>15%</color>.",
  str_skill_desc_300065 = "Teletransporta para qualquer casa em <color=#00F6FF>2 círculos ao redor</color> da unidade ou casas azuis no campo de batalha.",
  str_skill_desc_330065 = "Teletransporta para qualquer casa em <color=#00F6FF>2 círculos ao redor</color> da unidade ou casas azuis no campo de batalha. Pode usar mais uma vez após entrar na Hora da Aurora.",
  str_skill_desc_300115 = "Teletransporta para um local selecionado e <link=\"30020\"><#FFAE07><u>purifica</u></color></link> as casas em <color=#00F6FF>2 círculos ao redor</color> e outras casas aleatórias. Até <color=#00F6FF>3</color> casas dentro da área de purificação são convertidas a <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>.",
  str_skill_desc_305115 = "Teletransporta para um local selecionado e <link=\"30020\"><#FFAE07><u>purifica</u></color></link> as casas em <color=#00F6FF>2 círculos ao redor</color> e outras casas aleatórias. Até <color=#00F6FF>4</color> casas dentro da área de purificação são convertidas a <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>.",
  str_skill_desc_320115 = "Teletransporta para um local selecionado e <link=\"30020\"><#FFAE07><u>purifica</u></color></link> as casas em <color=#00F6FF>3 círculos ao redor</color> e outras casas aleatórias. Até <color=#00F6FF>4</color> casas dentro da área de purificação são convertidas a <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>.",
  str_skill_desc_325115 = "Teletransporta para um local selecionado e <link=\"30020\"><#FFAE07><u>purifica</u></color></link> as casas em <color=#00F6FF>3 círculos ao redor</color> e outras casas aleatórias. Até <color=#00F6FF>5</color> casas dentro da área de purificação são convertidas a <link=\"20001\"><#FFAE07><u>Casas Melhoradas</u></color></link>.",
  str_skill_desc_300126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz </color> centradas em 1 casa atravessável selecionada.",
  str_skill_desc_303126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz </color> centradas em 1 casa atravessável selecionada.",
  str_skill_desc_306126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz</color> centradas em 1 casa atravessável selecionada. Pode usar mais 1 vez após entrar na Hora da Aurora (ativado 1 vez por onda).",
  str_skill_desc_310126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz </color> centradas em 1 casa atravessável selecionada.",
  str_skill_desc_313126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz </color> centradas em 1 casa atravessável selecionada.",
  str_skill_desc_316126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz</color> centradas em 1 casa atravessável selecionada. Pode usar mais 1 vez após entrar na Hora da Aurora (ativado 1 vez por onda).",
  str_skill_desc_320126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz </color> centradas em 1 casa atravessável selecionada.",
  str_skill_desc_323126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz </color> centradas em 1 casa atravessável selecionada.",
  str_skill_desc_326126 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma cruz</color> centradas em 1 casa atravessável selecionada. Pode usar mais 1 vez após entrar na Hora da Aurora (ativado 1 vez por onda).",
  str_skill_desc_300129 = "Consome todas as <link=\"30021\"><#FFAE07><u>Proles</u></color></link> para causar dano a 1 inimigo. Cada <link=\"30021\"><#FFAE07><u>Prole</u></color></link> causa <color=#00F6FF>40%</color> de dano.",
  str_skill_desc_303129 = "Consome todas as <link=\"30022\"><#FFAE07><u>Proles</u></color></link> para causar dano a 1 inimigo. Cada <link=\"30022\"><#FFAE07><u>Prole</u></color></link> causa <color=#00F6FF>50%</color> de dano.",
  str_skill_desc_306129 = "Consome todas as <link=\"30023\"><#FFAE07><u>Proles</u></color></link> para causar dano a 1 inimigo. Cada <link=\"30023\"><#FFAE07><u>Prole</u></color></link> causa <color=#00F6FF>50%</color> de dano.",
  str_skill_desc_300055 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>160%</color> de dano e empurrando a todos os inimigos nessa direção.",
  str_skill_desc_302055 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>160%</color> de dano a todos os inimigos nessa direção e os empurrando. Se sua Habilidade Ativa estava pronta na última rodada, o dano final nesta rodada aumenta em <color=#00F6FF>60%</color>.",
  str_skill_desc_3020551 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>160%</color> de dano a todos os inimigos nessa direção e os empurrando. Se sua Habilidade Ativa estava pronta na última rodada, o dano final nesta rodada aumenta em <color=#00F6FF>60%</color>.",
  str_skill_desc_305055 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>160%</color> de dano a todos os inimigos nessa direção e os empurrando. Para cada <color=#00F6FF>1</color> casa em que um inimigo for empurrado, o dano final aumenta em <color=#00F6FF>5%</color>. Se sua Habilidade Ativa estava pronta na última rodada, o dano final nesta rodada aumenta em <color=#00F6FF>60%</color>.",
  str_skill_desc_3050551 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>160%</color> de dano a todos os inimigos nessa direção e os empurrando. Para cada <color=#00F6FF>1</color> casa em que um inimigo for empurrado, o dano final aumenta em <color=#00F6FF>5%</color>. Se sua Habilidade Ativa estava pronta na última rodada, o dano final nesta rodada aumenta em <color=#00F6FF>60%</color>.",
  str_skill_desc_300120 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>1 coluna</color> e empurra os inimigos. Converte casas na área de ataque em Verde.",
  str_skill_desc_16012001 = "Causa uma pequena quantidade de dano em 1 coluna e repele os inimigos. Converte as peças dentro da área de ataque em Verde.",
  str_skill_desc_16012002 = "Derruba 1 coluna de inimigos dentro de uma área especificada. Converte as peças na área de ataque em Verde.",
  str_skill_desc_303120 = "Teletransporta até um local selecionado. Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>1 coluna</color> e empurra os inimigos. Converte casas na área de ataque em Verde.",
  str_skill_desc_300123 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo dentro de <color=#00F6FF>1 círculo ao redor</color>. Ao atacar o mesmo alvo pela primeira vez, inflige <link=\"10004\"><#FFAE07><u>Paralisar</u></color></link> por 1 rodada. Ao atacar pela segunda vez, inflige <color=#00F6FF><color=#00F6FF>Atordoamento</color></color> por 1 rodada.",
  str_skill_desc_302123 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo dentro de <color=#00F6FF>1 círculo ao redor</color>. Ao atacar o mesmo alvo pela primeira vez, inflige <link=\"10004\"><#FFAE07><u>Paralisar</u></color></link> por 1 rodada. Ao atacar pela segunda vez, inflige <color=#00F6FF>Atordoamento</color> por 1 rodada.",
  str_skill_desc_305123 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo dentro de <color=#00F6FF>1 círculo ao redor</color>. Ao atacar o mesmo alvo pelas duas primeiras vezes, inflige <color=#00F6FF>Atordoamento</color> por 1 rodada cada vez.",
  str_skill_desc_320123 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo dentro de <color=#00F6FF>1 círculo ao redor</color>. Ao atacar o mesmo alvo pela primeira vez, inflige <link=\"10004\"><#FFAE07><u>Paralisar</u></color></link> por 1 rodada. Ao atacar pela segunda vez, o inflige <color=#00F6FF>Atordoamento</color> por 1 rodada. O dano da Habilidade Ativa aumenta com base no número de casas ocupadas pelo alvo.",
  str_skill_desc_322123 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo dentro de <color=#00F6FF>1 círculo ao redor</color>. Ao atacar o mesmo alvo pela primeira vez, inflige <link=\"10004\"><#FFAE07><u>Paralisar</u></color></link> por 1 rodada. Ao atacar pela segunda vez, o inflige <color=#00F6FF>Atordoamento</color> por 1 rodada. O dano da Habilidade Ativa aumenta com base no número de casas ocupadas pelo alvo.",
  str_skill_desc_325123 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo dentro de <color=#00F6FF>1 círculo ao redor</color>. Ao atacar o mesmo alvo nas duas primeiras vezes, inflige <color=#00F6FF>Atordoamento</color> por 1 rodada em cada vez. O dano da Habilidade Ativa aumenta com base no número de casas ocupadas pelo alvo.",
  str_skill_desc_300015 = "Selecione uma casa atravessável para invocar Gin e determinar sua direção. Em seguida, jogue 1 granada naquela direção. Essa granada pode quicar de novo para a distância mais longe possível na direção selecionada de Gin. A granada causa <color=#00F6FF>200%</color> de dano a inimigos pelos quais ela passa ao longo do caminho.",
  str_skill_desc_330015 = "Selecione uma casa atravessável para invocar Gin e determinar sua direção. Em seguida, jogue 1 granada naquela direção. Essa granada pode quicar de novo para a distância mais longe possível na direção selecionada de Gin. A granada causa <color=#00F6FF>200%</color> de dano a inimigos pelos quais ela passa ao longo do caminho. Gin pode ser feito para ficar em direções diagonais.",
  str_skill_desc_300131 = "Recupera o PV da equipe em <color=#00F6FF>220%</color> do ATQ de Novio e ganha um escudo igual a <color=#00F6FF>90%</color> do PV de Novio. Se houver cura em excesso, causa dano a inimigos dentro de <color=#00F6FF>12 casas em forma de diamante</color> igual ao excesso do valor recuperado sem considerar a defesa.",
  str_skill_desc_306131 = "Recupera o PV da equipe em <color=#00F6FF>220%</color> do ATQ de Novio e ganha um escudo igual a <color=#00F6FF>120%</color> do PV de Novio. Se houver cura em excesso, causa dano a inimigos dentro de <color=#00F6FF>12 casas em forma de diamante</color> igual ao excesso do valor recuperado sem considerar a defesa.",
  str_skill_desc_320131 = "Recupera o PV da equipe em <color=#00F6FF>220%</color> do ATQ de Novio e ganha um escudo igual a <color=#00F6FF>90%</color> do PV de Novio. Se houver cura em excesso, causa dano a inimigos dentro de <color=#00F6FF>2 círculos ao redor</color> igual ao excesso do valor recuperado sem considerar a defesa. Ao entrar na Hora da Aurora, o valor do escudo, contando até o PV Máx., será convertido em PV.",
  str_skill_desc_326131 = "Recupera o PV da equipe em <color=#00F6FF>220%</color> do ATQ de Novio e ganha um escudo igual a <color=#00F6FF>120%</color> do PV de Novio. Se houver cura em excesso, causa dano a inimigos dentro de <color=#00F6FF>2 círculos ao redor</color> igual ao excesso do valor recuperado sem considerar a defesa. Ao entrar na Hora da Aurora, o valor do escudo, contando até o PV Máx., será convertido em PV.",
  str_skill_desc_300132 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé ao final da rodada, o PV recuperado é igual ao dano.",
  str_skill_desc_302132 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé ao final da rodada, o PV recuperado é igual ao dano. Ao se recuperar, a recarga da Habilidade Ativa também é reduzida por <color=#00F6FF>1</color> rodada.",
  str_skill_desc_305132 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé ao final da rodada, o PV recuperado é igual ao dano. Ao se recuperar, a recarga da Habilidade Ativa também é reduzida por <color=#00F6FF>1</color> rodada.",
  str_skill_desc_320132 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé no final da rodada, ele recuperará PV igual ao dano. Ao entrar na Hora da Aurora, inimigos não podem recuperar PV quando a rodada acabar.",
  str_skill_desc_3201321 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé no final da rodada, ele recuperará PV igual ao dano. Ao entrar na Hora da Aurora, inimigos não podem recuperar PV quando a rodada acabar.",
  str_skill_desc_322132 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé no final da rodada, ele recuperará PV igual ao dano. Ao se recuperar, a recarga da Habilidade Ativa também é reduzida por <color=#00F6FF>1</color> rodada. Ao entrar na Hora da Aurora, inimigos não podem recuperar PV quando a rodada acabar.",
  str_skill_desc_3221321 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé no final da rodada, ele recuperará PV igual ao dano. Ao se recuperar, a recarga da Habilidade Ativa também é reduzida por <color=#00F6FF>1</color> rodada. Ao entrar na Hora da Aurora, inimigos não podem recuperar PV quando a rodada acabar.",
  str_skill_desc_325132 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé no final da rodada, ele recuperará PV igual ao dano. Ao se recuperar, a recarga da Habilidade Ativa também é reduzida por <color=#00F6FF>1</color> rodada. Ao entrar na Hora da Aurora, inimigos não podem recuperar PV quando a rodada acabar.",
  str_skill_desc_3251321 = "Causa <color=#00F6FF>{1}%</color> de dano a 1 inimigo selecionado. Se o inimigo estiver de pé no final da rodada, ele recuperará PV igual ao dano. Ao se recuperar, a recarga da Habilidade Ativa também é reduzida por <color=#00F6FF>1</color> rodada. Ao entrar na Hora da Aurora, inimigos não podem recuperar PV quando a rodada acabar.",
  str_skill_desc_300133 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>13 casas em forma de diamante</color> centradas na casa selecionada e empurra inimigos.",
  str_skill_desc_302133 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>13 casas em forma de diamante</color> centradas na casa selecionada e empurra inimigos.",
  str_skill_desc_300137 = "Seleciona 1 inimigo e converte até <color=#00F6FF>2</color> casas não Azuis no pé do inimigo em Azul.",
  str_skill_desc_310137 = "Seleciona 1 inimigo e converte até <color=#00F6FF>2</color> casas não Azuis no pé do inimigo em Azul.",
  str_skill_desc_304137 = "Seleciona 1 inimigo e converte até <color=#00F6FF>3</color> casas não Azuis no pé do inimigo em Azul.",
  str_skill_desc_314137 = "Seleciona 1 inimigo e converte até <color=#00F6FF>3</color> casas não Azuis no pé do inimigo em Azul.",
  str_skill_desc_300135 = "Seleciona 1 de <color=#00F6FF>4</color> direções e, em seguida, seleciona uma direção de cada lado, atacando os inimigos dentro <color=#00F6FF>45 graus</color> e lidar <color=#00F6FF>340%</color> danos na área. O dano diminui durante esta varredura para um mínimo de 30% do valor original.",
  str_skill_desc_302135 = "Seleciona 1 de <color=#00F6FF>4</color> direções e, em seguida, seleciona uma direção de cada lado, atacando os inimigos dentro <color=#00F6FF>45 graus</color> e lidar <color=#00F6FF>340%</color> danos na área. O dano diminui durante esta varredura para um mínimo de 30% do valor original.",
  str_skill_desc_305135 = "Seleciona 1 de <color=#00F6FF>4</color> direções e, em seguida, seleciona uma direção de cada lado, atacando os inimigos dentro <color=#00F6FF>45 graus</color> e lidar <color=#00F6FF>340%</color> danos na área. O dano diminui durante esta varredura para um mínimo de 40% do valor original.",
  str_skill_desc_320135 = "Seleciona 1 de <color=#00F6FF>4</color> direções e, em seguida, seleciona uma direção de cada lado, atacando os inimigos dentro <color=#00F6FF>90 graus</color> e lidar <color=#00F6FF>340%</color> danos na área. O dano diminui durante esta varredura para um mínimo de 30% do valor original.",
  str_skill_desc_322135 = "Seleciona 1 de <color=#00F6FF>4</color> direções e, em seguida, seleciona uma direção de cada lado, atacando os inimigos dentro <color=#00F6FF>90 graus</color> e lidar <color=#00F6FF>340%</color> danos na área. O dano diminui durante esta varredura para um mínimo de 30% do valor original.",
  str_skill_desc_325135 = "Seleciona 1 de <color=#00F6FF>4</color> direções e, em seguida, seleciona uma direção de cada lado, atacando os inimigos dentro <color=#00F6FF>90 graus</color> e lidar <color=#00F6FF>340%</color> danos na área. O dano diminui durante esta varredura para um mínimo de 40% do valor original.",
  str_skill_desc_300134 = "Selecione uma casa e cause <color=#00F6FF>{1}%</color> de dano em inimigos pelo caminho e em casas adjacentes, os empurrando o mais longe possível.",
  str_skill_desc_303134 = "Seleciona uma casa e causa <color=#00F6FF>{1}%</color> de dano em inimigos pelo caminho e em casas adjacentes, os empurrando o mais longe possível.",
  str_skill_desc_320134 = "Seleciona uma casa e causa <color=#00F6FF>{1}%</color> de dano em inimigos <color=#00F6FF>pelo caminho</color> e em casas <color=#00F6FF>adjacentes</color>, os empurrando o mais longe possível. Inimigos <color=#00F6FF>pelo caminho</color> receberão <color=#00F6FF>1,3x</color> de dano.",
  str_skill_desc_323134 = "Seleciona uma casa e causa <color=#00F6FF>{1}%</color> de dano em inimigos <color=#00F6FF>pelo caminho</color> e em casas <color=#00F6FF>adjacentes</color>, os empurrando o mais longe possível. Inimigos <color=#00F6FF>pelo caminho</color> receberão <color=#00F6FF>1,3x</color> de dano.",
  str_skill_desc_300136 = "Causa <color=#00F6FF>{1}%</color> de dano em todos os inimigos e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> em todos os inimigos em casas Verdes por 2 rodadas.",
  str_skill_desc_302136 = "Causa <color=#00F6FF>{1}%</color> de dano em todos os inimigos e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> em todos os inimigos em casas Verdes por 2 rodadas.",
  str_skill_desc_320136 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> em todos os inimigos em casas Verdes por 2 rodadas. Os inimigos receberão <color=#00F6FF>2 acúmulos</color> de Marca Letal antes da Habilidade Ativa causar dano.",
  str_skill_desc_322136 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> em todos os inimigos em casas Verdes por 2 rodadas. Os inimigos receberão <color=#00F6FF>2 acúmulos</color> de Marca Letal antes da Habilidade Ativa causar dano.",
  str_skill_desc_325136 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos e aplica <link=\"10006\"><#FFAE07><u>Lentidão</u></color></link> em todos os inimigos em casas Verdes por 2 rodadas. Os inimigos receberão <color=#00F6FF>3 acúmulos</color> de Marca Letal antes da Habilidade Ativa causar dano.",
  str_skill_passive_desc_410022 = "Aumenta o dano da Habil. Ativa em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410051 = "Aumenta o dano da Habil. Ativa em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410047 = "Aumenta o Fator de Cura do Combo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410049 = "Há <color=#00F6FF>{1}</color> de chance de aumentar o dano de Combo em <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_410050 = "Aumenta o dano de Combo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410052 = "Habil. Ativas tem <color=#00F6FF>{1}</color> de chance de <link=\"10006\"><#FFAE07><u>Desacelerar</u></color></link> inimigos por 2 rod.",
  str_skill_passive_desc_410074 = "Aumenta o dano da Habil. Ativa em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410008 = "O dano do Ataque Normal de Tiny One aumenta em <color=#00F6FF>{1}</color> nessa rodada após usar uma Habil. Ativa.",
  str_skill_passive_desc_410007 = "Ao usar Combo, causa +<color=#00F6FF>{1}</color> de dano ao primeiro inimigo atingido e aplica 1 acúmulo de Veneno, dura 2 rodadas.",
  str_skill_passive_desc_410032 = "Cada raio tem um <color=#00F6FF>15%</color> chance de lidar com um adicional <color=#00F6FF>{1}</color> dano.",
  str_skill_passive_desc_410053 = "Aumenta o dano de Combo em <color=#00F6FF>{1}</color> quando a Habil. Ativa está pronta.",
  str_skill_passive_desc_410058 = "Se o estandarte ainda existir no final da rodada, regenera o PV da equipe em <color=#00F6FF>{1}</color> vezes a DEF de Amy.",
  str_skill_passive_desc_400035 = "Após usar essa habilidade de movimento, Eho aumenta o dano de ataque normal em <color=#00F6FF>{1}</color> na rodada.",
  str_skill_passive_desc_410035 = "Após usar essa habilidade de movimento, Eho aumenta o dano de ataque normal em <color=#00F6FF>{1}</color> na rodada.",
  str_skill_passive_desc_420035 = "Após usar essa habilidade de movimento, Eho aumenta o dano de ataque normal e o dano de Combo em <color=#00F6FF>{1}</color> na rodada.",
  str_skill_passive_desc_410017 = "Quando um Aurorian aliado empurra um inimigo, Rabbie causa dano igual a <color=#00F6FF>{1}</color> de seu ATQ nesse inimigo (esse dano ignora DEF).",
  str_skill_passive_desc_430017 = "Quando um Aurorian aliado empurra um inimigo, Rabbie causa dano igual a <color=#00F6FF>{1}</color> de seu ATQ nesse inimigo (esse dano ignora DEF). Aumenta o dano que ignora DEF em <color=#00F6FF>10%</color> para cada 1 casa em que o inimigo for empurrado.",
  str_skill_passive_desc_410040 = "Concede 1 pilha de Stickiness Mark no início de cada rodada. Cada pilha aumenta a chance de habilidades Chain Combo infligir <link=\"10002\"> <#FFAE07><u>Queimar</u></color></link> que dura 2 rodadas por <color=#00F6FF>{1}</color>. Todas as pilhas são limpas no início de cada onda.",
  str_skill_passive_desc_420040 = "Concede 1 pilha de Stickiness Mark no início de cada rodada. Cada pilha aumenta a chance de habilidades Chain Combo infligir <link=\"10002\"> <#FFAE07><u>Queimar</u></color></link> que dura 2 rodadas por <color=#00F6FF>{1}</color>. Todas as pilhas são limpas no início de cada onda.",
  str_skill_passive_desc_410041 = "Aumenta o ATQ de Blanc em <color=#00F6FF>{1}</color> com PV cheio.",
  str_skill_passive_desc_420041 = "Aumenta o ATK de Blanc em <color=#00F6FF>{1}</color> quando o HP está acima de 70%.",
  str_skill_passive_desc_430041 = "Aumenta o ATK de Blanc em <color=#00F6FF>{1}</color> e aumenta o ATK de outros Aurorianos da Água implantados em <color=#00F6FF>{2}</color> do ATK de Blanc quando o HP está acima de 70%.",
  str_skill_passive_desc_410021 = "Aumenta o dano do Chain Combo em <color=#00F6FF>{1}</color> quando a habilidade ativa não está pronta.",
  str_skill_passive_desc_420021 = "Aumenta o dano do Chain Combo em <color=#00F6FF>{1}</color> e Dano de Ataque Normal por <color=#00F6FF>{2}</color> quando a habilidade ativa não está pronta.",
  str_skill_passive_desc_410004 = "Aumenta o PV Máx. da equipe em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410073 = "Libera 1 combo adicional no começo da linha, causando <color=#00F6FF>{1}</color> de dano normal.",
  str_skill_passive_desc_430073 = "Libera 1 combo adicional no começo da linha, causando <color=#00F6FF>{1}</color> de dano normal. Aumenta o dano em <color=#00F6FF>100%</color> onde os combos inicial e atual se sobrepõem.",
  str_skill_passive_desc_410061 = "Concede 1 acúmulo de Marca: Negatividade quando uma Habil. Ativa é usada, até <color=#00F6FF>3</color> acúmulos. Cada acúmulo aumenta o número de ataques de Habil. Ativa em 1 e reduz o dano final em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420061 = "Concede 1 acúmulo de Marca: Negatividade quando uma Habil. Ativa é usada, até <color=#00F6FF>5</color> acúmulos. Cada acúmulo aumenta o número de ataques de Habil. Ativa em 1 e reduz o dano final em <color=#00F6FF>{1}</color>. Cada marca aumenta o dano de Combo em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430061 = "Concede 1 acúmulo de Marca: Negatividade quando uma Habil. Ativa é usada, até <color=#00F6FF>5</color> acúmulos. Cada acúmulo aumenta o número de ataques de Habil. Ativa em 1 e reduz o dano final em <color=#00F6FF>{1}</color>. Cada marca aumenta o dano de Combo em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_414061 = "Concede 1 acúmulo de Marca: Negatividade quando uma Habil. Ativa é usada, até <color=#00F6FF>3</color> acúmulos. Cada acúmulo aumenta o número de ataques de Habil. Ativa em 1 e reduz o dano final em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_424061 = "Concede 1 acúmulo de Marca: Negatividade quando uma Habil. Ativa é usada, até <color=#00F6FF>5</color> acúmulos. Cada acúmulo aumenta o número de ataques de Habil. Ativa em 1 e reduz o dano final em <color=#00F6FF>{1}</color>. Cada marca aumenta o dano de Combo em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_434061 = "Concede 1 acúmulo de Marca: Negatividade quando uma Habil. Ativa é usada, até <color=#00F6FF>5</color> acúmulos. Cada acúmulo aumenta o número de ataques de Habil. Ativa em 1 e reduz o dano final em <color=#00F6FF>{1}</color>. Cada marca aumenta o dano de Combo em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410054 = "Quando uma lanterna desaparece no final de sua duração, ela libera uma luz que ilumina <color=#00F6FF>1 círculo ao redor</color>, causando <color=#00F6FF>{1}</color> de dano e tem uma chance de <color=#00F6FF>{2}</color> de aplicar <link=\"10005\"><#FFAE07><u>Ofuscado</u></color></link> em inimigos por 1 rodada.",
  str_skill_passive_desc_430054 = "Enquanto uma lanterna existir, ela libera luz que ilumina <color=#00F6FF>1 círculo ao redor</color> no final de cada rodada, causando <color=#00F6FF>{1}</color> de dano e tem uma chance de <color=#00F6FF>{2}</color> de aplicar <link=\"10005\"><#FFAE07><u>Ofuscado</u></color></link> em inimigos por 1 rodada.",
  str_skill_passive_desc_410016 = "Concede 1 acúmulo de carga sempre que passar por uma casa Amarela, até 99 acúmulos. Cada acúmulo aumenta o dano de Habil. Ativa em <color=#00F6FF>{1}</color>. Usar a Habil. Ativa limpa todos os acúmulos.",
  str_skill_passive_desc_410046 = "Cada acúmulo de Marca: Riso aumenta o dano de ataque normal dos Aurorians de Trovão em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430046 = "Derrotar inimigos com a Marca: Riso aplica <color=#00F6FF>1</color> acúmulo adicional a todos os inimigos restantes. Cada marca aumenta o dano de ataque normal em Aurorians de Trovão em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410044 = "Quando Combos causarem dano a todos os inimigos, Aurorians de Trovão recebem <color=#00F6FF>{1}</color> do ATQ de Vivian como bônus de ataque durante a rodada.",
  str_skill_passive_desc_430044 = "Quando Combos causarem dano a todos os inimigos, Aurorians de Água, Trovão e Illumina recebem <color=#00F6FF>{1}</color> do ATQ de Vivian como bônus de ATQ durante a rodada.",
  str_skill_passive_desc_410048 = "Aumenta o dano de Dayna contra inimigos ocupando uma casa Amarela em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430048 = "Aumenta o dano de Dayna contra inimigos ocupando um ladrilho Amarelo em <color=#00F6FF>{1}</color>. Também concede companheiros de equipe Thunder Aurorian <color=#00F6FF>50%</color> desse bônus.",
  str_skill_passive_desc_410009 = "No início de cada rodada, há uma chance de <color=#00F6FF>{1}</color> de aplicar <link=\"10003\"><#FFAE07><u>Pavor</u></color></link> em inimigos por 1 rodada.",
  str_skill_passive_desc_420009 = "No início de cada rodada, inimigos tem uma chance de <color=#00F6FF>{1}</color> de serem afetados com <link=\"10003\"><#FFAE07><u>Pavor</u></color></link> por 1 rodada. Ativa uma explosão quando derrotar um inimigo <link=\"10003\"><#FFAE07><u>Assustado</u></color></link>, causando <color=#00F6FF>10%</color> do PV Máx. como dano em inimigos a 1 círculo ao redor.",
  str_skill_passive_desc_410012 = "Cada acerto de Combo concede 1 acúmulo de Marca: Juízo. Cada acúmulo aumenta a DEF em <color=#00F6FF>{1}</color>. A marca desaparece no final da rodada.",
  str_skill_passive_desc_420012 = "Cada acerto de Combo concede 1 acúmulo de Marca: Juízo (2 se usar a Habil. Ativa). Cada acúmulo aumenta a DEF em <color=#00F6FF>{1}</color>. Mantém 50% dos acúmulos no final da rodada.",
  str_skill_passive_desc_430012 = "Cada acerto de Combo concede 1 acúmulo de Marca: Juízo (acertar a Habil. Ativa concede 2 acúmulos). Cada acúmulo aumenta o ATQ em <color=#00F6FF>3%</color> e a DEF em <color=#00F6FF>{1}</color>. Mantém 50% dos acúmulos no final da rodada.",
  str_skill_passive_desc_410013 = "Quando o escudo desaparece, converte <color=#00F6FF>{1}</color> do restante do escudo em PV.",
  str_skill_passive_desc_430013 = "Quando o escudo desaparece, converte <color=#00F6FF>{1}</color> do restante do escudo em PV. Aumenta a DEF de Noah em <color=#00F6FF>50%</color>, se um escudo existir.",
  str_skill_passive_desc_410018 = "Combos causam até <color=#00F6FF>{1}</color> de dano aumentado. Quanto mais perto os inimigos, maior o dano. Uma distância maior que 3 casas não oferece bônus de dano.",
  str_skill_passive_desc_420018 = "Quanto mais perto os inimigos, maior o dano de Habil. Ativas e Combos (até <color=#00F6FF>{1}</color>). Uma distância maior que 3 casas não oferece bônus de dano.",
  str_skill_passive_desc_430018 = "Aumenta o ATK em <color=#00F6FF>5%</color> para cada inimigo dentro <color=#00F6FF>1 cluster circundante</color>. Quanto mais próximos estiverem os inimigos, maior será o dano das habilidades ativas e dos combos em cadeia (até <color=#00F6FF>{1}</color>). Uma distância além de 3 aglomerados não oferece bônus de dano.",
  str_skill_passive_desc_410033 = "Vice ganha 1 acúmulo de Marca: Confinado, quando ela causar dano. Cada acúmulo aumenta o dano em <color=#00F6FF>{1}</color>. Todos os acúmulos são limpos no final da rodada.",
  str_skill_passive_desc_430033 = "Vice ganha 1 acúmulo de Marca: Confinado, quando ela causar dano. Cada acúmulo aumenta o dano em <color=#00F6FF>{1}</color> e o dano de Combo em <color=#00F6FF>{2}</color>.Todos os acúmulos são limpos no final da rodada.",
  str_skill_passive_desc_410036 = "Concede 1 Marca: Lobo no início de cada rodada. Quando atacado pela primeira vez, consome 1 marca para causar dano igual a <color=#00F6FF>{1}</color> do ATQ de Hydrad de volta no alvo (esse dano ignora DEF). Todas as Marcas: Lobo são limpas no final da rodada.",
  str_skill_passive_desc_420036 = "Concede 1 Marca: Lobo no início de cada rodada. Quando atacado, consome 1 marca para causar dano igual a <color=#00F6FF>{1}</color> do ATQ de Hydrad de volta no alvo (esse dano ignora DEF). Nenhuma Marca: Lobo <color=#00F6FF>é limpa</color> no final da rodada.",
  str_skill_passive_desc_410010 = "Ao ativar <link=\"30010\"><#FFAE07><u>Hora da Aurora</u></color></link>, o PV da equipe imediatamente é recuperado em <color=#00F6FF>{1}</color> do PV Máx. de Louise e aumenta sua DEF em <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_420010 = "Ao ativar <link=\"30010\"><#FFAE07><u>Hora da Aurora</u></color></link>, o PV da equipe imediatamente é recuperado em <color=#00F6FF>{1}</color> do PV Máx. de Louise e aumenta sua DEF em <color=#00F6FF>50%</color> por 2 rodadas.",
  str_skill_passive_desc_410014 = "Aumenta a DEF de Schwartz em <color=#00F6FF>{1}</color> para cada Aurorian de Trovão ou Lumópolis atribuído.",
  str_skill_passive_desc_430014 = "Aumenta a DEF de Schwartz em {1} para cada Trovão ou Aurorian de Lumópolis atribuído (também aumenta o ATQ na mesma quantidade de DEF concedida).",
  str_skill_passive_desc_410078 = "Aumenta o dano de Robyn contra inimigos ocupando casas Verdes em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430078 = "Aumenta o dano de Robyn contra inimigos ocupando um ladrilho Verde em <color=#00F6FF>{1}</color>. Também concede companheiros de equipe da Floresta Auroriana <color=#00F6FF>50%</color> desse bônus.",
  str_skill_passive_desc_410076 = "Após usar um Combo, toca em <color=#00F6FF>4 inimigos adjacentes em forma de cruz</color> e aplica <link=\"10003\"><#FFAE07><u>Pavor</u></color></link> por 1 rodada, se o PV do inimigo estiver abaixo de <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420076 = "Após usar um Combo, aplica <link=\"10003\"><#FFAE07><u>Pavor</u></color></link> em 1 inimigo com o PV mais baixo (abaixo de <color=#00F6FF>{1}</color> PV) em <color=#00F6FF>4 casas em forma de cruz</color> por 1 rodada. Derrotar um inimigo <link=\"10003\"><#FFAE07><u>Assustado</u></color></link> tem uma chance de <color=#00F6FF>50%</color> de aplicar <link=\"10003\"><#FFAE07><u>Pavor</u></color></link> em inimigos a <color=#00F6FF>4 casas dele, em forma de cruz</color>.",
  str_skill_passive_desc_410042 = "Ataques normais podem atirar diagonalmente e causam <color=#00F6FF>{1}</color> de dano.",
  str_skill_passive_desc_420042 = "Ataques normais podem atirar diagonalmente para causar <color=#00F6FF>{1}</color> de dano e aplicam 1 Marca: Poder de Fogo que dura 2 rodadas. O ataque normal de Barton causa <color=#00F6FF>10%</color> de dano adicional a inimigos com a marca.",
  str_skill_passive_desc_430042 = "Ataques normais podem atirar diagonalmente para causar <color=#00F6FF>{1}</color> de dano e aplicam 1 Marca: Poder de Fogo que dura 2 rodadas. O ataque de Barton causa <color=#00F6FF>10%</color> de <color=#00F6FF>dano</color> adicional a inimigos com a marca.",
  str_skill_passive_desc_410001 = "Concede Mirror Mark no início da batalha. Enquanto a Marca existir, Nikinis ganhos <color=#00F6FF>{1}</color> DEF aumentada. A marca desaparece uma vez Nikinis perde HP. A marca do espelho pode ser atualizada por <color=#00F6FF>usando uma Habilidade Ativa</color>.",
  str_skill_passive_desc_420001 = "Concede Mirror Mark no início da batalha. Enquanto a Marca existir, Nikinis ganhos <color=#00F6FF>{1}</color> DEF aumentada. A marca desaparece uma vez Nikinis perde HP. A marca do espelho pode ser atualizada por <color=#00F6FF>usando uma habilidade ativa ou entrando no Aurora Time</color>.",
  str_skill_passive_desc_410011 = "Ataques normais aplicam 1 acúmulo de Marca: Dracodente, até <color=#00F6FF>4</color> acúmulos. Cada acúmulo aumenta o dano final de Combo de Sharona em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430011 = "Ataques normais aplicam 1 acúmulo de Marca: Dracodente, até <color=#00F6FF>6</color> acúmulos. Cada acúmulo aumenta o <color=#00F6FF>dano de Habil. Ativa</color> e dano final de Combo de Sharona em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_440011 = "Ataques normais aplicam 1 pilha de Dragontooth Mark, até <color=#00F6FF>7</color> pilhas. Cada pilha aumenta o poder de Sharona <color=#00F6FF>Habilidade ativa</color> e dano final do Chain Combo por <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410019 = "Victoria regenera <color=#00F6FF>{1}</color> do PV Máx. por acúmulo de <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> sempre que seu Combo atingir um inimigo afetado por <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link>.",
  str_skill_passive_desc_420019 = "Victoria regenera <color=#00F6FF>{1}</color> do PV Máx. por acúmulo de <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> sempre que seu Combo atingir um inimigo afetado por <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link>.",
  str_skill_passive_desc_430019 = "Victoria regenera PV igual a <color=#00F6FF>{1}</color> de seu PV Máx. por acúmulo de <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link>, sempre que ela atingir um inimigo afetado por <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> usando um Combo. Esse efeito de recuperação aumenta <color=#00F6FF>50%</color>, se a porcentagem de PV do inimigo for maior que a da sua equipe.",
  str_skill_passive_desc_410023 = "Ganha 1 acúmulo de Marca: Tremor ao usar um Combo, até <color=#00F6FF>5</color> acúmulos. Cada acúmulo aumenta o dano da Habil. Ativa em <color=#00F6FF>{1}</color>. Usar uma Habilidade Ativa aplica <link=\"10003\"><#FFAE07><u>Pavor</u></color></link> em um número de inimigos equivalente ao número de acúmulos por <color=#00F6FF>1</color> rodada. Ativar a Habil. Ativa <color=#00F6FF>não limpa acúmulos</color>.",
  str_skill_passive_desc_430023 = "Ganha 1 pilha de Shiver Mark ao usar um Chain Combo, até <color=#00F6FF>5</color> pilhas. Cada pilha aumenta o dano da Habilidade Ativa em <color=#00F6FF>{1}</color>. Usar uma habilidade ativa inflige <link=\"10003\"><#FFAE07><u>Susto</u></color></link> em um número de inimigos equivalente ao número de stacks para <color=#00F6FF>1</color> redondo. Ativando a habilidade ativa <color=#00F6FF>não limpa pilhas</color>. Se ela já tiver 5 stacks antes de usar um Chain Combo, causará dano adicional ao inimigo do armário.",
  str_skill_passive_desc_410002 = "Hiiro entra na postura Duelo no começo da rodada. O próximo ataque normal causa <color=#00F6FF>{1}</color> de dano ao inimigo e <color=#00F6FF>{2}</color> de dano a inimigos em uma área de <color=#00F6FF>4 casas em forma de cruz</color>.",
  str_skill_passive_desc_420002 = "Hiiro entra na postura Duelo no início da rodada ou sempre que passar por uma <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link>. O próximo ataque normal causa <color=#00F6FF>{1}</color> de dano ao inimigo e <color=#00F6FF>{2}</color> de dano a inimigos em uma área de <color=#00F6FF>4 casas em forma de cruz</color>.",
  str_skill_passive_desc_430002 = "Hiiro entra na postura Duelo no início da rodada ou sempre que passar por uma <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link>. O próximo ataque normal causa <color=#00F6FF>{1}</color> de dano ao inimigo e <color=#00F6FF>{2}</color> de dano a inimigos a <color=#00F6FF>4 casas em forma de cruz</color>. O ATQ aumenta <color=#00F6FF>4%</color> nessa rodada por uso de Unido ao Duelo. O aumento máximo é de <color=#00F6FF>20%</color>.",
  str_skill_passive_desc_410005 = "Mia ganha 1 acúmulo de Alma ao derrotar um inimigo com sua Habil. Ativa, até 5 acúmulos. Cada acúmulo libera uma explosão que causa <color=#00F6FF>{1}</color> de dano de ATQ.",
  str_skill_passive_desc_420005 = "Mia ganha 1 acúmulo de Alma ao derrotar um inimigo com sua Habil. Ativa, até 5 acúmulos. Cada acúmulo libera uma Explosão de Alma que causa <color=#00F6FF>{1}</color> de dano de ATQ e aumenta o ataque normal de Mia em <color=#00F6FF>3%</color> e o dano de Combo em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430005 = "Mia ganha 1 acúmulo de Alma para cada inimigo derrotado por <color=#00F6FF>aurorianos</color> no campo com suas Habilidades Ativas, até <color=#00F6FF>7</color> pilhas. Cada pilha desencadeia uma explosão que causa <color=#00F6FF>{1}</color> Dano de ATK a um único alvo, aumentando adicionalmente o Ataque Normal de Mia em <color=#00F6FF>3%</color>, e dano de Chain Combo por <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_410006 = "Carleen ganha +<color=#00F6FF>{1}</color> de ATQ Básico para cada 1 casa de Água que ela entrar ou atravessar na rodada (até <color=#00F6FF>{2}</color>).",
  str_skill_passive_desc_420006 = "Carleen ganha +<color=#00F6FF>{1}</color> de ATQ Básico para cada casa Azul que ela entrar ou atravessar na rodada (até <color=#00F6FF>{2}</color>). Os efeitos dobram após usar uma Habil. Ativa.",
  str_skill_passive_desc_430006 = "Carleen ganha +<color=#00F6FF>{1}</color> de ATQ para cada casa de Água que ela entrar ou atravessar na rodada (até <color=#00F6FF>{2}</color>). Os efeitos dobram por uma Habil. Ativa. Seus ataques normais ganham Perfurar em uma casa de Água e causam <color=#00F6FF>40%</color> de dano a uma casa alvo atrás do inimigo.",
  str_skill_passive_desc_410025 = "Adiciona dano que ignora DEF igual a <color=#00F6FF>{1}</color> do ATQ a ataques normais.",
  str_skill_passive_desc_430025 = "Ataques normais <color=#00F6FF>podem atacar diagonalmente</color>. Adiciona dano que ignora DEF igual a <color=#00F6FF>{1}</color> do ATQ a ataques normais.",
  str_skill_passive_desc_410026 = "Cada acúmulo de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link> aumenta o dano de Aur. de Fogo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430026 = "No início de cada rodada, aplica 1 acúmulo de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link> em inimigos ocupando casas Vermelhas por 2 rodadas. Cada acúmulo de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link> aumenta o dano de Aurorians de Fogo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410028 = "Cada casa Azul gerada no mapa recupera o PV da equipe em <color=#00F6FF>{1}</color> do PV Máx. de Raphaela.",
  str_skill_passive_desc_420028 = "Cada casa Azul gerada no mapa recupera o PV da equipe em <color=#00F6FF>{1}</color> do PV de Raphaela. Quanto menor o PV da equipe, maior a efetividade da cura até um adicional de <color=#00F6FF>bônus de 100%</color>.",
  str_skill_passive_desc_410029 = "Pelo menos 1 <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link> será gerada por <color=#00F6FF>{1}</color> casas Verdes atravessadas nessa rodada.",
  str_skill_passive_desc_430029 = "Durante essa rodada, pelo menos 1 <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link> será gerada por <color=#00F6FF>{1}</color> casas Verdes atravessadas e casas Verdes serão melhoradas primeiro.",
  str_skill_passive_desc_410038 = "Concede 1 Tormenta Magnética por 3 rodadas. O próximo Combo causa <color=#00F6FF>{1}</color> de dano a 1 inimigo adicional na área de ataque e aplica <link=\"10004\"><#FFAE07><u>Paralisia</u></color></link> por 1 rodada.",
  str_skill_passive_desc_420038 = "Concede 1 Tormenta Magnética por 3 rodadas. O próximo Combo causa <color=#00F6FF>{1}</color> de dano adicional a 1 inimigo na área de ataque e aplica <link=\"10004\"><#FFAE07><u>Paralisia</u></color></link> por 1 rodada. Há <color=#00F6FF>50%</color> de chance de atacar outro inimigo.",
  str_skill_passive_desc_430038 = "Concede 1 Tormenta Magnética por 3 rodadas no início da próxima batalha. O próximo Combo causa <color=#00F6FF>{1}</color> de dano adicional a 1 inimigo na área de ataque e aplica <link=\"10004\"><#FFAE07><u>Paralisia</u></color></link>. Tem <color=#00F6FF>50%</color> de chance de atacar outro inimigo.",
  str_skill_passive_desc_410077 = "Aurorianos que usaram uma Habil. Ativa receberão um bônus nesta rodada, igual a <color=#00F6FF>{1}</color> do ATQ básico de Bethlehem.",
  str_skill_passive_desc_420077 = "Aurorianos que usaram uma Habil. Ativa nesta rodada receberão um bônus igual a <color=#00F6FF>{1}</color> do ATQ básico de Bethlehem. Ao entrar na Hora da Aurora, a equipe receberá um bônus nesta rodada igual a <color=#00F6FF>{2}</color> do ATQ básico de Bethlehem.",
  str_skill_passive_desc_430077 = "Os Aurorians que usaram uma Habil. Ativa receberão um bônus igual a <color=#00F6FF>{1}</color> do ATQ básico de Bethlehem nesta rodada. Bethlehem também ganha um bônus de ATQ básico de <color=#00F6FF>{2}</color>. Este bônus de ATQ que Bethlehem ganha na mesma rodada pode ser acumulado. Após entrar na Hora da Aurora, a equipe ganha um bônus adicional nesta rodada igual a <color=#00F6FF>{2}</color> do ATQ básico de Bethlehem.",
  str_skill_passive_desc_400092 = "Quando um inimigo marcado morre, ganhe PV igual a <color=#00F6FF>{1}</color> do PV Máx. dele e de <link=\"30007\"><#FFAE07><u>efeitos de recuperação</u></color></link>.",
  str_skill_passive_desc_410092 = "Quando um inimigo marcado morre, ganhe PV igual a <color=#00F6FF>{1}</color> do PV Máx. dele e de <link=\"30007\"><#FFAE07><u>efeitos de recuperação</u></color></link>.",
  str_skill_passive_desc_420092 = "Quando um inimigo marcado morre, ganhe PV igual a <color=#00F6FF>{1}</color> do PV Máx. dele e de <link=\"30007\"><#FFAE07><u>efeitos de recuperação</u></color></link>. Até 1 casa da localização do inimigo é alterada para uma <link=\"20001\"><#FFAE07><u>casa melhorada</u></color></link>.",
  str_skill_passive_desc_400075 = "Ataques normais têm uma chance de <color=#00F6FF>{1}</color> de aplicar 1 acúmulo de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_passive_desc_410075 = "Ataques normais têm uma chance de <color=#00F6FF>{1}</color> de aplicar 1 acúmulo de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_passive_desc_430075 = "Ataques normais podem atingir inimigos em <color=#00F6FF>ladrilhos diagonais</color> e ter um <color=#00F6FF>{1}</color> chance de infligir 1 pilha de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas.",
  str_skill_passive_desc_400086 = "Recupera PV igual a <color=#00F6FF>{1}</color> da DEF de Uriah ao atravessar uma casa Verde <link=\"20001\"><#FFAE07><u>melhorada</u></color></link>.",
  str_skill_passive_desc_410086 = "Recupera PV igual a <color=#00F6FF>{1}</color> da DEF de Uriah ao atravessar uma casa Verde <link=\"20001\"><#FFAE07><u>melhorada</u></color></link>.",
  str_skill_passive_desc_400068 = "Quando um Aurorian teletransporta, Wendy ganha 1 acúmulo de marca para cada grupo entre a localização inicial e destino do Aurorian. Cada acúmulo aumenta o dano do próximo ataque normal de Wendy em <color=#00F6FF>{1}</color>. Lançar ataques normais limpa a marca.",
  str_skill_passive_desc_410068 = "Quando um Aurorian teletransporta, Wendy ganha 1 acúmulo de marca para cada grupo entre a localização inicial e destino do Aurorian. Cada acúmulo aumenta o dano do próximo ataque normal de Wendy em <color=#00F6FF>{1}</color>. Lançar ataques normais limpa a marca.",
  str_skill_passive_desc_430068 = "Quando um auroriano se teletransporta, Wendy ganha 1 pilha de Marca para cada aglomerado entre a localização inicial do auroriano e seu destino de teletransporte. Cada pilha aumenta o dano do próximo ataque normal de Wendy em <color=#00F6FF>{1}</color>. Wendy retém <color=#00F6FF>30%</color> dessas pilhas de Mark após o lançamento de ataques normais.",
  str_skill_passive_desc_400082 = "Combos têm uma chance de <color=#00F6FF>{1}</color> de aplicar 1 acúmulo de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_passive_desc_410082 = "Combos têm uma chance de <color=#00F6FF>{1}</color> de aplicar 1 acúmulo de <link=\"10001\"><#FFAE07><u>Veneno</u></color></link> por 2 rodadas.",
  str_skill_passive_desc_400057 = "No início de cada rodada, a equipe recupera PV igual a <color=#00F6FF>{1}</color> do ATQ de Philyshy e <color=#00F6FF>{2}</color> do PV perdido pela equipe.",
  str_skill_passive_desc_410057 = "No início de cada rodada, a equipe recupera PV igual a <color=#00F6FF>{1}</color> do ATQ de Philyshy e <color=#00F6FF>{2}</color> do PV perdido pela equipe.",
  str_skill_passive_desc_430057 = "No início de cada rodada, a equipe recupera PV igual a <color=#00F6FF>{1}</color> do ATQ de Philyshy e <color=#00F6FF>{2}</color> do PV perdido pela equipe. Para cada <color=#00F6FF>5%</color> de PV perdido pela equipe, o ATQ de Philyshy aumenta <color=#00F6FF>1%</color>.",
  str_skill_passive_desc_400091 = "Ao usar uma Habil. Ativa ou um Combo, reduz o ATQ de inimigos em <color=#00F6FF>1 círculo ao redor</color> da unidade em <color=#00F6FF>{1}</color> por 1 rodada.",
  str_skill_passive_desc_410091 = "Ao usar uma Habil. Ativa ou um Combo, reduz o ATQ de inimigos em <color=#00F6FF>1 círculo ao redor</color> da unidade em <color=#00F6FF>{1}</color> por 1 rodada.",
  str_skill_passive_desc_420091 = "Ao usar uma Habil. Ativa ou um Combo, reduz o ATQ de inimigos em <color=#00F6FF>1 círculo ao redor</color> da unidade em <color=#00F6FF>{1}</color> por 1 rodada.",
  str_skill_passive_desc_430091 = "Ao usar uma Habil. Ativa ou um Combo, reduz o ATQ e a DEF de inimigos em <color=#00F6FF>2 círculos ao redor</color> da unidade em <color=#00F6FF>{1}</color> por 1 rodada.",
  str_skill_passive_desc_400079 = "Quando sofrer um ataque de um alvo com uma porcentagem maior de PV, converte <color=#00F6FF>{1}</color> do ATQ de Michenny em DEF.",
  str_skill_passive_desc_410079 = "Quando sofrer um ataque de um alvo com uma porcentagem maior de PV, converte <color=#00F6FF>{1}</color> do ATQ de Michenny em DEF.",
  str_skill_passive_desc_420079 = "Quando estiver sob ataque de um alvo com maior porcentagem de PV, ele converte <color=#00F6FF>{1}</color> do ATQ de Michenny em DEF. Quando Michenny causa dano, converte a mesma porcentagem da DEF de Michenny em ATQ.",
  str_skill_passive_desc_400085 = "Quando uma Habil. Ativa causa dano em um inimigo, aumenta o dano final em <color=#00F6FF>10%</color> para cada <color=#00F6FF>{1}</color> de PV perdido pelo inimigo.",
  str_skill_passive_desc_410085 = "Quando uma Habil. Ativa causa dano em um inimigo, aumenta o dano final em <color=#00F6FF>10%</color> para cada <color=#00F6FF>{1}</color> de PV perdido pelo inimigo.",
  str_skill_passive_desc_400089 = "Concede 1 Marca: Pântano Dourado ao atravessar uma <link=\"30001\"><#FFAE07><u>casa Prisma</u></color></link>. Cada acúmulo de Marca: Pântano Dourado aumenta o dano de Combo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410089 = "Concede 1 Marca: Pântano Dourado ao atravessar uma <link=\"30001\"><#FFAE07><u>casa Prisma</u></color></link>. Cada acúmulo de Marca: Pântano Dourado aumenta o dano de Combo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420089 = "Concede 1 Marca: Pântano Dourado ao atravessar uma <link=\"30001\"><#FFAE07><u>casa Prisma</u></color></link>. Cada acúmulo de Marca: Pântano Dourado aumenta o dano de Combo em <color=#00F6FF>{1}</color> e dano de ataque normal em <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430089 = "Concede 1 Marca: Pântano Dourado ao atravessar uma <link=\"30001\"><#FFAE07><u>casa Prisma</u></color></link>. Cada acúmulo de Marca: Pântano Dourado aumenta o dano de Combo em <color=#00F6FF>{1}</color> e dano de ataque normal em <color=#00F6FF>3%</color>. Ao ativar <link=\"30010\"><#FFAE07><u>Hora da Aurora</u></color></link>, converte a casa inicial em <link=\"30001\"><#FFAE07><u>casa Prisma</u></color></link>.",
  str_skill_passive_desc_400027 = "Concede 1 acúmulo de Marca: Trovão Silencioso no início de cada rodada. Ataques normais consomem 1 acúmulo de Marca: Trovão Silencioso para causar dano extra igual a <color=#00F6FF>{1}</color> do PV atual ao inimigo.",
  str_skill_passive_desc_410027 = "Concede 1 acúmulo de Marca: Trovão Silencioso no início de cada rodada. Ataques normais consomem 1 acúmulo de Marca: Trovão Silencioso para causar dano extra igual a <color=#00F6FF>{1}</color> do PV atual ao inimigo.",
  str_skill_passive_desc_420027 = "Concede 1 acúmulo de Marca: Trovão Silencioso no início de cada rodada e ao usar uma Habil. Ativa ou Combo. Ataques normais consomem 1 acúmulo de Marca: Trovão Silencioso para causar dano extra igual a <color=#00F6FF>{1}</color> do PV atual ao inimigo.",
  str_skill_passive_desc_400060 = "Durante o estado Meio-Dia, ataques normais causam <color=#00F6FF>{1}%</color> de <link=\"30015\"><#FFAE07><u>dano ao redor</u></color></link> a todos os alvos em <color=#00F6FF>4 casas em forma de cruz</color>",
  str_skill_passive_desc_410060 = "Durante o estado Meio-Dia, ataques normais causam <color=#00F6FF>{1}%</color> de <link=\"30015\"><#FFAE07><u>dano ao redor</u></color></link> a todos os alvos em <color=#00F6FF>4 casas em forma de cruz</color>",
  str_skill_passive_desc_420060 = "Durante o estado Meio-Dia, aumenta o dano de ataques normais em <color=#00F6FF>20%</color> e eles causam <color=#00F6FF>{1}</color> de dano a todos os alvos em <color=#00F6FF>4 casas em forma de cruz</color> <link=\"30015\"><#FFAE07><u>ao redor</u></color></link> do inimigo.",
  str_skill_passive_desc_430060 = "Durante o estado Meio-Dia, aumenta o dano de ataques normais em <color=#00F6FF>20%</color> e eles causam <color=#00F6FF>{1}</color> de dano a todos os alvos em <color=#00F6FF>4 casas em forma de cruz</color> <link=\"30015\"><#FFAE07><u>ao redor</u></color></link> do inimigo.",
  str_skill_passive_desc_400064 = "Pode <link=\"30008\"><#FFAE07><u>reservar munição</u></color></link>. Cada vez que um Combo causar dano, 1 munição é consumida(até <color=#00F6FF>3</color> Munições consumidas no Estado de Sobrecarga). Para cada Munição consumida, o dano final aumenta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410064 = "Pode <link=\"30008\"><#FFAE07><u>reservar munição</u></color></link>. Cada vez que um Combo causar dano, 1 munição é consumida(até <color=#00F6FF>3</color> Munições consumidas no Estado de Sobrecarga). Para cada Munição consumida, o dano final aumenta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430064 = "Pode <link=\"30009\"><#FFAE07><u>reservar munição</u></color></link>. Cada vez que um Combo causar dano, 1 munição é consumida(até <color=#00F6FF>3</color> Munições consumidas no Estado de Sobrecarga). Para cada Munição consumida, o dano final aumenta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400070 = "Ataques normais têm uma chance de <color=#00F6FF>{1}</color> de ativar 1 Ataque do Dragão Rubro que causa dano igual a <color=#00F6FF>50%</color> do dano do ataque normal de Leona.",
  str_skill_passive_desc_410070 = "Ataques normais têm uma chance de <color=#00F6FF>{1}</color> de ativar 1 Ataque do Dragão Rubro que causa dano igual a <color=#00F6FF>50%</color> do dano do ataque normal de Leona.",
  str_skill_passive_desc_420070 = "Ataques normais têm uma chance de <color=#00F6FF>{1}</color> de ativar 1 Ataque do Dragão Rubro que causa dano igual a <color=#00F6FF>50%</color> do dano do ataque normal de Leona e aplica 1 acúmulo de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link> por 2 rodadas.",
  str_skill_passive_desc_400088 = "Aumenta o dano de Combo de Maggie em <color=#00F6FF>{1}</color> a cada <color=#00F6FF>10</color> combos.",
  str_skill_passive_desc_410088 = "Aumenta o dano de Combo de Maggie em <color=#00F6FF>{1}</color> a cada <color=#00F6FF>10</color> combos.",
  str_skill_passive_desc_420088 = "Aumenta o dano de Combo de Maggie em <color=#00F6FF>{1}</color> a cada <color=#00F6FF>10</color> combos e reduz as casas para ativar o combo em <color=#00F6FF>1</color>.",
  str_skill_passive_desc_430088 = "Aumenta o dano de Combo de Maggie em <color=#00F6FF>{1}</color> a cada <color=#00F6FF>8</color> combos e reduz as casas para ativar o combo em <color=#00F6FF>1</color>.",
  str_skill_passive_desc_400084 = "Após usar um Combo, reduz o ATQ de inimigos em <color=#00F6FF>1 círculo ao redor</color> da unidade em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410084 = "Após usar um Combo, reduz o ATQ de inimigos em <color=#00F6FF>1 círculo ao redor</color> da unidade em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420084 = "Após usar um Combo, reduz o ATQ de inimigos em <color=#00F6FF>2 círculos ao redor</color> da unidade em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400090 = "Aumenta o dano de Barbara em <color=#00F6FF>{1}</color> contra inimigos ocupando uma casa Vermelha.",
  str_skill_passive_desc_410090 = "Aumenta o dano de Barbara em <color=#00F6FF>{1}</color> contra inimigos ocupando uma casa Vermelha.",
  str_skill_passive_desc_430090 = "Aumenta o dano de Bárbara contra inimigos ocupando um ladrilho Vermelho em <color=#00F6FF>{1}</color>. Também concede companheiros de equipe Fire Aurorian <color=#00F6FF>50%</color> desse bônus.",
  str_skill_passive_desc_400045 = "O ATQ e a DEF de Nails aumenta conforme sua porcentagem de PV cai, concedendo um bônus de até <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410045 = "O ATQ e a DEF de Nails aumenta conforme sua porcentagem de PV cai, concedendo um bônus de até <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_400081 = "Após usar uma Habil. Ativa, aumenta o ATQ de Aurorians de Fogo em <color=#00F6FF>{1}</color> do ATQ de Brock para cada inimigo em <color=#00F6FF>1 círculo ao redor</color> da unidade.",
  str_skill_passive_desc_410081 = "Após usar uma Habil. Ativa, aumenta o ATQ de Aurorians de Fogo em <color=#00F6FF>{1}</color> do ATQ de Brock para cada inimigo em <color=#00F6FF>1 círculo ao redor</color> da unidade.",
  str_skill_passive_desc_430081 = "Após usar uma Habil. Ativa, aumenta o ATQ de Aurorians de Fogo em <color=#00F6FF>{1}</color> do ATQ de Brock para cada inimigo em <color=#00F6FF>2 círculos ao redor</color> da unidade.",
  str_skill_passive_desc_400083 = "Habil. Ativas tem chance de <color=#00F6FF>{1}</color> de reduzir o alcance de mov. de inimigos em <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_410083 = "Habil. Ativas tem chance de <color=#00F6FF>{1}</color> de reduzir o alcance de mov. de inimigos em <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_430083 = "Habil. Ativas tem chance de <color=#00F6FF>{1}</color> de reduzir o alcance de mov. de inimigos em <color=#00F6FF>50%</color>.",
  str_skill_passive_desc_400059 = "Concede até <color=#00F6FF>{1}</color> acúmulo(s) de <link=\"30002\"><#FFAE07><u>Marca: Pepi</u></color></link>. O alcance de movimento da Habil. Ativa torna-se um número de círculos ao redor da unidade igual aos acúmulos da marca. Ativar a Habil. Ativa limpa todos os acúmulos.",
  str_skill_passive_desc_410059 = "Concede até <color=#00F6FF>{1}</color> acúmulo(s) de <link=\"30002\"><#FFAE07><u>Marca: Pepi</u></color></link>. O alcance de movimento da Habil. Ativa torna-se um número de círculos ao redor da unidade igual aos acúmulos da marca. Ativar a Habil. Ativa limpa todos os acúmulos.",
  str_skill_passive_desc_420059 = "Concede até <color=#00F6FF>{1}</color> acúmulo(s) de <link=\"30003\"><#FFAE07><u>Marca: Pepi</u></color></link>. O alcance de movimento da Habil. Ativa torna-se um número de círculos ao redor da unidade igual aos acúmulos da marca. Ativar a Habil. Ativa limpa todos os acúmulos.",
  str_skill_passive_desc_400080 = "Quando não houver inimigos em alcance do Combo, recupera o PV da equipe em <color=#00F6FF>{1}</color> do ATQ de Unimet.",
  str_skill_passive_desc_410080 = "Quando não houver inimigos em alcance do Combo, recupera o PV da equipe em <color=#00F6FF>{1}</color> do ATQ de Unimet.",
  str_skill_passive_desc_400093 = "Depois de lançar um Chain Combo ou uma Habilidade Ativa, se o HP do alvo for menor que <color=#00F6FF>{1}</color>, lança mais 1 ataque causando dano ignorando DEF igual a <color=#00F6FF>{2}</color> de ATK.",
  str_skill_passive_desc_410093 = "Depois de lançar um Chain Combo ou uma Habilidade Ativa, se o HP do alvo for menor que <color=#00F6FF>{1}</color>, lança mais 1 ataque causando dano ignorando DEF igual a <color=#00F6FF>{2}</color> de ATK.",
  str_skill_passive_desc_430093 = "Após ativar um Chain Combo ou uma Habilidade Ativa, se o HP do alvo for menor que <color=#00F6FF>{1}</color>, lança mais 1 ataque causando dano ignorando DEF igual a <color=#00F6FF>{2}</color> de ATK. Se o HP do alvo for menor que o ATK de Migard após o ataque extra, ele é morto.",
  str_skill_passive_desc_400097 = "Ataques normais viram ataques de 2 combos que causam <color=#00F6FF>{1}</color> de dano básico por acerto.",
  str_skill_passive_desc_410097 = "Ataques normais viram ataques de 2 combos que causam <color=#00F6FF>{1}</color> de dano básico por acerto.",
  str_skill_passive_desc_420097 = "Ataques normais viram ataques de 2 combos que causam <color=#00F6FF>{1}</color> de dano básico por acerto. Cada ataque tem chance de <color=#00F6FF>20%</color> de causar <color=#00F6FF>50%</color> de dano extra.",
  str_skill_passive_desc_430097 = "Ataques normais viram ataques de 2 combos que causam <color=#00F6FF>{1}</color> de dano básico por acerto. Cada ataque tem chance de <color=#00F6FF>20%</color> de causar <color=#00F6FF>50%</color> de dano extra. Cada combo aumenta a chance em 0,5%, até 50%.",
  str_skill_passive_desc_400095 = "Ao causar dano a um inimigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada acúmulo de Veneno aumenta o dano final em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410095 = "Ao causar dano a um inimigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada acúmulo de Veneno aumenta o dano final em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420095 = "Ao causar dano a um inimigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada acúmulo de Veneno aumenta o dano final em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430095 = "Ao causar dano a um inimigo <link=\"10001\"><#FFAE07><u>Envenenado</u></color></link>, cada acúmulo de Veneno aumenta o dano final em <color=#00F6FF>{1}</color>. Quando uma Habil. Ativa ou Combo atinge um alvo Envenenado, a unidade recebe 1 acúmulo extra de Veneno.",
  str_skill_passive_desc_400062 = "Quando um ataque normal, Combo ou Habil. Ativa causa dano em apenas 1 inimigo, esse dano ignora <color=#00F6FF>{1}</color> da DEF do alvo.",
  str_skill_passive_desc_410062 = "Quando um ataque normal, Combo ou Habil. Ativa causa dano em apenas 1 inimigo, esse dano ignora <color=#00F6FF>{1}</color> da DEF do alvo.",
  str_skill_passive_desc_430062 = "Quando Normal Attack, Chain Combo ou Active Skill causa dano a apenas 1 inimigo, este dano é ignorado <color=#00F6FF>{1}</color> da DEF do alvo. Quando há apenas 1 inimigo no tabuleiro, as Habilidades Ativas de outros Aurorianos da Floresta na equipe também ganham 50% desse efeito.",
  str_skill_passive_desc_400024 = "Ataques normais causam <color=#00F6FF>{1}</color> de dano extra a inimigos ocupando casas Vermelhas.",
  str_skill_passive_desc_410024 = "Ataques normais causam <color=#00F6FF>{1}</color> de dano extra a inimigos ocupando casas Vermelhas.",
  str_skill_passive_desc_400087 = "Quando um Combo atinge um alvo, ele também causa dano a <color=#00F6FF>{1}</color> alvo(s) aleatório(s) (cada alvo só pode receber dano uma vez) em <color=#00F6FF>1 círculo ao redor</color> do alvo. O dano reduz em <color=#00F6FF>{2}</color> a cada acerto.",
  str_skill_passive_desc_410087 = "Quando um Combo atinge um alvo, ele também causa dano a <color=#00F6FF>{1}</color> alvo(s) aleatório(s) (cada alvo só pode receber dano uma vez) em <color=#00F6FF>1 círculo ao redor</color> do alvo. O dano reduz em <color=#00F6FF>{2}</color> a cada acerto.",
  str_skill_passive_desc_420087 = "Quando um Combo atinge um alvo, ele também causa dano a <color=#00F6FF>{1}</color> alvo(s) aleatório(s) (cada alvo só pode receber dano uma vez) em <color=#00F6FF>2 círculos ao redor</color> do alvo. O dano reduz em <color=#00F6FF>{2}</color> a cada acerto.",
  str_skill_passive_desc_400101 = "Aumenta o dano que Ansia causa a inimigos no limite do campo de batalha (o dano bônus é maior quando os inimigos estão no canto), até um aumento de <color=#00F6FF>{1}</color> do dano final.",
  str_skill_passive_desc_410101 = "Aumenta o dano que Ansia causa a inimigos no limite do campo de batalha (o dano bônus é maior quando os inimigos estão no canto), até um aumento de <color=#00F6FF>{1}</color> do dano final.",
  str_skill_passive_desc_400102 = "Subsídios 1 Tessa Marque sempre que um Thunder Aurorian na equipe usar sua Habilidade Ativa. Ao usar a Habilidade Ativa, cada marca causa <color=#00F6FF>{1}</color> dano aos inimigos dentro <color=#00F6FF>1 cluster circundante</color>. Ativar a habilidade ativa limpa todas as marcas.",
  str_skill_passive_desc_410102 = "Subsídios 1 Tessa Marque sempre que um Thunder Aurorian na equipe usar sua Habilidade Ativa. Ao usar a Habilidade Ativa, cada marca causa <color=#00F6FF>{1}</color> dano aos inimigos dentro <color=#00F6FF>1 cluster circundante</color>. Ativar a habilidade ativa limpa todas as marcas.",
  str_skill_passive_desc_420102 = "Subsídios 1 Tessa Marque sempre que um Thunder Aurorian na equipe usar sua Habilidade Ativa ou quando Tessa usa um Chain Combo. Ao usar a Habilidade Ativa, cada marca causa <color=#00F6FF>{1}</color> dano aos inimigos dentro <color=#00F6FF>1 cluster circundante</color>. Ativar a habilidade ativa limpa todas as marcas.",
  str_skill_passive_desc_430102 = "Subsídios 1 Tessa Marque sempre que um Thunder Aurorian na equipe usar sua Habilidade Ativa ou quando Tessa usa um Chain Combo. Ao usar a Habilidade Ativa, cada marca causa <color=#00F6FF>{1}</color> Danos ignorando DEF aos inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Ativar a habilidade ativa limpa todas as marcas.",
  str_skill_passive_desc_400099 = "Enquanto controlar a espada mágica, ataques normais perfurarão inimigos, causando <color=#00F6FF>{1}</color> de dano ao alvo 1 casa atrás do inimigo.",
  str_skill_passive_desc_410099 = "Enquanto controlar a espada mágica, ataques normais perfurarão inimigos, causando <color=#00F6FF>{1}</color> de dano ao alvo 1 casa atrás do inimigo.",
  str_skill_passive_desc_400100 = "Quando Sikare ataca inimigos pela primeira vez, ela ceifa a alma do alvo, causando dano igual a <color=#00F6FF>{1}</color> do ATQ naquele inimigo (esse dano ignora DEF).",
  str_skill_passive_desc_410100 = "Quando Sikare ataca inimigos pela primeira vez, ela ceifa a alma do alvo, causando dano igual a <color=#00F6FF>{1}</color> do ATQ naquele inimigo (esse dano ignora DEF).",
  str_skill_passive_desc_430100 = "Quando Sikare ataca inimigos pela primeira vez, ela ceifa a alma do alvo, causando dano igual a <color=#00F6FF>{1}</color> do ATQ, mais dano que ignora DEF igual a <color=#00F6FF>5%</color> do PV atual naquele inimigo.",
  str_skill_passive_desc_400098 = "Quando um Combo atinge um inimigo, aplica 1 acúmulo de Marca: Desmembrar. Acumula até 5 vezes. Cada acúmulo de Marca: Desmembrar aumenta o dano de Cuscuta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410098 = "Quando um Combo atinge um inimigo, aplica 1 acúmulo de Marca: Desmembrar. Acumula até 5 vezes. Cada acúmulo de Marca: Desmembrar aumenta o dano de Cuscuta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420098 = "Quando um Combo atinge um inimigo, aplica 1 acúmulo de Marca: Desmembrar. Acumula até 5 vezes. Cada acúmulo de Marca: Desmembrar aumenta o dano de Cuscuta em <color=#00F6FF>{1}</color>. Ataques normais tem uma chance de <color=#00F6FF>30%</color> de aplicar 1 acúmulo de Marca: Desmembrar.",
  str_skill_passive_desc_4200981 = "Quando um Chain Combo atinge um inimigo, inflige 1 pilha de Dismember Mark. Acumula até 10 vezes. Cada pilha de Dismember Mark aumenta o dano de Cuscuta em <color=#00F6FF>6%</color>. Os ataques normais têm um <color=#00F6FF>30%</color> chance de infligir 1 acúmulo de Dismember Mark.",
  str_skill_passive_desc_400094 = "Após um Combo acertar o alvo, reduz o ATQ do alvo em <color=#00F6FF>{1}</color> por 1 rodada.",
  str_skill_passive_desc_410094 = "Após um Combo acertar o alvo, reduz o ATQ do alvo em <color=#00F6FF>{1}</color> por 1 rodada.",
  str_skill_passive_desc_400096 = "Concede uma <link=\"30013\"><#FFAE07><u>Marca: Sariel</u></color></link>, até 8 acúmulos. Cada acúmulo aumenta a DEF de Sariel em <color=#00F6FF>{1}</color>. Mantém 50% dos acúmulos no final da rodada.",
  str_skill_passive_desc_410096 = "Concede uma <link=\"30013\"><#FFAE07><u>Marca: Sariel</u></color></link>, até 8 acúmulos. Cada acúmulo aumenta a DEF de Sariel em <color=#00F6FF>{1}</color>. Mantém 50% dos acúmulos no final da rodada.",
  str_skill_passive_desc_420096 = "Concede uma <link=\"30013\"><#FFAE07><u>Marca: Sariel</u></color></link>, até 8 acúmulos. Cada acúmulo aumenta a DEF de Sariel em <color=#00F6FF>{1}</color>, chegando até <color=#00F6FF>50%</color> da DEF, com base na quantidade de PV perdido. Mantém 50% dos acúmulos no final da rodada.",
  str_skill_passive_desc_400056 = "Quando um ataque normal ou uma Habil. Ativa causa dano (o que for maior), converte <color=#00F6FF>{1}</color> do dano em ATQ. Válido apenas na rodada atual.",
  str_skill_passive_desc_410056 = "Quando um ataque normal ou uma Habil. Ativa causa dano (o que for maior), converte <color=#00F6FF>{1}</color> do dano em ATQ. Válido apenas na rodada atual.",
  str_skill_passive_desc_430056 = "Quando um ataque normal ou uma Habil. Ativa causa dano (o que for maior), converte <color=#00F6FF>{1}</color> do dano em ATQ. Válido apenas na rodada atual. Quando há apenas 1 inimigo no campo de batalha, aumenta o ATQ de Aurorians de Água em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_400103 = "A cada 3 rodadas, Vazio pode ser ativado ou poupado para uso futuro. Após se tornar Vazio, o dano do Combo ignora a defesa e causa dano equivalente a <color=#00F6FF>{1}</color> do ATQ de Eicy, e recupera PV na mesma quantidade.",
  str_skill_passive_desc_410103 = "A cada 3 rodadas, Vazio pode ser ativado ou poupado para uso futuro. Após se tornar Vazio, o dano do Combo ignora a defesa e causa dano equivalente a <color=#00F6FF>{1}</color> do ATQ de Eicy, e recupera PV na mesma quantidade.",
  str_skill_passive_desc_430103 = "Concede o status Vazio uma vez a cada 3 rodadas (se não utilizada, o status é mantido). Durante o status Vazio, o Combo causa dano igual a <color=#00F6FF>{1}</color> do ATQ de Eicy (esse dano ignora DEF) e restaura PV na mesma quantidade. Quanto menor o PV da equipe, maior a efetividade da cura (até <color=#00F6FF>50%</color>).",
  str_skill_passive_desc_410067 = "Se PV foi recuperado nessa rodada, a DEF Básica de Alice aumenta em <color=#00F6FF>{1}</color> nesta rodada.",
  str_skill_passive_desc_430067 = "Se PV foi recuperado nessa rodada, a DEF Básica de Alice aumenta em <color=#00F6FF>{1}</color> nesta rodada.",
  str_skill_passive_desc_400030 = "Ataques normais <color=#00F6FF>podem acertar diagonalmente</color>. Ataques Normais na diagonal aplicam 1 acúmulo de Quebrar no alvo, que acumula até 5 vezes. Cada acúmulo reduz a DEF do alvo em <color=#00F6FF>{1}</color> da DEF Básica de Sinsa por 1 rodada.",
  str_skill_passive_desc_410030 = "Ataques normais <color=#00F6FF>podem acertar diagonalmente</color>. Ataques Normais na diagonal aplicam 1 acúmulo de Quebrar no alvo, que acumula até 5 vezes. Cada acúmulo reduz a DEF do alvo em <color=#00F6FF>{1}</color> da DEF Básica de Sinsa por 1 rodada.",
  str_skill_passive_desc_430030 = "Ataques normais <color=#00F6FF>podem acertar diagonalmente</color>. Ataques Normais na diagonal, Habil. Ativas e Combos aplicam 1 acúmulo de Quebrar no alvo, que acumula até 5 vezes. Cada acúmulo reduz a DEF do alvo em <color=#00F6FF>{1}</color> da DEF Básica de Sinsa por 1 rodada.",
  str_skill_passive_desc_410104 = "Habil. Ativas marcam o alvo do ataque. Quando Dawn ataca inimigos marcados com Habil Ativas e Combos, a marca é consumida e restaura PV igual a <color=#00F6FF>{1}</color> do dano causado.",
  str_skill_passive_desc_430104 = "Habil. Ativas marcam o alvo do ataque. Quando Dawn ataca inimigos marcados com Habil Ativas e Combos, a marca é consumida e restaura PV igual a <color=#00F6FF>{1}</color> do dano causado. Se a equipe está com PV cheio, o dano final desse ataque aumenta em <color=#00F6FF>25%</color>.",
  str_skill_passive_desc_410071 = "No início de cada rodada, aplica Marca: Queimadura ao inimigo com a maior porcentagem de PV, aumentando todo o dano que Taki causa ao alvo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430071 = "No início de cada rodada, aplica uma Burn Mark no inimigo com maior porcentagem de HP, aumentando todo o dano Taki lida com o alvo por <color=#00F6FF>{1}</color>. Cada vez que um inimigo afetado por Burn Mark é eliminado, o ATK de Taki aumenta em <color=#00F6FF>3%</color>, até um máximo de <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_400105 = "Quando Ataques Normais, Combos e Habilidades Ativas causam dano, cada <color=#00F6FF>8º</color> dano causado também causará <color=#00F6FF>{1}</color> de dano uma vez a <color=#00F6FF>todos</color> os inimigos.",
  str_skill_passive_desc_410105 = "Quando Ataques Normais, Combos e Habilidades Ativas causam dano, cada <color=#00F6FF>8º</color> dano causado também causará <color=#00F6FF>{1}</color> de dano uma vez a <color=#00F6FF>todos</color> os inimigos.",
  str_skill_passive_desc_420105 = "Quando Ataques Normais, Combos e Habilidades Ativas causam dano, cada <color=#00F6FF>8º</color> dano causado também causará <color=#00F6FF>{1}</color> de dano uma vez a <color=#00F6FF>todos</color> os inimigos.",
  str_skill_passive_desc_430105 = "Quando Ataques Normais, Combos e Habilidades Ativas causam dano, cada <color=#00F6FF>8º</color> dano causado também causará <color=#00F6FF>{1}</color> de dano uma vez a <color=#00F6FF>todos</color> os inimigos.",
  str_skill_passive_desc_430109 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada.",
  str_skill_passive_desc_433109 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada. Ganhe <color=#00F6FF>1</color> Vis pelo primeiro ataque normal lançado a cada rodada e aumente o dano desse ataque normal em <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_430110 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada. Ataques normais têm uma chance de <color=#00F6FF>30%</color> de liberar 1 relâmpago para atingir o inimigo mais distante.",
  str_skill_passive_desc_433110 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada. Ganha <color=#00F6FF>2</color> Vis extras ao derrotar um alvo com uma Habil. Ativa. Ataques normais têm uma chance de <color=#00F6FF>30%</color> de liberar 1 relâmpago para atingir o inimigo mais distante.",
  str_skill_passive_desc_430107 = "Ganhe 10 Vis no começo da batalha. Ao terminar a rodada em um estado não aumentado, ganhe <color=#00F6FF>5</color> Vis (ganha 1 Vis extra para cada 20% de PV perdido).",
  str_skill_passive_desc_436107 = "Ganhe 10 Vis no começo da batalha. No começo de cada rodada, para cada 1 inimigo <color=#00F6FF>em 4 casas em forma de cruz</color> ao redor, ganhe <color=#00F6FF>1</color> Vis. Ao terminar a rodada em um estado não aumentado, ganhe <color=#00F6FF>5</color> Vis (ganha 1 Vis extra para cada 20% de PV perdido).",
  str_skill_passive_desc_430108 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada. Ganhe <color=#00F6FF>5</color> Vis extras ao derrotar um alvo com uma Habil. Ativa.",
  str_skill_passive_desc_400116 = "Todo o dano que Fleur causa a inimigos com menos de 40% de seu PV Máx. é aumentado em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410112 = "Smokey ativa o <color=#00F6FF>Beijo da Manticora</color> <color=#00F6FF>cada vez</color> que ela ataca um inimigo com uma <color=#00F6FF>Habilidade Ativa ou Combo, ou a primeira vez que ela os atinge com um Ataque Básico a cada rodada</color> causando dano que ignora DEF igual a <color=#00F6FF>{1}</color> do ATQ. Esse efeito diminui quando é ativado repetidamente, até um mínimo de <color=#00F6FF>20%</color> do dano inicial.",
  str_skill_passive_desc_420112 = "Smokey gatilhos <color=#00F6FF>Beijo de Manticora</color> <color=#00F6FF>cada vez</color> ela ataca um inimigo com um <color=#00F6FF>Habilidade Ativa ou Combinação de Cadeia, ou a primeira vez que ela os acertar com um ataque normal a cada rodada</color>, causando dano adicional ignorando DEF igual a <color=#00F6FF>{1}</color> ATQ. Este efeito diminui quando acionado repetidamente, até um mínimo de <color=#00F6FF>20%</color> de seu dano inicial. <color=#00F6FF>Beijo de Manticora</color> ofertas <color=#00F6FF>em dobro</color> dano aos inimigos em telhas vermelhas.",
  str_skill_passive_desc_430112 = "Smokey gatilhos <color=#00F6FF>Beijo de Manticora</color> <color=#00F6FF>cada vez</color> ela ataca um inimigo com um <color=#00F6FF>Habilidade Ativa ou Combinação de Cadeia, ou a primeira vez que ela os acertar com um ataque normal a cada rodada</color>, causando dano adicional ignorando DEF igual a <color=#00F6FF>{1}</color> ATQ. Este efeito diminui quando acionado repetidamente, até um mínimo de <color=#00F6FF>20%</color> de seu dano inicial. <color=#00F6FF>Beijo de Manticora</color> ofertas <color=#00F6FF>em dobro</color> dano aos inimigos em telhas vermelhas.",
  str_skill_passive_desc_400113 = "Ganha Marca Divina no início da batalha ou ao usar uma Habil. Ativa. Enquanto a marca existir, a DEF de Bonacie aumenta em <color=#00F6FF>{1}</color>. A marca desaparece quando Bonacie perder PV.",
  str_skill_passive_desc_410113 = "Ganha Marca Divina no início da batalha ou ao usar uma Habil. Ativa. Enquanto a marca existir, a DEF de Bonacie aumenta em <color=#00F6FF>{1}</color>. A marca desaparece quando Bonacie perder PV.",
  str_skill_passive_desc_420113 = "Ganha Marca Divina no início da batalha ou ao usar uma Habilidade Ativa. Enquanto a marca existir, a DEF de Bonacie aumenta em <color=#00F6FF>{1}</color>. A marca desaparece quando Bonacie perder PV. Quando a marca existir, o dano de Combo causado por Aurorians de Trovão aumenta em <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_400114 = "Quando uma Habilidade Ativa causa dano, recupera o PV da equipe em <color=#00F6FF>{1}</color> do dano causado.",
  str_skill_passive_desc_410114 = "Quando uma Habilidade Ativa causa dano, recupera o PV da equipe em <color=#00F6FF>{1}</color> do dano causado.",
  str_skill_passive_desc_430114 = "Quando uma Habilidade Ativa causa dano, recupera o PV da equipe em <color=#00F6FF>{1}</color> do dano causado e aumenta o dano de Combo causado por Aurorians de Fogo em <color=#00F6FF>10%</color> nesta rodada.",
  str_skill_passive_desc_410127 = "No início de cada rodada, se há inimigos em <color=#00F6FF>2 círculos ao redor</color>, arremessa uma adaga em 1 inimigo, causando <color=#00F6FF>{1}</color> de dano e aplicando 1 acúmulo do status <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> por 2 rodadas.",
  str_skill_passive_desc_430127 = "No início de cada rodada, se há inimigos em <color=#00F6FF>2 círculos ao redor</color>, arremessa uma adaga em 1 inimigo, causando <color=#00F6FF>{1}</color> de dano e aplicando 1 acúmulo do status <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> por 2 rodadas. A adaga será ativada ao atravessar Garças de Papel.",
  str_skill_desc_3351221 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color> centrado na casa selecionada. Dano causado à casa selecionada ignora DEF. Limpa o efeito <color=#00F6FF>casa danificada</color> de casas ao alcance. Quando Bênção chegar a 10 acúmulos, o alcance da Habilidade Ativa se torna o <color=#00F6FF>limite máximo da forma radial</color>.",
  str_skill_passive_desc_410117 = "Pode acumular <link=\"30016\"><#FFAE07><u>Fúria</u></color></link>. Cada acúmulo de Fúria aumenta o ATQ Básico de Gram em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430117 = "Pode acumular <link=\"30017\"><#FFAE07><u>Fúria</u></color></link>. Cada acúmulo de Fúria aumenta o ATQ Básico de Gram em <color=#00F6FF>{1}</color>. Não há limite para quanta Fúria pode ser recebida por sua Habilidade Ativa. Esse efeito é limpo no final da onda. Para cada acúmulo limpo, Gram é curado em uma quantidade igual a <color=#00F6FF>5%</color> de seu PV Máx.",
  str_skill_passive_desc_410119 = "Pode acumular <link=\"30018\"><#FFAE07><u>Coração Intrépido</u></color></link>. Cada acúmulo de Coração Intrépido aumenta o ATQ Básico de Revy em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420119 = "Pode acumular <link=\"30018\"><#FFAE07><u>Coração Intrépido</u></color></link>. Cada acúmulo de Coração Intrépido aumenta o ATQ Básico de Revy em <color=#00F6FF>{1}</color> e o dano de Habilidade Ativa em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430119 = "Pode acumular <link=\"30018\"><#FFAE07><u>Coração Intrépido</u></color></link>. Cada acúmulo de Coração Intrépido aumenta o ATQ Básico de Revy em <color=#00F6FF>{1}</color> e o dano de Habilidade Ativa em <color=#00F6FF>5%</color>. Ataques normais <color=#00F6FF>podem acertar diagonalmente</color>.",
  str_skill_passive_desc_410122 = "Pode obter <link=\"30019\"><#FFAE07><u>Bênçãos</u></color></link>. Cada acúmulo de Bênção aumenta o dano da Habilidade Ativa de Allura em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410121 = "Ao passar por uma <link=\"20001\"><#FFAE07><u>Casa Melhorada</u></color></link>, ganha 1 acúmulo da Marca: Farpado. Cada acúmulo aumenta o dano em sequência em <color=#00F6FF>{1}</color>. Detêm 50% dos acúmulos no fim da rodada.",
  str_skill_passive_desc_430121 = "Ao passar por uma <link=\"20001\"><#FFAE07><u>Casa Melhorada</u></color></link>, ganha 1 acúmulo da Marca: Farpado. Cada acúmulo aumenta o dano do Combo em Sequência e do Ataque Normal em <color=#00F6FF>{1}</color>. Detém 50% dos acúmulos no fim da rodada.",
  str_skill_passive_desc_410065 = "Cada acerto de Combo concede 1 acúmulo de Marca: Snowpuff. Cada acúmulo aumenta a DEF em <color=#00F6FF>{1}</color>. A marca desaparece no final da rodada.",
  str_skill_passive_desc_410115 = "Ao passar por uma <link=\"20001\"><#FFAE07><u>Casa Melhorada</u></color></link>, ganha 1 acúmulo da Marca: Esmeralda. Cada acúmulo concede <color=#00F6FF>{1}</color> do ATQ básico de Naroxel. Detêm 50% dos acúmulos no fim da rodada.",
  str_skill_passive_desc_430115 = "Ao passar por uma <link=\"20001\"><#FFAE07><u>Casa Melhorada</u></color></link>, ganha 1 acúmulo da Marca: Esmeralda. Cada acúmulo concede <color=#00F6FF>{1}</color> do ATQ básico de Naroxel à equipe. Detêm 50% dos acúmulos no fim da rodada.",
  str_skill_passive_desc_410126 = "Invoca <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> na casa selecionada por sua Habilidade Ativa. Cada vez que uma unidade usa uma Habilidade Ativa, Frankel libera um <color=#00F6FF>Rugido</color>, causando <color=#00F6FF>{1}</color> de dano aos inimigos dentro de <color=#00F6FF>1 círculo ao redor</color>. Frankel também libera um <color=#00F6FF>Rugido</color> ao desaparecer.",
  str_skill_passive_desc_420126 = "Inovoca <link=\"30024\"><#FFAE07><u>Frankel</u></color></link> na casa selecionada por sua Habilidade Ativa. Cada vez que uma unidade usa uma Habilidade Ativa, Frankel libera um <color=#00F6FF>Rugido</color>, causando <color=#00F6FF>{1}</color> de dano aos inimigos dentro de <color=#00F6FF>1 círculo ao redor</color>. Se apenas um inimigo estiver dentro do alcance, libera <color=#00F6FF>Garra Cortante</color>, aumentando o dano em <color=#00F6FF>50%</color>. Frankel também libera um <color=#00F6FF>Rugido</color> ao desaparecer.",
  str_skill_passive_desc_410129 = "Habilidades Ativas e Combos em Sequência infligem 1 acúmulo de Marca: Parasita cada vez que causam dano. A Marca: Parasita acumula até <color=#00F6FF>9</color> vezes. Cada vez que um inimigo se move 1 casa, cada acúmulo da Marca causa <color=#00F6FF>{1}</color> de dano.",
  str_skill_passive_desc_420129 = "Habilidades Ativas e Combos em Sequência infligem 1 acúmulo de Marca: Parasita cada vez que causam dano. A Marca: Parasita acumula até <color=#00F6FF>9</color> vezes. Cada vez que um inimigo se move 1 casa, cada acúmulo da Marca causa <color=#00F6FF>{1}</color> de dano. Os ataques normais e Combos em Sequência de Luke causam <color=#00F6FF>30%</color> de dano aumentado ao inimigo afligido pelo maior número de acúmulos da Marca: Parasita.",
  str_skill_passive_desc_430129 = "Habilidades Ativas e Combos infligem 1 acúmulo de Marca: Parasita cada vez que causam dano. A Marca: Parasita acumula até <color=#00F6FF>9</color> vezes. Cada vez que um inimigo se move 1 casa, cada acúmulo da Marca: Parasita causa <color=#00F6FF>{1}</color> de dano. Esse dano aumenta para <color=#00F6FF>{2}</color> no inimigo com o maior número de acúmulos do campo. Os ataques normais e Combos de Luke causam <color=#00F6FF>30%</color> de dano aumentado ao inimigo afligido pelo maior número de acúmulos da Marca: Parasita.",
  str_skill_passive_desc_410055 = "Quando atacado, ganha 1 acúmulo de Marca: Batalha. Pode acumular até <color=#00F6FF>15</color> vezes. Cada acúmulo da Marca: Batalha aumenta o ATQ em <color=#00F6FF>{1}</color>. Os acúmulos diminuem em 50% a cada rodada.",
  str_skill_passive_desc_420055 = "Quando atacado, ganha 1 acúmulo de Marca: Batalha. Pode acumular até <color=#00F6FF>15</color> vezes. Cada acúmulo da Marca: Batalha aumenta o ATQ e DEF em <color=#00F6FF>{1}</color>. Os acúmulos diminuem em 50% a cada rodada.",
  str_skill_passive_desc_430055 = "Quando atacado, ganha 1 acúmulo de Marca: Batalha. Pode acumular até <color=#00F6FF>15</color> vezes. Cada acúmulo da Marca: Batalha aumenta o ATQ e DEF em <color=#00F6FF>{1}</color>. Os acúmulos diminuem em 50% a cada rodada. Para cada acúmulo perdido, ganha um escudo igual a <color=#00F6FF>12%</color> do PV Máx. de Pittman.",
  str_skill_passive_desc_410120 = "Ao usar Combos e Habil. Ativas, Pompey aparecerá em vez de Hedy e atacará. O ATQ de Pompey é igual a <color=#00F6FF>{1}</color> do ATQ de Hedy,",
  str_skill_passive_desc_430120 = "Ao usar Combos e Habil. Ativas, Pompey aparecerá em vez de Hedy e atacará. O ATQ de Pompey é igual a <color=#00F6FF>{1}</color> do ATQ de Hedy. Durante a Hora da Aurora, o ATQ de Pompey aumenta em <color=#00F6FF>2%</color> com cada conexão de casa até um máximo de <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410123 = "Para cada 1 inimigo em <color=#00F6FF>12 casas em forma de diamante</color>, o ATQ aumenta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430123 = "Para cada 1 inimigo em <color=#00F6FF>2 círculos</color>, o ATQ e DEF aumenta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_410015 = "Para cada círculo que as granadas atravessarem antes que a Habilidade Ativa cause dano, o dano final aumenta em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420015 = "Para cada círculo que as granadas atravessarem antes que a Habilidade Ativa cause dano, o dano final aumenta em <color=#00F6FF>{1}</color>. Para cada círculo que as granadas atravessarem antes que o Combo cause dano, o dano final aumenta em <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410131 = "Se a equipe não estiver com PV cheio antes de usar um ataque normal, o efeito deste ataque normal restaurará o PV igual a <color=#00F6FF>{1}</color> do ATQ de Novio.",
  str_skill_passive_desc_430131 = "Se a equipe não estiver com PV cheio antes de usar um ataque normal, o efeito deste ataque normal restaurará o PV igual a <color=#00F6FF>{1}</color> do ATQ de Novio. Se a equipe estiver com PV cheio, este ataque e seu Dano de Combo aumentarão em <color=#00F6FF>10%</color>. O bônus de dano aumentará para <color=#00F6FF>25%</color> se um escudo já existir.",
  str_skill_passive_desc_410132 = "Durante a Hora da Aurora, o ATQ é aumentado em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430132 = "Durante a Hora da Aurora, o ATQ é aumentado em <color=#00F6FF>{1}</color> e ativa o Combo ao atravessar quaisquer casas. O dano do Combo será sempre considerado do elemento Floresta.",
  str_skill_passive_desc_410133 = "Cada Combo aumenta o Dano de Combo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430133 = "Cada combo aumenta o Dano de Combo em <color=#00F6FF>{1}</color> e dano ao redor em <color=#00F6FF>{2}</color>.",
  str_skill_passive_desc_410137 = "A Habilidade Ativa causa dano em um inimigo selecionado e, para cada <color=#00F6FF>1</color> casa Azul sob os pés do inimigo, causa <color=#00F6FF>{1}</color> de dano do ATQ de Fafnir.",
  str_skill_passive_desc_430137 = "A Habilidade Ativa causa dano em um inimigo selecionado e, para cada <color=#00F6FF>1</color> casa Azul sob os pés do inimigo, causa <color=#00F6FF>{1}</color> de dano do ATQ de Fafnir. Habilidades Ativas de outros personagens da parceria com Dragon Maid também ativarão esse efeito ao acertar um inimigo.",
  str_skill_passive_desc_410134 = "Kanna ganha 3 cargas ao usar sua Habilidade Ativa e 1 carga quando qualquer Aurorian de Trovão ou personagem de Dragon Maid usar suas Habilidades Ativas, até um máximo de 10 cargas. Cada carga aumenta o ATQ básico em <color=#00F6FF>{1}</color> e será zerada após o fim da rodada.",
  str_skill_passive_desc_430134 = "Kanna ganha 3 cargas ao usar sua Habilidade Ativa e 1 carga quando qualquer Aurorian de Trovão ou personagem de Dragon Maid usar suas Habilidades Ativas, até 10 cargas. Cada carga aumenta o ATQ básico em <color=#00F6FF>{1}</color> e metade das cargas serão gastas ao final da rodada.",
  str_skill_passive_desc_416134 = "Kanna ganha 3 cargas ao usar sua Habilidade Ativa e 1 carga quando qualquer Auroriano de Trovão ou personagem de Dragon Maid usar suas Habilidades Ativas, até 10 cargas. Cada carga aumenta o ATQ básico em <color=#00F6FF>{1}</color> e será zerada após o final da rodada. Kanna ganha 2 cargas no início de cada onda.",
  str_skill_passive_desc_436134 = "Kanna ganha 3 cargas ao usar sua Habilidade Ativa e 1 carga quando qualquer Auroriano de Trovão ou personagem de Dragon Maid usa suas Habilidades Ativas, até 10 cargas. Cada carga aumenta o ATQ básico em <color=#00F6FF>{1}</color>, e metade das cargas serão gastas ao final da rodada. Kanna ganha 2 cargas no início de cada onda.",
  str_skill_passive_desc_410135 = "Aumenta o dano de Combo em <color=#00F6FF>{1}</color> com PV cheio.",
  str_skill_passive_desc_430135 = "Aumenta o dano do ataque normal, do Combo e da Habilidade Ativa em <color=#00F6FF>{1}</color> com PV cheio.",
  str_skill_passive_desc_410136 = "Quando um Combo acertar um inimigo, 1 acúmulo de Marca Letal é causado. Cada acúmulo da marca aumenta o dano recebido por esse inimigo por Habilidades Ativas de todos os Aurorians em <color=#00F6FF>{1}</color>. Acúmulo máximo de <color=#00F6FF>10</color> e duração por toda a batalha.",
  str_skill_desc_200501 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de X</color>.",
  str_skill_desc_210501 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de X</color>.",
  str_skill_desc_200221 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em formato de cruz</color> e empurra inimigos.",
  str_skill_desc_200471 = "Recupera o PV da equipe em <color=#00F6FF>160%</color> do ATQ de Zoya.",
  str_skill_desc_210471 = "Recupera o PV da equipe em <color=#00F6FF>210%</color> do ATQ de Zoya.",
  str_skill_desc_200491 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_210491 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_200511 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_200521 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_200071 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de cruz </color> <color=#00F6FF>2 vezes</color>.",
  str_skill_desc_200081 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_220081 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_200321 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de cruz</color>.",
  str_skill_desc_220321 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_200351 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de cruz</color>.",
