  str_skill_upgrade_desc_16013816 = "Aprimoramento de Habilidade de Equipamento: Ao ganhar escudo de <link=\"30025\"><#FFAE07><u>Marca da Web</u></color></link>, ganha um escudo adicional igual a <color=#00F6FF>15%</color> do HP de Siobhan se houver mais de 10 pilhas de marca.",
  str_skill_desc_300138 = "Seleciona 1 ladrilho e seleciona outro ladrilho para confirmar um intervalo de 2×2 ou 1×4 e converte os ladrilhos em verde.",
  str_skill_desc_320138 = "Seleciona 1 ladrilho e seleciona outro ladrilho para confirmar um intervalo de 2×2 ou 1×4 e converte os ladrilhos em verde. As duas ladrilhos selecionadas se tornarão <link=\"20001\"><#FFAE07><u>Ladrilhos Aprimoradas</u></color></link>.",
  str_skill_desc_330138 = "Seleciona 1 ladrilho e seleciona outro ladrilho para confirmar um intervalo de 2×2 ou 1×4 e converte os ladrilhos em verde. As duas ladrilhos selecionadas se tornarão <link=\"20001\"><#FFAE07><u>Ladrilhos Aprimoradas</u></color></link>. Durante o Tempo de Aurora, atinge 15 Combos em Cadeia para reduzir o tempo de espera da Habilidade Ativa em <color=#00F6FF>1</color> rodada.",
  str_skill_desc_2001381 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 2 inimigos mais próximos dentro <color=#00F6FF>4 aglomerados circundantes</color>.",
  str_skill_desc_2001382 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 3 inimigos mais próximos dentro <color=#00F6FF>4 círculos ao redor</color>.",
  str_skill_desc_2001383 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>4 círculos ao redor</color>.",
  str_skill_passive_desc_410138 = "Ganhos <link=\"30025\"><#FFAE07><u>Marca da Web</u></color></link>. Limpa todas as pilhas antes de receber dano e ganha escudo igual a <color=#00F6FF>{1}</color> de DEF de Siobhan para cada pilha limpa.",
  str_skill_passive_desc_416138 = "Ganhos <link=\"30025\"><#FFAE07><u>Marca da Web</u></color></link>. Limpa todas as pilhas antes de receber dano e ganha escudo igual a <color=#00F6FF>{1}</color> de DEF de Siobhan para cada pilha limpa. Se os acúmulos de Marcas da Web forem maiores que 10, ganha um escudo adicional igual a <color=#00F6FF>15%</color> do HP de Siobhan ao ganhar escudo de <link=\"30025\"><#FFAE07><u>Marca da Web</u></color></link>",
  str_skill_upgrade_desc_16014113 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16014116 = "Aprimoramento de habilidade ativa: toque no ladrilho sob seus pés para alternar as direções para knockback e conversão de ladrilhos.",
  str_skill_desc_2001411 = "Ofertas <color=#00F6FF>115%</color> dano aos 2 inimigos mais próximos. Se houver apenas 1 alvo inimigo, inflige dano duas vezes.",
  str_skill_desc_2001412 = "Ofertas <color=#00F6FF>130%</color> dano aos 2 inimigos mais próximos. Se houver apenas 1 alvo inimigo, cause dano duas vezes.",
  str_skill_desc_2001413 = "Ofertas <color=#00F6FF>150%</color> dano aos 2 inimigos mais próximos. Se houver apenas 1 alvo inimigo, cause dano duas vezes.",
  str_skill_desc_300141 = "Selecione os <color=#00F6FF>máximo em forma de cruz</color> ou <color=#00F6FF>máximo em forma de X</color> alcance, negociação <color=#00F6FF>{1}%</color> dano, repelindo o inimigo e transformando as peças dentro de seu alcance de ataque em peças azuis.",
  str_skill_desc_306141 = "Selecione os <color=#00F6FF>máximo em forma de cruz</color> ou <color=#00F6FF>máximo em forma de X</color> alcance, negociação <color=#00F6FF>{1}%</color> dano, repelindo o inimigo e transformando as peças dentro de seu alcance de ataque em peças azuis. Toque no ladrilho sob seus pés para mudar de direção para knockback e conversão de ladrilhos.",
  str_skill_desc_320141 = "Selecione os <color=#00F6FF>máximo em forma de cruz</color> ou <color=#00F6FF>máximo em forma de X</color> alcance, negociação <color=#00F6FF>{1}%</color> dano, repelindo o inimigo e transformando as peças dentro de seu alcance de ataque em peças azuis. Cause dano uma vez aos alvos inimigos que são atingidos com base no nível de sua habilidade atualmente equipada.",
  str_skill_desc_326141 = "Selecione os <color=#00F6FF>máximo em forma de cruz</color> ou <color=#00F6FF>máximo em forma de X</color> alcance, negociação <color=#00F6FF>{1}%</color> dano, repelindo o inimigo e transformando as telhas dentro de seu alcance de ataque em telhas azuis. Toque no ladrilho sob seus pés para mudar de direção para knockback e conversão de ladrilhos. Cause dano uma vez nos alvos inimigos que são atingidos com base no nível de habilidade do equipamento atual.",
  str_skill_passive_desc_410141 = "Para cada <color=#00F6FF>3</color> vezes o Chain Combo causa dano ao mesmo alvo, inflige dano extra igual a <color=#00F6FF>{1}</color> do HP atual do alvo.",
  str_skill_passive_desc_420141 = "Para cada <color=#00F6FF>3</color> vezes o Chain Combo causa dano ao mesmo alvo, inflige dano extra igual a <color=#00F6FF>{1}</color> do HP atual do alvo.",
  str_skill_passive_desc_430141 = "Para cada <color=#00F6FF>3</color> vezes o Chain Combo causa dano ao mesmo alvo, inflige dano extra igual a <color=#00F6FF>{1}</color> do HP atual do alvo, não menos que <color=#00F6FF>{2}</color> do DEF básico do Ruby.",
