  str_skill_desc_2001422 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2001423 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_300142 = "Escolha 1 dos <color=#00F6FF>13 telhas em forma de diamante</color>, tratativa <color=#00F6FF>{1}%</color> danos ao ladrilho selecionado e sua <color=#00F6FF>2 aglomerados circundantes</color> e forçando os <color=#00F6FF>não-chefe</color> inimigos dentro do alcance a se moverem <color=#00F6FF>2</color> ladrilhos em direção ao ladrilho selecionado. O dano é reduzido em 53% por cluster.",
  str_skill_desc_302142 = "Escolha 1 dos <color=#00F6FF>13 telhas em forma de diamante</color>, tratativa <color=#00F6FF>{1}%</color> danos ao ladrilho selecionado e sua <color=#00F6FF>2 aglomerados circundantes</color> e forçando os inimigos dentro do alcance a se moverem <color=#00F6FF>2</color> ladrilhos em direção ao ladrilho selecionado. O dano é reduzido em 53% por cluster.",
  str_skill_desc_320142 = "Escolha 1 dos <color=#00F6FF>13 telhas em forma de diamante</color>, tratativa <color=#00F6FF>{1}%</color> danos ao ladrilho selecionado e sua <color=#00F6FF>3 aglomerados circundantes</color> e forçando os <color=#00F6FF>não-chefe</color> inimigos dentro do alcance a se moverem <color=#00F6FF>2</color> ladrilhos em direção ao ladrilho selecionado. O dano é reduzido em 53% por cluster.",
  str_skill_desc_322142 = "Escolha 1 dos <color=#00F6FF>13 telhas em forma de diamante</color>, tratativa <color=#00F6FF>{1}%</color> danos ao ladrilho selecionado e sua <color=#00F6FF>3 aglomerados circundantes</color> e forçando os inimigos dentro do alcance a se moverem <color=#00F6FF>2</color> ladrilhos em direção ao ladrilho selecionado. O dano é reduzido em 53% por cluster.",
  str_skill_passive_desc_410142 = "Para cada <color=#00F6FF>3º</color> ataque normal, a porcentagem atual de HP do alvo aumenta o dano de ataque normal. Se o alvo estiver em seu HP máximo, o dano aumenta o limite de <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420142 = "Para cada <color=#00F6FF>3º</color> e <color=#00F6FF>5 ª</color> ataque normal, a porcentagem atual de HP do alvo aumenta o dano de ataque normal. Se o alvo estiver em seu HP máximo, o dano aumenta o limite de <color=#00F6FF>{1}</color>.",
