  str_skill_desc_2001401 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2001402 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_2001403 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_300140 = "Depois de usar, Thunder Aurorians liberarão seu Chain Combo <color=#00F6FF>duas vezes</color> durante esta rodada. Para o <color=#00F6FF>segundo</color> lançamento, todos os ATK dos Thunder Aurorians são <color=#00F6FF>80%</color> de Florine.",
  str_skill_desc_306140 = "Depois de usar, Thunder Aurorians liberarão seu Chain Combo <color=#00F6FF>duas vezes</color> durante esta rodada. Para o <color=#00F6FF>segundo</color> lançamento, todos os ATK dos Thunder Aurorians são <color=#00F6FF>80%</color> de Florine.",
  str_skill_desc_320140 = "Depois de usar, Thunder Aurorians liberarão seu Chain Combo <color=#00F6FF>duas vezes</color> durante esta rodada. Para o <color=#00F6FF>segundo</color> lançamento, todos os ATK dos Thunder Aurorians são <color=#00F6FF>80%</color> de Florine. Ao mesmo tempo, o número de peças necessárias para ativar o Thunder Aurorian Chain Combo é <color=#00F6FF>-1</color>.",
  str_skill_desc_326140 = "Depois de usar, Thunder Aurorians liberarão seu Chain Combo <color=#00F6FF>duas vezes</color> durante esta rodada. Para o <color=#00F6FF>segundo</color> lançamento, todos os ATK dos Thunder Aurorians são <color=#00F6FF>80%</color> de Florine. Ao mesmo tempo, o número de peças necessárias para ativar o Thunder Aurorian Chain Combo é <color=#00F6FF>-1</color>.",
  str_skill_desc_330140 = "Depois de usar, Thunder Aurorians liberarão seu Chain Combo <color=#00F6FF>duas vezes</color> durante esta rodada. Para o <color=#00F6FF>segundo</color> lançamento, todos os ATK dos Thunder Aurorians são <color=#00F6FF>95%</color> de Florine. Ao mesmo tempo, o número de peças necessárias para ativar o Thunder Aurorian Chain Combo é <color=#00F6FF>-1</color>.",
  str_skill_desc_336140 = "Depois de usar, Thunder Aurorians liberarão seu Chain Combo <color=#00F6FF>duas vezes</color> durante esta rodada. Para o <color=#00F6FF>segundo</color> lançamento, todos os ATK dos Thunder Aurorians são <color=#00F6FF>95%</color> de Florine. Ao mesmo tempo, o número de peças necessárias para ativar o Thunder Aurorian Chain Combo é <color=#00F6FF>-1</color>.",
  str_skill_passive_desc_410140 = "O dano de todos os Combos em Cadeia dos Aurorianos do Trovão de diferentes níveis são respectivamente aumentados em <color=#00F6FF>{1}</color>/<color=#00F6FF>{2}</color>/<color=#00F6FF>{3}</color>.",
  str_skill_name_200150110 = "Fantasma - Rip",
  str_skill_desc_200150110 = "Corta com suas garras afiadas em alvos dentro do alcance.",
  str_skill_name_290200101 = "Sombra Nobutora",
  str_skill_desc_290200101 = "Quando o inimigo está dentro de 2 aglomerados ao redor, se teletransporta para um local a 6 quadrados de distância do inimigo e deixa um Shadow Nobutora para trás.",
  str_skill_name_290200102 = "Contra-Ataque",
  str_skill_desc_290200102 = "Quando não há inimigos dentro de 2 aglomerados ao redor, causa ataques à distância aos inimigos dentro do alcance e atrapalha a ordem da equipe auroriana.",
  str_skill_name_290200112 = "Contra-Ataque",
  str_skill_desc_290200112 = "Quando não há inimigos dentro de 2 aglomerados ao redor, causa ataques à distância aos inimigos dentro do alcance e atrapalha a ordem da equipe auroriana. O dano aumenta com a distância entre Fujikumo Nobutora e os inimigos.",
  str_skill_name_290200201 = "Golpe Sombrio",
  str_skill_desc_290200201 = "Shadow Nobutora ataca alvos dentro do alcance.",
  str_skill_upgrade_desc_16014313 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16014316 = "Aprimoramento de Habilidade de Equipamento: Mudanças de Capitão nesta rodada: <color=#FFFF00>+1</color>.",
  str_skill_desc_2001431 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_2001432 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_desc_2001433 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>4 círculos ao redor</color>.",
  str_skill_desc_300143 = "Invoca uma barreira que cobre <color=#00F6FF>2 aglomerados circundantes</color> em torno de si por 2 rodadas. Ao invocar ou quando a rodada termina, converte <color=#00F6FF>3</color> telhas não vermelhas aleatórias dentro da barreira para vermelho e <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas as peças vermelhas dentro do alcance.",
  str_skill_desc_306143 = "Invoca uma barreira que cobre <color=#00F6FF>2 aglomerados circundantes</color> em torno de si por 2 rodadas. Ao invocar ou quando a rodada termina, converte <color=#00F6FF>3</color> telhas não vermelhas aleatórias dentro da barreira para vermelho e <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas as peças vermelhas dentro do alcance.",
  str_skill_desc_330143 = "Invoca uma barreira que cobre <color=#00F6FF>2 aglomerados circundantes</color> em torno de si por 2 rodadas. Ao convocar ou quando a rodada termina, converte <color=#00F6FF>3</color> telhas não vermelhas aleatórias dentro da barreira para o vermelho, e <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas as peças vermelhas dentro do alcance. Quando cercado pela barreira, a DEF de Rinne é aumentada em <color=#00F6FF>50%</color>, enquanto a DEF de outros companheiros Aurorianos de fogo é aumentada em <color=#00F6FF>10%</color>.",
  str_skill_desc_336143 = "Invoca uma barreira que cobre <color=#00F6FF>2 aglomerados circundantes</color> em torno de si por 2 rodadas. Ao invocar ou quando a rodada termina, converte <color=#00F6FF>3</color> telhas não vermelhas aleatórias dentro da barreira para o vermelho, e <link=\"30020\"><#FFAE07><u>Purificar</u></color></link> todas as peças vermelhas dentro do alcance. Quando cercado pela barreira, a DEF de Rinne é aumentada em <color=#00F6FF>50%</color>, enquanto a DEF de outros companheiros Aurorianos de fogo é aumentada em <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_410143 = "Quando Rinne se torna a capitã, ela recupera HP igual a <color=#00F6FF>{1}</color> de sua DEF atual. Aciona até <color=#00F6FF>1</color> tempo por rodada.",
  str_skill_passive_desc_416143 = "Quando Rinne se torna a capitã, ela recupera HP igual a <color=#00F6FF>{1}</color> de sua DEF atual. Aciona até <color=#00F6FF>1</color> tempo por rodada. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_420143 = "Quando Rinne se torna a capitã, ela recupera HP igual a <color=#00F6FF>{1}</color> de sua DEF atual. Se o HP dela estiver cheio depois de acionado, o ladrilho azul mais próximo será convertido em vermelho. Aciona até <color=#00F6FF>1</color> tempo por rodada.",
  str_skill_passive_desc_426143 = "Quando Rinne se torna a capitã, ela recupera HP igual a <color=#00F6FF>{1}</color> de sua DEF atual. Se o HP dela estiver cheio depois de acionado, o ladrilho azul mais próximo será convertido em vermelho. Aciona até <color=#00F6FF>1</color> tempo por rodada. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_name_2001431 = "Exorcismo",
  str_skill_name_2001432 = "Exorcismo",
  str_skill_name_2001433 = "Exorcismo",
