  str_skill_passive_name_420143 = "Dançarino líder",
  str_skill_upgrade_desc_15014412 = "Aprimoramento de Habilidade Ativa: Troque de posição com qualquer companheiro de equipe.",
  str_skill_upgrade_desc_15014415 = "Aprimoramento de Habilidade de Equipamento: Mudanças de Capitão nesta rodada: <color=#FFFF00>+1</color>.",
  str_skill_desc_2001441 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2001442 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próx.",
  str_skill_desc_2001443 = "Causa <color=#00F6FF>{1}%</color> de dano aos 4 inimigos mais próx.",
  str_skill_desc_300144 = "Troque de posição com o capitão atual.",
  str_skill_desc_302144 = "Troque de posição com um companheiro de equipe selecionado.",
  str_skill_desc_305144 = "Troque de posição com um companheiro de equipe selecionado. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_desc_310144 = "Troque de posição com o capitão atual.",
  str_skill_desc_312144 = "Troque de posição com um companheiro de equipe selecionado.",
  str_skill_desc_315144 = "Troque de posição com um companheiro de equipe selecionado. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_410144 = "Quando Kayano perceber que não está na parte de trás, ela será forçada a recuar para a parte de trás do time enquanto o resto do time avança 1 ladrilho. Aurorianos <color=#00F6FF>que se retiraram</color> esta rodada receberá um bônus de ATK igual a <color=#00F6FF>{1}</color> do ATK básico de Kayano (o bônus mais alto é obtido quando acionado várias vezes).",
  str_skill_passive_desc_420144 = "Quando Kayano perceber que não está na parte de trás, ela será forçada a recuar para a parte de trás da equipe enquanto o resto da equipe avança 1 ladrilho. Aurorianos <color=#00F6FF>que se retiraram</color> esta rodada receberá um bônus de ATK igual a <color=#00F6FF>{1}</color> do ATK básico de Kayano (o bônus mais alto é obtido quando acionado várias vezes). Quanto mais recuar, maior será o bônus, até 2.5 vezes o valor básico.",
  str_skill_passive_desc_430144 = "Quando Kayano perceber que não está na parte de trás, ela será forçada a recuar para a parte de trás da equipe enquanto o resto da equipe avança 1 ladrilho. Aurorianos <color=#00F6FF>que se retiraram</color> esta rodada receberá um bônus de ATK igual a <color=#00F6FF>{1}</color> do ATK básico de Kayano (o bônus mais alto é obtido quando acionado várias vezes). Quanto mais recuar, maior será o bônus, até 2.5 vezes o valor básico. O capitão atual recebe o mesmo bônus de ATK que Kayano.",
  str_skill_passive_desc_415144 = "Quando Kayano perceber que não está na parte de trás, ela será forçada a recuar para a parte de trás do time enquanto o resto do time avança 1 ladrilho. Aurorianos <color=#00F6FF>que se retiraram</color> esta rodada receberá um bônus de ATK igual a <color=#00F6FF>{1}</color> do ATK básico de Kayano (o bônus mais alto é obtido quando acionado várias vezes). Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_425144 = "Quando Kayano perceber que não está na parte de trás, ela será forçada a recuar para a parte de trás do time enquanto o resto do time avança 1 ladrilho. Aurorianos <color=#00F6FF>que se retiraram</color> esta rodada receberá um bônus de ATK igual a <color=#00F6FF>{1}</color> do ATK básico de Kayano (o bônus mais alto é obtido quando acionado várias vezes). Quanto mais recuar, maior será o bônus, até 2.5 vezes o valor básico. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_435144 = "Quando Kayano perceber que não está na parte de trás, ela será forçada a recuar para a parte de trás da equipe enquanto o resto da equipe avança 1 ladrilho. Aurorianos <color=#00F6FF>que se retiraram</color> esta rodada receberá um bônus de ATK igual a <color=#00F6FF>{1}</color> do ATK básico de Kayano (o bônus mais alto é obtido quando acionado várias vezes). Quanto mais recuar, maior será o bônus, até 2.5 vezes o valor básico. O capitão atual recebe o mesmo bônus de ATK que Kayano. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
