  str_skill_passive_name_435144 = "Andarilho Sombrio",
  str_skill_name_290190110 = "Espada do Submundo - Assalto",
  str_skill_desc_290190110 = "Carrega em direção aos jogadores, causa uma enorme quantidade de dano e joga o Capitão para trás da equipe. Se os jogadores não estiverem em uma área em forma de cruz e longe, ela usará ataques à distância.",
  str_skill_name_290190120 = "Espada do Submundo - Ataque",
  str_skill_desc_290190120 = "Corta os jogadores ao lado dela e causa uma enorme quantidade de dano. Se os jogadores não estiverem em uma área em forma de cruz e longe, ela usará ataques à distância.",
  str_skill_desc_490190120 = "Depois de correr, corta os inimigos adjacentes, causando uma enorme quantidade de dano.",
  str_skill_name_290190130 = "Espada do Submundo - Hack",
  str_skill_desc_290190130 = "Depois de se mover em direção ao centro do Tabuleiro de Alquimia, ela saca sua arma e causa dano aos jogadores que não estão em uma área em forma de cruz e distantes.",
  str_skill_desc_490190130 = "Mira e atira, causando dano à distância a inimigos fora do alcance do ataque de corte.",
  str_skill_name_290191110 = "Nagi - Barra dupla",
  str_skill_desc_290191110 = "Quando os jogadores estão ao lado dela, ela ataca com uma barra horizontal e um impulso para frente.",
  str_skill_name_290191120 = "Nagi - Ataque de carga",
  str_skill_desc_290191120 = "Quando os jogadores estiverem longe, ela irá em direção a eles para causar dano.",
  str_skill_name_290191130 = "Nagi - Ataque Explosivo",
  str_skill_desc_290191130 = "Ela pisca para o centro do campo de batalha e causa uma enorme quantidade de dano ao seu redor. Se atingido, o capitão será jogado para trás da equipe.",
  str_skill_name_290210101 = "Devorar - Saudável",
  str_skill_desc_290210101 = "Quando o alvo está dentro do alcance, Aurorianos e fantasmas dentro de dois grupos à frente são devorados. Os Aurorianos são então cuspidos para a borda do tabuleiro e o Capitão é amaldiçoado, forçando o Capitão a recuar para a parte de trás da equipe.",
  str_skill_desc_291210101 = "Quando o alvo está dentro do alcance, Aurorianos e fantasmas dentro de dois aglomerados na direção à frente são devorados. Os Aurorianos sofrem danos e são cuspidos para a borda do tabuleiro, e o Capitão é forçado a recuar para a parte de trás da equipe.",
  str_skill_name_290210102 = "Devorar - Obliterar",
  str_skill_desc_290210102 = "Quando o alvo está dentro do alcance, causa uma enorme quantidade de dano a ele. A ordem da equipe auroriana fica confusa e os monstros ao redor são eliminados instantaneamente.",
  str_skill_name_290210201 = "Devorar - Exército Fantasma",
  str_skill_desc_290210201 = "Quando o alvo está dentro do alcance, um grande número de fantasmas é convocado e todos os fantasmas no campo de batalha são aprimorados.",
  str_skill_desc_291210201 = "Quando o alvo está dentro do alcance, um grande número de fantasmas é convocado e todos os fantasmas no campo de batalha são aprimorados e curados.",
  str_skill_name_290210301 = "Devorar - Saudável",
  str_skill_desc_290210301 = "Quando o alvo está dentro do alcance, Aurorianos e fantasmas dentro de dois grupos à frente são devorados, causando dano verdadeiro aos Aurorianos. Quanto mais fantasmas devorassem, maior o dano causado. Os Aurorianos são então cuspidos para a borda do tabuleiro e o Capitão é amaldiçoado, forçando o Capitão a recuar para a parte de trás da equipe.",
  str_skill_name_290042201 = "Ruptura do Dragão Maligno",
  str_skill_desc_290042201 = "Hakudoma abre o espaço à sua frente, causando dano aos alvos dentro da área de ataque.",
  str_skill_name_290042211 = "Ruptura do Dragão Maligno",
  str_skill_desc_290042211 = "Hakudoma abre o espaço à sua frente, causando dano aos alvos dentro da área de ataque e esmagando algumas das peças no campo de batalha.",
  str_skill_name_290042202 = "Reencarnação de Hakudoma",
  str_skill_desc_290042202 = "Para aumentar a força para a maré alta, Hakudoma bate as asas, derrubando o alvo na borda do tabuleiro e convoca Spikepest para o campo de batalha.",
  str_skill_name_290042204 = "Apóstolo da maré alta",
  str_skill_desc_290042204 = "Hakudoma voa para frente, empurrando todas as peças para cima por 4 peças, e bombardeia uma área fixa depois.",
  str_skill_name_290042214 = "Apóstolo da maré alta",
  str_skill_desc_290042214 = "Hakudoma voa e bombardeia uma área fixa. O alvo é arremessado para a borda do tabuleiro, independentemente de ter sido atingido. Quando Hakudoma pousa, ele invoca Spikepests na sua frente.",
  str_skill_upgrade_desc_16014513 = "Aprimoramento de Habilidade Ativa: Ganho <color=#FFFF00>1</color> ponto de Ninja Power no início de cada onda.",
  str_skill_upgrade_desc_16014516 = "Aprimoramento de Habilidade de Equipamento: Mudanças de Capitão nesta rodada: <color=#FFFF00>+1</color>.",
  str_skill_name_2001451 = "Implacável",
  str_skill_name_2001452 = "Implacável",
  str_skill_name_2001453 = "Implacável",
  str_skill_desc_2001451 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de cruz</color>.",
  str_skill_desc_2001452 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>12 telhas em forma de diamante</color> e convocação <color=#00F6FF>1</color> katana em um bloco transversal aleatório.",
  str_skill_desc_2001453 = "Ofertas <color=#00F6FF>{1}%</color> dano em <color=#00F6FF>1 aglomerado ao redor</color> e um <color=#00F6FF>forma cruzada para o alcance máximo</color> e invoca 1 katana cada <color=#00F6FF>2</color> ladrilhos transitáveis aleatórios dentro da área afetada.",
