  str_skill_name_3331454 = "Traço de sombra",
  str_skill_desc_300145 = "Consumir <color=#00F6FF>2</color> pontos de <link=\"30028\"><#FFAE07><u>Poder Ninja</u></color></link> e escolha <color=#00F6FF>1</color> tile atravessável para invocar 1 katana. Se uma katana já existir no bloco selecionado, Amemori se teletransportará para o bloco imediatamente e recuperará a katana, ganhando <color=#00F6FF>1</color> ponto de <link=\"30028\"><#FFAE07><u>Poder Ninja</u></color></link>.",
  str_skill_desc_330145 = "Consumir <color=#00F6FF>2</color> pontos de <link=\"30028\"><#FFAE07><u>Poder Ninja</u></color></link> e escolha <color=#00F6FF>1</color> tile atravessável para invocar 1 katana. Se uma katana já existir no bloco selecionado, Amemori se teletransportará para o bloco imediatamente e recuperará a katana, ganhando <color=#00F6FF>1</color> ponto de <link=\"30028\"><#FFAE07><u>Poder Ninja</u></color></link>.",
  str_skill_desc_303145 = "Consumir <color=#00F6FF>2</color> pontos de <link=\"30029\"><#FFAE07><u>Poder Ninja</u></color></link> e escolha <color=#00F6FF>1</color> tile atravessável para invocar 1 katana. Se uma katana já existir no bloco selecionado, Amemori se teletransportará para o bloco imediatamente e recuperará a katana, ganhando <color=#00F6FF>1</color> ponto de <link=\"30029\"><#FFAE07><u>Poder Ninja</u></color></link>.",
  str_skill_desc_333145 = "Consumir <color=#00F6FF>2</color> pontos de <link=\"30029\"><#FFAE07><u>Poder Ninja</u></color></link> e escolha <color=#00F6FF>1</color> tile atravessável para invocar 1 katana. Se uma katana já existir no bloco selecionado, Amemori se teletransportará para o bloco imediatamente e recuperará a katana, ganhando <color=#00F6FF>1</color> ponto de <link=\"30029\"><#FFAE07><u>Poder Ninja</u></color></link>.",
  str_skill_passive_name_410145 = "Golpe de Katana",
  str_skill_passive_name_413145 = "Golpe de Katana",
