  str_skill_passive_name_423145 = "Golpe de Katana",
  str_skill_passive_name_426145 = "Golpe de Katana",
  str_skill_passive_name_430145 = "Golpe de Katana",
  str_skill_passive_name_433145 = "Golpe de Katana",
  str_skill_passive_name_436145 = "Golpe de Katana",
  str_skill_passive_desc_410145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, cada katana <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Quanto maior a distância, menor o dano (mínimo de 20% de dano original).",
  str_skill_passive_desc_413145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, cada katana <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Quanto maior a distância, menor o dano (mínimo de 20% de dano original).",
  str_skill_passive_desc_416145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, todas as katanas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Quanto maior a distância, menor o dano (mínimo de 20% de dano original). Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_420145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, todas as katanas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Se pelo menos <color=#00F6FF>4</color> katanas são recuperadas, <color=#00F6FF>1</color> katana será convocada novamente.",
  str_skill_passive_desc_423145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, todas as katanas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Se pelo menos <color=#00F6FF>4</color> katanas são recuperadas, <color=#00F6FF>1</color> katana será convocada novamente.",
  str_skill_passive_desc_426145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, todas as katanas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Se pelo menos <color=#00F6FF>4</color> katanas são recuperadas, <color=#00F6FF>1</color> katana será convocada novamente. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_430145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, todas as katanas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Se pelo menos <color=#00F6FF>4</color> katanas são recuperadas, <color=#00F6FF>1</color> katana será convocada novamente. Quando Amemori se torna a Capitã, ela ganha <color=#00F6FF>1</color> <link=\"30028\"><#FFAE07><u>Poder Ninja</u></color></link>. Aciona até <color=#00F6FF>3</color> vezes por rodada.",
  str_skill_passive_desc_433145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, todas as katanas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Se pelo menos <color=#00F6FF>4</color> katanas são recuperadas, <color=#00F6FF>1</color> katana será convocada novamente. Quando Amemori se torna a Capitã, ela ganha <color=#00F6FF>1</color> <link=\"30029\"><#FFAE07><u>Poder Ninja</u></color></link>. Aciona até <color=#00F6FF>3</color> vezes por rodada.",
  str_skill_passive_desc_436145 = "Depois de recuperar todas as katanas usando a Habilidade Ativa—Teleporte, todas as katanas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> inimigo mais próximo enquanto ignora sua DEF. Se pelo menos <color=#00F6FF>4</color> katanas são recuperadas, <color=#00F6FF>1</color> katana será convocada novamente. Quando Amemori se torna a Capitã, ela ganha <color=#00F6FF>1</color> <link=\"30029\"><#FFAE07><u>Poder Ninja</u></color></link>. Aciona até <color=#00F6FF>3</color> vezes por rodada. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_upgrade_desc_16014613 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16014616 = "Aprimoramento de Habilidade de Equipamento: Mudanças de Capitão nesta rodada: <color=#FFFF00>+1</color>.",
