  str_skill_desc_2001462 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>16 telhas em forma radial</color> e <color=#00F6FF>2×</color> dano a 4 telhas ao redor.",
  str_skill_desc_2001463 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>24 telhas em forma radial</color> e <color=#00F6FF>2×</color> dano a 4 telhas ao redor.",
  str_skill_name_300146 = "enviado do céu",
  str_skill_name_303146 = "enviado do céu",
  str_skill_name_320146 = "enviado do céu",
  str_skill_name_323146 = "enviado do céu",
  str_skill_name_330146 = "enviado do céu",
  str_skill_name_333146 = "enviado do céu",
  str_skill_desc_300146 = "Troque de posição com o capitão atual e o Chain Combo desta rodada causa 2x de dano a <color=#00F6FF>4 peças adjacentes</color>. Quando a rodada terminar, troque de posição com o auroriano no final da equipe.",
  str_skill_desc_303146 = "Troque de posição com o capitão atual e o Chain Combo desta rodada causa 2x de dano a <color=#00F6FF>4 peças adjacentes</color>. Quando a rodada terminar, troque de posição com o auroriano no final da equipe.",
  str_skill_desc_320146 = "Troque de posição com o capitão atual, ganhe 1 pilha de <link=\"30026\"><#FFAE07><u>Marca Heroica</u></color></link>, e aumentar o Chain Combo desta rodada causa 2x de dano a <color=#00F6FF>4 peças adjacentes</color>. Quando a rodada terminar, troque de posição com o auroriano no final da equipe.",
  str_skill_desc_323146 = "Troque de posição com o capitão atual, ganhe 1 pilha de <link=\"30026\"><#FFAE07><u>Marca Heroica</u></color></link>, e aumentar o Chain Combo desta rodada causa 2x de dano a <color=#00F6FF>4 peças adjacentes</color>. Quando a rodada terminar, troque de posição com o auroriano no final da equipe.",
  str_skill_desc_330146 = "Troque de posição com o capitão atual, ganhe 1 pilha de <link=\"30026\"><#FFAE07><u>Marca Heroica</u></color></link>, e aumentar o Chain Combo desta rodada causa 2x de dano a <color=#00F6FF>4 peças adjacentes</color>. Quando a rodada terminar, troque de posição com o auroriano no final da equipe.",
  str_skill_desc_333146 = "Troque de posição com o capitão atual, ganhe 1 pilha de <link=\"30026\"><#FFAE07><u>Marca Heroica</u></color></link>, e aumentar o Chain Combo desta rodada causa 2x de dano a <color=#00F6FF>4 peças adjacentes</color>. Quando a rodada terminar, troque de posição com o auroriano no final da equipe.",
  str_skill_passive_name_410146 = "Caminho cruzado",
  str_skill_passive_name_416146 = "Caminho cruzado",
  str_skill_passive_name_430146 = "Caminho cruzado",
  str_skill_passive_name_436146 = "Caminho cruzado",
  str_skill_passive_desc_410146 = "Ganhos <link=\"30026\"><#FFAE07><u>Marca Heroica</u></color></link>. Se Yao já é ou se torna Capitão nesta rodada, cada pilha de Marca Heroica aumenta o ATK base de Yao em <color=#00F6FF>{1}</color>. Bônus e stacks são liberados no final da rodada.",
  str_skill_passive_desc_416146 = "Ganhos <link=\"30026\"><#FFAE07><u>Marca Heroica</u></color></link>. Se Yao já é ou se torna Capitão nesta rodada, cada pilha de Marca Heroica aumenta o ATK base de Yao em <color=#00F6FF>{1}</color>. Bônus e stacks são liberados no final da rodada. <color=#00F6FF>+1</color> Capitão Altera esta batalha.",
  str_skill_passive_desc_430146 = "Ganhos <link=\"30027\"><#FFAE07><u>Marca Heroica</u></color></link>. Se Yao já é ou se torna Capitão nesta rodada, cada pilha de Marca Heroica aumenta o ATK base de Yao em <color=#00F6FF>{1}</color>. Bônus e stacks são liberados no final da rodada. Toda vez que Yao assumir a posição de Capitão, ganhe <color=#00F6FF>1</color> Pilha de <link=\"30027\"><#FFAE07><u>Marca Heroica</u></color></link>.",
  str_skill_passive_desc_436146 = "Ganhos <link=\"30027\"><#FFAE07><u>Marca Heroica</u></color></link>. Se Yao já for Capitão ou mudar para esta rodada, cada pilha de Marca Heroica aumenta o ATK base de Yao em <color=#00F6FF>{1}</color>. Bônus e stacks são liberados no final da rodada. Toda vez que Yao assumir a posição de Capitão, ganhe <color=#00F6FF>1</color> Pilha de <link=\"30027\"><#FFAE07><u>Marca Heroica</u></color></link>. <color=#00F6FF>+1</color> Capitão mudança nesta batalha.",
  str_skill_upgrade_desc_15014712 = "Aprimoramento de Habilidade Ativa: Reduz o tempo de espera da habilidade em <color=#FFFF00>1</color> rodada ao ocupar uma posição de capitão. Aciona até <color=#00F6FF>3</color> vezes por rodada.",
  str_skill_upgrade_desc_15014715 = "Aprimoramento de Habilidade de Equipamento: Mudanças de Capitão nesta rodada: <color=#FFFF00>+1</color>.",
  str_skill_desc_2001471 = "Ofertas <color=#00F6FF>150%</color> dano 2 vezes. Atribui o dano aleatoriamente aos inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Quando um alvo sofre dano mais de uma vez, o dano do segundo acerto é reduzido pela metade.",
  str_skill_desc_2001472 = "Causa <color=#00F6FF>160%</color> de dano 3 vezes, atribuindo aleatoriamente a inimigos em <color=#00F6FF>3 círculos ao redor</color> desta unidade. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2001473 = "Acordo <color=#00F6FF>160%</color> dano 4 vezes a unidades inimigas aleatórias dentro <color=#00F6FF>3 aglomerados circundantes</color> deste rodízio. Se um alvo sofrer dano mais de uma vez, o dano pela segunda vez e depois é reduzido pela metade.",
  str_skill_desc_300147 = "Ofertas <color=#00F6FF>{1}%</color> dano <color=#00F6FF>8</color> vezes para 1 azulejo aleatório dentro <color=#00F6FF>3 aglomerados circundantes</color>.",
  str_skill_desc_302147 = "Ofertas <color=#00F6FF>{1}%</color> dano <color=#00F6FF>8</color> vezes para 1 azulejo aleatório dentro <color=#00F6FF>3 aglomerados circundantes</color>. Reduz o tempo de espera da habilidade em <color=#FFFF00>1</color> rodada ao ocupar uma posição de capitão. Aciona até <color=#00F6FF>3</color> vezes por rodada.",
  str_skill_desc_320147 = "Ofertas <color=#00F6FF>{1}%</color> dano <color=#00F6FF>8</color> vezes para 1 azulejo aleatório dentro <color=#00F6FF>3 aglomerados circundantes</color>, em seguida, trata de um adicional <color=#00F6FF>188%</color> dano aos inimigos no mesmo ladrilho e <color=#00F6FF>1 aglomerado circundante</color>.",
  str_skill_desc_322147 = "Ofertas <color=#00F6FF>{1}%</color> dano <color=#00F6FF>8</color> vezes para 1 azulejo aleatório dentro <color=#00F6FF>3 aglomerados circundantes</color>, em seguida, trata de um adicional <color=#00F6FF>188%</color> dano aos inimigos no mesmo ladrilho e <color=#00F6FF>1 aglomerado ao redor</color>. Reduz o tempo de espera da habilidade em <color=#FFFF00>1</color> rodada ao ocupar uma posição de capitão. Aciona até <color=#00F6FF>3</color> vezes por rodada.",
  str_skill_passive_desc_410147 = "No início de cada rodada, Momo e Anzu se tornarão o capitão automaticamente enquanto o resto da equipe recua 1 posição. Cada vez que Momo e Anzu se tornam o Capitão, um <link=\"30030\"><#FFAE07><u>Cozinha especial Kaniya</u></color></link> será obtido com um <color=#00F6FF>{1}</color> chance para um <color=#00F6FF>um adicional</color>.",
  str_skill_passive_desc_415147 = "No início de cada rodada, Momo e Anzu se tornarão o capitão automaticamente enquanto o resto da equipe recua 1 posição. Cada vez que Momo e Anzu se tornam o Capitão, um <link=\"30030\"><#FFAE07><u>Cozinha especial Kaniya</u></color></link> será obtido com um <color=#00F6FF>{1}</color> chance para um <color=#00F6FF>um adicional</color>. Mudanças de Capitão nesta rodada: <color=#00F6FF>+1</color>.",
  str_skill_passive_desc_430147 = "No início de cada rodada, Momo e Anzu se tornarão o capitão automaticamente, enquanto o resto da equipe recua 1 posição. Cada vez que Momo e Anzu se tornam o Capitão, uma <link=\"30030\"><#FFAE07><u>Special Kaniya Cuisine</u></color></link> será obtida com um <color=#00F6FF> {1}</color> chance de <color=#00F6FF>ganhar mais um</color>!",
  str_skill_passive_desc_435147 = "No início de cada rodada, Momo e Anzu se tornarão o capitão automaticamente, enquanto o resto da equipe recua 1 posição. Cada vez que Momo e Anzu se tornam o Capitão, uma <link=\"30030\"><#FFAE07><u>Special Kaniya Cuisine</u></color></link> será obtida com um <color=#00F6FF> {1}</color> chance de <color=#00F6FF>ganhar mais um</color>! Mudanças de capitão para a batalha: <color=#00F6FF>+1</color>.",
