  str_skill_desc_2001511 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>15%</color>.",
  str_skill_desc_2001512 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>10%</color>.",
  str_skill_desc_2001513 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>5%</color>.",
  str_skill_desc_23015101 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>15%</color>.",
  str_skill_desc_23015102 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>10%</color>.",
  str_skill_desc_23015103 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>5%</color>.",
  str_skill_desc_23015161 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25|0</color>, causa dano adicional 1|2|3 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>15%</color>.",
  str_skill_desc_23015162 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25|0</color>, causa dano adicional 1|2|3 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>10%</color>.",
  str_skill_desc_23015163 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25|0</color>, causa um dano adicional de 1|2|3. Reduz o Dano Final a cada vez em <color=#00F6FF>5%</color>.",
  str_skill_desc_2301511 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>15%</color>.",
  str_skill_desc_2301512 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>10%</color>.",
  str_skill_desc_2301513 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>5%</color>.",
  str_skill_desc_2301514 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>15%</color>.",
  str_skill_desc_2301515 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>10%</color>.",
  str_skill_desc_2301516 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25</color>, ele causa dano adicional 1|2 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>5%</color>.",
  str_skill_desc_2301517 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25|0</color>, causa dano adicional 1|2|3 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>15%</color>.",
  str_skill_desc_2301518 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25|0</color>, causa dano adicional 1|2|3 vezes. Reduz o Dano Final a cada vez em <color=#00F6FF>10%</color>.",
  str_skill_desc_2301519 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo com a menor porcentagem de HP 2 vezes. Quando o ponto de Sanidade está abaixo <color=#00F6FF>60|25|0</color>, causa um dano adicional de 1|2|3. Reduz o Dano Final a cada vez em <color=#00F6FF>5%</color>.",
  str_skill_desc_300151 = "Giles se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Usos <color=#00F6FF>15</color> pontos de sanidade para lidar <color=#00F6FF>{1}%</color> DMG para inimigos nas 4 peças adjacentes em um <color=#00F6FF>forma de cruz</color> cerca de 1 azulejo escolhido. Causa 2x de dano se a peça do lançador for selecionada.",
  str_skill_desc_3001510 = "Giles se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Usos <color=#00F6FF>15</color> pontos de sanidade para lidar <color=#00F6FF>{1}%</color> DMG para inimigos nas 4 peças adjacentes em um <color=#00F6FF>forma de cruz</color> cerca de 1 azulejo escolhido. Causa 2x de dano se a peça do lançador for selecionada. Após uma habilidade ativa matar um alvo, ela pode ser usada novamente para causar 2x de dano final ao custo de 2x pontos de sanidade.",
  str_skill_desc_3001511 = "Giles se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Usos <color=#00F6FF>30</color> pontos de sanidade para lidar <color=#00F6FF>{1}%</color> DMG para inimigos nas 4 peças adjacentes em um <color=#00F6FF>forma de cruz</color> cerca de 1 azulejo escolhido. Causa 2x de dano se a peça do lançador for selecionada. Após uma habilidade ativa matar um alvo, ela pode ser usada novamente para causar 2x de dano final ao custo de 2x pontos de sanidade.",
  str_skill_desc_3001512 = "Giles se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Usos <color=#00F6FF>60</color> pontos de sanidade para lidar <color=#00F6FF>{1}%</color> DMG para inimigos nas 4 peças adjacentes em um <color=#00F6FF>forma de cruz</color> cerca de 1 azulejo escolhido. Causa 2x de dano se a peça do lançador for selecionada. Após uma habilidade ativa matar um alvo, ela pode ser usada novamente para causar 2x de dano final ao custo de 2x pontos de sanidade.",
  str_skill_desc_3001513 = "Giles se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Usos <color=#00F6FF>120</color> pontos de sanidade para lidar <color=#00F6FF>{1}%</color> DMG para inimigos nas 4 peças adjacentes em um <color=#00F6FF>forma de cruz</color> cerca de 1 azulejo escolhido. Causa 2x de dano se a peça do lançador for selecionada. Após uma habilidade ativa matar um alvo, ela pode ser usada novamente para causar 2x de dano final ao custo de 2x pontos de sanidade.",
  str_skill_desc_3001514 = "Giles se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Usos <color=#00F6FF>240</color> pontos de sanidade para lidar <color=#00F6FF>{1}%</color> DMG para inimigos nas 4 peças adjacentes em um <color=#00F6FF>forma de cruz</color> cerca de 1 azulejo escolhido. Causa 2x de dano se a peça do lançador for selecionada. Após uma habilidade ativa matar um alvo, ela pode ser usada novamente para causar 2x de dano final ao custo de 2x pontos de sanidade.",
  str_skill_passive_desc_410151 = "<color=#00F6FF>Ativado após matar qualquer inimigo</color> nesta rodada: Sempre que Giles causa dano, seu ATK é aumentado de acordo com o ponto de Sanidade atual. Quanto menor o ponto de Sanidade, maior o dano, até <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_413151 = "<color=#00F6FF>Ativado após matar qualquer inimigo</color> nesta rodada: Sempre que Giles causa dano, DMG é aumentado de acordo com a Sanidade atual. Quanto menor a Sanidade, maior o aumento de dano, até <color=#00F6FF>{1}</color>. A matança de qualquer <color=#00F6FF>Miragem</color> adicionalmente aumenta os bônus em <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_416151 = "<color=#00F6FF>Ativado após matar qualquer inimigo</color> nesta rodada: Sempre que Giles causa dano, DMG é aumentado de acordo com a Sanidade atual. Quanto menor a Sanidade, maior o aumento de dano, até <color=#00F6FF>{1}</color>. A matança de qualquer <color=#00F6FF>Miragem</color> adicionalmente aumenta os bônus em <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_430151 = "<color=#00F6FF>Ativado após matar qualquer inimigo</color> nesta rodada: Sempre que Giles causa dano, DMG é aumentado de acordo com a Sanidade atual. Quanto menor a Sanidade, maior o aumento de dano, até <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_433151 = "<color=#00F6FF>Ativado após matar qualquer inimigo</color> nesta rodada: Sempre que Giles causa dano, DMG é aumentado de acordo com a Sanidade atual. Quanto menor a Sanidade, maior o aumento de dano, até <color=#00F6FF>{1}</color>. A matança de qualquer <color=#00F6FF>Miragem</color> adicionalmente aumenta os bônus em <color=#00F6FF>10%</color>.",
  str_skill_passive_desc_436151 = "<color=#00F6FF>Ativado após matar qualquer inimigo</color> nesta rodada: Sempre que Giles causa dano, DMG é aumentado de acordo com a Sanidade atual. Quanto menor a Sanidade, maior o aumento de dano, até <color=#00F6FF>{1}</color>. A matança de qualquer <color=#00F6FF>Miragem</color> adicionalmente aumenta os bônus em <color=#00F6FF>10%</color>.",
  str_skill_upgrade_desc_16015113 = "Aprimoramento de Habilidade de Equipamento: A morte de qualquer <color=#00F6FF>Miragem</color> adicionalmente aumenta os bônus em <color=#00F6FF>10%</color>.",
  str_skill_upgrade_desc_16015116 = "Aprimoramento de Combo de Cadeia: Quando Sanidade chegar a 0, desencadeie DMG bônus <color=#00F6FF>3</color> vezes (Válido para Ascensão III).",
