  str_skill_desc_300152 = "May junta-se à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Restaura <color=#00F6FF>25%</color> dos pontos de sanidade perdidos ao custo de <color=#00F6FF>20%</color> de seu HP atual.",
  str_skill_desc_302152 = "May junta-se à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Restaura <color=#00F6FF>25%</color> dos pontos de sanidade perdidos ao custo de <color=#00F6FF>15%</color> de seu HP atual.",
  str_skill_desc_305152 = "May é capaz de mudar o <link=\"30040\"><#FFAE07><u>sistema de sanidade</u></color></link> para esta batalha: Mais resistente aos efeitos debuff do Sanity System. Debuffs também são enfraquecidos. Restaura <color=#00F6FF>25%</color> dos pontos de sanidade perdidos ao custo de <color=#00F6FF>15%</color> de seu HP atual.",
  str_skill_desc_2001521 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de X</color>.",
  str_skill_desc_2001522 = "Ofertas <color=#00F6FF>{1}%</color> dano em um <color=#00F6FF>Forma X para o alcance máximo</color>.",
  str_skill_desc_2001523 = "Ofertas <color=#00F6FF>{1}%</color> dano em um <color=#00F6FF>Forma X para o alcance máximo</color>.",
  str_skill_passive_desc_410152 = "Para cada 1 ponto de sanidade perdido, restaure HP igual a <color=#00F6FF>{1}</color> do ATK de maio.",
  str_skill_passive_desc_415152 = "Para cada 1 ponto de sanidade perdido, restaure HP igual a <color=#00F6FF>{1}</color> do ATK de maio.",
  str_skill_passive_desc_420152 = "Para cada 1 ponto de sanidade perdido, restaure HP igual a <color=#00F6FF>{1}</color> do ATK de maio. Sua DEF aumenta à medida que a sanidade cai, até <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_425152 = "Para cada 1 ponto de sanidade perdido, restaure HP igual a <color=#00F6FF>{1}</color> do ATK de maio. Sua DEF aumenta à medida que a sanidade cai, até <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_430152 = "Para cada 1 ponto de sanidade perdido, restaure HP igual a <color=#00F6FF>{1}</color> do ATK de maio. Quanto menor a sanidade, maior a recuperação, até <color=#00F6FF>100%</color>. Sua DEF aumenta à medida que a sanidade cai, até <color=#00F6FF>100%</color>.",
  str_skill_passive_desc_435152 = "Para cada 1 ponto de sanidade perdido, restaure HP igual a <color=#00F6FF>{1}</color> do ATK de maio. Quanto menor a sanidade, maior a recuperação, até <color=#00F6FF>100%</color>. Sua DEF aumenta à medida que a sanidade cai, até <color=#00F6FF>100%</color>.",
  str_skill_upgrade_desc_15015212 = "Aprimoramento de Habilidade Ativa: Restaura <color=#00F6FF>25%</color> de pontos de sanidade perdidos ao custo de <color=#00F6FF>15%</color> de seu HP atual.",
  str_skill_upgrade_desc_15015215 = "Altere o Sistema de Sanidade para esta batalha: Aumento da resistência aos efeitos de debuff do Sistema de Sanidade. Debuffs também são enfraquecidos.",
  str_skill_name_20015011 = "Varredura de ponto duplo",
  str_skill_name_20015012 = "Varredura de ponto duplo",
  str_skill_name_20015013 = "Varredura de ponto duplo",
  str_skill_name_3001501 = "Mar Vermelho",
  str_skill_name_3031501 = "Mar Vermelho",
  str_skill_passive_name_410150 = "Maldição da Marionete",
  str_skill_upgrade_desc_16015013 = "Aprimoramento de Habilidade Ativa: Toda vez que uma habilidade ativa causa dano, o HP máximo de Lenore é aumentado por <color=#FFFF00>3%</color>.",
  str_skill_upgrade_desc_16015016 = "Aprimoramento de Combo de Cadeia: Quanto menor a Sanidade, maior o aumento de DMG, até <color=#FFFF00>100%</color> (Válido para Ascensão III).",
  str_skill_desc_20015011 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>1 fila</color>.",
  str_skill_desc_20015012 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>3 filas</color>.",
  str_skill_desc_20015013 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>5 linhas</color>.",
  str_skill_desc_22015011 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>1 fila</color>.",
  str_skill_desc_22015012 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>3 filas</color>.",
  str_skill_desc_22015013 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>5 linhas</color>. Quando a sanidade cai abaixo <color=#00F6FF>75</color> pontos, a condição de disparo é reduzida para <color=#00F6FF>15</color>. Se no <color=#00F6FF>estado insano</color>, reduza a condição de disparo para <color=#00F6FF>5</color>.",
  str_skill_desc_23015011 = "Ofertas <color=#00F6FF>{1}%</color> DMG para <color=#00F6FF>1 linha</color>. Quanto menor a Sanidade, maior o aumento de DMG, até <color=#00F6FF>80%</color>.",
  str_skill_desc_23015012 = "Ofertas <color=#00F6FF>{1}%</color> DMG para <color=#00F6FF>3 linhas</color>. Quanto menor a Sanidade, maior o aumento de DMG, até <color=#00F6FF>80%</color>.",
  str_skill_desc_23015013 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>5 linhas</color>. Quando a sanidade cai abaixo <color=#00F6FF>75</color> pontos, a condição de disparo é reduzida para <color=#00F6FF>15</color>. Se no <color=#00F6FF>estado insano</color>, reduza a condição de disparo para <color=#00F6FF>5</color>. Quanto menor a Sanidade, maior o aumento de DMG, até <color=#00F6FF>80%</color>.",
  str_skill_desc_23615011 = "Ofertas <color=#00F6FF>{1}%</color> DMG para <color=#00F6FF>1 linha</color>. Quanto menor a Sanidade, maior o aumento de DMG, até <color=#00F6FF>100%</color>.",
  str_skill_desc_23615012 = "Ofertas <color=#00F6FF>{1}%</color> DMG para <color=#00F6FF>3 linhas</color>. Quanto menor a Sanidade, maior o aumento de DMG, até <color=#00F6FF>100%</color>.",
  str_skill_desc_23615013 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>5 linhas</color>. Quando a sanidade cai abaixo <color=#00F6FF>75</color> pontos, a condição de disparo é reduzida para <color=#00F6FF>15</color>. Se no <color=#00F6FF>estado insano</color>, reduza a condição de disparo para <color=#00F6FF>5</color>. Quanto menor a Sanidade, maior o aumento de DMG, até <color=#00F6FF>100%</color>.",
  str_skill_desc_3001501 = "Lenore se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Escolha qualquer 1 ladrilho e, em seguida, selecione outro 1 dentro <color=#00F6FF>2 aglomerados circundantes</color> para gerar uma área retangular, dentro da qual lidar <color=#00F6FF>333%</color> DMG para telhas. Cada ladrilho no retângulo deduz <color=#00F6FF>3</color> pontos de sanidade. Se um inimigo sofrer dano mais de uma vez, o efeito subsequente é reduzido a <color=#00F6FF>33%</color>.",
  str_skill_desc_3031501 = "Lenore se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Escolha qualquer 1 ladrilho e, em seguida, selecione outro 1 dentro <color=#00F6FF>2 aglomerados circundantes</color> para gerar uma área retangular, dentro da qual lidar <color=#00F6FF>333%</color> DMG para telhas. Cada ladrilho no retângulo deduz <color=#00F6FF>3</color> Pontos de sensibilidade. Se uma unidade inimiga sofrer dano mais de uma vez, o efeito subsequente é reduzido a <color=#00F6FF>33%</color>. Toda vez que uma habilidade ativa causa DMG, o HP máximo de Lenore é aumentado por <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_410150 = "Se não no <color=#00F6FF>estado calmo</color> no início de cada rodada, dê DANO igual a <color=#00F6FF>{1}</color> do HP máximo da equipe para todos os inimigos. Quanto menor a Sanidade, maior o aumento de dano, até <color=#00F6FF>{2}</color> do HP máximo da equipe.",
  str_skill_name_290220101 = "Violação Noturna",
  str_skill_desc_290220101 = "Lança um ataque poderoso em todos os inimigos dentro do alcance da habilidade.",
  str_skill_name_290220102 = "Ódio Noturno",
  str_skill_desc_290220102 = "Causa dano massivo a alvos dentro de 2 aglomerados ao redor e converte 50% de pontos de contusão em HP.",
  str_skill_name_290220103 = "Contra-ataque noturno",
  str_skill_desc_290220103 = "Causa dano massivo a alvos dentro de 2 aglomerados ao redor e converte 50% de pontos de contusão em HP toda vez que um Auroriano libera uma Habilidade Ativa.",
  str_skill_name_290220201 = "Garra Sombria",
  str_skill_desc_290220201 = "Causa dano aos inimigos nas cinco peças adjacentes ao redor da cabeça com uma garra afiada.",
  str_skill_name_290220202 = "Swat Sombrio",
  str_skill_desc_290220202 = "Pule para frente no inimigo e esmague a armadilha ao pousar, causando dano aos inimigos dentro de 1 aglomerado ao redor.",
  str_skill_name_290220203 = "Cauda Sombria",
  str_skill_desc_290220203 = "Quando nenhum inimigo estiver na frente, vire-se para enfrentar o inimigo varrendo a cauda. Se houver obstáculos após a curva, lance um Gloomy Swoop imediatamente.",
  str_skill_name_290220204 = "Golpe Sombrio",
  str_skill_desc_290220204 = "Salte alto e voe em direção ao inimigo, causando dano massivo aos inimigos dentro de 1 aglomerado ao redor ao pousar. Todos os movimentos são concluídos depois.",
  str_skill_name_29026011 = "Dreamwalker - Golpe de Clivagem",
  str_skill_desc_29026011 = "Move-se em direção a um jogador e empunha sua foice para causar dano aos inimigos ao redor dentro do alcance.",
  str_skill_name_29026012 = "Dreamwalker - Foice giratória",
  str_skill_desc_29026012 = "Convoca uma foice da borda do campo de batalha até ele, causando dano aos inimigos dentro de uma área em forma de radial.",
  str_skill_name_29026021 = "Dreamwalker - Chuva de Lâminas",
  str_skill_desc_29026021 = "Move-se em direção a um jogador e, se o jogador estiver dentro de seu alcance de ataque, ele balança o antebraço para causar dano aos inimigos dentro de 2 quadrados à sua frente.\nCaso contrário, ele entra em um estado oculto, esquivando-se de todos os ataques normais (revelado quando afetado por efeitos de controle).",
  str_skill_name_29026023 = "Dreamwalker - Sangue Uivando",
  str_skill_desc_29026023 = "Lança habilidade no lugar, causando dano a todos os inimigos na tela.",
  str_skill_name_290270101 = "Forsakin: A chamada",
  str_skill_desc_290270101 = "Forsakin convoca 2 Eclipsites em locais aleatórios no campo para ajudá-la na batalha.",
  str_skill_name_290270102 = "Forsakin: Ataque",
  str_skill_desc_290270102 = "Forsakin repele todos os Aurorianos e outros Eclipsitas no campo e causa dano aos Aurorianos.",
  str_skill_name_290270103 = "Forsakin: Murchar",
  str_skill_desc_290270103 = "Lança uma onda de choque em direção à localização do auroriano na última rodada e 1 aglomerado ao redor. Se algum auroriano estiver no alcance da onda de choque, eles sofrerão danos graves.",
  str_skill_name_290270111 = "Forsakin: Sombria",
  str_skill_desc_290270111 = "Forsakin convoca Dark Region no campo, limitando o movimento dos Aurorianos.",
  str_skill_upgrade_desc_16015413 = "Aprimoramento do Chain Combo: Os tempos do ataque do Chain Combo sempre serão <color=#00F6FF>+1</color>.",
  str_skill_upgrade_desc_16015416 = "Aprimoramento do Combo de Cadeia: Aumenta o dano do Combo de Cadeia em <color=#FFFF00>20%</color>.",
  str_skill_name_200154 = "Dilúvio perfurante",
  str_skill_name_203154 = "Dilúvio perfurante",
  str_skill_name_206154 = "Dilúvio perfurante",
  str_skill_name_300154 = "Alvo protegido",
  str_skill_name_3001541 = "Alvo protegido",
  str_skill_name_320154 = "Alvo protegido",
  str_skill_name_330154 = "Alvo protegido",
  str_skill_desc_300154 = "Seleciona e <color=#00F6FF>trava em</color> 1 inimigo. Pode haver um máximo de <color=#00F6FF>1</color> alvo sendo travado ao mesmo tempo. Enquanto o alvo travado estiver vivo, os Combos de Cadeia do Vice: Keen Sight sempre serão <color=#00F6FF>alvo</color>. Se o inimigo selecionado já estiver bloqueado, <color=#00F6FF>100%</color> dano a ele uma vez em vez disso.",
  str_skill_desc_330154 = "Seleciona e <color=#00F6FF>trava em</color> 1 inimigo. Pode haver um máximo de <color=#00F6FF>1</color> alvo sendo travado ao mesmo tempo. Enquanto o alvo travado vive, os Combos de Cadeia do Vice: Keen Sight sempre serão <color=#00F6FF>alvo</color>. Se o inimigo selecionado já estiver bloqueado, <color=#00F6FF>100%</color> dano a ele uma vez em vez disso. Cada pilha de <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> no alvo aumenta o dano em <color=#00F6FF>5%</color> Além disso.",
  str_skill_desc_200154 = "Ofertas <color=#00F6FF>100%</color> dano uma vez ao alvo mais próximo para cada <color=#00F6FF>3</color> telhas consecutivas percorridas. O dano não é afetado pelo número de peças conectadas.",
  str_skill_desc_203154 = "Ofertas <color=#00F6FF>100%</color> dano uma vez ao alvo mais próximo para cada <color=#00F6FF>3</color> telhas consecutivas percorridas. O dano não é afetado pelo número de peças conectadas. Os tempos do ataque Chain Combo serão sempre <color=#00F6FF>+1</color>.",
  str_skill_desc_206154 = "Ofertas <color=#00F6FF>100%</color> dano uma vez ao alvo mais próximo para cada <color=#00F6FF>3</color> telhas consecutivas percorridas. O dano não é afetado pelo número de peças conectadas. Os tempos do ataque Chain Combo serão sempre <color=#00F6FF>+1</color>.",
  str_skill_passive_name_410154 = "Insígnia Atemporal",
  str_skill_passive_name_420154 = "Insígnia Atemporal",
  str_skill_passive_desc_410154 = "Inflige <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> no alvo travado. Cada pilha de <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> aumenta o dano Vice: Keen Sight lida com o alvo por <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420154 = "Inflige <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> no alvo travado. Cada pilha de <link=\"30042\"><#FFAE07><u>Marca atemporal</u></color></link> aumenta o dano Vice: Visão Aguçada lida com o alvo por <color=#00F6FF>{1}</color>. Vice: Keen Sight aplica 1 pilha adicional de Timeless Mark no alvo bloqueado para cada <color=#00F6FF>3%</color> dano que causa aos aliados.",
  str_skill_name_300155 = "Advento de lâmina dupla",
