  str_skill_passive_name_420155 = "Coragem Solitária",
  str_skill_passive_name_426155 = "Coragem Solitária",
  str_skill_passive_name_430155 = "Coragem Solitária",
  str_skill_passive_name_436155 = "Coragem Solitária",
  str_skill_desc_300155 = "Consome 20 <link=\"30045\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_303155 = "Consome 20 <link=\"30046\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_306155 = "Consome 20 <link=\"30047\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_310155 = "Consome 20 <link=\"30045\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_313155 = "Consome 20 <link=\"30046\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_316155 = "Consome 20 <link=\"30047\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_320155 = "Consome 20 <link=\"30045\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_323155 = "Consome 20 <link=\"30046\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_326155 = "Consome 20 <link=\"30047\"><#FFAE07><u>Energia Solitária</u></color></link> entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>10</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 10 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_2001551 = "<color=#00F6FF>Estado normal</color>: Ganhos <color=#00F6FF>3</color> Energia Solitária e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 aglomerado ao redor</color>.\n<color=#00F6FF>Estado Solitário</color>: Ofertas <color=#00F6FF>170%</color> danos a <color=#00F6FF>12 telhas em forma de diamante</color>.",
  str_skill_desc_2001552 = "<color=#00F6FF>Estado normal</color>: Ganhos <color=#00F6FF>4</color> Energia Solitária e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>12 telhas em forma de diamante</color>.\n<color=#00F6FF>Estado Solitário</color>: Ofertas <color=#00F6FF>190%</color> danos a <color=#00F6FF>16 telhas em forma radial</color>.",
  str_skill_desc_2001553 = "<color=#00F6FF>Estado normal</color>: Ganhos <color=#00F6FF>5</color> Energia Solitária e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>16 telhas em forma radial</color>.\n<color=#00F6FF>Estado Solitário</color>: Ofertas <color=#00F6FF>210%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_20015510 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_20015520 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_20015530 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_passive_desc_410155 = "Enquanto em <color=#00F6FF>Estado solitário, </color> ataques normais causam dano <color=#00F6FF>1 aglomerado ao redor</color>. Blocos não-alvo recebem <color=#00F6FF>{1}</color> de danos normais.",
  str_skill_passive_desc_416155 = "Enquanto em <color=#00F6FF>Estado solitário, </color> ataques normais causam dano <color=#00F6FF>1 aglomerado ao redor</color>. Blocos não-alvo recebem <color=#00F6FF>{1}</color> de danos normais.",
  str_skill_passive_desc_420155 = "Enquanto em <color=#00F6FF>Estado solitário</color>, ataques normais causam dano a <color=#00F6FF>1 aglomerado ao redor</color>. Blocos não-alvo recebem <color=#00F6FF>{1}</color> de danos normais. Enquanto em <color=#00F6FF>Estado solitário</color>, o primeiro ataque normal em cada inimigo a cada rodada será seguido por um ataque normal adicional, causando <color=#00F6FF>{1}</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color>.",
  str_skill_passive_desc_426155 = "Enquanto em <color=#00F6FF>Estado solitário</color>, ataques normais causam dano a <color=#00F6FF>1 aglomerado ao redor</color>. Blocos não-alvo recebem <color=#00F6FF>{1}</color> de danos normais. Enquanto em <color=#00F6FF>Estado solitário</color>, o primeiro ataque normal em cada inimigo a cada rodada será seguido por um ataque normal adicional, causando <color=#00F6FF>{1}</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color>.",
  str_skill_passive_desc_430155 = "Ataques normais podem <color=#00F6FF>atingir inimigos em um ladrilho diagonal</color>. Enquanto em <color=#00F6FF>Estado solitário, </color> ataques normais causam dano a <color=#00F6FF>1 aglomerado ao redor</color>. Blocos não-alvo recebem <color=#00F6FF>{1}</color> de danos normais. Enquanto em <color=#00F6FF>Estado solitário</color>, o primeiro ataque normal em cada inimigo a cada rodada será seguido por um ataque normal adicional, causando <color=#00F6FF>{1}</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color>.",
  str_skill_passive_desc_436155 = "Ataques normais podem <color=#00F6FF>atingir inimigos em um ladrilho diagonal</color>. Enquanto em <color=#00F6FF>Estado solitário, </color> ataques normais causam dano a <color=#00F6FF>1 aglomerado ao redor</color>. Blocos não-alvo recebem <color=#00F6FF>{1}</color> de danos normais. Enquanto em <color=#00F6FF>Estado solitário</color>, o primeiro ataque normal em cada inimigo a cada rodada será seguido por um ataque normal adicional, causando <color=#00F6FF>{1}</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color>.",
  str_skill_upgrade_desc_16015513 = "Aprimoramento de Habilidade Ativa: Ganhos <color=#00F6FF>20</color> Lone Energy no início de cada batalha.",
  str_skill_upgrade_desc_16015516 = "Aprimoramento de Habilidade Ativa: Ganha imediatamente <color=#00F6FF>5</color> Energia Solitária após usar Habilidade Ativa.",
  str_skill_passive_desc_440153 = "Ataques normais podem <color=#00F6FF>atingir inimigos em um ladrilho diagonal</color>. Enquanto em <color=#00F6FF>Estado solitário, </color> ataques normais causam dano a <color=#00F6FF>1 aglomerado ao redor</color>. Blocos não-alvo recebem <color=#00F6FF>65%</color> de danos normais. Enquanto em <color=#00F6FF>Estado solitário</color>, o primeiro ataque normal em cada inimigo a cada rodada será seguido por um ataque normal adicional, causando <color=#00F6FF>65%</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color>.",
  str_skill_desc_350155 = "Consome 20 <link=\"30045\"><#FFAE07><u>Energia Solitária</u></color></link> para entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>8</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 8 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_353155 = "Consome 20 <link=\"30046\"><#FFAE07><u>Energia Solitária</u></color></link> para entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>8</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 8 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_356155 = "Consome 20 <link=\"30047\"><#FFAE07><u>Energia Solitária</u></color></link> para entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>8</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 8 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_360155 = "Consome 16 <link=\"30045\"><#FFAE07><u>Energia Solitária</u></color></link> para entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>8</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 8 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_363155 = "Consome 16 <link=\"30046\"><#FFAE07><u>Energia Solitária</u></color></link> para entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>8</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 8 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_desc_366155 = "Consome 16 <link=\"30047\"><#FFAE07><u>Energia Solitária</u></color></link> para entrar <color=#00F6FF>Estado solitário</color> na rodada atual, aumentando o alcance e o dano do Chain Combo. No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>8</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 8 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_upgrade_refine_desc_16015511 = "Aprimoramento de habilidade de equipamento: Enquanto em estado solitário, ataques normais causam <color=#00F6FF>65%</color> de dano normal a blocos não-alvo.",
  str_skill_upgrade_refine_desc_16015512 = "Aprimoramento de Habilidade Ativa: No final da rodada, se a Energia Solitária restante no final da rodada não for menor que <color=#00F6FF>8</color>, Energia Solitária será <color=#00F6FF>metade</color> (reduzindo pelo menos 8 pontos) e <color=#00F6FF>manter estado solitário</color> na próxima rodada.",
  str_skill_upgrade_refine_desc_16015513 = "Aprimoramento de Habilidade Ativa: Consome <color=#00F6FF>16</color> Energia Solitária para entrar no Estado solitário.",
  str_skill_upgrade_desc_16015313 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate.\nAprimoramento de Habilidade de Equipamento: Após entrar em combate, ganha instantaneamente <color=#FFFF00>2</color> Finale. (Válido para Ascensão I)",
  str_skill_upgrade_desc_16015316 = "Aprimoramento de Habilidade Ativa: Reduz os cooldowns de habilidade em <color=#FFFF00>1</color>.\nAprimoramento de habilidade de equipamento: Sempre que passar por um Ladrilho Escuro, aumenta o fator de dano do Combo em Cadeia em <color=#FFFF00>2%</color>. (Válido para Ascensão II)",
  str_skill_name_2001531 = "Explosão de Iluminação",
  str_skill_name_2001532 = "Explosão de Iluminação",
  str_skill_name_2001533 = "Explosão de Iluminação",
  str_skill_name_300153 = "Final Iluminado",
  str_skill_name_306153 = "Final Iluminado",
  str_skill_name_320153 = "Final Iluminado",
  str_skill_name_326153 = "Final Iluminado",
  str_skill_name_330153 = "Final Iluminado",
  str_skill_name_336153 = "Final Iluminado",
  str_skill_desc_300153 = "Seleciona qualquer <color=#00F6FF>4</color> telhas e convoca um Air Raid Beacon que dura por <color=#00F6FF>2</color> rodadas e, em seguida, entra <color=#00F6FF>Estado de finalização</color> por 2 rodadas. Enquanto no estado Finalidade, os ataques normais se estendem a <color=#00F6FF>ladrilhos diagonais</color>. Enquanto isso, a habilidade Chain Combo causa uma metade adicional do dano atual ao tile onde o Air Raid Beacon está localizado e 4 tiles ao redor. Ao causar dano várias vezes ao mesmo bloco, cada dano final seguinte é reduzido em <color=#00F6FF>20%</color>.",
  str_skill_desc_306153 = "Seleciona qualquer <color=#00F6FF>4</color> telhas e convoca um Air Raid Beacon que dura <color=#00F6FF>2</color> rodadas e, em seguida, entra <color=#00F6FF>Estado de finalização</color> por 2 rodadas. Enquanto no estado Finalidade, os ataques normais se estendem a <color=#00F6FF>ladrilhos diagonais</color>. Enquanto isso, a habilidade Chain Combo causa uma metade adicional do dano atual ao tile onde o Air Raid Beacon está localizado e 4 tiles ao redor. Ao causar dano várias vezes ao mesmo bloco, cada dano final seguinte é reduzido em <color=#00F6FF>20%</color>.",
  str_skill_desc_320153 = "Seleciona qualquer <color=#00F6FF>4</color> telhas e convoca um Air Raid Beacon que dura <color=#00F6FF>2</color> rodadas e, em seguida, entra <color=#00F6FF>Estado de finalização</color> por 2 rodadas. Enquanto no estado Finalidade, os ataques normais se estendem a <color=#00F6FF>ladrilhos diagonais</color>. Enquanto isso, a habilidade Chain Combo causa uma metade adicional do dano atual ao tile onde o Air Raid Beacon está localizado e 4 tiles ao redor. Ao causar dano várias vezes ao mesmo bloco, cada dano final seguinte é reduzido em <color=#00F6FF>20%</color>. Ganha um adicional de <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finalização</u></color></link> independentemente do limite enquanto no estado de Finalidade.",
  str_skill_desc_326153 = "Seleciona qualquer <color=#00F6FF>4</color> telhas e convoca um Air Raid Beacon que dura <color=#00F6FF>2</color> rodadas e, em seguida, entra <color=#00F6FF>Estado de finalização</color> por 2 rodadas. Enquanto no estado Finalidade, os ataques normais se estendem a <color=#00F6FF>ladrilhos diagonais</color>. Enquanto isso, a habilidade Chain Combo causa uma metade adicional do dano atual ao tile onde o Air Raid Beacon está localizado e 4 tiles ao redor. Ao causar dano várias vezes ao mesmo bloco, cada dano final seguinte é reduzido em <color=#00F6FF>20%</color>. Ganha um adicional de <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finalização</u></color></link> independentemente do limite enquanto no estado de Finalidade.",
  str_skill_desc_330153 = "Seleciona qualquer <color=#00F6FF>4</color> telhas e convoca um Air Raid Beacon que dura <color=#00F6FF>2</color> rodadas e, em seguida, entra <color=#00F6FF>Estado de finalização</color> por 2 rodadas. Enquanto no estado Finalidade, os ataques normais se estendem a <color=#00F6FF>ladrilhos diagonais</color>. Enquanto isso, a habilidade Chain Combo causa uma metade adicional do dano atual ao tile onde o Air Raid Beacon está localizado e 4 tiles ao redor. Ao causar dano várias vezes ao mesmo bloco, cada dano final seguinte é reduzido em <color=#00F6FF>20%</color>. Ganha um adicional de <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finalização</u></color></link> independentemente do limite enquanto no estado de Finalidade.",
  str_skill_desc_336153 = "Seleciona qualquer <color=#00F6FF>4</color> telhas e convoca um Air Raid Beacon que dura <color=#00F6FF>2</color> rodadas e, em seguida, entra <color=#00F6FF>Estado de finalização</color> por 2 rodadas. Enquanto no estado Finalidade, os ataques normais se estendem a <color=#00F6FF>ladrilhos diagonais</color>. Enquanto isso, a habilidade Chain Combo causa uma metade adicional do dano atual ao tile onde o Air Raid Beacon está localizado e 4 tiles ao redor. Ao causar dano várias vezes ao mesmo bloco, cada dano final seguinte é reduzido em <color=#00F6FF>20%</color>. Ganha um adicional de <color=#00F6FF>5</color> <link=\"300442\"><#FFAE07><u>Finalização</u></color></link> independentemente do limite enquanto no estado de Finalidade.",
  str_skill_desc_2001531 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 3 inimigos mais próximos dentro <color=#00F6FF>3 aglomerados circundantes</color>.",
  str_skill_desc_2001532 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos dentro <color=#00F6FF>4 círculos ao redor</color>.",
  str_skill_desc_2001533 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>4 círculos ao redor</color>.",
