  str_skill_desc_2001561 = "<color=#00F6FF>Modo guarda-sol</color>: Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 aglomerado ao redor</color>.\n<color=#00F6FF>Modo Desarmado</color>: Ofertas <color=#00F6FF>150%</color> dano a 2 inimigos mais próximos.",
  str_skill_desc_2001562 = "<color=#00F6FF>Modo guarda-sol</color>: Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>12 telhas em forma de diamante</color>.\n<color=#00F6FF>Modo Desarmado</color>: Ofertas <color=#00F6FF>160%</color> dano a 3 inimigos mais próximos.",
  str_skill_desc_2001563 = "<color=#00F6FF>Modo guarda-sol</color>: Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color>.\n<color=#00F6FF>Modo Desarmado</color>: Ofertas <color=#00F6FF>170%</color> dano aos 4 inimigos mais próximos.",
  str_skill_desc_2001564 = "<color=#00F6FF>Modo guarda-sol</color>: Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 aglomerado ao redor</color>.\n<color=#00F6FF>Modo Desarmado</color>: Ofertas <color=#00F6FF>150%</color> dano a 2 inimigos mais próximos.",
  str_skill_desc_2001565 = "<color=#00F6FF>Modo guarda-sol</color>: Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>12 telhas em forma de diamante</color>.\n<color=#00F6FF>Modo Desarmado</color>: Ofertas <color=#00F6FF>160%</color> dano a 3 inimigos mais próximos.",
  str_skill_desc_2001566 = "<color=#00F6FF>Modo guarda-sol</color>: Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color>.\n<color=#00F6FF>Modo Desarmado</color>: Ofertas <color=#00F6FF>170%</color> dano aos 4 inimigos mais próximos.",
  str_skill_desc_300156 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>80%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_3001560 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>80%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_303156 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>80%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_3031560 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>80%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_306156 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>100%</color> de dano aos blocos ao longo do caminho, depois alterna para <color=#00F6FF>100%</color> de dano aos blocos ao longo do caminho. <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>1.000%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para o <color=#00F6FF>Modo Guarda-sol</color>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_3061560 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>100%</color> de dano aos blocos ao longo do caminho, depois alterna para <color=#00F6FF>100%</color> de dano aos blocos ao longo do caminho. <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>1.000%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para o <color=#00F6FF>Modo Guarda-sol</color>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_310156 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>80%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_3101560 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 bloco transversal e arremessa o guarda-sol no bloco selecionado, causando <color=#00F6FF>80%</color> de dano aos blocos ao longo do caminho e, em seguida, alterna para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_313156 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 peça transversal e arremessa a sombrinha na peça selecionada, causando <color=#00F6FF>80%</color> de dano às peças ao longo do caminho e lança sua Habilidade de Equipamento uma vez no ponto de pouso, então muda para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_3131560 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 peça transversal e arremessa a sombrinha na peça selecionada, causando <color=#00F6FF>80%</color> de dano às peças ao longo do caminho e lança sua Habilidade de Equipamento uma vez no ponto de pouso, então muda para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>640%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
  str_skill_desc_316156 = "<color=#00F6FF>Modo Guarda-sol</color>: Seleciona 1 peça transversal e arremessa a sombrinha na peça selecionada, causando <color=#00F6FF>100%</color> de dano às peças ao longo do caminho e lança sua Habilidade de Equipamento uma vez no ponto de pouso, então muda para <color=#00F6FF>Modo Desarmado</color>.\n<color=#00F6FF>Modo Desarmado</color>: Recupera o guarda-sol, causando <color=#00F6FF>1,000%</color> de dano aos ladrilhos ao longo do caminho, depois alterna para o <color=#00F6FF>Modo Guarda-sol</color> cor>.\nMuda para o <color=#00F6FF>Modo Guarda-sol</color> sempre que o guarda-sol é coberto ou removido. Quando estiver coberto por um inimigo, a recarga da habilidade <color=#00F6FF>+1</color> rodada.",
