  str_skill_passive_desc_410156 = "Sempre que mudar de <color=#00F6FF>Modo Desarmado</color> para <color=#00F6FF>Modo guarda-sol</color>, negocie imediatamente <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1 aglomerado ao redor</color>.",
