  str_skill_desc_3221570 = "Usos <color=#00F6FF>3</color> <link=\"30048\"><#FFAE07><u>Pontos de discussão</u></color></link> para convocar <color=#00F6FF>Manae</color> em um ladrilho disponível ou usa <color=#00F6FF>1</color> <link=\"30048\"><#FFAE07><u>Ponto de rosca</u></color></link> mover <color=#00F6FF>Manae</color>. Leve Manae de volta no final de nossa rodada. Enquanto se move, Manae fará o possível para <color=#00F6FF>manter a posição relativa</color> com Sanae e causar dano ignorando DEF <color=#00F6FF>igual ao ATK de Manae</color> para o inimigo que ela esbarra. Manae herda <color=#00F6FF>70%</color> do ATK básico de Sanae.",
  str_skill_desc_3321570 = "Usos <color=#00F6FF>3</color> <link=\"30048\"><#FFAE07><u>Pontos de discussão</u></color></link> para convocar <color=#00F6FF>Manae</color> em um ladrilho disponível ou usa <color=#00F6FF>1</color> <link=\"30048\"><#FFAE07><u>Ponto de rosca</u></color></link> mover <color=#00F6FF>Manae</color>. Leve Manae de volta no final de nossa rodada. Enquanto se move, Manae fará o possível para <color=#00F6FF>manter a posição relativa</color> com Sanae e causar dano ignorando DEF <color=#00F6FF>igual ao ATK de Manae</color> para o inimigo que ela esbarra. Manae herda <color=#00F6FF>70%</color> do ATK básico de Sanae. Entrar no Aurora Time concede 1 adicional <color=#00F6FF>jogada</color> para Mané.",
  str_skill_desc_3051570 = "Usos <color=#00F6FF>3</color> <link=\"30049\"><#FFAE07><u>Pontos de discussão</u></color></link> para convocar <color=#00F6FF>Manae</color> em um ladrilho disponível ou usa <color=#00F6FF>1</color> <link=\"30049\"><#FFAE07><u>Ponto de rosca</u></color></link> mover <color=#00F6FF>Manae</color>. Leve Manae de volta no final de nossa rodada. Enquanto se move, Manae fará o possível para <color=#00F6FF>manter a posição relativa</color> com Sanae e causar dano ignorando DEF <color=#00F6FF>igual ao ATK de Manae</color> para o inimigo que ela esbarra. Manae herda <color=#00F6FF>70%</color> do ATK básico de Sanae.",
  str_skill_desc_3151570 = "Usos <color=#00F6FF>3</color> <link=\"30049\"><#FFAE07><u>Pontos de discussão</u></color></link> para convocar <color=#00F6FF>Manae</color> em um ladrilho disponível ou usa <color=#00F6FF>1</color> <link=\"30049\"><#FFAE07><u>Ponto de rosca</u></color></link> mover <color=#00F6FF>Manae</color>. Leve Manae de volta no final de nossa rodada. Enquanto se move, Manae fará o possível para <color=#00F6FF>manter a posição relativa</color> com Sanae e causar dano ignorando DEF <color=#00F6FF>igual ao ATK de Manae</color> para o inimigo que ela esbarra. Manae herda <color=#00F6FF>70%</color> do ATK básico de Sanae.",
  str_skill_desc_3251570 = "Usos <color=#00F6FF>3</color> <link=\"30049\"><#FFAE07><u>Pontos de discussão</u></color></link> para convocar <color=#00F6FF>Manae</color> em um ladrilho disponível ou usa <color=#00F6FF>1</color> <link=\"30049\"><#FFAE07><u>Ponto de rosca</u></color></link> mover <color=#00F6FF>Manae</color>. Leve Manae de volta no final de nossa rodada. Enquanto se move, Manae fará o possível para <color=#00F6FF>manter a posição relativa</color> com Sanae e causar dano ignorando DEF <color=#00F6FF>igual ao ATK de Manae</color> para o inimigo que ela esbarra. Manae herda <color=#00F6FF>70%</color> do ATK básico de Sanae.",
  str_skill_desc_3351570 = "Usos <color=#00F6FF>3</color> <link=\"30049\"><#FFAE07><u>Pontos de discussão</u></color></link> para convocar <color=#00F6FF>Manae</color> em um ladrilho disponível ou usa <color=#00F6FF>1</color> <link=\"30049\"><#FFAE07><u>Ponto de rosca</u></color></link> mover <color=#00F6FF>Manae</color>. Leve Manae de volta no final de nossa rodada. Enquanto se move, Manae fará o possível para <color=#00F6FF>manter a posição relativa</color> com Sanae e causar dano ignorando DEF <color=#00F6FF>igual ao ATK de Manae</color> para o inimigo que ela esbarra. Manae herda <color=#00F6FF>70%</color> do ATK básico de Sanae. Entrar no Aurora Time concede 1 adicional <color=#00F6FF>jogada</color> para Mané.",
  str_skill_passive_desc_410157 = "Manae ganha 1 aplicação da Marca do Fio quando causa dano. Cada pilha aumenta sua herança do ATK de Sanae em <color=#00F6FF>{1}</color>, até 30 pilhas.",
  str_skill_passive_desc_420157 = "Manae ganha 1 aplicação da Marca do Fio quando causa dano. Cada pilha aumenta sua herança do ATK de Sanae em <color=#00F6FF>{1}</color>, até 30 pilhas. Uma vez que Manae carrega 30 acúmulos da Marca de Fio ou ganha <color=#00F6FF>5</color> pilhas em uma única rodada, ela será capaz de <color=#00F6FF>liberar Chain Combo simultaneamente</color> com Sanae.",
  str_skill_upgrade_desc_16015813 = "Aprimoramento de Habilidade de Equipamento: Quando Joker muda pela primeira vez de membro da equipe para Capitão durante a batalha, Joker ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_upgrade_desc_16015816 = "Aprimoramento de Habilidade de Equipamento: Quando Joker muda entre membro da equipe e Capitão, o Capitão muda +1, acionado uma vez por rodada.",
  str_skill_desc_300158 = "Joker entra na batalha com a <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Seleciona 1 inimigo para causar <color=#00F6FF>{1}%</color> de dano e <color=#00F6FF>para dobrar</color> os acúmulos de <link=\"30052\"><#FFAE07><u>Explorar Fraquezas</u></color></link>. A Habilidade Ativa causa dano baseado nos números de espaços ocupados pelo alvo.",
  str_skill_desc_320158 = "Joker entra na batalha com a <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Seleciona 1 inimigo para causar <color=#00F6FF>{1}%</color> de dano e <color=#00F6FF>para dobrar</color> os acúmulos de <link=\"30052\"><#FFAE07><u>Explorar Fraquezas</u></color></link>. Se a habilidade ativa do Joker estava pronta na rodada anterior, as pilhas são <color=#00F6FF>triplicado</color> em vez de. A Habilidade Ativa causa dano baseado nos números de espaços ocupados pelo alvo.",
  str_skill_desc_3201580 = "Joker entra na batalha com a <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Seleciona 1 inimigo para causar <color=#00F6FF>{1}%</color> de dano e <color=#00F6FF>para dobrar</color> os acúmulos de <link=\"30052\"><#FFAE07><u>Explorar Fraquezas</u></color></link>. Se a habilidade ativa do Joker estava pronta na rodada anterior, as pilhas são <color=#00F6FF>triplicado</color> em vez de. A Habilidade Ativa causa dano baseado nos números de espaços ocupados pelo alvo.",
  str_skill_desc_2001581 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 3 inimigos mais próximos dentro <color=#00F6FF>4 aglomerados circundantes</color>, e inflige <color=#00F6FF>3 pilhas</color> do <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido.",
  str_skill_desc_2001582 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos dentro <color=#00F6FF>4 aglomerados circundantes</color>, e inflige <color=#00F6FF>5 pilhas</color> do <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido.",
  str_skill_desc_2001583 = "Ofertas <color=#00F6FF>{1}%</color> dano a todos os inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color>, e inflige <color=#00F6FF>7 pilhas</color> do <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido.",
  str_skill_passive_desc_410158 = "A cada derrota inimiga, <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas são distribuídas entre os inimigos restantes, concedendo até <color=#00F6FF>{1}</color> pilhas para cada inimigo.",
  str_skill_passive_desc_413158 = "A cada derrota do inimigo, <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas são distribuídas entre os inimigos restantes, concedendo até <color=#00F6FF>{1}</color> pilhas para cada inimigo. Quando Joker muda de membro da equipe para Capitão durante a batalha, Joker ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_passive_desc_416158 = "A cada derrota inimiga, <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas são distribuídas entre os inimigos restantes, concedendo até <color=#00F6FF>{1}</color> pilhas para cada inimigo. Quando Joker muda de membro da equipe para Capitão durante a batalha, Joker ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada. Quando Joker muda de papel entre o membro da equipe e o Capitão, o Capitão muda +1, acionado uma vez por rodada.",
  str_skill_passive_desc_430158 = "A cada derrota do inimigo, <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas são distribuídas entre os inimigos restantes, concedendo até <color=#00F6FF>{1}</color> pilhas para cada inimigo. Joker inflige <color=#00F6FF>1</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> com cada Ataque Normal.",
  str_skill_passive_desc_433158 = "A cada derrota do inimigo, <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas são distribuídas entre os inimigos restantes, concedendo até <color=#00F6FF>{1}</color> pilhas para cada inimigo. Joker inflige <color=#00F6FF>1</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> com cada Ataque Normal. Quando Joker muda de membro da equipe para Capitão durante a batalha, Joker ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_passive_desc_436158 = "A cada derrota do inimigo, <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas são distribuídas entre os inimigos restantes, concedendo até <color=#00F6FF>{1}</color> pilhas para cada inimigo. Joker inflige <color=#00F6FF>1</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> com cada Ataque Normal. Quando Joker muda de membro da equipe para Capitão durante a batalha, Joker ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada. Quando Joker muda de papel entre o membro da equipe e o Capitão, o Capitão muda +1, acionado uma vez por rodada.",
  str_skill_upgrade_desc_16015913 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16015916 = "Aprimoramento de Habilidade de Equipamento: Quando a Queen muda pela primeira vez de membro da equipe para Capitão durante a batalha, a Queen ganha <color=#00F6FF>15%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_desc_300159 = "Queen entra na batalha com a <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Causas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>todos os</color> inimigos e inflige <color=#00F6FF>6</color> acúmulos de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>.",
  str_skill_desc_320159 = "Queen entra na batalha com a <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Causas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>todos os</color> inimigos e inflige <color=#00F6FF>6</color> acúmulos de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>. Os inimigos da água recebem <color=#00F6FF>12 pilhas</color> em vez de.",
  str_skill_desc_2001591 = "Ofertas <color=#00F6FF>{1}%</color> dano a todos os inimigos dentro <color=#00F6FF>1 aglomerado ao redor</color>, e inflige <color=#00F6FF>2 pilhas</color> do <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido. Os inimigos da água recebem <color=#00F6FF>4 pilhas</color> em vez de.",
  str_skill_desc_2001592 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 peças em forma radial</color> e inflige <color=#00F6FF>3 pilhas</color> de <link=\"30052\"><#FFAE07><u>Explore a Fraqueza</u></color></link> para cada inimigo atingido. Os inimigos da água recebem <color=#00F6FF>6 pilhas</color> em vez disso.",
  str_skill_desc_2001593 = "Ofertas <color=#00F6FF>{1}%</color> dano a todos os inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>, e inflige <color=#00F6FF>4 pilhas</color> do <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido. Os inimigos da água recebem <color=#00F6FF>8 pilhas</color> em vez de.",
  str_skill_passive_desc_410159 = "Ataques normais tornam-se ataques de 2 combos que <color=#00F6FF>{1}</color> de dano básico por acerto.",
  str_skill_passive_desc_416159 = "Ataques normais tornam-se ataques de 2 combos que <color=#00F6FF>{1}</color> de dano básico por acerto. Quando a Queen muda pela primeira vez de membro da equipe para Capitã durante a batalha, a Queen ganha <color=#00F6FF>15%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_passive_desc_430159 = "Ataques normais tornam-se ataques de 2 combos que <color=#00F6FF>{1}</color> de dano básico por acerto. Cada Ataque Normal inflige <color=#00F6FF>1</color> Pilha de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>. Os inimigos da água recebem <color=#00F6FF>2 pilhas</color> em vez de.",
  str_skill_passive_desc_436159 = "Ataques normais tornam-se ataques de 2 combos que <color=#00F6FF>{1}</color> de dano básico por acerto. Cada Ataque Normal inflige <color=#00F6FF>1</color> Pilha de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>. Os inimigos da água recebem <color=#00F6FF>2 pilhas</color> em vez de. Quando a Queen muda pela primeira vez de membro da equipe para Capitã durante a batalha, a Queen ganha <color=#00F6FF>15%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_desc_300160 = "Fox entra na batalha com seu <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> e inflige <color=#00F6FF>9</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>.",
  str_skill_desc_320160 = "Fox entra na batalha com seu <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> e inflige <color=#00F6FF>9</color> acúmulos de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>. Os inimigos de fogo recebem <color=#00F6FF>18</color> pilhas em vez disso.",
  str_skill_desc_2001601 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 coluna</color>, e inflige <color=#00F6FF>1</color> Pilha de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> a cada inimigo. Os inimigos de fogo recebem <color=#00F6FF>3</color> pilhas em vez disso.",
  str_skill_desc_2001602 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>3 colunas</color>, e inflige <color=#00F6FF>2</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> a cada inimigo. Os inimigos de fogo recebem <color=#00F6FF>4</color> pilhas em vez disso.",
  str_skill_desc_2001603 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>3 colunas</color>, e inflige <color=#00F6FF>3</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> a cada inimigo. Os inimigos de fogo recebem <color=#00F6FF>6</color> pilhas em vez disso.",
  str_skill_passive_desc_410160 = "O primeiro ataque normal a cada rodada causa <color=#00F6FF>{1}</color> vezes danos.",
  str_skill_passive_desc_415160 = "O primeiro Ataque Normal a cada rodada causa <color=#00F6FF>{1}</color> vezes a quantidade de dano. Quando Fox muda de membro da equipe para capitão durante a batalha, Fox ganha <color=#00F6FF>15%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_passive_desc_430160 = "Cada Ataque Normal inflige <color=#00F6FF>1</color> Pilha de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>, Inimigos de fogo recebem <color=#00F6FF>2</color> pilhas em vez disso. O primeiro ataque normal a cada rodada causa e inflige <color=#00F6FF>{1}</color> vezes o dano e <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas.",
  str_skill_passive_desc_435160 = "Cada Ataque Normal inflige <color=#00F6FF>1</color> Pilha de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>, Inimigos de fogo recebem <color=#00F6FF>2</color> pilhas em vez disso. O primeiro ataque normal a cada rodada causa e inflige <color=#00F6FF>{1}</color> vezes o dano e <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> pilhas. Quando Fox muda de membro da equipe para capitão durante a batalha, Fox ganha <color=#00F6FF>15%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_upgrade_desc_15016012 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_15016015 = "Aprimoramento de Habilidade de Equipamento: Quando Fox muda de membro da equipe para Capitão durante a batalha, Fox ganha <color=#00F6FF>15%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_desc_300161 = "Violet entra na batalha com sua <link=\"30051\"><#FFAE07><u>Habilidade Especial</u></color></link>. Causa <color=#00F6FF>{1}%</color> dano a <color=#00F6FF>13 peças em forma de diamante</color> centradas em torno de 1 peça selecionada e inflige <color=#00F6FF>9</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar Fraqueza</u></color></link>.",
  str_skill_desc_320161 = "Violet entra na batalha com sua <link=\"30051\"><#FFAE07><u>Habilidade Especial</u></color></link>. Causa <color=#00F6FF>{1}%</color> dano a <color=#00F6FF>13 peças em forma de diamante</color> centradas em torno de 1 peça selecionada e inflige <color=#00F6FF>9</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar Fraqueza</u></color></link>. Os inimigos da floresta recebem <color=#00F6FF>18</color> pilhas em vez disso.",
  str_skill_desc_2001611 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 coluna</color>, e inflige <color=#00F6FF>2</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> a cada inimigo. Os inimigos da floresta recebem <color=#00F6FF>4</color> pilhas em vez disso.",
  str_skill_desc_2001612 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>3 colunas</color>, e inflige <color=#00F6FF>3</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> a cada inimigo. Os inimigos da floresta recebem <color=#00F6FF>6</color> pilhas em vez disso.",
  str_skill_desc_2001613 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>3 colunas</color>, e inflige <color=#00F6FF>4</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> a cada inimigo. Os inimigos da floresta recebem <color=#00F6FF>8</color> pilhas em vez disso.",
  str_skill_passive_desc_410161 = "Violet aumenta todo o dano causado aos inimigos infligidos com o <color=#00F6FF>FRACO</color> status por <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_415161 = "Violet aumenta todo o dano causado a inimigos infligidos com o <color=#00F6FF>FRACO</color> status por <color=#00F6FF>{1}</color>. Quando Violet muda pela primeira vez de membro da equipe para Capitão durante a batalha, Violet ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_passive_desc_430161 = "Violet aumenta todo o dano causado aos inimigos infligidos com o <color=#00F6FF>FRACO</color> status por <color=#00F6FF>{1}</color>. Cada Ataque Normal inflige <color=#00F6FF>1</color> Pilha de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>, os inimigos da floresta recebem <color=#00F6FF>2</color> pilhas em vez disso.",
  str_skill_passive_desc_435161 = "Violet aumenta todo o dano causado a inimigos infligidos com o <color=#00F6FF>FRACO</color> status por <color=#00F6FF>{1}</color>. Cada Ataque Normal inflige <color=#00F6FF>1</color> Pilha de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>, os inimigos da floresta recebem <color=#00F6FF>2</color> pilhas em vez disso. Quando Violet muda pela primeira vez de membro da equipe para Capitão durante a batalha, Violet ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_upgrade_desc_15016112 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_15016115 = "Aprimoramento de Habilidade de Equipamento: Quando Violet muda pela primeira vez de membro da equipe para Capitão durante a batalha, Violet ganha <color=#00F6FF>20%</color> aumento do dano de Ataque Normal nesta rodada.",
  str_skill_upgrade_desc_15016212 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
