  str_skill_desc_3001621 = "Mona entra na batalha com seu <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Seleciona um bloco e negócios <color=#00F6FF>{1}%</color> dano ao longo do caminho e em ladrilhos adjacentes, e inflige <color=#00F6FF>5</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido.",
  str_skill_desc_3201621 = "Mona entra na batalha com seu <link=\"30051\"><#FFAE07><u>Habilidade especial</u></color></link>. Seleciona um bloco e negócios <color=#00F6FF>{1}%</color> dano ao longo do caminho e em ladrilhos adjacentes, e inflige <color=#00F6FF>5</color> pilhas de <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link>. Os inimigos do trovão recebem <color=#00F6FF>10 pilhas</color> em vez de.",
