  str_skill_desc_2001622 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 3 inimigos mais próximos dentro <color=#00F6FF>3 aglomerados circundantes</color>, e inflige <color=#00F6FF>2 pilhas</color> do <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido. Os inimigos do trovão recebem <color=#00F6FF>4 pilhas</color> em vez de.",
  str_skill_desc_2001623 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos dentro <color=#00F6FF>3 aglomerados circundantes</color>, e inflige <color=#00F6FF>3 pilhas</color> do <link=\"30052\"><#FFAE07><u>Explorar fraqueza</u></color></link> para cada inimigo atingido. Os inimigos do trovão recebem <color=#00F6FF>5 pilhas</color> em vez de.",
