  str_skill_desc_3301652 = "Converte o <color=#00F6FF>4</color> telhas verdes mais próximas de amarelas e deixa para trás uma <color=#00F6FF>Mina de Flecha Solar</color>. Se a Habilidade Ativa estiver pronta na última rodada, aumenta a contagem de conversão de peças em <color=#00F6FF>1</color> nesta rodada.",
  str_skill_desc_3351652 = "Converte o <color=#00F6FF>5</color> telhas verdes mais próximas de amarelas e deixa para trás uma <color=#00F6FF>Mina de Flecha Solar</color>. Se a Habilidade Ativa estiver pronta na última rodada, aumenta a contagem de conversão de peças em <color=#00F6FF>1</color> nesta rodada.",
  str_skill_passive_name_400165 = "Domínio Flecha Solar",
  str_skill_passive_desc_400165 = "<color=#00F6FF>Em qualquer momento</color> uma combinação em cadeia atinge um alvo, deixa um <color=#00F6FF>Mina de Flechas Solares</color> em uma telha aleatória dentro <color=#00F6FF>1 cluster circundante</color> que <color=#00F6FF>desencadeia e explode</color> quando um inimigo passa por cima dele, causando dano ignorando DEF igual a <color=#00F6FF>{1}</color> do ATK de Ciel para <color=#00F6FF>5 ladrilhos em forma de cruz</color>. <color=#00F6FF>Minas de flechas solares</color> desaparecer depois que eles <color=#00F6FF>explodir</color> ou depois do <color=#00F6FF>final da rodada</color>.",
  str_skill_passive_name_420165 = "Domínio Flecha Solar",
  str_skill_passive_desc_420165 = "<color=#00F6FF>Em qualquer momento</color> um combo em cadeia atinge o alvo, deixa um <color=#00F6FF>Mina de Flecha Solar</color> em uma telha aleatória dentro <color=#00F6FF>1 aglomerado ao redor</color> que desaparece depois <color=#00F6FF>desencadeando e explodindo</color> quando um inimigo passa por ele ou <color=#00F6FF>quando a rodada termina</color>, causando dano ignorando DEF igual a <color=#00F6FF>{1}</color> do ATK de Ciel para <color=#00F6FF>5 azulejos em forma de cruz</color>.",
  str_skill_upgrade_desc_15016512 = "Melhoria de Habilidade Ativa: Se a habil. já estava pronta na última rodada, aumenta as casas convertidas em <color=#FFFF00>1</color> nessa rodada.",
