  str_skill_desc_300164 = "Consome <color=#00F6FF>2</color> <link=\"30053\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas.",
  str_skill_desc_303164 = "Consome <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas.",
  str_skill_desc_306164 = "Consome <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas.",
  str_skill_desc_320164 = "Consome <color=#00F6FF>2</color> <link=\"30053\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>ladrilhos ao longo do caminho e 1 ladrilho na frente</color>.",
  str_skill_desc_323164 = "Consome <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>ladrilhos ao longo do caminho e 1 ladrilho na frente</color>.",
  str_skill_desc_326164 = "Consome <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>ladrilhos ao longo do caminho e 1 ladrilho na frente</color>.",
  str_skill_desc_330164 = "Consome <color=#00F6FF>2</color> <link=\"30053\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>ladrilhos ao longo do caminho e 1 ladrilho na frente</color>. Ganhos <color=#00F6FF>1</color> <link=\"30053\"><#FFAE07><u>Smoldering Soul</u></color></link> se um inimigo for atingido. Aciona até <color=#00F6FF>1</color> tempo em cada rodada.",
  str_skill_desc_333164 = "Consome <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>ladrilhos ao longo do caminho e 1 ladrilho na frente</color>. Ganhos <color=#00F6FF>1</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> se um inimigo for atingido. Aciona até <color=#00F6FF>1</color> tempo em cada rodada.",
  str_skill_desc_336164 = "Consome <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> para se teletransportar para qualquer ladrilho dentro <color=#00F6FF>16 azulejos em forma de cruz</color>, então converte <color=#00F6FF>as 2 telhas na frente e atrás</color> a unidade para telhas vermelhas e ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>ladrilhos ao longo do caminho e 1 ladrilho na frente</color>. Ganhos <color=#00F6FF>1</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> se um inimigo for atingido. Aciona até <color=#00F6FF>2</color> vezes em cada rodada.",
  str_skill_passive_name_410164 = "Radiância serena",
  str_skill_passive_desc_410164 = "Os ataques normais de Carleen: Smoldering Soul causam dano adicional ignorando DEF igual a <color=#00F6FF>{1}</color> de ATK para inimigos em telhas vermelhas.",
  str_skill_upgrade_desc_16016413 = "Aprimoramento de Habilidade Ativa: Ganhos <color=#00F6FF>2</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> no início da batalha.",
  str_skill_upgrade_desc_16016416 = "Aprimoramento de Habilidade Ativa: Ganhos <color=#00F6FF>1</color> <link=\"30054\"><#FFAE07><u>Smoldering Soul</u></color></link> ao acertar um inimigo. Aciona até <color=#00F6FF>2</color> vezes em cada rodada (válido para Ascension III).",
  str_skill_desc_5220011 = "Converte <color=#00F6FF>1</color> ladrilho percorrível em um <color=#00F6FF>ladrilho cromático</color>.",
