  str_skill_name_320168 = "Explosão de Gêiser",
  str_skill_name_330168 = "Explosão de Gêiser",
  str_skill_desc_2001681 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 2 inimigos mais próximos, então gera um <link=\"30061\"><#FFAE07><u>Marca de banho de sol</u></color></link> em 1 ladrilho aleatório ocupado por um inimigo.",
  str_skill_desc_2001682 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 3 inimigos mais próximos, então gera um <link=\"30061\"><#FFAE07><u>Marca de banho de sol</u></color></link> em 1 ladrilho aleatório ocupado por um inimigo.",
  str_skill_desc_2001683 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos, então gera um <link=\"30061\"><#FFAE07><u>Marca de banho de sol</u></color></link>em 1 ladrilho aleatório ocupado por um inimigo.",
  str_skill_desc_300168 = "Ativa todos <link=\"30061\"><#FFAE07><u>Marcas de banho de sol</u></color></link> em campo e promoções <color=#00F6FF>240%</color> danos a <color=#00F6FF>5 azulejos em forma de cruz</color> Ao redor deles. Se um alvo sofrer dano mais de uma vez, o dano para cada acerto após o primeiro é reduzido, até <color=#00F6FF>10%</color> do dano original.",
  str_skill_desc_320168 = "Ativa todos <link=\"30061\"><#FFAE07><u>Marcas de banho de sol</u></color></link> em campo e promoções <color=#00F6FF>240%</color> danos a <color=#00F6FF>9 ladrilhos em forma quadrada</color> Ao redor deles. Se um alvo sofrer dano mais de uma vez, o dano para cada acerto após o primeiro é reduzido, até <color=#00F6FF>10%</color> do dano original.",
  str_skill_desc_330168 = "Ativa todos <link=\"30061\"><#FFAE07><u>Marcas de banho de sol</u></color></link> em campo e promoções <color=#00F6FF>240%</color> danos a <color=#00F6FF>9 ladrilhos em forma quadrada</color> Ao redor deles. Se um alvo sofrer dano mais de uma vez, o dano para cada acerto após o primeiro é reduzido, até <color=#00F6FF>10%</color> do dano original. Se alguma peça do campo estiver ocupada por <color=#00F6FF>3</color> marcas ativadas, mas nenhuma Marca de Chuva de Sol, gera 1 nova Marca de Chuva de Sol naquele bloco.",
  str_skill_passive_name_410168 = "Bolha de proteção",
  str_skill_passive_name_415168 = "Bolha de proteção",
  str_skill_passive_desc_410168 = "Concede um escudo que é <color=#00F6FF>{1}</color> da DEF do Rainbow e dura 1 rodada ao passar por um <link=\"30061\"><#FFAE07><u>Marca de banho de sol</u></color></link>.",
  str_skill_passive_desc_415168 = "Concede um escudo que é <color=#00F6FF>{1}</color> da DEF do Rainbow e dura 1 rodada ao passar por um <link=\"30061\"><#FFAE07><u>Marca de banho de sol</u></color></link>. Gera uma marca Sunshower em <color=#00F6FF>1</color> azul aleatório no início de cada rodada.",
