  str_skill_desc_2001672 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos dentro <color=#00F6FF>3 aglomerados circundantes</color>.",
  str_skill_desc_2001673 = "Causa <color=#00F6FF>{1}%</color> de dano a todos os inimigos em <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_desc_300167 = "Jeno começa a batalha com o <link=\"30058\"><#FFAE07><u>Convés de Origem</u></color></link> e a <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ganha 1 Cartão de Origem aleatório para cada <color=#00F6FF>{1}</color> Sanidade consumida. Quando lançado novamente na mesma rodada, aumenta o consumo em <color=#00F6FF>5</color>.",
  str_skill_desc_303167 = "Jeno começa a batalha com o <link=\"30059\"><#FFAE07><u>Convés de Origem</u></color></link> e a <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ganha 1 Cartão de Origem aleatório para cada <color=#00F6FF>{1}</color> Sanidade consumida. Quando lançado novamente na mesma rodada, aumenta o consumo em <color=#00F6FF>5</color>.",
  str_skill_desc_306167 = "Jeno começa a batalha com o <link=\"30060\"><#FFAE07><u>Convés de Origem</u></color></link> e a <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ganha 1 Cartão de Origem aleatório para cada <color=#00F6FF>{1}</color> Sanidade consumida. Quando lançado novamente na mesma rodada, aumenta o consumo em <color=#00F6FF>5</color>.",
  str_skill_desc_320167 = "Jeno começa a batalha com o <link=\"30058\"><#FFAE07><u>Convés de Origem</u></color></link> e a <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ganha 1 Cartão de Origem aleatório para cada <color=#00F6FF>{1}</color> Sanidade consumida. Quando lançado novamente na mesma rodada, aumenta o consumo em <color=#00F6FF>5</color>. Para Aurorianos simultaneamente aprimorados por Aglomerado Luminoso e Trânsito Astronômico, quanto menor a Sanidade, maior o bônus de ATK, até <color=#00F6FF>66,6%</color>.",
  str_skill_desc_323167 = "Jeno começa a batalha com o <link=\"30059\"><#FFAE07><u>Convés de Origem</u></color></link> e a <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ganha 1 Cartão de Origem aleatório para cada <color=#00F6FF>{1}</color> Sanidade consumida. Quando lançado novamente na mesma rodada, aumenta o consumo em <color=#00F6FF>5</color>. Para Aurorianos simultaneamente aprimorados por Aglomerado Luminoso e Trânsito Astronômico, quanto menor a Sanidade, maior o bônus de ATK, até <color=#00F6FF>66,6%</color>.",
  str_skill_desc_326167 = "Jeno começa a batalha com o <link=\"30060\"><#FFAE07><u>Convés de Origem</u></color></link> e a <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ganha 1 Cartão de Origem aleatório para cada <color=#00F6FF>{1}</color> Sanidade consumida. Quando lançado novamente na mesma rodada, aumenta o consumo em <color=#00F6FF>5</color>. Para Aurorianos simultaneamente aprimorados por Aglomerado Luminoso e Trânsito Astronômico, quanto menor a Sanidade, maior o bônus de ATK, até <color=#00F6FF>66,6%</color>.",
  str_skill_passive_name_410167 = "Mudança de coração",
  str_skill_passive_desc_410167 = "Ao lançar o Deck de Origem, restaura o HP da equipe <color=#00F6FF>{1}</color> do ATK básico de Jeno. Este efeito não é afetado pelo Sistema de Sanidade. Quanto menor o HP da equipe, maior o efeito de recuperação, até um bônus de 100%.",
  str_skill_passive_name_413167 = "Mudança de coração",
  str_skill_passive_desc_413167 = "Ao lançar o Deck de Origem, restaura o HP da equipe <color=#00F6FF>{1}</color> do ATK básico de Jeno. Este efeito não é afetado pelo Sistema de Sanidade. Quanto menor o HP da equipe, maior o efeito de recuperação, até um bônus de 100%. Ganhos <color=#00F6FF>2</color> cartas aleatórias no início da batalha.",
  str_skill_passive_name_416167 = "Mudança de coração",
  str_skill_passive_desc_416167 = "Ao lançar o Deck de Origem, restaura o HP da equipe <color=#00F6FF>{1}</color> do ATK básico de Jeno. Este efeito não é afetado pelo Sistema de Sanidade. Quanto menor o HP da equipe, maior o efeito de recuperação, até um bônus de 100%. Ganhos <color=#00F6FF>2</color> cartas aleatórias no início da batalha.",
  str_skill_passive_name_430167 = "Mudança de coração",
  str_skill_passive_desc_430167 = "Ao lançar o Deck de Origem, restaura o HP da equipe <color=#00F6FF>{1}</color> do ATK básico de Jeno. Este efeito não é afetado pelo Sistema de Sanidade. Quanto menor o HP da equipe, maior o efeito de recuperação, até um bônus de 100%. Ganha 1 carta aleatória ao entrar no Aurora Time.",
  str_skill_passive_name_433167 = "Mudança de coração",
  str_skill_passive_desc_433167 = "Ao lançar o Deck de Origem, restaura o HP da equipe <color=#00F6FF>{1}</color> do ATK básico de Jeno. Este efeito não é afetado pelo Sistema de Sanidade. Quanto menor o HP da equipe, maior o efeito de recuperação, até um bônus de 100%. Ganhos <color=#00F6FF>2</color> cartas aleatórias no início da batalha, e ganha 1 carta aleatória ao entrar no Aurora Time.",
  str_skill_passive_name_436167 = "Mudança de coração",
  str_skill_passive_desc_436167 = "Ao lançar o Deck de Origem, restaura o HP da equipe <color=#00F6FF>{1}</color> do ATK básico de Jeno. Este efeito não é afetado pelo Sistema de Sanidade. Quanto menor o HP da equipe, maior o efeito de recuperação, até um bônus de 100%. Ganhos <color=#00F6FF>2</color> cartas aleatórias no início da batalha, e ganha 1 carta aleatória ao entrar no Aurora Time.",
  str_skill_upgrade_desc_16016713 = "Ganhos <color=#00F6FF>2</color> aleatória<link=\"30059\"><#FFAE07><u> Cartões de Origem</u></color></link> no início de uma batalha.",
