  str_skill_desc_3001670 = "O Auroriano <color=#00F6FF>na última posição da equipe</color> ganha ATK adicional que é <color=#00F6FF>7%</color> do ATK básico de Jeno.",
  str_skill_name_3001671 = "Aglomerado Luminoso",
  str_skill_desc_3001671 = "o <color=#00F6FF>atual capitão</color> ganha ATK adicional que é <color=#00F6FF>8%</color> do ATK básico de Jeno.",
