  str_skill_upgrade_desc_16016616 = "Aprimoramento de Habilidade Ativa: Para o <color=#00F6FF>2º/3º</color> rodada que existe uma Marca de Caça, Kyllo negocia <color=#00F6FF>350%/500%</color> dano.",
