  str_skill_name_323166 = "A Estratégia Kyllo",
  str_skill_name_326166 = "A Estratégia Kyllo",
  str_skill_desc_300166 = "Consome <color=#00F6FF>1</color> ponto de <link=\"30055\"><#FFAE07><u>Valor da isca</u></color></link> para colocar 1 Marca de Caça em qualquer peça, ou selecione 1 Marca de Caça para liberar Kyllo. Enquanto a Marca de Caça estiver ativa por <color=#00F6FF>01/02/3</color> rodada(s), Kyllo ataca o <color=#00F6FF>Peça de Marca de Caça/5 peças em forma de cruz/13 peças em forma de diamante/25 peças em forma de quadrado</color>, lidando <color=#00F6FF>150%/200%/250%/300%</color> dano.",
  str_skill_desc_320166 = "Consome <color=#00F6FF>1</color> ponto de <link=\"30055\"><#FFAE07><u>Valor da isca</u></color></link> para colocar 1 Marca de Caça em qualquer peça, ou selecione 1 Marca de Caça para liberar Kyllo. Enquanto a Marca de Caça estiver ativa por <color=#00F6FF>01/02/3</color> rodada(s), Kyllo ataca o <color=#00F6FF>Peça de Marca de Caça/5 peças em forma de cruz/13 peças em forma de diamante/25 peças em forma de quadrado</color>, lidando <color=#00F6FF>150%/200%/250%/300%</color> dano. Reduz a DEF básica do alvo em <color=#00F6FF>5%</color> para a rodada. Efeito pode ser empilhado.",
  str_skill_desc_303166 = "Consome <color=#00F6FF>1</color> ponto de <link=\"30056\"><#FFAE07><u>Valor da isca</u></color></link> para colocar 1 Marca de Caça em qualquer peça, ou selecione 1 Marca de Caça para liberar Kyllo. Enquanto a Marca de Caça estiver ativa por <color=#00F6FF>01/02/3</color> rodada(s), Kyllo ataca o <color=#00F6FF>Peça Marca de Caça/5 peças em forma de cruz/13 peças em forma de diamante/25 peças em forma de quadrado</color>, lidando <color=#00F6FF>150%/200%/250%/300%</color> dano.",
  str_skill_desc_306166 = "Consome <color=#00F6FF>1</color> ponto de <link=\"30056\"><#FFAE07><u>Valor da isca</u></color></link> para colocar 1 Marca de Caça em qualquer peça, ou selecione 1 Marca de Caça para liberar Kyllo. Enquanto a Marca de Caça estiver ativa por <color=#00F6FF>01/02/3</color> rodada(s), Kyllo ataca o <color=#00F6FF>Peça de Marca de Caça/5 peças em forma de cruz/13 peças em forma de diamante/25 peças em forma de quadrado</color>, lidando <color=#00F6FF>150%/200%/350%/500%</color> dano.",
  str_skill_desc_323166 = "Consome <color=#00F6FF>1</color> ponto de <link=\"30056\"><#FFAE07><u>Valor da isca</u></color></link> para colocar 1 Marca de Caça em qualquer peça, ou selecione 1 Marca de Caça para liberar Kyllo. Enquanto a Marca de Caça estiver ativa por <color=#00F6FF>01/02/3</color> rodada(s), Kyllo ataca o <color=#00F6FF>Peça de Marca de Caça/5 peças em forma de cruz/13 peças em forma de diamante/25 peças em forma de quadrado</color>, lidando <color=#00F6FF>150%/200%/250%/300%</color> dano. Reduz a DEF básica do alvo em <color=#00F6FF>5%</color> para a rodada. Efeito pode ser empilhado.",
  str_skill_desc_326166 = "Consome <color=#00F6FF>1</color> ponto de <link=\"30056\"><#FFAE07><u>Valor da isca</u></color></link> para colocar 1 Marca de Caça em qualquer peça, ou selecione 1 Marca de Caça para liberar Kyllo. Enquanto a Marca de Caça estiver ativa por <color=#00F6FF>01/02/3</color> rodada(s), Kyllo ataca o <color=#00F6FF>Peça de Marca de Caça/5 peças em forma de cruz/13 peças em forma de diamante/25 peças em forma de quadrado</color>, lidando <color=#00F6FF>150%/200%/350%/500%</color> dano. Reduz a DEF básica do alvo em <color=#00F6FF>5%</color> para a rodada. Efeito pode ser empilhado.",
