  str_skill_desc_2001663 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>3 colunas</color>.",
  str_skill_name_29039011 = "Golpe Único: Ataque",
  str_skill_name_29039013 = "Compartilhar é cuidar: elenco",
  str_skill_desc_29039011 = "Se um auroriano não estiver em forma de cruz na extensão máxima de seu alcance, move-se em direção ao auroriano e ataca quando estiver a 4 quadrados adjacentes do auroriano.",
  str_skill_desc_290390111 = "Se um auroriano não estiver em uma forma radial no alcance máximo, move-se em direção ao auroriano e ataca quando estiver dentro de 1 aglomerado ao redor do auroriano.",
  str_skill_desc_29039013 = "Se um auroriano estiver em forma de cruz na extensão máxima de seu alcance, lança a habilidade no local para causar dano ao auroriano.",
  str_skill_desc_290390131 = "Se um auroriano estiver em forma radial até o alcance máximo, lança a habilidade no local para causar dano ao auroriano.",
  str_skill_name_291030101 = "Ataque Espelho",
  str_skill_name_291030102 = "Piscadela do Espelho",
  str_skill_name_291030103 = "Invocação Espelho",
  str_skill_desc_291030101 = "Nepolis se move e causa dano aos alvos à frente através da imagem do espelho.",
  str_skill_desc_291030102 = "Se a verdadeira forma de Nepólis estiver mais próxima do jogador, ela troca de posição com sua imagem no espelho, causando dano aos alvos ao longo do caminho.",
  str_skill_desc_291030103 = "Convoca uma criatura espelho que se autodestrói na próxima rodada, amaldiçoando um Auroriano aleatório por 2 rodadas.",
  str_skill_name_5220011 = "Caltrops Furiosos",
  str_skill_name_2001301 = "Eu sou o Juiz Chefe!",
  str_skill_name_2001302 = "Eu sou o Juiz Chefe!",
  str_skill_name_2001303 = "Eu sou o Juiz Chefe!",
  str_skill_desc_2001301 = "O nível de <link=\"30062\"><#FFAE07><u>Estatutos de Direito</u></color></link> dentro de <color=#00F6FF>1 aglomerado circundante</color> <color=#00F6FF>+1</color>.",
  str_skill_desc_2001302 = "O nível de <link=\"30062\"><#FFAE07><u>Estatutos de Direito</u></color></link> dentro de <color=#00F6FF>12 blocos em forma de diamante</color> <color=#00F6FF>+1</color>.",
  str_skill_desc_2001303 = "O nível de <link=\"30062\"><#FFAE07><u>Estatutos de Direito</u></color></link> dentro de <color=#00F6FF>2 aglomerados circundantes</color> <color=#00F6FF>+1</color>.",
  str_skill_name_300130 = "Esteja sentado!",
  str_skill_desc_300130 = "<color=#00F6FF>Destrói</color> todas as <link=\"30062\"><#FFAE07><u>Estátuas da Lei</u></color></link> dentro de 2 aglomerados circunvizinhos centrados em 1 transitável selecionado tile, e gera uma nova Estátua da Lei no tile selecionado, com um nível igual a <color=#00F6FF>a soma de todos os níveis das Estátuas destruídas</color>. Se nenhuma Estátua da Lei for detectada dentro do alcance, gera um Lv. 1 Estátua da Lei na peça selecionada.",
  str_skill_passive_name_400130 = "Justiça feita!",
  str_skill_passive_desc_400130 = "Gera 1 Nv. 1 <link=\"30062\"><#FFAE07><u>Estatua de Direito</u></color></link> para cada 5 peças percorridas. Para estatutos atuais, <color=#00F6FF>nível +1</color>.",
