  str_skill_passive_name_400171 = "Golpe Único",
  str_skill_passive_name_430171 = "Golpe Único",
  str_skill_desc_2001711 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de cruz</color>.",
  str_skill_desc_2001712 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de cruz</color>.",
  str_skill_desc_2001713 = "Ofertas <color=#00F6FF>{1}%</color> dano <color=#00F6FF>em forma de cruz para o alcance máximo</color>.",
  str_skill_desc_2201711 = "Causa <color=#00F6FF>{1}%</color> dano a <color=#00F6FF>8 peças em forma de cruz</color>, que se difundem para afetar 1 peça adicional nos lados esquerdo e direito quando bloqueadas .",
  str_skill_desc_2201712 = "Causa <color=#00F6FF>{1}%</color> dano a <color=#00F6FF>12 peças em forma de cruz</color>, que se difundem para afetar 1 peça adicional nos lados esquerdo e direito quando bloqueadas .",
  str_skill_desc_2201713 = "Causa <color=#00F6FF>{1}%</color> dano <color=#00F6FF>em forma de cruz até o alcance máximo</color>, que se difundem para afetar 1 peça adicional nos lados esquerdo e direito quando bloqueado.",
  str_skill_desc_3001711 = "Custa <color=#00F6FF>2</color> <link=\"30063\"><#FFAE07><u>Trigger Points</u></color></link> e limpa os pontos restantes. Causa <color=#00F6FF>200%</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color> após o ataque de Combinação de Cadeia desta rodada terminar. O dano final aumenta em <color=#00F6FF>20%</color> para cada Trigger Point eliminado.",
  str_skill_desc_3021711 = "Custa <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>Trigger Points</u></color></link> e limpa os pontos restantes. Causa <color=#00F6FF>200%</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color> após o fim do ataque de combinação em cadeia desta rodada. O dano final aumenta em <color=#00F6FF>20%</color> para cada Trigger Point eliminado.",
  str_skill_desc_3051711 = "Custa <color=#00F6FF>2</color> <link=\"30064\"><#FFAE07><u>Trigger Points</u></color></link> e limpa os pontos restantes. Causa <color=#00F6FF>200%</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color> após o ataque de Combinação de Cadeia desta rodada terminar. O dano final aumenta em <color=#00F6FF>25%</color> para cada Trigger Point eliminado.",
  str_skill_passive_desc_400171 = "Identifica 1 <color=#00F6FF>Fraqueza do oponente</color> ao conectar 1 peça Verde ou Peça Aprimorada. Depois de detectar 6 fraquezas, o próximo Ataque Normal causa Dano Crítico aleatório de <color=#00F6FF>120%-{1}</color>. Redefine a pilha de <color=#00F6FF>Fraqueza do oponente</color>.",
  str_skill_passive_desc_430171 = "Mancha 1 <color=#00F6FF>Ponto fraco</color> ao conectar 1 ladrilho verde ou ladrilho aprimorado. Após detectar 6 Pontos Fracos, o próximo Ataque Normal causa Dano Crítico aleatório de <color=#00F6FF>120%-{1}</color>. Redefine a pilha de <color=#00F6FF>Ponto Fraco</color> e ganha 1 Ponto de Gatilho.",
  str_skill_upgrade_desc_15017112 = "Aprimoramento de Habilidade Ativa: Ganha <color=#00F6FF>2</color> Pontos de Gatilho adicionais no início de cada batalha.",
  str_skill_upgrade_desc_15017115 = "Aprimoramento de Habilidade Ativa: O dano final aumenta em <color=#00F6FF>25%</color> para cada Trigger Point eliminado.",
