  str_skill_name_336170 = "Expansão de bala",
  str_skill_passive_name_410170 = "Alvo",
  str_skill_passive_name_420170 = "Alvo",
  str_skill_desc_2001701 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_2001702 = "Causa <color=#00F6FF>{1}%</color> de dano a peças amarelas dentro de <color=#00F6FF>1 aglomerado ao redor</color> e a área <color=#00F6FF>se estendendo em forma de cruz</color >.",
  str_skill_desc_2001703 = "Causa <color=#00F6FF>{1}%</color> de dano a peças amarelas dentro de <color=#00F6FF>1 aglomerado ao redor</color> e a área <color=#00F6FF>se estendendo nas 8 direções</color >.",
  str_skill_desc_300170 = "Seleciona 1 ladrilho e, em seguida, escolhe uma direção à direita ou à esquerda do ladrilho selecionado. As cores de todos os ladrilhos na direção selecionada mudarão uma coluna nessa direção e todos os ladrilhos na <color=#00F6FF>mesma coluna do ladrilho selecionado</color> se tornarão ladrilhos amarelos.",
  str_skill_desc_306170 = "Seleciona 1 ladrilho e, em seguida, escolhe uma direção à direita ou à esquerda do ladrilho selecionado. As cores de todos os ladrilhos na direção selecionada mudarão uma coluna nessa direção e todos os ladrilhos na <color=#00F6FF>mesma coluna do ladrilho selecionado</color> se tornarão ladrilhos amarelos.",
  str_skill_desc_320170 = "Seleciona 1 ladrilho e, em seguida, escolhe uma direção à direita ou à esquerda do ladrilho selecionado. As cores de todos os ladrilhos na direção selecionada mudarão uma coluna nessa direção e todos os ladrilhos na <color=#00F6FF>mesma coluna do ladrilho selecionado</color> se tornarão ladrilhos amarelos. Causa <color=#00F6FF>250%</color> de dano à coluna do bloco selecionado.",
  str_skill_desc_326170 = "Seleciona 1 ladrilho e, em seguida, escolhe uma direção à direita ou à esquerda do ladrilho selecionado. As cores de todos os ladrilhos na direção selecionada mudarão uma coluna nessa direção e todos os ladrilhos na <color=#00F6FF>mesma coluna do ladrilho selecionado</color> se tornarão ladrilhos amarelos. Causa <color=#00F6FF>250%</color> de dano à coluna do bloco selecionado.",
  str_skill_desc_330170 = "Seleciona 1 ladrilho e, em seguida, escolhe uma direção à direita ou à esquerda do ladrilho selecionado. As cores de todos os ladrilhos na direção selecionada mudarão uma coluna nessa direção e todos os ladrilhos na <color=#00F6FF>mesma coluna do ladrilho selecionado</color> se tornarão ladrilhos amarelos. Causa <color=#00F6FF>250%</color> de dano à coluna do bloco selecionado e, se o bloco selecionado estiver no pé de um <color=#00F6FF>inimigo de bloco único</color>, o alvo será forçado a mover 1 ladrilho na direção selecionada.",
  str_skill_desc_336170 = "Seleciona 1 ladrilho e, em seguida, escolhe uma direção à direita ou à esquerda do ladrilho selecionado. As cores de todos os ladrilhos na direção selecionada mudarão uma coluna nessa direção e todos os ladrilhos na <color=#00F6FF>mesma coluna do ladrilho selecionado</color> se tornarão ladrilhos amarelos. Causa <color=#00F6FF>250%</color> de dano à coluna do bloco selecionado e, se o bloco selecionado estiver no pé de um <color=#00F6FF>inimigo de bloco único</color>, o alvo será forçado a mover 1 ladrilho na direção selecionada.",
  str_skill_passive_desc_410170 = "Quando Chain Combo causa dano, quanto mais longe o alvo estiver, maior será o dano causado. O dano final aumenta em <color=#00F6FF>{1}</color> por cluster.",
  str_skill_passive_desc_420170 = "Quando Chain Combo e Active Skill causam dano, quanto mais longe o alvo estiver, maior será o dano causado. O dano final é aumentado em <color=#00F6FF>{1}</color> por cluster.",
  str_skill_upgrade_desc_16017013 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16017016 = "Melhoria de Habilidade Ativa: Reduz a recarga em <color=#FFFF00>1</color> rodada.",
  str_skill_name_290370121 = "Canhão Principal da Torre - Choque",
  str_skill_desc_290370121 = "Depois de mover 1 ladrilho, o canhão principal dispara um ataque de choque que impacta a área com 4 ladrilhos à sua frente, causando dano aos alvos no alcance e repelindo-os em 3 ladrilhos.",
  str_skill_desc_290370123 = "O canhão principal dispara um ataque de choque que atinge a área com 4 quadrados à sua frente, causando dano aos alvos no alcance e repelindo-os em 3 quadrados.",
  str_skill_name_290370122 = "Canhão Principal Overrun - Choque",
  str_skill_desc_290370122 = "Depois de se mover por 2 ladrilhos, o canhão principal dispara um ataque de choque que impacta a área com 4 ladrilhos à sua frente, causando dano massivo aos alvos no alcance e repelindo-os em 3 ladrilhos.",
  str_skill_name_290370131 = "Ombro Strafe - Esquerda",
  str_skill_desc_290370131 = "Depois de se mover por 1 ladrilho, bloqueie os inimigos em uma área em forma de leque e dispare vários tiros, causando dano.",
  str_skill_desc_290370133 = "Bloqueie os inimigos em uma área em forma de leque e dispare vários tiros, causando dano.",
  str_skill_name_290370132 = "Overrun Strafe - Esquerda",
  str_skill_desc_290370132 = "Depois de se mover por 2 quadrados, bloqueie os inimigos em uma área em forma de leque e dispare vários tiros, causando dano massivo.",
  str_skill_name_290370141 = "Ombro Strafe - Direita",
  str_skill_desc_290370141 = "Depois de se mover por 1 ladrilho, bloqueie os inimigos em uma área em forma de leque e dispare vários tiros, causando dano.",
  str_skill_desc_290370143 = "Bloqueie os inimigos em uma área em forma de leque e dispare vários tiros, causando dano.",
  str_skill_name_290370142 = "Overrun Strafe - Direita",
  str_skill_desc_290370142 = "Depois de se mover por 2 quadrados, bloqueie os inimigos em uma área em forma de leque e dispare vários tiros, causando dano massivo.",
  str_skill_name_290370151 = "Superação",
  str_skill_desc_290370151 = "Entra no estado de superação, o que aumenta a distância de movimento e ATK.",
  str_skill_name_490370401 = "Manutenção de emergência",
  str_skill_desc_490370401 = "Bloqueia HP e realiza manutenção de emergência. Empurra os aurorianos de volta para a borda do campo com seu canhão e concede a si mesmo um escudo. Após 1 rodada, recuperará HP igual ao dobro do valor do escudo.",
  str_skill_name_40004451 = "Contaminação",
  str_skill_desc_40004451 = "Murkmite causa dano aos alvos no alcance e os repele.",
  str_skill_name_49004213 = "Reencarnador",
  str_skill_desc_49004213 = "Nozard carrega energia para a Maré Crescente iminente e convoca Thumper para proteção.",
  str_skill_name_49004215 = "Maré Elevada",
  str_skill_desc_49004215 = "Nozard realiza um bombardeio em uma área fixa no campo e bloqueia as peças dentro do alcance.",
  str_skill_name_400060101 = "Ímpeto de Luta",
  str_skill_desc_400060101 = "O Espreitador se liga ao Eclipsite dentro de 1 aglomerado ao seu redor, fornecendo ao Eclipsite um Escudo e aprimorando seu ATK e ACT.",
  str_skill_name_400060201 = "Regeneração Aprimorada",
  str_skill_desc_400060201 = "Quando estiver dentro de 1 aglomerado ao redor de Dawn, funde-se com ela para recuperar seu HP, aumenta seu ATK e concede a ela um escudo.",
  str_skill_desc_400071502 = "Causa dano igual a uma porcentagem do HP máximo do alvo a alvos dentro de seu alcance máximo de forma radial. Se não houver alvos nas 8 direções ao seu redor, ele ganha uma barreira defensiva.",
  str_skill_desc_400072502 = "Causa dano igual a uma porcentagem do HP máximo do alvo a alvos em forma radial até o alcance máximo centrado na unidade. Se não houver alvos nas 8 direções ao redor da unidade, restaura HP para unidades aliadas.",
  str_skill_desc_490050302 = "Solmorph causa dano a alvos dentro da área de ataque e os puxa. Converte ladrilhos dentro de 2 aglomerados circundantes, independentemente de o ataque atingir um inimigo ou não, e bloqueia os ladrilhos dentro de 1 aglomerado circundante centrado no alvo ao acertar um golpe.",
  str_skill_desc_491050301 = "Solmorph desencadeia uma onda de explosão de 2 ladrilhos no local do alvo, causando dano aos alvos ao longo do caminho. Redefine as peças dentro do alcance de ataque.",
  str_skill_desc_491050302 = "Solmorph causa dano a alvos dentro da área de ataque e os puxa. Redefine as peças dentro de 3 aglomerados ao redor, independentemente de o ataque atingir um inimigo ou não.",
  str_skill_desc_490028304 = "O Dark Summoner invoca 4 beacons e depois cura todos os beacons.",
  str_skill_desc_491028304 = "O Dark Summoner invoca 4 beacons e depois cura todos os beacons.",
  str_skill_desc_490025102 = "Evoque 1 Fantasma Raivoso para ajudar o Fantasma. O Phantasm existente será recuperado antes que um novo seja convocado. Aumenta permanentemente o ATK do Phantom após um recall bem-sucedido.",
  str_skill_desc_490025201 = "O Fantasma raivoso ataca 2 vezes, convocando o Fantasma para ajudar.",
  str_skill_name_491025203 = "Recordação de Ilusão",
  str_skill_desc_491025203 = "O Phantasm existente será recuperado antes que um novo seja convocado, e os efeitos de recuperação de HP, aumento de ATK e ACT desaparecem. Aumenta seu próprio ACT sem Phantasm no campo de batalha.",
  str_skill_name_215007811 = "Ataque Normal",
  str_skill_desc_215007811 = "Robyn ataca alvos dentro do alcance de ataque.",
  str_skill_name_215007812 = "Pingo Ondulado",
  str_skill_desc_215007812 = "Causa dano em alvos dentro de 2 clusters ao redor.",
  str_skill_name_215007813 = "Sopro Rastejante",
  str_skill_desc_215007813 = "Causa dano a alvos no campo de batalha.",
  str_skill_name_214004811 = "Palpitações",
  str_skill_desc_214004811 = "Causa dano a alvos ao alcance.",
  str_skill_name_214004812 = "Trovão Caprichoso",
  str_skill_desc_214004812 = "Causa dano a alvos no campo de batalha.",
