  str_skill_desc_214009112 = "Causa dano a alvos no campo de batalha.",
  str_skill_name_214009121 = "Salmo de Apoio",
  str_skill_desc_214009121 = "Quando lançado, ACT de todos os membros aliados +1, e cada tile Azul no campo de batalha concede aos membros aliados um bônus de ATK igual a 0,5%.",
  str_skill_desc_490022306 = "O Tédio acumula poder para um ataque de Fogo em forma de cruz, que causa dano aos alvos e inflige Queimadura. Tédio convoca Dreadblades para proteção ao acumular poder e aumenta o ACT para outros Eclipsites no campo de batalha após a convocação bem-sucedida.",
  str_skill_desc_490022310 = "O tédio acumula poder para um ataque de trovão em forma de cruz, que causa dano aos alvos e inflige Paralisia. Tédio convoca Dreadblades para proteção ao acumular poder e aumenta o ACT para outros Eclipsites no campo de batalha após a convocação bem-sucedida.",
  str_skill_desc_490064302 = "A energia do Caracalune transborda, causando dano a 4 colunas e linhas.",
  str_skill_desc_490060103 = "Causa dano em 7 áreas aleatórias 2×2 e gera fogo dentro do alcance. Converte todas as peças em 1 aglomerado ao redor de qualquer Auroriano atingido e inflige Maldição no Capitão da equipe.",
  str_skill_desc_49006811 = "Flashes sem forma até a borda do Tabuleiro de Alquimia, longe da localização de sua equipe, e então realizam ataques à distância. Ele lança 2 Nonentities e 1 Chasm para locais aleatórios dentro de um intervalo específico de onde seus Aurorianos se conectam.",
  str_skill_desc_49006812 = "Formless lança 4 Nonentities em locais aleatórios em todo o campo de batalha.",
  str_skill_desc_490091202 = "Lança um raio impactante em direção ao local do alvo na última rodada, causando dano aos alvos no caminho do raio e no local do alvo. Inflige Maldição no Capitão da equipe Auroriana após acertar um golpe.",
  str_skill_desc_490091203 = "Causa dano a alvos ao alcance.",
  str_skill_desc_490006301 = "Nozard distorce e abre o espaço na frente, causando dano elemental. Qualquer golpe auroriano será cegado.",
  str_skill_desc_490006302 = "Nozard repele os Aurorianos e carrega energia para a tempestade iminente.",
  str_skill_desc_490006304 = "Nozard bombardeia uma área fixa repetidamente e invoca Skill Banning Stele em cada área.",
  str_skill_desc_490006306 = "Nozard bombardeia uma área fixa repetidamente e invoca Skill Banning Stele em cada área.",
  str_skill_desc_491006304 = "Nozard bombardeia uma área fixa repetidamente e esmaga as peças dentro da área.",
  str_skill_desc_491006305 = "Nozard bombardeia uma área fixa repetidamente e esmaga as peças dentro da área.",
  str_skill_desc_491006302 = "Nozard repele Aurorianos, convoca Thumper para o campo e carrega energia para a tempestade iminente.",
  str_skill_desc_492006306 = "Nozard bombardeia uma área fixa repetidamente e esmaga as peças dentro da área.",
  str_skill_desc_490110101 = "Maude lança ondas de choque para frente em uma forma retangular de 2 peças que viaja até o alcance máximo possível, causando dano aos alvos atingidos. Se o alvo for atingido, recupera HP para si mesmo.",
  str_skill_desc_490110201 = "Maude lança ondas de choque para frente em uma forma retangular de 2 peças que viaja até o alcance máximo possível, causando dano aos alvos atingidos. Se o alvo for atingido, esgota o alvo.",
  str_skill_name_490110301 = "Corno de Guerra de Solus",
  str_skill_desc_490110301 = "Maude aumenta ATK e ACT para Eclipsites em campo.",
  str_skill_name_400040101 = "Cruz da Escuridão",
  str_skill_desc_400040101 = "Quando o Dark Summoner armazena energia, o Beacon ataca alvos dentro de uma área em forma de cruz.",
  str_skill_name_810410092 = "Chamado do Recife",
  str_skill_desc_810410092 = "Invoca 2 Runas Especiais, que se transformarão em Estelas de Proibição de Habilidades após certas rodadas.",
  str_skill_desc_490040103 = "Schummer convoca Lightning Power para causar dano a várias áreas em forma de cruz no campo. Inimigos no centro das áreas serão mortos instantaneamente.",
  str_skill_desc_490040106 = "Schummer convoca Lightning Power para causar dano a várias áreas em forma de cruz no campo e convoca pequenos Eclipsites para o campo.",
  str_skill_desc_490040108 = "Schummer controla o Colossus para liberar um Sonic Blast, causando dano a todos os alvos. Pequenos Eclipsites serão mortos instantaneamente. Cada morte restaura 1% de HP.",
  str_skill_desc_490067201 = "Schummer controla o Colossus para liberar um Sonic Blast, causando dano a todos os alvos e convertendo peças específicas no campo.",
  str_skill_desc_490067202 = "Schummer libera energia raivosa, ataca todos os alvos no tabuleiro e converte as cores em peças específicas no campo. Quanto mais longe um alvo estiver de Schummer, mais dano ele sofrerá.",
  str_skill_desc_490021101 = "Umbrahulk invoca 4 Seixos aleatoriamente para o campo de batalha e invoca 1 Estela de Proibição de Habilidade perto da posição dos Aurorianos no início da rodada.",
  str_skill_desc_490021102 = "Umbrahulk se afasta do jogador e invoca 4 Seixos ao lado do jogador.",
  str_skill_name_490310101 = "Fogo Auxiliar",
  str_skill_desc_490310101 = "Quando os inimigos estão dentro de 2 aglomerados ao redor, causa dano aos alvos e os repele em 1 quadrado.",
  str_skill_name_490310102 = "Ligue para o suporte",
  str_skill_desc_490310102 = "Invoca 4 Nonentities quando os inimigos estão além de 2 clusters de distância.",
  str_skill_name_490310105 = "Ataque Normal de Barbara",
  str_skill_desc_490310105 = "Aproxima-se dos inimigos, lança ataque e os repele.",
  str_skill_name_491018101 = "Nota Final",
  str_skill_desc_491018101 = "Quando os inimigos estão dentro de 1 aglomerado ao redor, a Tempestade Solar explode, causando dano aos inimigos e repelindo-os.",
  str_skill_name_491018102 = "Ataque Normal de Regina",
