  str_skill_name_491105101 = "Tornado de Olhos Vermelhos: Menor",
  str_skill_desc_491105101 = "Se houver inimigos dentro de 2 aglomerados ao redor, afaste-se dos inimigos e cause dano a eles 10 vezes.",
  str_skill_name_491105102 = "Tornado de Olhos Vermelhos: Major",
  str_skill_desc_491105102 = "Se os inimigos estiverem além de 2 aglomerados de distância, bloqueie os inimigos e cause dano a eles 20 vezes.",
  str_skill_name_491030101 = "Ataque Normal de Sinsa",
