  str_skill_name_491030102 = "Disparo Espalhado",
  str_skill_desc_491030102 = "Causa grande dano em forma radial até o alcance máximo.",
  str_skill_desc_490060101 = "Carregue no alvo e jogue-o em uma peça adjacente, convertendo todas as peças nos 3 grupos ao redor no final da investida.",
  str_skill_upgrade_desc_16017313 = "Aprimoramento de Habilidade Ativa: Remova 1 pilha de Marca Mortal toda vez que uma Habilidade Ativa causar dano.\nAprimoramento de Habilidade de Equipamento: O ATK básico é aumentado em <color=#FFFF00>25%</color> depois que todas as Marcas Mortais forem removidas.\n(Válido para Ascensão II)",
  str_skill_upgrade_desc_16017316 = "Aprimoramento de Habilidade Ativa: Pode ser lançado <color=#FFFF00>1</color> mais tempo depois de entrar no horário de Aurora.",
