  str_skill_name_3331731 = "Veredicto rápido",
  str_skill_name_3361731 = "Veredicto rápido",
  str_skill_desc_3001731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido.",
  str_skill_desc_3061731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido. A habilidade ativa pode ser lançada mais 1 vez após entrar no Aurora Time.",
  str_skill_desc_3201731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido.",
  str_skill_desc_3231731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido. Cada vez que o dano é causado, remove 1 pilha de Marca Mortal.",
  str_skill_desc_3261731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido. Cada vez que o dano é causado, remove 1 pilha de Marca Mortal. A habilidade ativa pode ser lançada mais 1 vez após entrar no Aurora Time.",
  str_skill_desc_3301731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido. Cada vez que 1 peça aprimorada é absorvida, remove 1 pilha de Marcas Mortais.",
  str_skill_desc_3331731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido. Cada vez que o dano é causado ou 1 peça aprimorada é absorvida, remove 1 pilha de Marcas Mortais.",
  str_skill_desc_3361731 = "Selecione qualquer 1 ladrilho e, em seguida, selecione outro 1 ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> determinar uma área retangular. <link=\"30065\"><#FFAE07><u>Absorve</u></color></link> a <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> nesta área e negócios <color=#00F6FF>100%</color> dano aos inimigos dentro desta área. Aumenta o dano final em <color=#00F6FF>50%</color> para cada 1 ladrilho aprimorado absorvido. Cada vez que o dano é causado ou 1 peça aprimorada é absorvida, remove 1 pilha de Marcas Mortais. A habilidade ativa pode ser lançada mais 1 vez após entrar no Aurora Time.",
  str_skill_name_2001731 = "Fim Fantasmático",
  str_skill_name_2001732 = "Fim Fantasmático",
  str_skill_name_2001733 = "Fim Fantasmático",
