  str_skill_name_2301733 = "Fim Fantasmático",
  str_skill_desc_2001731 = "Ofertas <color=#00F6FF>140%</color> dano aos alvos mais próximos e mais distantes, mas os danos subsequentes causados aos mesmos alvos são <color=#00F6FF>metade</color>. Invocação <color=#00F6FF>até 1</color> <link=\"20001\"><#FFAE07><u>bloco aprimorado</u></color></link> aos pés dos alvos.",
  str_skill_desc_2001732 = "Ofertas <color=#00F6FF>160%</color> dano aos alvos mais próximos e mais distantes, mas os danos subsequentes causados aos mesmos alvos são <color=#00F6FF>metade</color>. Invocação <color=#00F6FF>até 1</color> <link=\"20001\"><#FFAE07><u>bloco aprimorado</u></color></link> aos pés dos alvos.",
  str_skill_desc_2001733 = "Ofertas <color=#00F6FF>180%</color> dano aos alvos mais próximos e mais distantes, mas os danos subsequentes causados aos mesmos alvos são <color=#00F6FF>metade</color>. Invocação <color=#00F6FF>até 1</color> <link=\"20001\"><#FFAE07><u>bloco aprimorado</u></color></link> aos pés dos alvos.",
  str_skill_desc_2301731 = "Ofertas <color=#00F6FF>140%</color> dano aos alvos mais próximos e mais distantes, mas os danos subsequentes causados aos mesmos alvos são <color=#00F6FF>metade</color>. Invocação <color=#00F6FF>até 1</color> <link=\"20001\"><#FFAE07><u>bloco aprimorado</u></color></link> aos pés dos alvos.",
  str_skill_desc_2301732 = "Ofertas <color=#00F6FF>160%</color> dano aos alvos mais próximos e mais distantes, mas os danos subsequentes causados aos mesmos alvos são <color=#00F6FF>metade</color>. Invocação <color=#00F6FF>até 1</color> <link=\"20001\"><#FFAE07><u>bloco aprimorado</u></color></link> aos pés dos alvos.",
  str_skill_desc_2301733 = "Ofertas <color=#00F6FF>180%</color> dano aos alvos mais próximos e mais distantes, mas os danos subsequentes causados aos mesmos alvos são <color=#00F6FF>metade</color>. Invocação <color=#00F6FF>até 1</color> <link=\"20001\"><#FFAE07><u>bloco aprimorado</u></color></link> aos pés dos alvos.",
  str_skill_passive_name_410173 = "Liberação Onipotente",
  str_skill_passive_name_420173 = "Liberação Onipotente",
  str_skill_passive_name_423173 = "Liberação Onipotente",
  str_skill_passive_desc_410173 = "Ofertas imediatas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> alvo aleatório em campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> (Incluindo <link=\"30065\"><#FFAE07><u>absorvente</u></color></link>).",
  str_skill_passive_desc_420173 = "Ofertas imediatas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> alvo aleatório em campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> (Incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> Marca Mortal acumula e reduz <color=#00F6FF>1</color> empilhar para cada peça aprimorada obtida. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>20%</color>, permitindo que seus ataques normais atinjam ladrilhos diagonais, aumentando o dano de Habilidade de Equipamento para <color=#00F6FF>2,5</color> vezes, e permitindo que seu Chain Combo cause dano normal ao atingir o mesmo alvo novamente.",
  str_skill_passive_desc_423173 = "Ofertas imediatas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>1</color> alvo aleatório em campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> (Incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> Marca Mortal acumula e reduz <color=#00F6FF>1</color> empilhar para cada peça aprimorada obtida. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>25%</color>, permitindo que seus ataques normais atinjam ladrilhos diagonais, aumentando o dano de Habilidade de Equipamento para <color=#00F6FF>2,5</color> vezes, e permitindo que seu Chain Combo cause dano normal ao atingir o mesmo alvo novamente.",
