  str_skill_passive_name_430172 = "Guardado na câmera",
  str_skill_desc_2001721 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 aglomerado ao redor</color>. Se estiver do lado de fora de um <color=#00F6FF>matriz deslumbrante</color>, gera uma matriz deslumbrante que abrange <color=#00F6FF>1 aglomerado ao redor</color> no local atual.",
  str_skill_desc_2001722 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 aglomerado ao redor</color>. Se estiver do lado de fora de um <color=#00F6FF>matriz deslumbrante</color>, gera uma matriz deslumbrante que abrange <color=#00F6FF>1 aglomerado ao redor</color> no local atual.",
  str_skill_desc_2001723 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>12 telhas em forma de diamante</color>. Se estiver do lado de fora de um <color=#00F6FF>matriz deslumbrante</color>, gera uma matriz deslumbrante que abrange <color=#00F6FF>12 telhas em forma de diamante</color> no local atual.",
  str_skill_desc_3001721 = "Teleporta para qualquer local dentro de um <link=\"30066\"><#FFAE07><u>matriz deslumbrante</u></color></link>. Só pode haver <color=#00F6FF>2</color> matrizes deslumbrantes no campo a qualquer momento.",
  str_skill_desc_3201721 = "Teleporta para qualquer local dentro de um <link=\"30066\"><#FFAE07><u>matriz deslumbrante</u></color></link> e ofertas <color=#00F6FF>{1}%</color> danos às telhas dentro do vão do <color=#00F6FF>matriz deslumbrante</color>. Só pode haver <color=#00F6FF>2</color> matrizes deslumbrantes no campo a qualquer momento.",
  str_skill_desc_3031721 = "Teleporta para qualquer local dentro de um <link=\"30067\"><#FFAE07><u>matriz deslumbrante</u></color></link>. Só pode haver <color=#00F6FF>3</color> matrizes deslumbrantes no campo a qualquer momento.",
  str_skill_desc_3231721 = "Teleporta para qualquer local dentro de um <link=\"30067\"><#FFAE07><u>matriz deslumbrante</u></color></link> e ofertas <color=#00F6FF>{1}%</color> danos às telhas dentro do vão do <color=#00F6FF>matriz deslumbrante</color>. Só pode haver <color=#00F6FF>3</color> matrizes deslumbrantes no campo a qualquer momento.",
  str_skill_desc_3061721 = "Teleporta para qualquer local dentro de um <link=\"30068\"><#FFAE07><u>matriz deslumbrante</u></color></link>. Só pode haver <color=#00F6FF>3</color> matrizes deslumbrantes no campo a qualquer momento.",
  str_skill_desc_3261721 = "Teleporta para qualquer local dentro de um <link=\"30068\"><#FFAE07><u>matriz deslumbrante</u></color></link> e ofertas <color=#00F6FF>{1}%</color> danos às telhas dentro do vão do <color=#00F6FF>matriz deslumbrante</color>. Só pode haver <color=#00F6FF>3</color> matrizes deslumbrantes no campo a qualquer momento.",
  str_skill_passive_desc_410172 = "Ganhe um escudo igual a <color=#00F6FF>{1}</color> do DEF atual de Lilica para cada ladrilho percorrido dentro de um <color=#00F6FF>matriz deslumbrante</color>.",
  str_skill_passive_desc_430172 = "Ganhe um escudo igual a <color=#00F6FF>{1}</color> do DEF atual de Lilica para cada ladrilho percorrido dentro de um <color=#00F6FF>matriz deslumbrante</color>. No final da rodada, causa dano verdadeiro igual ao escudo restante em todas as peças dentro do intervalo de todas <color=#00F6FF>matrizes deslumbrantes</color>.",
  str_skill_upgrade_desc_16017213 = "Aprimoramento de Habilidade Ativa: Só pode haver <color=#00F6FF>3</color> matrizes deslumbrantes no campo a qualquer momento.",
  str_skill_upgrade_desc_16017216 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate. No início da batalha, gera uma matriz deslumbrante que é <color=#00F6FF>12 telhas em forma de diamante</color> no local de partida.",
  str_skill_name_29038011 = "Aí está você!",
  str_skill_desc_29038011 = "Sempre que um Auroriano está por perto, Astor se vira para o jogador, causando dano a unidades próximas em uma área em forma de diamante e repelindo-as.",
  str_skill_name_29038012 = "Quer Fugir?",
  str_skill_desc_29038012 = "Sempre que um Auroriano está dentro de um alcance em forma de cruz ao redor de Astor, Astor se vira para o jogador e ataca-o, causando dano à unidade à sua frente e repelindo-o.",
  str_skill_upgrade_desc_14016912 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_14016915 = "Aprimoramento de Habilidade Ativa: A Habilidade Ativa repele o alvo por <color=#FFFF00>3</color> azulejos.",
  str_skill_name_2001691 = "Derrube-os",
  str_skill_name_2001692 = "Derrube-os",
  str_skill_name_2001693 = "Derrube-os",
  str_skill_desc_2001691 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de cruz</color>.",
  str_skill_desc_2001692 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2001693 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_name_300169 = "Bola aérea",
  str_skill_name_305169 = "Bola aérea",
  str_skill_name_330169 = "Bola aérea",
  str_skill_name_335169 = "Bola aérea",
  str_skill_desc_300169 = "Ofertas <color=#00F6FF>300%</color> dano a 1 inimigo adjacente em um <color=#00F6FF>forma de cruz</color> e o repele por 2 ladrilhos. Quando <color=#00F6FF>bloqueado</color> ao ser empurrado para trás, leva um tempo adicional <color=#00F6FF>200%</color> dano e é <color=#00F6FF>atordoado</color> por 1 rodada.",
  str_skill_desc_305169 = "Ofertas <color=#00F6FF>300%</color> dano a 1 inimigo adjacente em um <color=#00F6FF>forma de cruz</color> e o empurra para trás por 3 peças. Quando <color=#00F6FF>bloqueado</color> ao ser empurrado para trás, é necessário um adicional <color=#00F6FF>200%</color> danos e é <color=#00F6FF>atordoado</color> para 1 rodada.",
  str_skill_desc_330169 = "Ofertas <color=#00F6FF>300%</color> dano a 1 inimigo adjacente em um <color=#00F6FF>forma de cruz</color> e o repele por 2 ladrilhos. Quando <color=#00F6FF>bloqueado</color> ao ser empurrado para trás, leva um tempo adicional <color=#00F6FF>200%</color> dano e é <color=#00F6FF>atordoado</color> por 1 rodada. Se for bloqueado por outro inimigo, esse inimigo também sofre dano e fica atordoado.",
  str_skill_desc_335169 = "Ofertas <color=#00F6FF>300%</color> dano a 1 inimigo adjacente em um <color=#00F6FF>forma de cruz</color> e o repele por 3 ladrilhos. Quando <color=#00F6FF>bloqueado</color> ao ser empurrado para trás, leva um tempo adicional <color=#00F6FF>200%</color> dano e é <color=#00F6FF>atordoado</color> por 1 rodada. Se for bloqueado por outro inimigo, esse inimigo também sofre dano e fica atordoado.",
  str_skill_passive_name_410169 = "Balanço do batedor",
  str_skill_passive_name_420169 = "Balanço do batedor",
  str_skill_passive_desc_410169 = "Aumenta o ATK básico de Sadie em <color=#00F6FF>{1}</color>. Sadie negocia até <color=#00F6FF>3</color> ataques normais ao conectar peças. Após 3 ataques, ganhe 1 <color=#00F6FF>Ponto de falha</color> ao fazer o próximo ataque normal. Cada Crash Point aumenta o fator de dano da Habilidade Ativa em <color=#00F6FF>{2}</color>, e todos os Crash Points são limpos após usar a Active Skill.",
  str_skill_passive_desc_420169 = "Aumenta o ATK básico de Sadie em <color=#00F6FF>{1}</color>. Sadie negocia até <color=#00F6FF>3</color> ataques normais ao conectar peças, e o 3º ataque normal causa o dobro de dano. Após 3 ataques, ganhe 1 <color=#00F6FF>Ponto de falha</color> ao fazer o próximo ataque normal. Cada Crash Point aumenta o fator de dano da Habilidade Ativa em <color=#00F6FF>{2}</color>, e todos os Crash Points são apagados após usar a Active Skill.",
  str_skill_desc_1601751001 = "Casa de Prisma",
  str_skill_desc_1601751003 = "Katana",
  str_skill_desc_1601751004 = "farol de ataque aéreo",
  str_skill_desc_1601751005 = "Abelha Mecânica",
  str_skill_desc_1601751006 = "Mina de Flechas Solares",
  str_skill_desc_1601751007 = "Bandeira",
  str_skill_desc_1601751008 = "Lanterna",
  str_skill_desc_1601751009 = "Lagarto de Ferro",
  str_skill_desc_1601751010 = "Casa Escura",
  str_skill_desc_160175101 = "consome <color=#00F6FF>2</color> Energia cúbica para converter qualquer 1 bloco em um bloco de prisma.",
  str_skill_desc_160175103 = "consome <color=#00F6FF>2</color> Energia cúbica para convocar 1 Katana em qualquer peça atravessável sem uma Katana existente nela.",
  str_skill_desc_160175104 = "consome <color=#00F6FF>1</color> Energia cúbica para invocar 1 Air Raid Beacon em qualquer ladrilho atravessável sem um Air Raid Beacon existente.",
  str_skill_desc_160175105 = "consome <color=#00F6FF>1</color> Energia cúbica para convocar 1 Abelha Mecânica em qualquer ladrilho atravessável dentro de 3 grupos circundantes sem uma Abelha Mecânica existente nele. Até 4 abelhas mecânicas podem existir no campo de batalha por vez.",
  str_skill_desc_160175106 = "consome <color=#00F6FF>1</color> Energia cúbica para invocar 1 Solar Arrow Mine em qualquer ladrilho atravessável sem uma Solar Arrow Mine existente.",
  str_skill_desc_160175107 = "consome <color=#00F6FF>3</color> Energia cúbica para convocar 1 Estandarte em qualquer ladrilho atravessável. Até 1 Estandarte pode existir no campo de batalha por vez.",
  str_skill_desc_160175108 = "consome <color=#00F6FF>4</color> Energia cúbica para convocar 1 Lanterna em qualquer ladrilho atravessável sem uma Lanterna existente. Até 1 Lanterna pode existir no campo de batalha por vez.",
  str_skill_desc_160175109 = "Consome <color=#00F6FF>2</color> energia cúbica para invocar 1 Lagarto de Ferro em 1 casa selecionada e percorrida sem Lagarto de Ferro.",
  str_skill_desc_160175110 = "Consome <color=#00F6FF>2</color> Energia Cúbica para converter qualquer 1 ladrilho em um Ladrilho Escuro.",
  str_skill_upgrade_desc_16017513 = "Aprimoramento de Habilidade Ativa: Ganhos <color=#FFFF00>2</color> Energia cúbica no início da batalha.",
  str_skill_upgrade_desc_16017516 = "Aprimoramento de Habilidade Ativa: Após Healing Orbs estarem no campo por 0/1/2 rodadas, o fator de recuperação aumenta <color=#FFFF00>40%/100%/250%</color> para aliados que passam por ele.\nO fator de recuperação aumenta <color=#FFFF00>80%/180%/400%</color> quando um orbe é absorvido com a habilidade ativa de Axelia.",
  str_skill_name_30017511 = "Pirueta Celestial",
  str_skill_name_30317511 = "Pirueta Celestial",
  str_skill_name_30617511 = "Pirueta Celestial",
  str_skill_name_32017511 = "Pirueta Celestial",
  str_skill_name_32317511 = "Pirueta Celestial",
  str_skill_name_32617511 = "Pirueta Celestial",
  str_skill_name_33017511 = "Pirueta Celestial",
  str_skill_name_33317511 = "Pirueta Celestial",
  str_skill_name_33617511 = "Pirueta Celestial",
  str_skill_name_30017513 = "Pirueta Celestial",
  str_skill_desc_30017511 = "Consome 1 <link=\"30069\"><#FFAE07><u>energia cúbica</u></color></link> invocar 1 <link=\"30072\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos.",
  str_skill_desc_30317511 = "Consome 1 <link=\"30070\"><#FFAE07><u>energia cúbica</u></color></link> invocar 1 <link=\"30072\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos.",
  str_skill_desc_30617511 = "Consome 1 <link=\"30070\"><#FFAE07><u>energia cúbica</u></color></link> convocar 1 <link=\"30073\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos.",
  str_skill_desc_32017511 = "Consome 1 <link=\"30069\"><#FFAE07><u>energia cúbica</u></color></link> invocar 1 <link=\"30072\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada.",
  str_skill_desc_32317511 = "Consome 1 <link=\"30070\"><#FFAE07><u>energia cúbica</u></color></link> invocar 1 <link=\"30072\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada.",
  str_skill_desc_32617511 = "Consome 1 <link=\"30070\"><#FFAE07><u>energia cúbica</u></color></link> convocar 1 <link=\"30073\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada.",
  str_skill_desc_33017511 = "Consome 1 <link=\"30069\"><#FFAE07><u>energia cúbica</u></color></link> convocar 1 <link=\"30072\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada. Axelia pode usar o <link=\"30071\"><#FFAE07><u>Módulo de autoridade</u></color></link> para convocar os objetos invocáveis de certas habilidades ativas de outros Thunder Aurorians.",
  str_skill_desc_33317511 = "Consome 1 <link=\"30070\"><#FFAE07><u>energia cúbica</u></color></link> convocar 1 <link=\"30072\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada. Axelia pode usar o <link=\"30071\"><#FFAE07><u>Módulo de autoridade</u></color></link> para convocar os objetos invocáveis de certas habilidades ativas de outros Thunder Aurorians.",
  str_skill_desc_33617511 = "Consome 1 <link=\"30070\"><#FFAE07><u>energia cúbica</u></color></link> invocar 1 <link=\"30073\"><#FFAE07><u>Orbe de Cura</u></color></link> em qualquer ladrilho atravessável ou para selecionar um Healing Orb já no campo e absorvê-lo para recuperar HP com base no número de rodadas que ele esteve no campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada. Axelia pode usar o <link=\"30071\"><#FFAE07><u>Módulo de autoridade</u></color></link> para convocar os objetos invocáveis de certas habilidades ativas de outros Thunder Aurorians.",
  str_skill_desc_330175111 = "Consome 1 <color=#D1970C><b>energia cúbica</b></color> para convocar 1 Healing Orb em qualquer ladrilho atravessável, que restaurará HP igual a <color=#D1970C><b>40%/100%/200%</b></color> do ATK de Axelia para os aurorianos que passarem por este orbe após ele estar em campo por <color=#D1970C><b>0/1/2</b></color> rodadas. Como alternativa, selecione um Healing Orb já no campo e absorva-o para recuperar HP igual a <color=#D1970C><b>40%/100%/200%</b></color> do ATK de Axelia com base no número de rodadas em campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada.",
  str_skill_desc_336175111 = "Consome 1 <color=#D1970C><b>energia cúbica</b></color> para convocar 1 Healing Orb em qualquer ladrilho atravessável, que restaurará HP igual a <color=#D1970C><b>40%/100%/250%</b></color> do ATK de Axelia para os aurorianos que passarem por este orbe após ele estar em campo por <color=#D1970C><b>0/1/2</b></color> rodadas. Como alternativa, selecione um Healing Orb já no campo e absorva-o para recuperar HP igual a <color=#D1970C><b>80%/180%/400%</b></color> do ATK de Axelia com base no número de rodadas em campo. Healing Orbs desaparecem quando tocados por inimigos, retornando 1 Cubic Energy cada.",
  str_skill_passive_name_4101751 = "Interruptor Cúbico",
  str_skill_passive_desc_4101751 = "Após um Thunder Aurorian da equipe usar uma Habilidade Ativa, Axelia ganha <color=#00F6FF>1</color> pilha de Energia de Conversão. Usar um Chain Combo limpa todas as pilhas de energia de conversão e negócios <color=#00F6FF>{1}</color> dano para cada pilha para o inimigo com o maior HP no campo.",
  str_skill_name_2001751 = "Bênção Celestial",
  str_skill_name_2001752 = "Bênção Celestial",
  str_skill_name_2001753 = "Bênção Celestial",
  str_skill_desc_2001751 = "Recupera o HP da equipe por <color=#00F6FF>135%</color> do ATK de Axelia.",
  str_skill_desc_2001752 = "Recupera o HP da equipe por <color=#00F6FF>160%</color> do ATK de Axelia.",
  str_skill_desc_2001753 = "Recupera o HP da equipe por <color=#00F6FF>190%</color> do ATK de Axelia.",
  str_skill_name_29036011 = "Corrosão",
  str_skill_desc_29036011 = "Causa dano severo ao alvo quando um Aurorian está dentro de 1 aglomerado circundante de Diavola e inflige Toxina.",
  str_skill_name_29036012 = "isca de minhoca",
  str_skill_desc_29036012 = "Quando os aurorianos se afastam de Diavola, Dawn Sprites são convocados para locais aleatórios no campo.",
  str_skill_name_20006091 = "Melhoria",
  str_skill_desc_20006091 = "Quando dentro de 1 grupo circundante de Diavola, aumenta o ataque de Diavola ao se fundir com ele.",
  str_skill_name_200190101 = "Espírito da Lanterna: Link",
  str_skill_desc_200190101 = "Se o Lantern Spirit puder atravessar um auroriano ao atacar, ele causará dano e formará um vínculo com o auroriano. Caso contrário, ele apenas causará dano ao auroriano e ganhará um aumento de ACT.",
  str_skill_name_290340101 = "Asmodeus: Cadeia de Pesadelos",
  str_skill_desc_290340101 = "Asmodeus ataca todos os aurorianos dentro do alcance, ligando-se a eles com sua Cadeia de Pesadelos. Aurorians ligados à Chain of Nightmares sofrerão dano para cada 1 ladrilho que atravessarem. Se um Aurorian já estiver ligado à Chain of Nightmares quando Asmodeus atacar, ela causa mais dano e ganha Life Drain.",
  str_skill_name_290341101 = "Asmodeus: Cadeia de Pesadelos",
  str_skill_desc_290341101 = "Asmodeus ataca todos os aurorianos dentro do alcance, ligando-se a eles com sua Corrente de Pesadelos. Quando a Cadeia dos Pesadelos é quebrada, causa alto dano aos Aurorianos. Se um Aurorian já estiver ligado à Chain of Nightmares quando Asmodeus atacar, ela causa mais dano e ganha Life Drain.",
  str_skill_name_290340102 = "Asmodeus: intensificação",
  str_skill_desc_290340102 = "Se Asmodeus não conseguir atacar nenhum auroriano, seu ACT continuará aumentando até que ela atinja um auroriano.",
  str_skill_name_290340201 = "Asmodeus: Flamejante",
  str_skill_desc_290340201 = "Asmodeus se teletransporta para o ladrilho mais distante de onde ela pode atacar os aurorianos e os ataca.",
  str_skill_name_2001761 = "Tempestade Australis",
  str_skill_name_2001762 = "Tempestade Australis",
  str_skill_name_2001763 = "Tempestade Australis",
  str_skill_name_3001761 = "resplendor boreal",
  str_skill_name_3021761 = "resplendor boreal",
