  str_skill_name_3221761 = "resplendor boreal",
  str_skill_name_3251761 = "resplendor boreal",
  str_skill_name_3301761 = "resplendor boreal",
  str_skill_name_3321761 = "resplendor boreal",
  str_skill_name_3351761 = "resplendor boreal",
  str_skill_passive_name_4101761 = "Australis Booster",
  str_skill_passive_name_4151761 = "Australis Booster",
  str_skill_passive_name_4201761 = "Australis Booster",
  str_skill_passive_name_4251761 = "Australis Booster",
  str_skill_passive_name_4301761 = "Australis Booster",
  str_skill_passive_name_4351761 = "Australis Booster",
  str_skill_desc_2001761 = "Ofertas <color=#00F6FF>60%</color> dano 2 vezes a inimigos aleatórios dentro <color=#00F6FF>3 aglomerados circundantes</color>. Cada vez que o dano é causado, aumenta o número de <color=#00F6FF>Lanças Australis</color> em inimigos alvejados por 1. Ao causar dano a um alvo mais de uma vez, o dano da segunda vez é reduzido pela metade.",
  str_skill_desc_2001762 = "Ofertas <color=#00F6FF>80%</color> danifique 3 vezes a inimigos aleatórios dentro <color=#00F6FF>3 aglomerados circundantes</color>. Cada vez que o dano é causado, aumenta o número de <color=#00F6FF>Lanças Australis</color> em inimigos alvejados por 1. Ao causar dano a um alvo mais de uma vez, o dano da segunda vez é reduzido pela metade.",
  str_skill_desc_2001763 = "Ofertas <color=#00F6FF>100%</color> danifique 4 vezes a inimigos aleatórios dentro <color=#00F6FF>3 aglomerados circundantes</color>. Cada vez que o dano é causado, aumenta o número de <color=#00F6FF>Lanças Australis</color> em inimigos alvejados por 1. Ao causar dano a um alvo mais de uma vez, o dano da segunda vez é reduzido pela metade.",
  str_skill_desc_3001761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%</color> dano para cada Lança Australis puxada.",
  str_skill_desc_3021761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%</color> dano para cada Lança Australis puxada.",
  str_skill_desc_3051761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%–120%</color> dano para cada Lança Australis puxada. Quanto menor o HP atual do alvo, maior o fator de dano.",
  str_skill_desc_3201761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%</color> dano e recupera HP por <color=#00F6FF>10%</color> do dano causado desta forma para cada Lança Australis puxada.",
  str_skill_desc_3221761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%</color> dano e recupera HP por <color=#00F6FF>10%</color> do dano causado desta forma para cada Lança Australis puxada.",
  str_skill_desc_3251761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%–120%</color> dano e recupera HP por <color=#00F6FF>10%</color> do dano causado desta forma para cada Lança Australis puxada. Quanto menor o HP atual do alvo, maior o fator de dano.",
  str_skill_desc_3301761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%</color> dano e recupera HP por <color=#00F6FF>10%–15%</color> do dano causado desta forma para cada Lança Australis puxada. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_desc_3321761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%</color> dano e recupera HP por <color=#00F6FF>10%–15%</color> do dano causado desta forma para cada Lança Australis puxada. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_desc_3351761 = "Retira lanças Australis de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>80%–120%</color> dano e recupera HP por <color=#00F6FF>10%–15% de</color> o dano causado desta forma para cada <color=#00F6FF>Lança Australis</color> puxado. Quanto menor o HP atual do alvo, maior o fator de dano. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_passive_desc_4101761 = "Todo <color=#00F6FF>{1}</color> ataques normais, Beretta perfura seu alvo atual com <color=#00F6FF>1</color> <color=#00F6FF>Lança Australis</color>.",
  str_skill_passive_desc_4151761 = "Todo <color=#00F6FF>{1}</color> ataques normais, Beretta perfura seu alvo atual com <color=#00F6FF>1</color> <color=#00F6FF>Lança Australis</color>.",
  str_skill_passive_desc_4201761 = "Todo <color=#00F6FF>{1}</color> ataques normais, Beretta perfura seu alvo atual com <color=#00F6FF>1</color> <color=#00F6FF>Lança Australis</color>.",
  str_skill_passive_desc_4251761 = "Todo <color=#00F6FF>{1}</color> ataques normais, Beretta perfura seu alvo atual com <color=#00F6FF>1</color> <color=#00F6FF>Lança Australis</color>.",
  str_skill_passive_desc_4301761 = "Todo <color=#00F6FF>{1}</color> ataques normais, Beretta perfura seu alvo atual com <color=#00F6FF>1</color> <color=#00F6FF>Lança Australis</color>.",
  str_skill_passive_desc_4351761 = "Todo <color=#00F6FF>{1}</color> ataques normais, Beretta perfura seu alvo atual com <color=#00F6FF>1</color> <color=#00F6FF>Lança Australis</color>.",
  str_skill_upgrade_desc_15017612 = "Aprimoramento de Habilidade Ativa: Aumenta o alcance da habilidade para <color=#FFFF00>3 aglomerados circundantes</color>.",
  str_skill_upgrade_desc_15017615 = "Aprimoramento de Habilidade Ativa: Quanto menor o HP do alvo, maior o fator de dano, até <color=#00F6FF>40%</color>.",
  str_skill_name_290350103 = "Cerritus: Esmagamento Destruidor",
  str_skill_desc_290350103 = "Cerritus quebra os ladrilhos sob seus pés e ataca os aurorianos, derrubando-os e destruindo todos os seixos ao longo de seu caminho e infligindo aos aurorianos que ele colide com Exausto.",
  str_skill_name_290350104 = "Cerritus: Terremoto Devastador",
  str_skill_desc_290350104 = "Cerritus esmaga os 2 ladrilhos à sua frente depois de se mover, causando dano massivo e quebrando os ladrilhos.",
  str_skill_desc_290350203 = "Cerritus quebra os ladrilhos sob seus pés e ataca os aurorianos, derrubando-os e destruindo todos os seixos ao longo de seu caminho.",
  str_skill_desc_290350204 = "Cerritus esmaga os 2 ladrilhos à sua frente depois de se mover, causando dano massivo e quebrando os ladrilhos. Os aurorianos ganharão o estado Exausto após receberem dano.",
  str_skill_name_216003811 = "Megachoque!",
  str_skill_desc_216003811 = "Phantom Gronru causa dano a 1 coluna.",
  str_skill_name_91001641 = "Melhoria",
  str_skill_desc_91001641 = "Aumenta o ACT e o ATK de todos os Eclipsites, exceto ele mesmo. Este efeito pode acumular.",
  str_skill_name_290290101 = "Ganância: Surto",
  str_skill_desc_290290101 = "Esmaga os aurorianos vizinhos, causando dano massivo que ignora a defesa inimiga e os repele em 1 ladrilho. Se os 4 ladrilhos ao lado dos aurorianos forem bloqueados, eles serão derrotados instantaneamente.",
  str_skill_desc_290291131 = "Esmaga os aurorianos vizinhos, derrotando-os instantaneamente!",
  str_skill_name_290290104 = "Ganância: Fratura",
  str_skill_desc_290290104 = "Se não houver aurorianos adjacentes, ele se desloca 1 ladrilho na direção da localização atual dos aurorianos e causa dano de área dentro de 1 aglomerado ao redor de sua cabeça.",
  str_skill_name_290290100 = "Corpo de Jormungand",
  str_skill_desc_290290100 = "O corpo de Jormungand é protegido por uma energia especial que pode anular todos os ataques. Seu corpo tem a capacidade de se replicar.",
  str_skill_name_290290102 = "Cauda de Jormungand",
  str_skill_desc_290290102 = "O dano causado em sua cauda é transmitido para sua cabeça.",
