  str_skill_desc_3331801 = "Converte o <color=#00F6FF>4</color> Azulejos Azuis mais próximos do Verde. Aleatoriamente inflige um <color=#00F6FF>marca de vigilância</color> na metade dos inimigos no campo, então gera um <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> sob os pés de até <color=#00F6FF>3</color> inimigos marcados. Se a Habilidade Ativa estiver pronta na última rodada, converte <color=#00F6FF>+1</color> telha nesta rodada.",
  str_skill_desc_3351801 = "Converte o <color=#00F6FF>5</color> Azulejos Azuis mais próximos do Verde. Aleatoriamente inflige um <color=#00F6FF>marca de vigilância</color> na metade dos inimigos no campo, então gera um <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> sob os pés de até <color=#00F6FF>3</color> inimigos marcados. Se a Habilidade Ativa estiver pronta na última rodada, converte <color=#00F6FF>+1</color> telha nesta rodada.",
  str_skill_desc_2001801 = "Ofertas <color=#00F6FF>{1}%</color> danos ao mais próximo e <color=#00F6FF>menor</color> inimigo.",
  str_skill_desc_2001802 = "Ofertas <color=#00F6FF>{1}%</color> danos ao mais próximo e <color=#00F6FF>menor</color> inimigo.",
  str_skill_desc_2001803 = "Ofertas <color=#00F6FF>{1}%</color> danos ao mais próximo e <color=#00F6FF>menor</color> inimigo.",
  str_skill_desc_2201801 = "Ofertas <color=#00F6FF>{1}%</color> danos ao mais próximo e <color=#00F6FF>menor</color> inimigo, então inflige um </color>marca de vigilância<color=#00F6FF> nele.",
  str_skill_desc_2201802 = "Ofertas <color=#00F6FF>{1}%</color> danos ao mais próximo e <color=#00F6FF>menor</color> inimigo, então inflige um </color>marca de vigilância<color=#00F6FF> nele.",
  str_skill_desc_2201803 = "Ofertas <color=#00F6FF>{1}%</color> danos ao mais próximo e <color=#00F6FF>menor</color> inimigo, então inflige um </color>marca de vigilância<color=#00F6FF> nele.",
  str_skill_passive_desc_410180 = "As Habilidades Ativas infligem um <color=#00F6FF>marca de vigilância</color> nos inimigos que aumenta o dano final que eles recebem das habilidades de Chain Combo de instância única em <color=#00F6FF>{1}</color>. Dura até o final da rodada auroriana.",
  str_skill_passive_desc_420180 = "Habilidades ativas e combos em cadeia infligem uma <color=#00F6FF>marca de vigilância</color> nos inimigos que aumenta o dano final que eles recebem das habilidades de Chain Combo de instância única em <color=#00F6FF>{1}</color>. Dura até o final da rodada auroriana.",
  str_skill_name_2001781 = "Mergulho e Retiro",
  str_skill_name_2001782 = "Mergulho e Retiro",
  str_skill_name_2001783 = "Mergulho e Retiro",
  str_skill_name_20017812 = "Mergulho e Retiro",
  str_skill_name_20017822 = "Mergulho e Retiro",
  str_skill_name_20017832 = "Mergulho e Retiro",
  str_skill_name_3001780 = "Caça e Golpe",
  str_skill_desc_2001781 = "Negociações aleatórias <color=#00F6FF>100%</color> dano a 3 inimigos diferentes no campo.",
  str_skill_desc_2001782 = "Negociações aleatórias <color=#00F6FF>120%</color> dano a 3 inimigos diferentes no campo.",
  str_skill_desc_2001783 = "Negociações aleatórias <color=#00F6FF>140%</color> dano a 3 inimigos diferentes no campo.",
  str_skill_desc_20017812 = "Negociações aleatórias <color=#00F6FF>100%</color> dano a 3 inimigos diferentes no campo. Se as peças azuis estiverem conectadas nesta rodada, Vic convoca bestas maravilhosas em vez disso, cada uma atacando seu próprio alvo (pode acabar sendo o mesmo alvo).",
  str_skill_desc_20017822 = "Negociações aleatórias <color=#00F6FF>120%</color> dano a 3 inimigos diferentes no campo. Se as peças azuis estiverem conectadas nesta rodada, Vic convoca bestas maravilhosas em vez disso, cada uma atacando seu próprio alvo (pode acabar sendo o mesmo alvo).",
  str_skill_desc_20017832 = "Negociações aleatórias <color=#00F6FF>140%</color> dano a 3 inimigos diferentes no campo. Se as peças azuis estiverem conectadas nesta rodada, Vic convoca bestas maravilhosas em vez disso, cada uma atacando seu próprio alvo (pode acabar sendo o mesmo alvo).",
  str_skill_desc_3001780 = "Invoca 3 bestas maravilhosas que priorizam a negociação <color=#00F6FF>200%</color> danos aos seus respectivos alvos.\nLittle Furball: O inimigo com mais marcas de status.\nBica: O inimigo com menor HP.\nCoruja Lutumi: O inimigo mais distante.",
  str_skill_passive_name_410178 = "Liberação e Perseguição",
  str_skill_passive_name_420178 = "Liberação e Perseguição",
  str_skill_passive_name_430178 = "Liberação e Perseguição",
  str_skill_passive_name_436178 = "Liberação e Perseguição",
  str_skill_passive_desc_410178 = "Se as peças azuis estiverem conectadas nesta rodada, em vez de aplicar um ataque normal, as bestas maravilhosas atacam seus respectivos alvos uma vez para cada peça atravessada, causando <color=#00F6FF>{1}</color> dano.\nTodo dano causado por bestas maravilhosas não se beneficia dos bônus de combo em cadeia.",
  str_skill_passive_desc_420178 = "Se as peças azuis estiverem conectadas nesta rodada, em vez de aplicar um ataque normal, as bestas maravilhosas atacam seus respectivos alvos uma vez para cada peça atravessada, causando <color=#00F6FF>{1}</color> dano.\nTodo dano causado por bestas maravilhosas não se beneficia dos bônus de combo em cadeia.",
  str_skill_passive_desc_430178 = "Se as peças azuis estiverem conectadas nesta rodada, em vez de aplicar um ataque normal, as bestas maravilhosas atacam seus respectivos alvos uma vez para cada peça atravessada, causando <color=#00F6FF>{1}</color> dano.\nTodo dano causado por bestas maravilhosas não se beneficia dos bônus de combo em cadeia. O dano final é aumentado em <color=#00F6FF>10%</color> se os alvos atenderem às condições correspondentes.\nLittle Furball: O inimigo tem pelo menos <color=#00F6FF>4</color> marcas de estado.\nBica: O inimigo tem menos de <color=#00F6FF>30%</color> HP.\nCoruja Lutumi: O inimigo é pelo menos <color=#00F6FF>4</color> telhas de distância.",
  str_skill_passive_desc_436178 = "Se as peças azuis estiverem conectadas nesta rodada, em vez de aplicar um ataque normal, as bestas maravilhosas atacam seus respectivos alvos uma vez para cada peça atravessada, causando <color=#00F6FF>{1}</color> dano.\nTodo dano causado por bestas maravilhosas não se beneficia dos bônus de combo em cadeia. O dano final é aumentado em <color=#00F6FF>30%</color> se os alvos atenderem às condições correspondentes.\nLittle Furball: O inimigo tem pelo menos <color=#00F6FF>4</color> marcas de estado.\nBica: O inimigo tem menos de <color=#00F6FF>30%</color> HP.\nCoruja Lutumi: O inimigo é pelo menos <color=#00F6FF>4</color> azulejos de distância.",
  str_skill_upgrade_desc_16017813 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16017816 = "Aprimoramento de habilidade de equipamento: Para todo dano causado por bestas maravilhosas, o dano final será aumentado em <color=#00F6FF>30%</color> se os alvos atenderem às condições correspondentes. (Válido para Ascensão III)",
