  str_skill_desc_2001772 = "<color=#00F6FF>Modo ídolo (9 cadeias)</color>: Restaura o HP da equipe por um valor igual a <color=#00F6FF>170%</color> do ATK de Goldie.\n<color=#00F6FF>Modo Warsong (11 cadeias)</color>: Ofertas <color=#00F6FF>150%</color> danos a <color=#00F6FF>todos os inimigos</color>.",
