  str_skill_name_3001821 = "Constrição da Serpente",
  str_skill_name_3101821 = "Constrição da Serpente",
  str_skill_name_3201821 = "Constrição da Serpente",
  str_skill_desc_2001821 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_2001822 = "Se o 1º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 1º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>9 ladrilhos em formato quadrado</color>.",
  str_skill_desc_2001823 = "Se o 2º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 2º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>.",
  str_skill_desc_2001824 = "Se o 3º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 3º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>.",
  str_skill_desc_2031821 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 cluster circundante</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2031822 = "Se o 1º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 1º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>9 ladrilhos em formato quadrado</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2031823 = "Se o 2º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 2º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>3</color>.",
  str_skill_desc_2031824 = "Se o 3º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 3º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>7</color>.",
  str_skill_desc_2061821 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 cluster circundante</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2061822 = "Se o 1º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 1º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2061823 = "Se o 2º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 2º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>3</color>.",
  str_skill_desc_2061824 = "Se o 3º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 3º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>25 ladrilhos em formato quadrado</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>7</color>.",
  str_skill_desc_2301821 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_2301822 = "Se o 1º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 1º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>9 ladrilhos em formato quadrado</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2301823 = "Se o 2º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 2º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2301824 = "Se o 3º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 3º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2331821 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 cluster circundante</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2331822 = "Se o 1º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 1º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>9 ladrilhos em formato quadrado</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color> e o custo de desencadeamento é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2331823 = "Se o 2º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 2º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color> e o custo de desencadeamento é reduzido para <color=#00F6FF>3</color>.",
  str_skill_desc_2331824 = "Se o 3º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 3º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color> e o custo de desencadeamento é reduzido para <color=#00F6FF>7</color>.",
  str_skill_desc_2361821 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 cluster circundante</color>. Durante o Aurora Time, o custo de ativação é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2361822 = "Se o 1º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 1º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color> e o custo de desencadeamento é reduzido para <color=#00F6FF>0</color>.",
  str_skill_desc_2361823 = "Se o 2º Serpent Flare estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 2º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color> e o custo de desencadeamento é reduzido para <color=#00F6FF>3</color>.",
  str_skill_desc_2361824 = "Se o 3º Serpent Flare já estiver aceso, desencadeia o Chain Combo do <color=#00F6FF>nível anterior</color>. Caso contrário, acende o 3º Serpent Flare e pula em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>180%</color> danos a <color=#00F6FF>25 ladrilhos em formato quadrado</color>. Durante o Aurora Time, o alcance do salto se expande em <color=#00F6FF>2 aglomerados circundantes</color> e o custo de desencadeamento é reduzido para <color=#00F6FF>7</color>.",
  str_skill_desc_3001821 = "A Habilidade Ativa pode ser liberada quando <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Sinalizadores de Serpente</u></color></link> estão acesos. Seleciona 1 ladrilho e negocia <color=#00F6FF>300%</color> danos a <color=#00F6FF>9 ladrilhos em formato quadrado</color>. Todos os Serpent Flares serão extintos após o uso da Habilidade Ativa.",
  str_skill_desc_3101821 = "A Habilidade Ativa pode ser liberada quando <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Sinalizadores de Serpente</u></color></link> estão acesos. Seleciona 1 ladrilho e negocia <color=#00F6FF>300%</color> danos a <color=#00F6FF>9 ladrilhos em formato quadrado</color>. Todos os Serpent Flares serão extintos após o uso da Habilidade Ativa.",
  str_skill_desc_3201821 = "A Habilidade Ativa pode ser liberada quando <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Sinalizadores de Serpente</u></color></link> estão acesos. Seleciona 1 ladrilho e negocia <color=#00F6FF>300%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Todos os Serpent Flares serão extintos após o uso da Habilidade Ativa.",
