  str_skill_passive_desc_433182 = "Ofertas <color=#00F6FF>{1}</color> danos a <color=#00F6FF>todos</color> inimigos ao usar a Habilidade Ativa.",
  str_skill_upgrade_desc_16018213 = "Aprimoramento do Chain Combo: Durante o Aurora Time, o custo de ativação do Chain Combo <color=#00F6FF>-6</color>.",
  str_skill_upgrade_desc_16018216 = "Aprimoramento do Chain Combo: Aumenta o alcance do dano do nível <color=#00F6FF>2|3|4</color> Cadeia de combinação para <color=#00F6FF>13 ladrilhos em formato de losango | 17 ladrilhos em formato radial | 25 ladrilhos em formato quadrado</color>.",
  str_skill_name_29041011 = "Ligar",
  str_skill_desc_29041011 = "Yoh conjura uma poderosa ilusão e atrai os aurorianos para ela.\nDurante este período, ele convoca vários projéteis com uma trajetória fixa para voar pelo campo e causar dano pesado aos aurorianos ao atingi-los.\nA equipe pode se mover 5 vezes à vontade. Cada movimento é limitado a 1 peça.",
  str_skill_name_29041012 = "Ao controle",
  str_skill_desc_29041012 = "Quando há projéteis no campo, Yoh os controla, direcionando-os para os aurorianos para causar dano.\nQuando não há projéteis no campo, Yoh irá dividir e esconder. Ao receber dano, você saberá qual das réplicas é realmente ele.",
  str_skill_name_29041013 = "Vazio da Realidade",
  str_skill_desc_29041013 = "Quando há projéteis no campo, Yoh os controla, direcionando-os para os aurorianos para causar dano.\nQuando não há projéteis no campo, Yoh irá dividir e esconder. Ao receber dano, você saberá qual das réplicas é realmente ele.",
  str_skill_name_29041014 = "Discurso",
  str_skill_desc_29041014 = "Depois de se mover, as réplicas de Yoh causarão dano aos alvos em linha reta à sua frente e deixarão um projétil em seu local original.",
  str_skill_name_29041015 = "Dispersar",
  str_skill_desc_29041015 = "Yoh e suas réplicas causam dano a todos os alvos na tela.",
  str_skill_name_20022013 = "Aríete",
  str_skill_desc_20022013 = "\"Script\" causa dano pesado aos alvos na zona de perigo à frente.",
  str_skill_name_20022022 = "Ao controle",
  str_skill_desc_20022022 = "Quando a ilusão não está ativa, Yoh controla \"Palavras\", arremessando-as como projéteis para atingir diretamente os aurorianos. (Os aurorianos podem destruir projéteis durante este período para evitar danos.)",
  str_skill_name_490310106 = "Nefarious - Doce Beijo",
  str_skill_desc_490310106 = "Excluindo certas zonas seguras, Nefarious Barbara causa dano em grande área e esmaga blocos vermelhos fora das zonas seguras.",
  str_skill_name_490310107 = "Nefarious - Nota Final",
  str_skill_desc_490310107 = "Nefarious Barbara convoca aliados para o centro do tabuleiro, causando dano em tela cheia e repelindo os alvos.",
  str_skill_desc_490023202 = "Vani usa energia para lançar ataques à distância em alvos dentro da área de ataque, deixando os alvos Exaustos ao acertar.",
  str_skill_desc_490023212 = "Vani usa energia para lançar ataques à distância em alvos dentro da área de ataque, deixando os alvos Cegos ao acertar.",
  str_skill_desc_480043414 = "Mara Sol convoca vários Chasms para o campo. O número de Chasms é determinado pelas pilhas de Chasm Strike de Mara Sol acumuladas durante a primeira onda.",
  str_skill_desc_400012401 = "Convoca Chasms para o campo de batalha a cada rodada.",
  str_skill_upgrade_desc_16018113 = "Aprimoramento de Habilidade de Equipamento: Ganhe 5 Pontos de Insight ao entrar em batalha e <color=#00F6FF>5</color> Insight Points no início de cada onda.",
  str_skill_upgrade_desc_16018116 = "Aprimoramento de Habilidade de Equipamento: Zhong Xu ganha Insight Points sempre que passa <color=#00F6FF>ladrilhos de qualquer elemento</color>.",
  str_skill_name_2001811 = "Chamas Impiedosas",
  str_skill_name_2001812 = "Chamas Impiedosas",
  str_skill_name_2001813 = "Chamas Impiedosas",
  str_skill_desc_2001811 = "Causa <color=#00F6FF>{1}%</color> de dano a 3 inimigos em <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_2001812 = "Causa <color=#00F6FF>{1}%</color> de dano a 3 inimigos em <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_desc_2001813 = "Ofertas <color=#00F6FF>{1}%</color> dano a 3 inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color>.",
