  str_skill_name_300181122 = "Estratégia Indomável",
  str_skill_name_300181123 = "Estratégia Indomável",
  str_skill_name_32018112 = "Estratégia Indomável",
  str_skill_name_320181121 = "Estratégia Indomável",
  str_skill_name_320181122 = "Estratégia Indomável",
  str_skill_name_320181123 = "Estratégia Indomável",
  str_skill_name_33018112 = "Estratégia Indomável",
  str_skill_name_330181121 = "Estratégia Indomável",
  str_skill_name_330181122 = "Estratégia Indomável",
  str_skill_name_330181123 = "Estratégia Indomável",
  str_skill_desc_3001811 = "Convoca <color=#00F6FF>1</color> Chama Ancestral e converte o ladrilho selecionado em um ladrilho Vermelho. A Chama Ancestral pode ser convocada para um ladrilho em que um inimigo está e se moverá junto com o alvo. <color=#00F6FF>Antes de mover e conectar as peças</color>, todas as peças ao longo do caminho percorrido pela Chama Ancestral serão <color=#00F6FF>convertidas em ladrilhos Vermelhos</color>. As Chamas Ancestrais nos inimigos desaparecerão <color=#00F6FF>quando os Aurorianos começarem a se mover ao longo dos ladrilhos conectados</color>.",
  str_skill_desc_30018112 = "Consome 8 Pontos de Insight. Força 1 inimigo não-chefe a mover 1 ladrilho. Só pode ser lançado 1 vez a cada rodada.",
  str_skill_desc_300181121 = "Consome 7 Pontos de Insight. Força 1 inimigo não-chefe a mover 1 ladrilho. Só pode ser lançado 1 vez a cada rodada.",
  str_skill_desc_300181122 = "Consome 6 Pontos de Insight. Força 1 inimigo não-chefe a mover 1 ladrilho. Só pode ser lançado 1 vez a cada rodada.",
  str_skill_desc_300181123 = "Consome 5 Pontos de Insight. Força 1 inimigo não-chefe a mover 1 ladrilho. Só pode ser lançado 1 vez a cada rodada.",
  str_skill_desc_32018112 = "Consome 8 Insight Points para forçar 1 inimigo não-chefe a mover 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (cada uso custará <color=#00F6FF>8</color> mais pontos do que o uso anterior).",
  str_skill_desc_320181121 = "Consome 7 Insight Points para forçar 1 inimigo não-chefe a mover 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (cada uso custará <color=#00F6FF>7</color> mais pontos do que o uso anterior).",
  str_skill_desc_320181122 = "Consome 6 Insight Points para forçar 1 inimigo não-chefe a mover 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (cada uso custará <color=#00F6FF>6</color> mais pontos do que o uso anterior).",
  str_skill_desc_320181123 = "Consome 5 Insight Points para forçar 1 inimigo não-chefe a mover 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (cada uso custará <color=#00F6FF>5</color> mais pontos do que o uso anterior).",
  str_skill_desc_33018112 = "Consome 8 Insight Points para forçar 1 inimigo não-chefe a mover 1 ladrilho, ou consome 8 Insight Points para mover Chama Ancestral 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (movendo um <color=#00F6FF>inimigo/Chama Ancestral</color> vai custar <color=#00F6FF>8/8</color> mais pontos do que o uso anterior).",
  str_skill_desc_330181121 = "Consome 7 Insight Points para forçar 1 inimigo não chefe a mover 1 ladrilho, ou consome 8 Insight Points para mover Ancestral Flame 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (movendo um <color=#00F6FF>inimigo/Chama Ancestral</color> vai custar <color=#00F6FF>7/8</color> mais pontos do que o uso anterior).",
  str_skill_desc_330181122 = "Consome 6 Pontos de Insight para forçar 1 inimigo não-chefe a mover 1 ladrilho, ou consome 8 Pontos de Insight para mover Chama Ancestral 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (movendo um <color=#00F6FF>inimigo/Chama Ancestral</color> vai custar <color=#00F6FF>6/8</color> mais pontos do que o uso anterior).",
  str_skill_desc_330181123 = "Consome 5 Pontos de Insight para forçar 1 inimigo não-chefe a mover 1 ladrilho, ou consome 8 Pontos de Insight para mover Chama Ancestral 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (movendo um <color=#00F6FF>inimigo/Chama Ancestral</color> vai custar <color=#00F6FF>5/8</color> mais pontos do que o uso anterior).",
