  str_skill_passive_name_436181 = "Estratégia Indomável",
  str_skill_passive_desc_410181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30075\"><#FFAE07><u>Pontos de percepção</u></color></link> forçar 1 <color=#00F6FF>inimigo não-chefe</color> para mover 1 ladrilho. Só pode ser lançado 1 vez a cada rodada. Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>azulejo vermelho</color>.",
  str_skill_passive_desc_413181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30076\"><#FFAE07><u>Pontos de percepção</u></color></link> forçar 1 <color=#00F6FF>inimigo não-chefe</color> para mover 1 ladrilho. Só pode ser lançado 1 vez a cada rodada. Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>azulejo vermelho</color>.",
  str_skill_passive_desc_416181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30077\"><#FFAE07><u>Pontos de percepção</u></color></link>. Forças 1 <color=#00F6FF>inimigo não-chefe</color> para mover 1 ladrilho. Só pode ser lançado 1 vez a cada rodada. Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>telha</color>.",
  str_skill_passive_desc_420181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30075\"><#FFAE07><u>Pontos de percepção</u></color></link> forçar 1 <color=#00F6FF>inimigo não-chefe</color> para mover 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (cada uso custará <color=#00F6FF>{1}</color> mais pontos do que o uso anterior). Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>Azulejo vermelho</color>.",
  str_skill_passive_desc_423181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30076\"><#FFAE07><u>Pontos de percepção</u></color></link> forçar 1 <color=#00F6FF>inimigo não-chefe</color> para mover 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (cada uso custará <color=#00F6FF>{1}</color> mais pontos do que o uso anterior). Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>Azulejo vermelho</color>.",
  str_skill_passive_desc_426181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30077\"><#FFAE07><u>Pontos de percepção</u></color></link> forçar 1 <color=#00F6FF>inimigo não-chefe</color> para mover 1 ladrilho. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (cada uso custará <color=#00F6FF>{1}</color> mais pontos do que o uso anterior). Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>telha</color>.",
  str_skill_passive_desc_430181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30075\"><#FFAE07><u>Pontos de percepção</u></color></link> para forçar 1 <color=#00F6FF>inimigo não-chefe</color> a mover 1 ladrilho, ou consome 8 Pontos de Insight para <color=#00F6FF>mover Chama Ancestral</color> 1 azulejo. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (movendo um <color=#00F6FF>inimigo/Chama Ancestral</color> vai custar <color=#00F6FF>{1}/8</color> mais pontos do que o uso anterior). Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>azulejo vermelho</color>.",
  str_skill_passive_desc_433181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30076\"><#FFAE07><u>Pontos de percepção</u></color></link> para forçar 1 <color=#00F6FF>inimigo não-chefe</color> a mover 1 ladrilho, ou consome 8 Pontos de Insight para <color=#00F6FF>mover Chama Ancestral</color> 1 azulejo. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (movendo um <color=#00F6FF>inimigo/Chama Ancestral</color> vai custar <color=#00F6FF>{1}/8</color> mais pontos do que o uso anterior). Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>azulejo vermelho</color>.",
  str_skill_passive_desc_436181 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>{1}</color> <link=\"30077\"><#FFAE07><u>Pontos de percepção</u></color></link> para forçar 1 <color=#00F6FF>inimigo não-chefe</color> a mover 1 ladrilho, ou consome 8 Pontos de Insight para <color=#00F6FF>mover Chama Ancestral</color> 1 azulejo. O custo do Insight Point se multiplica quando esta habilidade é lançada várias vezes na mesma rodada (movendo um <color=#00F6FF>inimigo/Chama Ancestral</color> vai custar <color=#00F6FF>{1}/8</color> mais pontos do que o uso anterior). Zhong Xu ganha 1 Ponto de Insight toda vez que passa por 1 <color=#00F6FF>telha</color>.",
  str_skill_desc_15011312 = "Derruba todos os inimigos não chefes que ocupam um único ladrilho no tabuleiro por 1 ladrilho à direita e causa dano a todos os inimigos no campo.",
  str_skill_desc_15011313 = "Derruba todos os inimigos que não sejam chefes que ocupam um único ladrilho no tabuleiro em 1 ladrilho para cima e causa dano a todos os inimigos no campo.",
  str_skill_desc_15011314 = "Derruba todos os inimigos não chefes que ocupam um único ladrilho no tabuleiro por 1 ladrilho à esquerda e causa dano a todos os inimigos no campo.",
  str_skill_desc_15011315 = "Derruba todos os inimigos não chefes que ocupam um único ladrilho no tabuleiro em 1 ladrilho para baixo e causa dano a todos os inimigos no campo.",
  str_skill_desc_14008112 = "Causa dano a todos os inimigos e os puxa para você.",
  str_skill_desc_15001812 = "A Tempestade Solar explode, causando dano a todos os inimigos no campo e repelindo os inimigos atingidos.",
  str_skill_name_200230101 = "Assistente Afônico de Cura",
  str_skill_desc_200230101 = "O Assistente Afônico restaura o HP de outros Eclipsitas dentro de 2 clusters. Quanto mais peças ocupadas por outros Eclipsitas dentro do alcance da habilidade do Assistente Afônico, mais forte será o efeito de sua cura.",
  str_skill_desc_29048011 = "Explode do chão onde seu alvo está localizado, empurrando o alvo para trás e causando dano.",
  str_skill_upgrade_desc_16018413 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate. A área de seleção inicial torna-se 2 clusters circundantes.",
  str_skill_upgrade_desc_16018416 = "Desbloqueia um <color=#FFFF00>nova habilidade ativa</color>: Disponível quando Aurora Time está ativo. Teleporte para qualquer posição dentro de 1 cluster ao redor.",
  str_skill_name_2001841 = "Plumas Voadoras, Balanças Dançantes",
  str_skill_name_2001842 = "Plumas Voadoras, Balanças Dançantes",
  str_skill_name_2001843 = "Plumas Voadoras, Balanças Dançantes",
  str_skill_desc_2001841 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2001842 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_2001843 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_name_2201841 = "Plumas Voadoras, Balanças Dançantes",
  str_skill_name_2201842 = "Plumas Voadoras, Balanças Dançantes",
  str_skill_name_2201843 = "Plumas Voadoras, Balanças Dançantes",
  str_skill_desc_2201841 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2201842 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>16 ladrilhos em forma radial</color> e gera <color=#00F6FF>1</color> <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> dentro da área afetada.",
  str_skill_desc_2201843 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color> e gera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> dentro da área afetada.",
  str_skill_name_300184 = "Em meio a nuvens de poeira",
  str_skill_name_303184 = "Em meio a nuvens de poeira",
  str_skill_desc_300184 = "Teletransporta para uma posição escolhida dentro <color=#00F6FF>12 peças em forma de diamante</color>. Se o ponto de pouso for um <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link>, você pode selecionar outro ponto de pouso dentro <color=#00F6FF>12 peças em forma de diamante</color>. Absorve todas as peças aprimoradas ao longo do caminho. Cada absorção lida <color=#00F6FF>100%</color> dano a 12 ladrilhos em forma de diamante.",
  str_skill_desc_303184 = "Teletransporta para uma posição escolhida dentro <color=#00F6FF>2 aglomerados circundantes</color>. Se o ponto de pouso for um <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link>, você pode selecionar outro ponto de pouso dentro <color=#00F6FF>12 peças em forma de diamante</color>. Absorve todas as peças aprimoradas ao longo do caminho. Cada absorção lida <color=#00F6FF>100%</color> dano a 12 ladrilhos em forma de diamante.",
  str_skill_name_306184 = "Flurry of Feathers",
  str_skill_desc_306184 = "Disponível quando o Aurora Time está ativo: se teletransporta para qualquer posição dentro <color=#00F6FF>1 cluster circundante</color>.",
  str_skill_passive_name_410184 = "Sussurrador de alto-falante",
  str_skill_passive_name_430184 = "Sussurrador de alto-falante",
  str_skill_passive_desc_410184 = "Quando a equipe se teletransporta com uma Habilidade Ativa, trata <color=#00F6FF>{1}</color> danos a <color=#00F6FF>12 peças em forma de diamante</color>. Aumenta o próximo dano final em <color=#00F6FF>{2}</color> para cada ladrilho aprimorado absorvido.",
  str_skill_passive_desc_430184 = "Quando a equipe se teletransporta com uma Habilidade Ativa, trata <color=#00F6FF>{1}</color> danos a <color=#00F6FF>12 peças em forma de diamante</color> e gera 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> dentro da área afetada. Aumenta o próximo dano final em <color=#00F6FF>{2}</color> para cada ladrilho aprimorado absorvido.",
  str_skill_name_280061101 = "Boi - Torreta",
  str_skill_desc_280061101 = "Lança um airdrop. Escolhe um ladrilho atravessável para convocar um <color=#00F6FF>Armadilha de Torreta</color> para isso.",
  str_skill_name_280061102 = "Bullock - Tração",
  str_skill_desc_280061102 = "Lança um airdrop. Escolhe um ladrilho atravessável para convocar um <color=#00F6FF>Arrastador</color> para isso.",
  str_skill_name_280061103 = "Boi - Chama",
  str_skill_desc_280061103 = "Lança um airdrop. Escolhe uma peça atravessável para convocar um <color=#00F6FF>Armadilha de fogo</color> para isso.",
  str_skill_name_280061104 = "Boi - Destruição",
  str_skill_desc_280061104 = "Seleciona uma armadilha invocada por Bullock 8 e a destrói.",
  str_skill_name_280061105 = "Bullock - Reparo de Emergência",
  str_skill_desc_280061105 = "Reparação de emergência! Restaura 3 blocos de HP para Bullock 8.",
  str_skill_desc_140127101 = "Seleciona até 4 ladrilhos (incluindo ladrilhos abissais) e coloca guindastes de papel sobre eles enquanto os converte em ladrilhos cromáticos. Os guindastes de papel desaparecerão depois que os companheiros de equipe passarem por eles.",
  str_skill_name_2001851 = "Blizzard Express",
  str_skill_name_2001852 = "Blizzard Express",
  str_skill_name_2001853 = "Blizzard Express",
  str_skill_name_3001851 = "Corre, Kya, corre",
  str_skill_name_3001852 = "Num instante",
  str_skill_name_3361852 = "Num instante",
  str_skill_passive_name_410185 = "Ataque Homing",
  str_skill_passive_name_416185 = "Ataque Homing",
  str_skill_passive_name_420185 = "Ataque Homing",
  str_skill_passive_name_426185 = "Ataque Homing",
  str_skill_passive_name_430185 = "Ataque Homing",
  str_skill_passive_name_432185 = "Ataque Homing",
  str_skill_passive_name_436185 = "Ataque Homing",
  str_skill_desc_2001851 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2001852 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próx.",
  str_skill_desc_2001853 = "Causa <color=#00F6FF>{1}%</color> de dano aos 4 inimigos mais próx.",
  str_skill_desc_3001851 = "Teletransporta para qualquer posição dentro <color=#00F6FF>12 ladrilhos em forma de cruz</color>.",
  str_skill_desc_3001852 = "Desbloqueia após acumular <color=#00F6FF>8</color> stacks of Kyanite Power: Escolha um inimigo e se teletransporte para a posição mais próxima dentro <color=#00F6FF>1 cluster circundante</color> ao redor do alvo.",
  str_skill_desc_3361852 = "Desbloqueia após acumular <color=#00F6FF>5</color> stacks of Kyanite Power: Escolha um inimigo e se teletransporte para a posição mais próxima dentro <color=#00F6FF>1 cluster circundante</color> ao redor do alvo.",
  str_skill_passive_desc_410185 = "Quando a equipe se teletransportar com uma Habilidade Ativa, lide <color=#00F6FF>{1}</color> dano ao inimigo que tem o menor HP dentro <color=#00F6FF>1 cluster circundante</color>.",
  str_skill_passive_desc_416185 = "Quando a equipe se teletransportar com uma Habilidade Ativa, lide <color=#00F6FF>{1}</color> dano ao inimigo que tem o menor HP dentro <color=#00F6FF>1 cluster circundante</color> e ganho <color=#00F6FF>1</color> pilha de poder cianita. Cada pilha aumentará o dano em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_420185 = "Quando a equipe se teletransportar com uma Habilidade Ativa, lide <color=#00F6FF>{1}</color> dano ao inimigo que tem o menor HP dentro <color=#00F6FF>1 cluster circundante</color>. Quando a Habilidade Ativa de Kya ativa esse efeito, seu dano final será aumentado em <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_426185 = "Quando a equipe se teletransportar com uma Habilidade Ativa, lide <color=#00F6FF>{1}</color> dano ao inimigo que tem o menor HP dentro <color=#00F6FF>1 cluster circundante</color> e ganho <color=#00F6FF>1</color> pilha de poder cianita. Quando a Habilidade Ativa de Kya ativa esse efeito, seu dano final será aumentado em <color=#00F6FF>60%</color>. Cada pilha de poder de cianita aumentará o dano em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_430185 = "Quando a equipe se teletransportar com uma Habilidade Ativa, lide <color=#00F6FF>{1}</color> dano ao inimigo que tem o menor HP dentro <color=#00F6FF>1 cluster circundante</color> e ganho <color=#00F6FF>1</color> pilha de poder cianita. Quando a Habilidade Ativa de Kya ativa esse efeito, seu dano final será aumentado em <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_432185 = "Quando a equipe se teletransportar com uma Habilidade Ativa, lide <color=#00F6FF>{1}</color> dano ao inimigo que tem o menor HP dentro <color=#00F6FF>1 cluster circundante</color> e ganho <color=#00F6FF>1</color> pilha de poder cianita. Quando a Habilidade Ativa de Kya ativa esse efeito, seu dano final será aumentado em <color=#00F6FF>60%</color>.",
  str_skill_passive_desc_436185 = "Quando a equipe se teletransportar com uma Habilidade Ativa, lide <color=#00F6FF>{1}</color> dano ao inimigo que tem o menor HP dentro <color=#00F6FF>1 cluster circundante</color> e ganho <color=#00F6FF>1</color> pilha de poder cianita. Quando a Habilidade Ativa de Kya ativa esse efeito, seu dano final será aumentado em <color=#00F6FF>60%</color>. Cada pilha de poder de cianita aumentará o dano em <color=#00F6FF>5%</color>.",
  str_skill_upgrade_desc_15018512 = "Aprimoramento de Habilidade Ativa: O número de acúmulos necessários para Blink of an Eye reduz para <color=#00F6FF>5</color>. (Válido para Ascensão III)",
  str_skill_upgrade_desc_15018515 = "Aprimoramento de Habilidade de Equipamento: Cada gatilho de habilidade irá gerar <color=#00F6FF>1</color> pilha de poder cianita. Cada pilha de poder de cianita aumentará o dano da habilidade de equipamento de Kya em <color=#00F6FF>5%</color>.",
  str_skill_name_28005016 = "Arrastador",
  str_skill_desc_28005016 = "Puxa Eclipsites dentro de um pequeno intervalo na frente do bloco Arrastador 1 em sua direção. Cada Eclipsite só pode ser afetado pelo efeito de puxar do Dragger uma vez por turno.",
  str_skill_name_400054101 = "Desenraizar",
  str_skill_desc_400054101 = "Causa dano a todos os alvos dentro do alcance e esmaga todos os ladrilhos dentro do alcance, destruindo todos os Bullock 8 invocados neles.",
  str_skill_desc_5410100 = "Usa lança para atacar Eclipsites dentro do alcance do ataque.",
  str_skill_desc_888426101 = "Após o jogador usar Habilidades Ativas 3 vezes seguidas, convoque um Lumo Piker para o campo de batalha.",
  str_skill_desc_4100002 = "Invoca Fire Dreadblades a cada rodada até que 4 Fire Dreadblades estejam no campo de batalha.",
  str_skill_desc_4100004 = "Invoca Thunder Dreadblades a cada rodada até que 4 Thunder Dreadblades estejam no campo de batalha.",
  str_skill_desc_4100005 = "Invoca um Enferno a cada rodada até que 2 Enfernos estejam no campo de batalha.",
  str_skill_desc_4100006 = "Convoca um Enferno para o campo de batalha a cada rodada. Não convocará se já houver um Eferno no campo de batalha.",
  str_skill_desc_5401005 = "Enferno invoca chuva ardente em locais aleatórios perto do Construtor Lumo, causando dano elementar e queimando alvos.",
  str_skill_name_290470111 = "Caçador Mecânico: Aniquilar",
  str_skill_desc_290470111 = "Canaliza Darkflow com seu martelo gigante, causando dano massivo a todos os alvos no campo. Este ataque reduz o HP dos aurorianos dentro da zona protegida para 1.",
  str_skill_name_290470121 = "Caçador Mecânico: Hunt Down",
  str_skill_desc_290470121 = "Se seu alvo estiver na zona protegida, ele se move para perto dele e causa dano corpo a corpo. Se o alvo estiver fora da zona protegida, ele engancha um alvo na mesma linha ou coluna e puxa o alvo para perto de si.",
  str_skill_desc_290470122 = "Se o alvo estiver na zona protegida, ele se move para perto dele e causa dano corpo a corpo. Se o alvo estiver fora da zona protegida, ele engancha um alvo na mesma linha ou coluna e puxa o alvo para perto de si.",
  str_skill_name_290470131 = "Caçador Mecânico: Banir",
  str_skill_desc_290470131 = "Envia ondas de energia turbulenta com seu martelo gigante, causando dano a todos os inimigos no campo. O jogador será jogado para a borda do campo pela energia se estiver dentro da zona protegida.",
  str_skill_name_290490101 = "Os Quatro Cavaleiros: Batalha em Equipe",
  str_skill_desc_290490101 = "Move-se para uma diagonal de ladrilho do membro dos Quatro Cavaleiros mais próximo do alvo (se o lançador for o membro mais próximo dos Quatro Cavaleiros, eles permanecerão no mesmo ladrilho) e, em seguida, ataca os alvos dentro de 1 grupo ao redor.",
  str_skill_desc_290490103 = "Move-se para uma diagonal de ladrilho do membro dos Quatro Cavaleiros mais próximo do alvo (se o lançador for o membro mais próximo dos Quatro Cavaleiros, eles permanecerão no mesmo ladrilho) e, em seguida, ataca os alvos dentro de 1 grupo circundante, infligindo Fragilidade aos Aurorianos . Cada acúmulo de Fragilidade reduz a DEF dos aurorianos em 2%.",
  str_skill_desc_290490107 = "Ataca alvos dentro de 1 cluster ao redor.",
  str_skill_name_290490102 = "Os Quatro Cavaleiros: Golpe Rápido",
  str_skill_desc_290490102 = "Os Quatro Cavaleiros se dividiram, correndo para as bordas do campo, então atacaram o alvo.",
  str_skill_desc_290490108 = "Ataca os alvos enquanto permanece no lugar.",
  str_skill_name_290550101 = "Demônio Hati: Chama de Cobalto",
  str_skill_desc_290550101 = "Demônio Hati perde 15% de seu HP atual e se teletransporta o mais próximo possível de um inimigo dentro de 12 ladrilhos em forma de diamante e, em seguida, causa dano aos inimigos dentro de 1 aglomerado ao redor. Se ela atingir um alvo, ela recupera 15% de seu HP perdido.",
  str_skill_name_290550111 = "Demônio Hati: Chama de Cobalto+",
  str_skill_desc_290550111 = "Demônio Hati perde 15% de seu HP atual e se teletransporta o mais próximo possível de um inimigo dentro de 2 grupos ao redor, então causa dano aos inimigos dentro de 1 grupo ao redor. Se ela atingir um alvo, ela recupera 15% de seu HP perdido.",
  str_skill_name_290550121 = "Demônio Hati: Chama de Cobalto++",
  str_skill_desc_290550121 = "Demônio Hati perde 15% de seu HP atual e se teletransporta o mais próximo possível de um inimigo dentro de 2 grupos ao redor, então causa dano aos inimigos dentro de 2 grupos ao redor. Se ela atingir um alvo, ela recupera 15% de seu HP perdido.",
  str_skill_name_290550102 = "Demônio Hati: Chamas Nether",
  str_skill_desc_290550102 = "Demônio Hati se teletransporta ao lado dos aurorianos e consome 15% de seu HP atual para causar dano massivo aos aurorianos. Se ela atingir um auroriano, ela recupera 15% de seu HP perdido.",
  str_skill_name_2001891 = "Retribuição iminente",
  str_skill_name_2001892 = "Retribuição iminente",
  str_skill_name_2001893 = "Retribuição iminente",
  str_skill_desc_2001891 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2001892 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_2001893 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_name_3001890 = "Carnificina Turbilhão",
  str_skill_name_3001891 = "Carnificina Turbilhão",
  str_skill_name_3001892 = "Carnificina Turbilhão",
  str_skill_name_3061891 = "Carnificina Turbilhão",
  str_skill_name_3061892 = "Carnificina Turbilhão",
  str_skill_name_3301892 = "Sobrecarga de combate",
  str_skill_name_3331892 = "Sobrecarga de combate",
  str_skill_desc_3001890 = "Seleciona 1 ladrilho de <color=#00F6FF>4 ladrilhos em forma de cruz</color> no local atual e ofertas <color=#00F6FF>100%</color> danos a <color=#00F6FF>2 carreiras em forma de leque</color> Nessa direção.",
  str_skill_desc_3001891 = "Seleciona 1 ladrilho de <color=#00F6FF>4 ladrilhos em forma de cruz</color> no local atual e promoções <color=#00F6FF>100%</color> danos a <color=#00F6FF>2 carreiras em forma de leque</color> Nessa direção. O zelo aumenta o dano e o alcance, causando até <color=#00F6FF>400%</color> danos a <color=#00F6FF>7 carreiras em forma de leque</color>. O zelo será eliminado após lançar a habilidade.",
  str_skill_desc_3001892 = "Seleciona 1 ladrilho de <color=#00F6FF>4 ladrilhos em forma de cruz</color> no local atual e ofertas <color=#00F6FF>100%</color> danos a <color=#00F6FF>2 carreiras em forma de leque</color> Nessa direção. O zelo aumenta o dano e o alcance, causando até <color=#00F6FF>400%</color> danos a <color=#00F6FF>7 carreiras em forma de leque</color>. O zelo será eliminado após lançar a habilidade.",
  str_skill_desc_3061891 = "Seleciona 1 ladrilho de <color=#00F6FF>4 ladrilhos em forma de cruz</color> no local atual e ofertas <color=#00F6FF>100%</color> danos a <color=#00F6FF>2 carreiras em forma de leque</color> Nessa direção. O zelo aumenta o dano e o alcance, causando até <color=#00F6FF>400%</color> danos a <color=#00F6FF>7 carreiras em forma de leque</color>. O zelo será eliminado após lançar a habilidade. Se você optar por lançar esta habilidade com seu ladrilho atual, ela aumentará o zelo em <color=#00F6FF>35</color> pontos em vez de causar dano.",
  str_skill_desc_3061892 = "Seleciona 1 ladrilho de <color=#00F6FF>4 ladrilhos em forma de cruz</color> no local atual e ofertas <color=#00F6FF>100%</color> danos a <color=#00F6FF>2 carreiras em forma de leque</color> Nessa direção. O zelo aumenta o dano e o alcance, causando até <color=#00F6FF>400%</color> danos a <color=#00F6FF>7 carreiras em forma de leque</color>. O zelo será eliminado após lançar a habilidade. Se você optar por lançar esta habilidade com seu ladrilho atual, ela aumentará o zelo em <color=#00F6FF>35</color> pontos em vez de causar dano.",
  str_skill_desc_3301892 = "Ainda pode usar ataques normais no estado excessivamente zeloso nesta rodada. O zelo se dissipará no final da rodada.",
  str_skill_desc_3331892 = "Aumenta o Zelo para <color=#00F6FF>100</color>. Ainda pode usar ataques normais no estado excessivamente zeloso nesta rodada. O zelo se dissipará no final da rodada.",
