  str_skill_desc_2001901 = "Ofertas <color=#00F6FF>140%</color> dano aos 2 inimigos mais próximos dentro <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2001902 = "Ofertas <color=#00F6FF>155%</color> dano aos 2 inimigos mais próximos dentro <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2001903 = "Ofertas <color=#00F6FF>160%</color> dano aos 2 inimigos mais próximos dentro <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2001933 = "Ofertas <color=#00F6FF>160%</color> dano aos 2 inimigos mais próximos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Cada vez que os aurorianos de fogo lançam habilidades ativas, a condição de ativação aumenta em <color=#00F6FF>1</color>. Além disso, o número de alvos atingidos aumenta em 1, ou o alcance da habilidade aumenta em <color=#00F6FF>1</color> conjunto.",
  str_skill_desc_3001901 = "Converte o <color=#00F6FF>4</color> ladrilhos Verdes mais próximos do Vermelho.",
  str_skill_desc_3001902 = "Converte os <color=#00F6FF>4</color> blocos Verdes mais próximos em Vermelho. Se a Habilidade Ativa estiver pronta na última rodada, aumenta a contagem de conversão de blocos em <color=#00F6FF>1</color> nesta rodada.",
  str_skill_desc_3001903 = "Converte os <color=#00F6FF>5</color> blocos Verdes mais próximos em Vermelho. Se a Habilidade Ativa estiver pronta na última rodada, aumenta a contagem de conversão de blocos em <color=#00F6FF>1</color> nesta rodada.",
  str_skill_desc_3021901 = "Converte os <color=#00F6FF>4</color> blocos Verdes mais próximos em Vermelho. Se a Habilidade Ativa estiver pronta na última rodada, aumenta a contagem de conversão de blocos em <color=#00F6FF>1</color> nesta rodada.",
  str_skill_desc_3051901 = "Converte os <color=#00F6FF>5</color> blocos Verdes mais próximos em Vermelho. Se a Habilidade Ativa estiver pronta na última rodada, aumenta a contagem de conversão de blocos em <color=#00F6FF>1</color> nesta rodada.",
