  str_skill_passive_name_420190 = "Guardião da Santidade",
  str_skill_passive_name_430190 = "Guardião da Santidade",
  str_skill_passive_desc_410189 = "Os ataques normais de Leyn ganham um bônus de dano de até <color=#00F6FF>{1}</color> baseado em seu <link=\"30078\"><#FFAE07><u>Zelo</u></color></link>, quanto maior o zelo, maior o bônus de dano. Quando o Zelo chega <color=#00F6FF>100</color>, ele entra no estado Superzeloso e não pode usar Ataques Normais.",
  str_skill_passive_desc_420189 = "Os ataques normais de Leyn ganham um bônus de dano de até <color=#00F6FF>{1}</color> baseado em seu <link=\"30078\"><#FFAE07><u>Zelo</u></color></link>, quanto maior o zelo, maior o bônus de dano. Quando o Zelo chega <color=#00F6FF>100</color>, ele entra no estado Superzeloso e não pode usar Ataques Normais. No entanto, o dano final de seus Chain Combos aumenta em <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_430189 = "Os ataques normais de Leyn ganham um bônus de dano de até <color=#00F6FF>{1}</color> baseado em seu <link=\"30078\"><#FFAE07><u>Zelo</u></color></link>, quanto maior o zelo, maior o bônus de dano. Quando o Zelo chega <color=#00F6FF>100</color>, ele entra no estado Superzeloso e não pode usar Ataques Normais. No entanto, o dano final de seus Chain Combos aumenta em <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_433189 = "Os ataques normais de Leyn ganham um bônus de dano de até <color=#00F6FF>{1}</color> baseado em seu <link=\"30078\"><#FFAE07><u>Zelo</u></color></link>, quanto maior o zelo, maior o bônus de dano. Quando o Zelo chega <color=#00F6FF>100</color>, ele entra no estado Superzeloso e não pode usar Ataques Normais. No entanto, o dano final de seus Chain Combos aumenta em <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_410190 = "<color=#00F6FF>50%</color> de dano causado por Chain Combos é convertido em um escudo. O valor deste escudo não pode exceder <color=#00F6FF>{1}</color> do ATK de Matthieu.",
  str_skill_passive_desc_420190 = "<color=#00F6FF>50%</color> de dano causado por Chain Combos é convertido em um escudo. O valor deste escudo não pode exceder <color=#00F6FF>{1}</color> do ATK de Matthieu. Sempre que Fire Aurorians lançarem habilidades ativas, ganhe um escudo igual a <color=#00F6FF>10%</color> do ATK de Matthieu.",
  str_skill_passive_desc_430190 = "<color=#00F6FF>50%</color> de dano causado por Chain Combos é convertido em um escudo. O valor deste escudo não pode exceder <color=#00F6FF>{1}</color> do ATK de Matthieu. Sempre que Fire Aurorians lançarem habilidades ativas, ganhe um escudo igual a <color=#00F6FF>10%</color> do ATK de Matthieu.",
  str_skill_upgrade_desc_16018613 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16018616 = "Aprimoramento de habilidade ativa: aumenta o número de peças que você pode conectar <color=#00F6FF>1</color>.",
