  str_skill_passive_desc_410186 = "Aumenta a primeira ocorrência de dano causado por Tina cada rodada por <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_430186 = "Aumenta a primeira ocorrência de dano causado por Tina cada rodada por <color=#00F6FF>{1}</color>. Se Tina não agiu na última rodada, o efeito é dobrado nesta rodada.",
  str_skill_name_3001861 = "Descanse em Santa Luz",
  str_skill_name_3061861 = "Descanse em Santa Luz",
  str_skill_name_3201861 = "Descanse em Santa Luz",
  str_skill_name_3261861 = "Descanse em Santa Luz",
  str_skill_desc_3001861 = "Tina começa a andar como sonâmbula, ignorando as cores dos ladrilhos por até <color=#00F6FF>3</color> ladrilhos consecutivos enquanto <color=#00F6FF>converte os ladrilhos pelos quais ela passa</color> em Azul e, em seguida, retorna ao ladrilho inicial.",
  str_skill_desc_3061861 = "Tina começa a andar como sonâmbula, ignorando as cores dos ladrilhos por até <color=#00F6FF>4</color> ladrilhos consecutivos enquanto <color=#00F6FF>converte os ladrilhos pelos quais ela passa</color> em Azul e, em seguida, retorna ao ladrilho inicial.",
  str_skill_desc_3201861 = "Tina começa a andar como sonâmbula, ignorando as cores dos ladrilhos por até <color=#00F6FF>3</color> ladrilhos consecutivos enquanto <color=#00F6FF>converte seu ladrilho inicial e os ladrilhos pelos quais ela passa</color> em ladrilhos Azuis antes de retornar a ela ladrilho inicial. Se houver inimigos no final de seu caminho, ela pode optar por descer sobre o inimigo para causar <color=#00F6FF>200%</color> de dano a eles, antes de pousar no ladrilho logo antes do inimigo.",
  str_skill_desc_3261861 = "Tina começa a andar como sonâmbula, ignorando as cores dos ladrilhos por até <color=#00F6FF>4</color> ladrilhos consecutivos enquanto <color=#00F6FF>converte seu ladrilho inicial e os ladrilhos pelos quais ela passa</color> em ladrilhos Azuis antes de retornar a ela ladrilho inicial. Se houver inimigos no final de seu caminho, ela pode optar por descer sobre o inimigo para causar <color=#00F6FF>200%</color> de dano a eles, antes de pousar no ladrilho logo antes do inimigo.",
  str_skill_upgrade_desc_16018913 = "Aprimoramento de habilidade ativa: Sobrecarga de combate torna-se um <color=#FFFF00>Ataque preventivo</color> e aumenta o zelo para <color=#00F6FF>100</color> quando ativado. (Válido para Ascensão III)",
  str_skill_upgrade_desc_16018916 = "Aprimoramento de Habilidade Ativa: Pode selecionar o bloco atual para aumentar o Zelo em <color=#00F6FF>35</color> em vez de causar dano. (Válido para Ascensão I)",
  str_skill_upgrade_desc_15019012 = "Melhoria de Habilidade Ativa: Se a habil. já estava pronta na última rodada, aumenta as casas convertidas em <color=#FFFF00>1</color> nessa rodada.",
  str_skill_upgrade_desc_15019015 = "Melhoria de Habilidade Ativa: Aumenta as casas convertidas em <color=#FFFF00>1</color>.",
  str_skill_upgrade_refine_desc_16001111 = "Aprimoramento de Habilidade de Equipamento: Aplica-se até <color=#00F6FF>7</color> pilhas de Dragontooth Mark nos inimigos.",
  str_skill_upgrade_refine_desc_16001112 = "<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Teletransporta para um local selecionado dentro <color=#FFFF00>3 aglomerados circundantes</color>, negócios <color=#FFFF00>200%</color> danos a <color=#FFFF00>1 cluster circundante</color>, e aplica 2 pilhas de Dragontooth Mark (se ela matar um inimigo, as pilhas máximas de Dragontooth Mark são aplicadas a outros inimigos dentro da área).",
  str_skill_upgrade_refine_desc_16001113 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Teleporta para <color=#FFFF00>qualquer local</color>, ofertas <color=#FFFF00>360%</color> danos a <color=#FFFF00>3 aglomerados circundantes</color>, e aplica 2 pilhas de Dragontooth Mark (se ela matar um inimigo, as pilhas máximas de Dragontooth Mark são aplicadas a outros inimigos dentro da área).",
  str_skill_desc_3300111 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Teletransporta para um local selecionado dentro <color=#FFFF00>3 aglomerados circundantes</color>, ofertas <color=#FFFF00>200%</color> danos a <color=#FFFF00>1 cluster circundante</color>, e aplica 2 pilhas de Dragontooth Mark (se ela matar um inimigo, as pilhas máximas de Dragontooth Mark são aplicadas a outros inimigos dentro da área).",
  str_skill_desc_3300112 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Teleporta para <color=#FFFF00>qualquer local</color>, ofertas <color=#FFFF00>360%</color> danos a <color=#FFFF00>3 aglomerados circundantes</color>, e aplica 2 pilhas de Dragontooth Mark (se ela matar um inimigo, as pilhas máximas de Dragontooth Mark são aplicadas a outros inimigos dentro da área).",
  str_skill_upgrade_desc_16019113 = "Ganhe nova habilidade ativa: consome <color=#00F6FF>10%</color> do HP atual da equipe para causar 250% de dano a <color=#00F6FF>1 cluster circundante</color>.",
  str_skill_upgrade_desc_16019116 = "Melhoria de Habilidade Ativa: Reduz a recarga em 1 rodada.",
