  str_skill_desc_2001911 = "Salta em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>150%</color> danos a <color=#00F6FF>9 ladrilhos em formato quadrado</color>.",
  str_skill_desc_2001912 = "Salta em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>160%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>.",
  str_skill_desc_2001913 = "Salta em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>170%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>.",
  str_skill_desc_2301911 = "Salta em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>150%</color> danos a <color=#00F6FF>9 ladrilhos em forma de quadrado</color>. Quando o HP é inferior a 40%, o alcance do salto é expandido para <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2301912 = "Salta em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>160%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Quando o HP é inferior a 40%, o alcance do salto é expandido para <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2301913 = "Salta em direção ao inimigo mais próximo com o maior HP dentro <color=#00F6FF>12 peças em forma de diamante</color>, então trata <color=#00F6FF>170%</color> danos a <color=#00F6FF>17 ladrilhos em forma radial</color>. Quando o HP é inferior a 40%, o alcance do salto é expandido para <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_name_3001911 = "Perseguição Abrasadora",
  str_skill_name_3201911 = "Perseguição Abrasadora",
  str_skill_name_32019111 = "Perseguição Abrasadora",
  str_skill_desc_3001911 = "Seleciona 1 inimigo dentro <color=#00F6FF>24 peças em forma de diamante</color>, então se teletransporta para o ladrilho mais próximo do alvo e distribui <color=#00F6FF>150%</color> danos a eles.",
  str_skill_desc_3201911 = "Seleciona 1 inimigo dentro <color=#00F6FF>24 peças em forma de diamante</color>, então se teletransporta para o ladrilho mais próximo do alvo e distribui <color=#00F6FF>150%</color> danos a eles. Se a Habilidade Ativa estava pronta na última rodada, o intervalo de seleção nesta rodada torna-se <color=#00F6FF>4 aglomerados circundantes</color>.",
  str_skill_desc_32019112 = "Seleciona 1 inimigo dentro <color=#00F6FF>24 peças em forma de diamante</color>, então se teletransporta para o ladrilho mais próximo do alvo e distribui <color=#00F6FF>150%</color> danos a eles. Se a Habilidade Ativa estava pronta na última rodada, o intervalo de seleção nesta rodada torna-se <color=#00F6FF>4 aglomerados circundantes</color> e o dano é aumentado para <color=#00F6FF>200%</color>.",
  str_skill_desc_32019113 = "Seleciona 1 inimigo dentro <color=#00F6FF>24 peças em forma de diamante</color>, então se teletransporta para o ladrilho mais próximo do alvo e distribui <color=#00F6FF>150%</color> dano a 5 ladrilhos em forma de cruz. Se a Habilidade Ativa estava pronta na última rodada, o intervalo de seleção nesta rodada se torna <color=#00F6FF>4 aglomerados circundantes</color> e o dano é aumentado para <color=#00F6FF>200%</color>.",
  str_skill_name_3001912 = "Chama Ominosa",
  str_skill_name_3061912 = "Chama Ominosa",
  str_skill_desc_3001912 = "consome <color=#00F6FF>10%</color> do HP atual da equipe para lidar {1}% de dano a <color=#00F6FF>1 cluster circundante</color>.",
  str_skill_passive_name_410191 = "Garras Incineradoras",
  str_skill_passive_desc_410191 = "O dano de Hati aumenta conforme o HP do time diminui, até <color=#00F6FF>{1}</color> quando o HP da equipe é menor que <color=#00F6FF>30%</color>.",
  str_skill_passive_desc_4101911 = "O dano de Hati aumenta conforme o HP do time diminui, até <color=#00F6FF>60%</color> quando o HP da equipe é menor que <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16019111 = "Aprimoramento de habilidade de equipamento: o bônus sobe para <color=#00F6FF>60%</color> quando o HP da equipe é inferior a 30%.",
  str_skill_upgrade_refine_desc_16019112 = "Novo Efeito de Habilidade Ativa: Se a Habilidade Ativa estava pronta na última rodada, o alcance de seleção nesta rodada se torna 4 grupos ao redor <color=#00F6FF>e o dano é aumentado para 200%</color>.",
  str_skill_upgrade_refine_desc_16019113 = "Aprimoramento de Habilidade Ativa: Causa dano a <color=#00F6FF>5 ladrilhos em forma de cruz</color> em vez de 1 alvo.",
