  str_skill_name_3451931 = "Para os Céus Variante I",
  str_skill_name_3401932 = "Para os Céus Variante II",
  str_skill_desc_2001931 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>8 casas em forma de cruz</color>.",
  str_skill_desc_2001932 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_20019333 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color> e inimigos em uma área <color=#00F6FF>em forma de cruz até o alcance máximo</color>.",
  str_skill_desc_2201931 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>8 ladrilhos em forma de cruz</color>. Aumenta o dano causado aos inimigos ao longo de uma forma de cruz em 30%.",
  str_skill_desc_2201932 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>12 peças em forma de diamante</color>. Aumenta o dano causado aos inimigos ao longo de uma forma de cruz em 30%.",
  str_skill_desc_2201933 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>1 cluster circundante</color> e <color=#00F6FF>uma forma de cruz para o alcance máximo</color>. Aumenta o dano causado aos inimigos ao longo de uma forma de cruz em 30%.",
  str_skill_desc_3001931 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>160%</color> dano a todos os inimigos nesta direção.",
  str_skill_desc_3051931 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>200%</color> dano a todos os inimigos nesta direção.",
  str_skill_desc_3301931 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>160%</color> dano a todos os inimigos nesta direção. Quanto mais longe o alvo estiver, mais dano será causado. O dano final aumenta em <color=#00F6FF>10%</color> por cluster.",
  str_skill_desc_3351931 = "Ataca em qualquer direção selecionada, causando <color=#00F6FF>200%</color> dano a todos os inimigos nesta direção. Quanto mais longe o alvo estiver, mais dano será causado. O dano final aumenta em <color=#00F6FF>10%</color> por cluster.",
  str_skill_desc_3401931 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 160% de dano a todos os inimigos em 1 direção selecionada e depois troca de posição com o <color=#FFFF00>precedente</color> membro da equipe. Quanto mais longe o alvo estiver, mais dano será causado. O dano final aumenta em 10% por grupo. <color=#FFFF00>Se um ladrilho externo for selecionado, Kristen avança 1 ladrilho antes de lançar a habilidade</color>.",
  str_skill_desc_3451931 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 200% de dano a todos os inimigos em 1 direção selecionada e depois troca de posição com o <color=#FFFF00>precedente</color> membro da equipe. Quanto mais longe o alvo estiver, mais dano causado. O dano final aumenta em 10% por grupo. <color=#FFFF00>Se um ladrilho externo for selecionado, Kristen avança 1 ladrilho antes de lançar a habilidade</color>.",
  str_skill_desc_3401932 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. <color=#FFFF00>sem atacar</color>, troca de posição com o <color=#FFFF00>sucesso</color> membro da equipe. <color=#FFFF00>Aumenta o dano da próxima habilidade ativa em 50%</color>. Este bônus de dano não se acumula quando lançado mais de uma vez.",
  str_skill_passive_name_410193 = "Laser Jetstream",
  str_skill_passive_name_430193 = "Laser Jetstream",
  str_skill_passive_desc_410193 = "Ataques normais penetrarão nos inimigos, causando <color=#00F6FF>{1}</color> dano ao alvo 1 ladrilho atrás do inimigo.",
  str_skill_passive_desc_430193 = "Ataques normais penetrarão nos inimigos, causando <color=#00F6FF>{1}</color> dano ao alvo 1 ladrilho atrás do inimigo.",
  str_skill_passive_desc_4401933 = "Ataques normais irão penetrar nos inimigos, causando <color=#00F6FF>60%</color> dano ao alvo 1 ladrilho atrás do inimigo. As mudanças de capitão para a batalha aumentam em <color=#00F6FF>1</color> quando Kristen troca de posição com um membro da equipe. Aciona até 1 vez por rodada.",
  str_skill_upgrade_refine_desc_15019311 = "<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa dano a todos os inimigos em 1 direção selecionada, depois troca de posição com o <color=#FFFF00>precedente</color> membro da equipe. Quanto mais longe o alvo estiver, mais dano causado. O dano final aumenta em 10% por grupo. <color=#FFFF00>Se um ladrilho externo for selecionado, Kristen avança 1 ladrilho antes de lançar a habilidade</color>.",
  str_skill_upgrade_refine_desc_15019312 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. <color=#FFFF00>sem atacar</color>, troca de posição com o <color=#FFFF00>sucesso</color> membro da equipe. <color=#FFFF00>Aumenta o dano da próxima habilidade ativa em 50%</color>. Este bônus de dano não se acumula quando lançado mais de uma vez.",
  str_skill_upgrade_refine_desc_15019313 = "Aprimoramento de habilidade de equipamento: mudanças de capitão para a batalha aumentam em 1 quando Kristen troca de posição com um membro da equipe. Aciona até 1 vez por rodada.",
  str_skill_upgrade_desc_15019312 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_15019315 = "Melhoria de Habilidade Ativa: Aumenta o dano da Habil. Ativa em <color=#FFFF00>40%</color>.",
  str_skill_upgrade_refine_desc_14004811 = "Aprimoramento de habilidade de equipamento: para cada 1 ladrilho amarelo aos pés do inimigo, o dano aumenta em <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_14004812 = "Aprimoramento de habilidade ativa: causa o dobro de dano ao ladrilho no centro do alcance da habilidade.",
  str_skill_upgrade_refine_desc_14004813 = "Aprimoramento de Habilidade Ativa: Se a Habilidade Ativa estiver pronta na última rodada, o intervalo de seleção torna-se <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_passive_desc_4400481 = "Aumenta o dano de Dayna contra inimigos ocupando um ladrilho Amarelo em <color=#00F6FF>10%</color>. Para cada ladrilho amarelo aos pés do inimigo, o bônus de dano aumenta em <color=#00F6FF>1%</color>. Também concede companheiros de equipe Thunder Aurorian <color=#00F6FF>50%</color> deste bônus.",
  str_skill_name_3400482 = "Trovão Caprichoso",
  str_skill_name_3420482 = "Trovão Caprichoso",
  str_skill_name_3400483 = "Trovão Caprichoso",
  str_skill_name_3420483 = "Trovão Caprichoso",
  str_skill_desc_3400482 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho central selecionado é dobrado.",
  str_skill_desc_3420482 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho central selecionado é dobrado. Converte até 1 ladrilho sob o inimigo para Amarelo.",
  str_skill_desc_3400483 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho central selecionado é dobrado. Se esta habilidade ativa estava pronta na última rodada, o intervalo de seleção torna-se <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_3420483 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho central selecionado é dobrado. Converte até 1 ladrilho sob o inimigo para Amarelo. Se esta habilidade ativa estava pronta na última rodada, o intervalo de seleção torna-se <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_upgrade_refine_desc_15009811 = "Aprimoramento do Chain Combo: Aumenta o fator de dano do Chain Combo em <color=#00F6FF>15%/20%/20%</color>.",
  str_skill_upgrade_refine_desc_15009812 = "Aprimoramento de habilidade de equipamento: Marca de desmembramento acumula até <color=#00F6FF>10 vezes</color> e cada pilha aumenta o dano em 6%.",
  str_skill_upgrade_refine_desc_15009813 = "Aprimoramento de Habilidade Ativa: Aumenta o fator de dano da Habilidade Ativa para <color=#00F6FF>500%</color>. Se o inimigo selecionado por esta Habilidade Ativa não puder ser deslocado, <color=#00F6FF>recarga de habilidade -1</color> após a fundição.",
  str_skill_desc_2009811 = "Ofertas <color=#00F6FF>150%</color> dano a 3 inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>.",
  str_skill_desc_2009821 = "Ofertas <color=#00F6FF>160%</color> dano a 4 inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>.",
  str_skill_desc_2009831 = "Ofertas <color=#00F6FF>170%</color> dano a todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>.",
  str_skill_desc_3300981 = "Seleciona 1 inimigo dentro <color=#00F6FF>3 aglomerados circundantes</color> e negócios <color=#00F6FF>500%</color> danos a ele. Se o inimigo ocupar um único ladrilho e puder ser repelido, mova-o para uma posição selecionada dentro do alcance do ataque. Se o inimigo não puder ser repelido, <color=#00F6FF>cooldown de habilidade é reduzido em 1</color> após a fundição. Se um alvo que tem uma Marca for morto, causa dano ignorando DEF igual a <color=#00F6FF>40%</color> do ATK de Cuscuta para inimigos dentro <color=#00F6FF>1 cluster circundante</color>.",
  str_skill_desc_3350981 = "Seleciona 1 inimigo e negocia <color=#00F6FF>500%</color> danos a ele. Se o inimigo ocupar um único ladrilho e puder ser repelido, ele é movido para uma posição selecionada dentro do alcance do ataque. Se o inimigo não puder ser repelido, <color=#00F6FF>cooldown de habilidade é reduzido em 1</color> após a fundição. Se um alvo que tem uma Marca for morto, causa dano ignorando DEF igual a <color=#00F6FF>40%</color> do ATK de Cuscuta para inimigos dentro <color=#00F6FF>1 cluster circundante</color>.",
  str_skill_desc_3200331 = "Ofertas <color=#00F6FF>95%</color> dano <color=#00F6FF>5</color> vezes para inimigos aleatórios no campo de batalha. Lança 1 ataque adicional para cada ladrilho Azul dentro <color=#00F6FF>1 cluster circundante</color> do local atual. A primeira ocorrência de dano causado a cada alvo é <color=#00F6FF>dobrou</color>.",
  str_skill_desc_3250331 = "Ofertas <color=#00F6FF>95%</color> dano <color=#00F6FF>6</color> vezes para inimigos aleatórios no campo de batalha. Lança 1 ataque adicional para cada ladrilho Azul dentro <color=#00F6FF>12 aglomerados circundantes</color> da unidade. A primeira ocorrência de dano causado a cada alvo é <color=#00F6FF>dobrou</color>.",
  str_skill_passive_desc_4300331 = "Vice ganha 1 pilha de Locking Mark sempre que causa dano. Cada pilha aumenta o dano em <color=#00F6FF>2,5%</color> e dano Chain Combo por <color=#00F6FF>5%</color>. Todas as pilhas são limpas no final da rodada.",
  str_skill_passive_desc_4300332 = "Vice ganha 1 pilha de Locking Mark sempre que causa dano. Cada pilha aumenta o dano em <color=#00F6FF>2,5%</color> e dano Chain Combo por <color=#00F6FF>5%</color>, além de aumentar o ATK básico de Vice em 0,5%. Todas as pilhas são limpas no final da rodada.",
  str_skill_upgrade_refine_desc_15003311 = "Aprimoramento de Habilidade de Equipamento: Cada pilha de Marca aumenta o dano em <color=#00F6FF>2,5%</color> e dano Chain Combo por <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_15003312 = "Aprimoramento de Habilidade Ativa: A primeira ocorrência de dano causado a cada alvo é <color=#00F6FF>dobrou</color>.",
  str_skill_upgrade_refine_desc_15003313 = "Aprimoramento de Habilidade de Equipamento: Cada pilha de Marca aumenta o ATK básico em <color=#00F6FF>0,5%</color>.",
  str_skill_desc_340093 = "Teletransporta para qualquer local dentro <color=#00F6FF>3 aglomerados circundantes</color> e negócios <color=#00F6FF>250%</color> dano aos inimigos dentro <color=#00F6FF>1 cluster circundante</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. O dano final aumenta em <color=#00F6FF>15%</color> para cada inimigo morto. Acumula até 10 vezes. O alcance do teletransporte aumenta em 1 aglomerado ao redor para cada 5 inimigos mortos.",
  str_skill_desc_346093 = "Teletransporta para qualquer local dentro <color=#00F6FF>3 aglomerados circundantes</color> e negócios <color=#00F6FF>250%</color> dano aos inimigos dentro <color=#00F6FF>1 cluster circundante</color>. O dano é dobrado quando há apenas 1 inimigo na área de ataque. O dano final aumenta em <color=#00F6FF>15%</color> para cada inimigo morto. Acumula até 10 vezes. Remove o cooldown da habilidade ativa se o alvo for derrotado com a habilidade (uma vez por rodada). O alcance do teletransporte aumenta em 1 aglomerado ao redor para cada 5 inimigos mortos.",
  str_skill_passive_desc_4300931 = "Depois de lançar um Chain Combo ou uma Habilidade Ativa, se o HP do alvo for menor que <color=#00F6FF>30%</color>, lança mais 1 ataque causando dano ignorando DEF igual a <color=#00F6FF>120%</color> de ATK. Se o alvo tiver menos HP do que o ATK de Migard após este ataque extra, ele será morto.",
  str_skill_passive_desc_4300932 = "Depois de lançar um Chain Combo ou uma Habilidade Ativa, se o HP do alvo for menor que <color=#00F6FF>30%</color>, lança mais 1 ataque causando dano ignorando DEF igual a <color=#00F6FF>120%</color> de ATK. Se o alvo tiver menos HP do que 250% do ATK de Migard após este ataque extra, ele será morto.",
  str_skill_upgrade_refine_desc_16009311 = "Aprimoramento de Habilidade de Equipamento: O dano do ataque extra aumenta para <color=#00F6FF>120%</color>.",
  str_skill_upgrade_refine_desc_16009312 = "Aprimoramento de Habilidade Ativa: Cada <color=#00F6FF>5 vezes</color> esta Habilidade Ativa ganha um bônus de dano, o alcance da seleção aumenta em <color=#00F6FF>1 cluster</color>.",
  str_skill_upgrade_refine_desc_16009313 = "Aprimoramento de Habilidade de Equipamento: Se o HP do alvo for menor que <color=#00F6FF>250%</color> do ATK de Migard após o ataque extra, ele é morto.",
  str_skill_upgrade_refine_desc_15001811 = "Aprimoramento de habilidade de equipamento: quanto mais próximos os inimigos, mais dano as habilidades ativas e os combos em cadeia causam (até <color=#00F6FF>110%</color>).",
  str_skill_upgrade_refine_desc_15001812 = "Aprimoramento do Chain Combo: Aumenta o fator de dano do Chain Combo em <color=#00F6FF>10%/15%/20%</color>.",
  str_skill_upgrade_refine_desc_15001813 = "Aprimoramento de habilidade de equipamento: o alcance do efeito aumenta para <color=#00F6FF>5 clusters</color>.",
  str_skill_passive_desc_440018 = "Aumenta o ATK em <color=#00F6FF>5%</color> para cada inimigo dentro <color=#00F6FF>1 cluster circundante</color>. Quanto mais próximos estiverem os inimigos, mais dano as habilidades ativas e os combos em cadeia causam (até <color=#00F6FF>110%</color>). Distâncias além de 3 aglomerados não oferecem bônus de dano.",
  str_skill_passive_desc_450018 = "Aumenta o ATK em <color=#00F6FF>5%</color> para cada inimigo dentro <color=#00F6FF>1 cluster circundante</color>. Quanto mais próximos estiverem os inimigos, mais dano as habilidades ativas e os combos em cadeia causam (até <color=#00F6FF>110%</color>). Distâncias além de 5 aglomerados não oferecem bônus de dano.",
  str_skill_desc_2400181 = "Ofertas <color=#00F6FF>115%</color> danos a <color=#00F6FF>1 coluna</color>.",
  str_skill_desc_2400182 = "Ofertas <color=#00F6FF>125%</color> danos a <color=#00F6FF>3 colunas</color>.",
  str_skill_desc_2400183 = "Ofertas <color=#00F6FF>130%</color> danos a <color=#00F6FF>5 colunas</color>.",
  str_skill_upgrade_refine_desc_16006411 = "Aprimoramento de habilidade ativa: o tempo de recarga da habilidade é reduzido em <color=#00F6FF>2</color> no início de cada batalha.",
  str_skill_upgrade_refine_desc_16006412 = "Aprimoramento de Habilidade de Equipamento: <color=#00F6FF>5</color> os marcadores podem ser reservados ao usar a Habilidade Ativa. <color=#00F6FF>1</color> bala pode ser reservada quando qualquer auroriano usar sua Habilidade Ativa.",
  str_skill_upgrade_refine_desc_16006413 = "Aprimoramento de habilidade de equipamento: você pode alternar manualmente se os Chain Combos consomem munição.",
  str_skill_passive_desc_440064 = "Pode <link=\"30079\"><#FFAE07><u>reserva de munição</u></color></link>. Cada vez que um Chain Combo causa dano, 1 munição é consumida (até <color=#00F6FF>3</color> A munição pode ser consumida no estado Sobrecarga). Para cada munição consumida, o dano final aumenta em <color=#00F6FF>30%</color>.",
  str_skill_desc_341064 = "Entra no estado de sobrecarga, no qual o dano do Chain Combo de Wrath aumenta em <color=#00F6FF>50%</color> e causa dano ao inimigo mais próximo 2 vezes. Dura 2 rodadas. O cooldown da habilidade é reduzido em <color=#00F6FF>2</color> no início de cada batalha.",
  str_skill_upgrade_refine_desc_16001911 = "Victoria junta-se à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>.\n<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>300%</color> dano a até 3 inimigos dentro do alcance. Ofertas <color=#FFFF00>300%</color> Dano que ignora DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a uma porcentagem do dano causado. <color=#FFFF00>Além disso, perde Sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_upgrade_refine_desc_16001912 = "Aprimoramento de Habilidade Ativa: A Habilidade Ativa pode atacar 1 inimigo adicional.",
  str_skill_upgrade_refine_desc_16001913 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 250% de dano a até 4 inimigos dentro do alcance. Causa 250% de dano ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada pilha de Sangramento que eles tiverem. Restaura HP igual a uma porcentagem do dano causado. <color=#FFFF00>Além disso, restaura a sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_3200192 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>300%</color> dano a até 3 inimigos dentro de 3 grupos ao redor. Ofertas <color=#FFFF00>300%</color> Danos ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada pilha de Sangramento que eles tiverem. Restaura HP igual a 25% do dano causado. <color=#FFFF00>Além disso, perde Sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_3200191 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 250% de dano a até 3 inimigos em 3 grupos ao redor. Causa 250% de dano ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada pilha de Sangramento que eles tiverem. Restaura HP igual a 25% do dano causado. <color=#FFFF00>Além disso, restaura a sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_3230192 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>300%</color> dano a até 3 inimigos dentro de 3 grupos ao redor. Ofertas <color=#FFFF00>300%</color> Dano que ignora DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, perde Sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_3230191 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 250% de dano a até 3 inimigos em 3 grupos ao redor. Causa 250% de dano ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada pilha de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, restaura a sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_3260192 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>300%</color> dano aos 3 inimigos mais próximos. Ofertas <color=#FFFF00>300%</color> Dano que ignora DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, perde Sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_3260191 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 250% de dano aos 3 inimigos mais próximos. Causa 250% de dano ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, restaura a sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_32001922 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>300%</color> dano a até 4 inimigos dentro de 3 grupos circundantes. Ofertas <color=#FFFF00>300%</color> Dano que ignora DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 25% do dano causado. <color=#FFFF00>Além disso, perde Sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_32001912 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 250% de dano a até 4 inimigos em 3 grupos ao redor. Causa 250% de dano ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 25% do dano causado. <color=#FFFF00>Além disso, restaura a sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_32301922 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>300%</color> dano a até 4 inimigos dentro de 3 grupos circundantes. Ofertas <color=#FFFF00>300%</color> Dano que ignora DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, perde Sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_32301912 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 250% de dano a até 4 inimigos em 3 grupos ao redor. Causa 250% de dano ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, restaura a sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_32601922 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>300%</color> dano aos 4 inimigos mais próximos. Ofertas <color=#FFFF00>300%</color> Danos ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada pilha de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, perde Sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_32601912 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 250% de dano aos 4 inimigos mais próximos. Causa 250% de dano ignorando DEF quando há apenas 1 inimigo no alcance. O dano final causado aos alvos aumenta em 10% para cada pilha de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado. <color=#FFFF00>Além disso, restaura a sanidade igual à porcentagem de HP restaurada</color>.",
  str_skill_desc_340019 = "Ofertas <color=#00F6FF>250%</color> dano a até 4 inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>250%</color> Danos ignorando DEF quando há apenas 1 inimigo no alcance. Aumenta o dano final causado aos alvos em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 25% do dano causado.",
  str_skill_desc_343019 = "Ofertas <color=#00F6FF>250%</color> dano a até 4 inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>250%</color> Dano que ignora DEF quando há apenas 1 inimigo no alcance. Aumenta o dano final causado aos alvos em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado.",
  str_skill_desc_346019 = "Ofertas <color=#00F6FF>250%</color> dano aos 4 inimigos mais próximos. Ofertas <color=#00F6FF>250%</color> Dano que ignora DEF quando há apenas 1 inimigo no alcance. Aumenta o dano final causado aos alvos em 10% para cada acúmulo de Sangramento que eles tiverem. Restaura HP igual a 35% do dano causado.",
  str_skill_name_290510101 = "Campo de Perfuração",
  str_skill_desc_290510101 = "O Perfurador seleciona aleatoriamente uma área aberta para mover, causando dano de descarga a 4 ladrilhos adjacentes. No final do movimento, a habilidade gera um certo número de Campos de Energia e Campos de Suporte dentro de 2 grupos ao redor.",
  str_skill_desc_290511102 = "O Sondador seleciona aleatoriamente uma área aberta para mover, causando dano de descarga a 4 ladrilhos adjacentes. Ao final do movimento, esta habilidade gera um certo número de Campos de Energia e Campos de Suporte.",
  str_skill_desc_290511103 = "Ao agir, gera um certo número de Campos de Energia e Campos de Suporte na área circundante.",
  str_skill_name_290510102 = "Campo de Energia do Perfurador",
  str_skill_desc_290510102 = "O Perfurador absorve Campos de Energia no campo, transformando-os em uma Plataforma de Perfuração no local e causa dano em todo o campo.",
  str_skill_name_290510203 = "Campo de Apoio ao Perfurador",
  str_skill_desc_290510203 = "O Perfurador bloqueia a localização dos Aurorians com a Plataforma de Perfuração e leva os 5 Campos de Suporte mais próximos ao jogador para causar dano ao jogador. Contagem regressiva de carga de energia em 2.",
  str_skill_desc_290510213 = "O Perfurador bloqueia a localização dos Aurorians com a Plataforma de Perfuração e leva os 3 Campos de Suporte mais próximos ao jogador para causar dano ao jogador. Contagem regressiva de carga de energia em 1.",
  str_skill_name_290510204 = "Autodestruição da plataforma do perfurador",
  str_skill_desc_290510204 = "A plataforma de perfuração se autodestrói ao reunir energia total, causando grande dano a todo o campo.",
  str_skill_name_290510123 = "Em operação",
  str_skill_desc_290510123 = "O sondador opera atrás da plataforma. O Perfurador e a Plataforma Perfurador possuem HP independente.",
  str_skill_desc_290511101 = "O Perfurador se move em direção ao jogador, causando dano de descarga a 4 ladrilhos adjacentes. Ao final do movimento, a habilidade gera Campos de Suporte em 4 ladrilhos adjacentes.",
  str_skill_desc_290511203 = "O Driller bloqueia a localização do jogador com a Plataforma do Driller e usa todos os Campos de Suporte para causar dano ao jogador. A quantidade de dano causado ao jogador aumenta com o número de Campos de Suporte.",
  str_skill_desc_290512101 = "O Perfurador se concentra em cavar, gerando um pequeno número de Campos de Energia e Campos de Suporte ao seu redor no início da rodada.",
  str_skill_upgrade_desc_16019913 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16019916 = "Aprimoramento de Habilidade de Equipamento: Quando Yingel causa dano a alvos que tenham uma Ferida Aberta, ela ignora <color=#00F6FF>5%</color> de sua DEF para cada 1 Ferida Aberta que eles tiverem. (Válido para Ascensão III).",
  str_skill_name_2001991 = "hiper foco",
  str_skill_name_2001992 = "hiper foco",
  str_skill_name_2001993 = "hiper foco",
  str_skill_desc_2001991 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo mais próximo.",
  str_skill_desc_2001992 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo mais próximo.",
  str_skill_desc_2001993 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo mais próximo.",
