  str_skill_name_2201993 = "hiper foco",
  str_skill_desc_2201991 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo que tem mais HP e mais Feridas Abertas, ou então ataca o inimigo mais próximo.",
  str_skill_desc_2201992 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo que tem mais HP e mais Feridas Abertas, ou então ataca o inimigo mais próximo.",
  str_skill_desc_2201993 = "Ofertas <color=#00F6FF>{1}%</color> dano ao inimigo que tem mais HP e mais Feridas Abertas, ou então ataca o inimigo mais próximo.",
  str_skill_name_3001991 = "ressonância do céu",
  str_skill_desc_3001991 = "Converte qualquer 1 azulejo selecionado para um amarelo <link=\"30080\"><#FFAE07><u>telha prisma em forma de cruz</u></color></link>.",
  str_skill_passive_name_410199 = "Recarga Especializada",
  str_skill_passive_name_420199 = "Recarga Especializada",
  str_skill_passive_name_430199 = "Recarga Especializada",
  str_skill_passive_name_436199 = "Recarga Especializada",
  str_skill_passive_desc_410199 = "O Ataque Normal de Yingel causa dano a cada <color=#00F6FF>segundo</color> Ataque normal. Seu multiplicador de dano aumenta para <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_420199 = "O Ataque Normal de Yingel causa dano a cada <color=#00F6FF>segundo</color> Ataque Normal. Seu multiplicador de dano aumenta para <color=#00F6FF>{1}</color> e inflige 1 Ferida Aberta, até 20 acúmulos. Para cada Ferida Aberta que um alvo tiver, o dano final do Chain Combo de Yingel aumenta em <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_430199 = "O Ataque Normal de Yingel causa dano a cada <color=#00F6FF>segundo</color> Ataque normal. Seu multiplicador de dano aumenta para <color=#00F6FF>{1}</color> e inflige 1 Ferida Aberta, até 20 acúmulos. Para cada Ferida Aberta que um alvo tiver, os ataques de Yingel ignoram <color=#00F6FF>3%</color> de sua DEF e seu dano final Chain Combo aumenta em <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_436199 = "O Ataque Normal de Yingel causa dano a cada <color=#00F6FF>segundo</color> Ataque Normal. Seu multiplicador de dano aumenta para <color=#00F6FF>{1}</color> e inflige 1 Ferida Aberta, até 20 acúmulos. Para cada Ferida Aberta que um alvo tiver, os ataques de Yingel ignoram <color=#00F6FF>5%</color> de sua DEF e seu dano final Chain Combo aumenta em <color=#00F6FF>3%</color>.",
  str_skill_desc_1601751002 = "Azulejo de prisma em forma de cruz",
  str_skill_desc_160175102 = "consome <color=#00F6FF>3</color> Energia cúbica para converter qualquer 1 ladrilho em um ladrilho de prisma em forma de cruz.",
  str_skill_name_3400231 = "Sonata do Abismo Variante I",
  str_skill_name_3430231 = "Sonata do Abismo Variante I",
  str_skill_name_3400232 = "Sonata do Abismo Variante II",
  str_skill_name_3430232 = "Sonata do Abismo Variante II",
  str_skill_desc_3400231 = "<color=#FFFF00>Tempo de recarga da habilidade -2 após a conjuração</color>. Ofertas <color=#FFFF00>250%</color> dano a todos os inimigos. Esta variante não pode ativar o efeito Assustar da Habilidade de Equipamento.",
  str_skill_desc_3430231 = "<color=#FFFF00>Tempo de recarga da habilidade -2 após a conjuração</color>. Ofertas <color=#FFFF00>250%</color> dano a todos os inimigos. Esta variante não pode ativar o efeito Assustar da Habilidade de Equipamento.",
  str_skill_desc_3400232 = "<color=#FFFF00>Recarga de habilidade +2 após conjuração</color>. <color=#FFFF00>Inflige todos os inimigos com <link=\"10003\"><#FFAE07><u>Amedrontar</u></color></link> por 1 rodada</color> e negócios <color=#FFFF00>550%</color> danos a eles.",
  str_skill_desc_3430232 = "<color=#FFFF00>Recarga de habilidade +2 após conjuração</color>. <color=#FFFF00>Inflige todos os inimigos com <link=\"10003\"><#FFAE07><u>Amedrontar</u></color></link> por 1 rodada</color> e negócios <color=#FFFF00>550%</color> danos a eles.",
  str_skill_passive_desc_440023 = "Ganha 1 stack de Shiver Mark ao usar um Chain Combo, até <color=#00F6FF>5</color> pilhas. Cada pilha aumenta o dano da Habilidade Ativa em <color=#00F6FF>20%</color>. Usar uma Habilidade Ativa inflige <link=\"10003\"><#FFAE07><u>Amedrontar</u></color></link> em um número de inimigos equivalente ao número de pilhas para <color=#00F6FF>1</color> redondo. Ativando a Habilidade Ativa <color=#00F6FF>não limpa pilhas</color>. Se 5 stacks já estiverem presentes antes de liberar uma habilidade Chain Combo, ela causará dano adicional ao inimigo mais próximo. Connolly causa um dano final adicional de 15% a <link=\"10003\"><#FFAE07><u>Com medo</u></color></link> inimigos.",
  str_skill_upgrade_refine_desc_16002311 = "<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Tempo de recarga da habilidade -2 após a conjuração</color>. Ofertas <color=#FFFF00>250%</color> dano a todos os inimigos. Esta variante não pode ativar o efeito Assustar da Habilidade de Equipamento.",
  str_skill_upgrade_refine_desc_16002312 = "Aprimoramento de Habilidade de Equipamento: Connolly ofertas <color=#00F6FF>um dano final adicional de 15%</color> aos inimigos infligidos com Frighten.",
  str_skill_upgrade_refine_desc_16002313 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Recarga de habilidade +2 após conjuração</color>. <color=#FFFF00>Inflige todos os inimigos com <link=\"10003\"><#FFAE07><u>Amedrontar</u></color></link> por 1 rodada</color> e negócios <color=#FFFF00>550%</color> danos a eles.",
  str_skill_name_290520101 = "Blitz feroz",
  str_skill_desc_290520101 = "Move-se em direção aos aurorianos e causa muito dano, depois se afasta do alvo.",
  str_skill_name_290520102 = "Blitz Feroz",
  str_skill_desc_290520102 = "Causa dano a todos os aurorianos dentro do alcance após o movimento.",
  str_skill_name_200250101 = "fogo de aproximação",
  str_skill_desc_200250101 = "Lança um ataque à distância em alvos dentro do alcance.",
  str_skill_name_200250102 = "faca de assalto",
  str_skill_desc_200250102 = "Lança um ataque corpo a corpo em alvos dentro do alcance.",
  str_skill_name_290500122 = "ovo de aranha",
  str_skill_desc_290500122 = "Um ovo de aranha posto pela Rainha Aranha. Ele eclode em um Filhote de Aranha em um curto período de tempo.",
  str_skill_name_3400901 = "Doce Beijo Variante I",
  str_skill_name_3420901 = "Doce Beijo Variante I",
  str_skill_name_3400902 = "Doce Beijo Variante II",
  str_skill_name_3420902 = "Doce Beijo Variante II",
  str_skill_desc_3400901 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Ofertas <color=#FFFF00>{1}%</color> danos a todos os inimigos <color=#FFFF00>e os atordoa</color>.",
  str_skill_desc_3420901 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Ofertas <color=#FFFF00>{1}%</color> danos a todos os inimigos <color=#FFFF00>e os atordoa</color>.",
  str_skill_desc_3400902 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>{1}%</color> dano a todos os inimigos.",
  str_skill_desc_3420902 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>{1}%</color> dano a todos os inimigos.",
  str_skill_passive_desc_440090 = "Aumenta o dano de Barbara contra inimigos ocupando um ladrilho vermelho em <color=#00F6FF>10%</color>. Para cada ladrilho vermelho aos pés do inimigo, o bônus de dano aumenta em <color=#00F6FF>1%</color>. Também concede companheiros de equipe Fire Aurorian <color=#00F6FF>50%</color> deste bônus.",
  str_skill_upgrade_refine_desc_15009011 = "Aprimoramento de habilidade de equipamento: para cada 1 ladrilho vermelho aos pés do inimigo, o bônus de dano aumenta em <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15009012 = "<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Ofertas <color=#FFFF00>600%</color> danos a todos os inimigos <color=#FFFF00>e os atordoa</color>.",
  str_skill_upgrade_refine_desc_15009013 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Ofertas <color=#FFFF00>450%</color> dano a todos os inimigos.",
  str_skill_name_5000961 = "Vincular",
  str_skill_desc_5000961 = "Quando os aurorianos entram em 2 aglomerados ao redor do Spikepest, um link é automaticamente estabelecido entre eles. O link é interrompido quando os aurorianos movem 4 aglomerados próximos para longe do Spikepest. Enquanto vinculado, o Spikepest compartilha 50% do dano recebido pelo jogador.",
  str_skill_desc_4001531 = "Lança habilidade para repelir os inimigos dentro de 3 grupos circundantes por 1 ladrilho e converte os ladrilhos sob os inimigos em ladrilhos amarelos.",
  str_skill_desc_4001751 = "Ao lançar a habilidade, cada vez que o jogador sofrer dano nesta rodada, 1 ladrilho do mesmo elemento do capitão será atualizado e uma pequena quantidade do HP do time será restaurada.",
  str_skill_name_2001921 = "Ataque da Espada",
