  str_skill_name_3301922 = "Entrada Gloriosa",
  str_skill_name_3301923 = "Entrada Gloriosa",
  str_skill_name_3401921 = "Golpe do Garanhão Blindado",
  str_skill_desc_2001921 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2001922 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_2001923 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_3001920 = "Ofertas <color=#00F6FF>270%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado.",
  str_skill_desc_34019200 = "Ofertas <color=#00F6FF>270%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado e gera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> aleatoriamente dentro da área de efeito. Os efeitos desta habilidade são aprimorados de acordo com o número de <color=#00F6FF>espinhos</color>:\n<color=#00F6FF>mais de 9</color>: Expande o alcance do dano para 25 blocos em uma forma quadrada.\n<color=#00F6FF>mais de 19</color>: Cooldown da habilidade -1.\n<color=#00F6FF>mais de 29</color>: Causa 270% de dano a todos os inimigos.",
  str_skill_desc_34019201 = "Ofertas <color=#00F6FF>270%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado e gera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> aleatoriamente dentro da área de efeito. Os efeitos desta habilidade são aprimorados de acordo com o número de <color=#00F6FF>espinhos</color>:\n<color=#00F6FF>mais de 9</color>: Expande o alcance do dano para 25 blocos em uma forma quadrada.\n<color=#00F6FF>mais de 19</color>: Cooldown da habilidade -1.\n<color=#00F6FF>mais de 29</color>: Causa 270% de dano a todos os inimigos.",
  str_skill_desc_34019202 = "Ofertas <color=#00F6FF>270%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado e gera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> aleatoriamente dentro da área de efeito. Os efeitos desta habilidade são aprimorados de acordo com o número de <color=#00F6FF>espinhos</color>:\n<color=#00F6FF>mais de 9</color>: Expande o alcance do dano para 25 blocos em uma forma quadrada.\n<color=#00F6FF>mais de 19</color>: Cooldown da habilidade -1.\n<color=#00F6FF>mais de 29</color>: Causa 270% de dano a todos os inimigos.",
