  str_skill_desc_3301921 = "Ofertas <color=#00F6FF>270%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centrado em 1 ladrilho selecionado. Os efeitos da habilidade são aprimorados de acordo com o número de <color=#00F6FF>espinhos</color>:\n<color=#00F6FF>>9</color>: Expande o alcance do dano para 25 blocos em uma forma quadrada.\n<color=#00F6FF>>19</color>: Cooldown da habilidade -1.\n<color=#00F6FF>>29</color>: Causa 270% de dano a todos os inimigos.",
  str_skill_desc_3301922 = "Ofertas <color=#00F6FF>270%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centrado em 1 ladrilho selecionado. Os efeitos da habilidade são aprimorados de acordo com o número de <color=#00F6FF>espinhos</color>:\n<color=#00F6FF>>9</color>: Expande o alcance do dano para 25 blocos em uma forma quadrada.\n<color=#00F6FF>>19</color>: Cooldown da habilidade -1.\n<color=#00F6FF>>29</color>: Causa 270% de dano a todos os inimigos.",
  str_skill_desc_3301923 = "Ofertas <color=#00F6FF>270%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centrado em 1 ladrilho selecionado. Os efeitos da habilidade são aprimorados de acordo com o número de <color=#00F6FF>espinhos</color>:\n<color=#00F6FF>>9</color>: Expande o alcance do dano para 25 blocos em um formato quadrado.\n<color=#00F6FF>>19</color>: Cooldown da habilidade -1.\n<color=#00F6FF>>29</color>: Causa 270% de dano a todos os inimigos.",
  str_skill_desc_3401921 = "custos <color=#00F6FF>5</color> Espinhos: Nesta rodada, ataques normais podem ser lançados na diagonal e o dano de ataque normal aumenta em <color=#00F6FF>20%</color> (pode ser empilhado quando usado mais de uma vez). Este ataque não é considerado uma habilidade ativa.",
  str_skill_passive_name_410192 = "Selo de Espinhos",
  str_skill_passive_name_416192 = "Selo de Espinhos",
  str_skill_passive_name_430192 = "Selo de Espinhos",
  str_skill_passive_name_436192 = "Selo de Espinhos",
  str_skill_passive_desc_410192 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta a taxa de dano do Chain Combo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416192 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta a taxa de dano do Chain Combo em <color=#00F6FF>{1}</color>. Ganhos <color=#00F6FF>5</color> Espinhos no início de cada onda.",
  str_skill_passive_desc_430192 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta a taxa de dano do Chain Combo em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_436192 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta a taxa de dano do Chain Combo em <color=#00F6FF>{1}</color>. Ganhos <color=#00F6FF>5</color> Espinhos no início de cada onda.",
  str_skill_passive_desc_440192 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta a taxa de dano do Chain Combo em <color=#00F6FF>3%</color>.",
  str_skill_passive_desc_446192 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta a taxa de dano do Chain Combo em <color=#00F6FF>3%</color>. Ganhos <color=#00F6FF>5</color> Espinhos no início de cada onda.",
