  str_skill_upgrade_refine_desc_16019212 = "Aprimoramento de Habilidade de Equipamento: Ganhos <color=#00F6FF>5</color> Espinhos no início da batalha.",
  str_skill_upgrade_refine_desc_16019213 = "Aprimoramento de Habilidade Ativa: Gera <color=#00F6FF>2</color> <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> aleatoriamente dentro da área de efeito.",
  str_skill_passive_desc_440193 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta o dano do Chain Combo em <color=#00F6FF>3%</color>. Ganhos <color=#00F6FF>5</color> Espinhos no início da batalha.",
  str_skill_passive_desc_446193 = "Ganhos 1 <color=#00F6FF>Espinho</color> para cada 1 <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link> obtido pela equipe (incluindo <link=\"30065\"><#FFAE07><u>absorvido</u></color></link> azulejos). Cada Espinho aumenta a taxa de dano do Chain Combo em <color=#00F6FF>3%</color>. Ganhos <color=#00F6FF>5</color> Espinhos no início da batalha e no início de cada onda.",
  str_skill_upgrade_desc_16019213 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16019216 = "Aprimoramento de Habilidade de Equipamento: Ganhos <color=#00F6FF>5</color> Espinhos no início de cada onda.",
  str_skill_name_5010152 = "Encorajar",
  str_skill_desc_5010152 = "Shadow Walker se move para a área com as unidades mais amigas e aplica Strength Mark a todos os aliados, concedendo aumento de ATK.",
  str_skill_name_888450061 = "Reef Cozen",
  str_skill_desc_888450061 = "Invoca 1 Cozen que ataca aurorianos a cada 2 rodadas.",
  str_skill_desc_888450081 = "Siphorb absorve energia do ladrilho em que está e ladrilhos que compartilham o mesmo elemento dentro de 1 cluster circundante e, em seguida, libera um Orbe de Energia que ataca todos os inimigos. O dano aumenta com o número de peças absorvidas. Gera uma área perigosa onde os aurorianos ficam parados 2 rodadas depois de atingir os aurorianos.",
  str_skill_upgrade_refine_desc_13004611 = "Aprimoramento de Habilidade de Equipamento: <color=#00F6FF>duplas</color> o bônus de dano de Ataque Normal Keating recebe de cada Marca do Riso.",
  str_skill_upgrade_refine_desc_13004613 = "Aprimoramento de Habilidade de Equipamento: Todo Ataque Normal Keating negócios tem um <color=#00F6FF>35%</color> chance de infligir 1 Marca do Riso nos inimigos.",
  str_skill_passive_desc_4400461 = "Matar inimigos com Laughter Mark inflige <color=#00F6FF>1</color> pilha adicional de Marca do Riso para todos os inimigos restantes. Cada marca aumenta o dano do Ataque Normal dos Thunder Aurorians em <color=#00F6FF>1,8%</color>. o bônus Keating recebe é <color=#00F6FF>dobrou</color>.",
  str_skill_desc_340046 = "Reduz o cooldown da habilidade em <color=#00F6FF>2</color> no início da batalha. Gera um clone em um ladrilho selecionado que puxa os inimigos dentro de <color=#00F6FF>3 grupos circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color> </link> em inimigos com 5 pilhas de Mark por 2 rodadas.",
  str_skill_desc_342046 = "Reduz o cooldown da habilidade em <color=#00F6FF>2</color> no início da batalha. Gera um clone em um ladrilho selecionado que puxa os inimigos dentro de <color=#00F6FF>3 grupos circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color> </link> em inimigos com 4 acúmulos de Marca por 2 rodadas e inflige <link=\"10004\"><#FFAE07><u>Paralisia</u></color></link> em inimigos com 6 acúmulos de Marca por 1 rodada.",
  str_skill_desc_345046 = "Reduz o cooldown da habilidade em <color=#00F6FF>2</color> no início da batalha. Gera um clone em um bloco selecionado que puxa <color=#00F6FF>todos</color> os inimigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link > em inimigos com 4 acúmulos de Marca por 2 rodadas e inflige <link=\"10004\"><#FFAE07><u>Paralisia</u></color></link> em inimigos com 6 acúmulos de Marca por 1 rodada .",
  str_skill_passive_desc_4400463 = "Matar inimigos com Marca do Riso inflige <color=#00F6FF>+1</color> pilha adicional a todos os inimigos restantes. Cada marca aumenta o dano do Ataque Normal dos Thunder Aurorians em <color=#00F6FF>2%</color>. O bônus que Keating recebe é <color=#00F6FF>dobrado</color>. Cada Ataque Normal que Keating faz tem uma chance de <color=#00F6FF>35%</color> de infligir 1 Marca do Riso nos inimigos.",
  str_skill_upgrade_refine_desc_16006011 = "Aprimoramento de Habilidade de Equipamento: Aumenta o dano de respingo de Ataques Normais infligidos no estado Meio-dia para <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_16006012 = "Aprimoramento de Habilidade de Equipamento: Aumenta o dano de Ataques Normais infligidos no estado Meio-dia em <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_16006013 = "Aprimoramento do Chain Combo: Aumenta o alcance do Chain Combo em 1 cluster ao redor no estado Noon.",
  str_skill_passive_desc_4400601 = "No estado Meio-dia, os Ataques Normais causam <color=#00F6FF>20%</color> de dano aumentado e um adicional de <color=#00F6FF>60%</color> <link=\"30015\"><#FFAE07><u >Splash</u></color></link> dano a todos os alvos em <color=#00F6FF>4 ladrilhos em forma de cruz</color> ao redor do inimigo.",
  str_skill_passive_desc_4400602 = "No estado Meio-dia, os Ataques Normais causam <color=#00F6FF>25%</color> de dano aumentado e um adicional de <color=#00F6FF>60%</color> <link=\"30015\"><#FFAE07><u >Splash</u></color></link> dano a todos os alvos em <color=#00F6FF>4 ladrilhos em forma de cruz</color> ao redor do inimigo.",
  str_skill_desc_243601 = "Ofertas <color=#00F6FF>155%</color> dano a 4 inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Aumenta o alcance em 1 cluster ao redor no estado Meio-dia.",
  str_skill_desc_243602 = "Ofertas <color=#00F6FF>160%</color> dano a 4 inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Aumenta o alcance em 1 cluster ao redor no estado Meio-dia.",
  str_skill_desc_243603 = "Ofertas <color=#00F6FF>175%</color> dano a 4 inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color>. Aumenta o alcance em 1 cluster ao redor no estado Meio-dia.",
  str_skill_name_2002001 = "A Escuridão Vem",
  str_skill_name_2002002 = "A Escuridão Vem",
  str_skill_name_2002003 = "A Escuridão Vem",
