  str_skill_name_2102003 = "A Escuridão Vem",
  str_skill_name_300200 = "Ode às Profundezas",
  str_skill_name_305200 = "Ode às Profundezas",
  str_skill_name_320200 = "Ode às Profundezas",
  str_skill_name_325200 = "Ode às Profundezas",
  str_skill_passive_name_410200 = "Análise de Fraqueza",
  str_skill_passive_name_430200 = "Análise de Fraqueza",
  str_skill_desc_2002001 = "Causa <color=#00F6FF>{1}%</color> de dano a 3 inimigos em <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_desc_2002002 = "Ofertas <color=#00F6FF>{1}%</color> dano a 3 inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color>.",
  str_skill_desc_2002003 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próx.",
  str_skill_desc_2102001 = "Causa <color=#00F6FF>{1}%</color> de dano a 3 inimigos em <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_desc_2102002 = "Ofertas <color=#00F6FF>{1}%</color> dano a 3 inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color>.",
  str_skill_desc_2102003 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próx.",
  str_skill_desc_300200 = "Seleciona até 2 inimigos através dos ladrilhos abaixo deles, causando <color=#00F6FF>{1}%</color> danos a eles. Todos os inimigos nas peças selecionadas e nas peças intermediárias são <link=\"30081\"><#FFAE07><u>retirado</u></color></link> ao centro desta área. Se apenas um inimigo for selecionado, ele receberá apenas dano e não será puxado.",
  str_skill_desc_305200 = "Escolha até 2 inimigos por meio de um ladrilho que eles ocupam e cause <color=#00F6FF>{1}%</color> de dano a eles. Todos os inimigos nas peças selecionadas e nas peças intermediárias são <link=\"30081\"><#FFAE07><u>puxados</u></color></link> para o centro da área formada. Se apenas 1 inimigo for selecionado, ele receberá apenas dano, mas não será puxado. O dano final aumenta em <color=#00F6FF>10%</color> para cada <color=#00F6FF>1</color> ladrilho que um inimigo derruba.",
  str_skill_desc_320200 = "Escolha até 2 inimigos por meio de um ladrilho que eles ocupam e cause <color=#00F6FF>{1}%</color> de dano a eles. Todos os inimigos nas peças selecionadas e nas peças intermediárias são <link=\"30081\"><#FFAE07><u>puxados</u></color></link> para o centro da área formada. Se apenas 1 inimigo for selecionado, Anatoli substituirá como segundo alvo e se reunirá no centro.",
  str_skill_desc_325200 = "Escolha até 2 inimigos por meio de um ladrilho que eles ocupam e cause <color=#00F6FF>{1}%</color> de dano a eles. Todos os inimigos nas peças selecionadas e nas peças intermediárias são <link=\"30081\"><#FFAE07><u>puxados</u></color></link> para o centro da área formada. Se apenas 1 inimigo for selecionado, Anatoli substituirá como segundo alvo e se reunirá no centro. O dano final aumenta em <color=#00F6FF>10%</color> para cada <color=#00F6FF>1</color> ladrilho que um inimigo derruba.",
  str_skill_passive_desc_410200 = "Os Chain Combos de Anatoli causam um dano adicional <color=#00F6FF>{1}</color> dano a inimigos aleatórios adjacentes ao alvo.",
  str_skill_passive_desc_430200 = "Os Chain Combos de Anatoli causam um dano adicional <color=#00F6FF>{1}</color> dano a inimigos aleatórios adjacentes ao alvo. <color=#00F6FF>Alvo único</color> Chain Combos de todos os aliados lidam <color=#00F6FF>7%</color> dano final aumentado para <link=\"30082\"><#FFAE07><u>agrupado</u></color></link> inimigos.",
  str_skill_upgrade_desc_15020012 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_15020015 = "Aprimoramento de Habilidade Ativa: Aumenta o dano final em <color=#00F6FF>10%</color> para cada <color=#00F6FF>1</color> inimigos lado a lado são puxados.",
  str_skill_name_290530101 = "Marca do Terror",
  str_skill_desc_290530101 = "Causa dano ao alvo diretamente e gera uma marca no ladrilho em que o alvo está.",
  str_skill_name_290530102 = "Corrida do Terror",
  str_skill_desc_290530102 = "Avance até 2 ladrilhos em direção ao alvo, causando dano aos alvos ao longo do caminho e dentro de 4 ladrilhos em forma de cruz no destino. Se Dread Rush errar o alvo, Helios libera uma Marca de Terror adicional.",
  str_skill_desc_290530312 = "Avança até 2 ladrilhos em direção ao alvo, causando dano aos alvos ao longo do caminho e a 4 ladrilhos em forma de cruz no destino.",
  str_skill_name_290530103 = "salto do terror",
  str_skill_desc_290530103 = "Se o alvo estiver dentro do alcance, Helios pula próximo ao alvo, causando grande dano a ele e repelindo-o ao pousar. Se Leap of Terror errar o alvo ou o alvo não estiver dentro do alcance, Helios libera uma Terror Mark adicional.",
  str_skill_name_290530104 = "frenesi furioso",
  str_skill_desc_290530104 = "Helios se move para os locais das Marcas do Terror de acordo com a ordem em que foram geradas, então se aproxima do alvo, causando dano massivo aos alvos ao longo do caminho e dentro de um certo alcance no destino. Ao mesmo tempo, Helios converte uma parte de seus hematomas acumulados em HP.",
  str_skill_name_215009011 = "Ataque Normal",
  str_skill_desc_215009011 = "Ataca os inimigos dentro do alcance uma vez após o movimento.",
  str_skill_name_11150713 = "fonte de perigo",
  str_skill_desc_11150713 = "Retorna à Área Perigosa, recupera algum HP e se aprimora permanentemente.",
  str_skill_name_290530302 = "Corrida do Terror",
  str_skill_desc_290530302 = "Avança até 2 ladrilhos em direção ao alvo, causando dano aos alvos ao longo do caminho e a 4 ladrilhos em forma de cruz no destino.",
  str_skill_desc_11150313 = "Um misterioso Cristal de Luz que pode ser acionado ao passar por ele, convocando um raio para atacar todos os alvos, incluindo os aurorianos.",
  str_skill_name_290500102 = "Presa",
  str_skill_name_290500112 = "Presa: Spawn",
  str_skill_name_290500103 = "Caçar",
  str_skill_name_290500113 = "Caçar+",
  str_skill_name_290500104 = "Corrida",
  str_skill_name_290500114 = "Rali+",
  str_skill_desc_290500102 = "A Rainha Aranha desce sobre sua presa, lança uma teia para bloquear os ladrilhos e danifica os aurorianos.",
  str_skill_desc_290500112 = "A Rainha Aranha desce sobre sua presa, tecendo uma teia para bloquear ladrilhos e danificar os aurorianos enquanto convoca filhotes para o campo de batalha.",
  str_skill_desc_290500103 = "A Rainha Aranha coloca uma teia para prender os ladrilhos ao redor dos aurorianos e, em seguida, convoca seus filhotes para atacá-los e causar dano.",
  str_skill_desc_290500113 = "Rainha Aranha tece uma teia para prender os ladrilhos ao redor dos aurorianos, então convoca seus filhotes para atacá-los e causar dano. As peças bloqueadas retornam ao seu estado original após 1 rodada.",
  str_skill_desc_290500104 = "A Rainha Aranha convoca seus filhotes para atacar. Eles colocarão teias de aranha e bloquearão um grande número de ladrilhos.",
  str_skill_desc_290500114 = "A Rainha Aranha convoca seus filhotes para atacar. Eles vão tecer teias de aranha, bloqueando um grande número de peças. As peças bloqueadas retornam ao seu estado original após 1 rodada.",
  str_skill_name_200240102 = "Patrulha",
  str_skill_name_200240103 = "Presa",
  str_skill_name_200240104 = "Corrida",
  str_skill_desc_200240102 = "Filhotes de aranha patrulham seu território e atacam qualquer inimigo que detectem.",
  str_skill_desc_200240103 = "Filhotes de aranha atacam suas presas e tentam matá-los com um golpe.",
  str_skill_desc_200240104 = "Ao receber a convocação da Rainha Aranha, os Filhotes de Aranha se reúnem para um ataque conjunto.",
  str_skill_name_290530204 = "frenesi furioso",
  str_skill_desc_290530204 = "Helios se move para os locais das Marcas do Terror de acordo com a ordem em que foram geradas, então se aproxima do alvo, causando dano aos alvos ao longo do caminho e dentro de um certo alcance no destino. Ao mesmo tempo, Helios limpa todas as Marcas de Terror no campo de batalha e converte uma parte de seus Contusões acumulados em HP com base no número de Marcas de Terror limpas.",
  str_skill_name_290530404 = "frenesi furioso",
  str_skill_desc_290530404 = "Helios se move para os locais das Marcas do Terror de acordo com a ordem em que foram geradas, então se aproxima do alvo, causando dano massivo aos alvos ao longo do caminho e dentro de um certo alcance no destino. Ao mesmo tempo, Helios converte uma parte de seus hematomas acumulados em HP.",
  str_skill_upgrade_desc_16020113 = "Aprimoramento de habilidade ativa: mudanças <color=#FFFF00>A Invocação</color> para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate.",
  str_skill_upgrade_desc_16020116 = "Aprimoramento de habilidade ativa: reduz o tempo de recarga de <color=#FFFF00>Nascimento de Baba Yaga</color> por <color=#FFFF00>1</color>.",
  str_skill_upgrade_refine_desc_16020111 = "Aprimoramento de Habilidade de Equipamento: Quando equipado com um escudo, aumenta o bônus de dano básico para <color=#FFFF00>15%</color>.",
  str_skill_upgrade_refine_desc_16020112 = "Aprimoramento de Habilidade Ativa: Aumenta o Escudo obtido de <color=#FFFF00>A Invocação</color> para <color=#FFFF00>90%</color> de HP.",
  str_skill_upgrade_refine_desc_16020113 = "Aprimoramento de habilidade de equipamento: quando o HP cai ao mínimo, ganha um bônus de dano adicional de até <color=#00F6FF>10%</color>.",
  str_skill_name_2002011 = "Nada permanece",
  str_skill_name_2002012 = "Nada permanece",
  str_skill_name_2002013 = "Nada permanece",
  str_skill_desc_2002011 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2002012 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_2002013 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_passive_name_410201 = "Auxílio de Verônica",
  str_skill_passive_desc_410201 = "Quando blindados, todos Mia: O dano de Lustrous Soul aumenta em <color=#00F6FF>{1}</color>, e ela ganha bônus de dano com base no valor do escudo. Quando o valor do escudo atinge 50% do HP máximo da equipe, o bônus de dano atinge o máximo em <color=#00F6FF>10%</color>.",
  str_skill_passive_name_420201 = "Auxílio de Verônica",
  str_skill_passive_desc_420201 = "Quando blindados, todos Mia: O dano de Lustrous Soul aumenta em <color=#00F6FF>{1}</color>, e ela ganha bônus de dano com base no valor do escudo e na porcentagem de HP atual. Quando o valor do escudo atinge 50% do HP máximo da equipe, o bônus de dano atinge o máximo em <color=#00F6FF>10%</color>, e quando o HP atinge o nível mais baixo, o dano bônus atinge o máximo em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_4202011 = "Quando blindados, todos Mia: O dano de Lustrous Soul aumenta em <color=#00F6FF>15%</color>, e ela ganha bônus de dano com base no valor do escudo e na porcentagem de HP atual. Quando o valor do escudo atinge 50% do HP máximo da equipe, o bônus de dano atinge o máximo em <color=#00F6FF>10%</color>, e quando o HP atinge o mínimo, o bônus de dano atinge o máximo em <color=#00F6FF>5%</color>.",
  str_skill_passive_desc_4432011 = "Quando blindados, todos Mia: O dano de Lustrous Soul aumenta em <color=#00F6FF>15%</color>, e ela ganha bônus de dano com base no valor do escudo e na porcentagem de HP atual. Quando o valor do escudo atinge 50% do HP máximo da equipe, o dano bônus atinge o máximo em <color=#00F6FF>10%</color>, e quando o HP atinge o mínimo, o bônus de dano atinge o máximo em <color=#00F6FF>10%</color>.",
  str_skill_name_300201 = "A Invocação",
  str_skill_name_330201 = "Nascimento de Baba Yaga",
  str_skill_name_336201 = "Nascimento de Baba Yaga",
  str_skill_name_340201 = "Nascimento de Baba Yaga",
  str_skill_name_346201 = "Nascimento de Baba Yaga",
  str_skill_desc_300201 = "Ao entrar no Estado Lustroso, aumenta o ATK básico em <color=#00F6FF>15%</color> e os Ataques Normais podem ser aplicados na diagonal, duram 1 rodada. Instantaneamente ganha um escudo igual a <color=#00F6FF>75%</color> de Mia: HP de Lustrous Soul.",
  str_skill_desc_342201 = "Ao entrar no Estado Lustroso, aumenta o ATK básico em <color=#00F6FF>15%</color> e os Ataques Normais podem ser aplicados na diagonal, duram 1 rodada. Instantaneamente ganha um escudo igual a <color=#00F6FF>90%</color> de Mia: HP de Lustrous Soul.",
