  str_skill_desc_3252031 = "consome <color=#00F6FF>10%</color> do HP máximo da equipe. Ao conectar peças para esta rodada, a primeira peça será considerada uma <color=#00F6FF>azulejo cromático</color>. Esta habilidade não pode ser usada quando o HP é insuficiente.",
  str_skill_passive_name_410203 = "Proteja-me!",
  str_skill_passive_name_430203 = "Proteja-me!",
