  str_skill_name_3302022 = "Escuridão Despedaçada",
  str_skill_name_3362022 = "Escuridão Despedaçada",
  str_skill_desc_2002021 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_2002022 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>24 telhas em forma radial</color>.",
  str_skill_desc_2002023 = "Ofertas <color=#00F6FF>{1}%</color> dano em um <color=#00F6FF>forma radial para o alcance máximo</color> e gera 1 Lâmina de Dawn em qualquer um dos ladrilhos atravessáveis mais distantes. Aciona até 1 vez por rodada.\n\n",
  str_skill_desc_3002021 = "No início da batalha, reduz o cooldown da skill em <color=#00F6FF>3</color>. Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>500%</color> dano. Em seguida, gera Blade of Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatoriamente dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego reduz o cooldown da skill em <color=#00F6FF>1</color>.",
  str_skill_desc_3032021 = "Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>500%</color> dano. Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatórios dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego reduz o cooldown da skill em <color=#00F6FF>1</color>.",
  str_skill_desc_3202021 = "No início da batalha, reduz o cooldown da skill em <color=#00F6FF>3</color>. Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>500%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> do alvo <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatoriamente dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego reduz o cooldown da skill em <color=#00F6FF>1</color>.",
  str_skill_desc_3232021 = "Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>500%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> deles <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatoriamente dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego reduz o cooldown da skill em <color=#00F6FF>1</color>.",
  str_skill_desc_3402021 = "No início da batalha, reduz o cooldown da skill em <color=#00F6FF>3</color>. Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>500%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> do alvo <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatórios dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego ou recuperado reduz o cooldown da habilidade em <color=#00F6FF>1</color>.",
  str_skill_desc_3432021 = "Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>500%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> deles <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatórios dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego ou recuperado reduz o cooldown da habilidade em <color=#00F6FF>1</color>.",
  str_skill_desc_3402022 = "No início da batalha, reduz o cooldown da habilidade em <color=#00F6FF>3</color>. Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>650%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> do alvo <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatórios dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego ou recuperado reduz o cooldown da habilidade em <color=#00F6FF>1</color>.",
  str_skill_desc_3432022 = "Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>650%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> deles <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatoriamente dentro de 2 clusters ao redor do ladrilho selecionado. Cada lâmina de Dawn pego ou recuperado reduz o cooldown da habilidade em <color=#00F6FF>1</color>.",
  str_skill_desc_3402023 = "No início da batalha, reduz o cooldown da skill em <color=#00F6FF>3</color>. Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>650%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> do alvo <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatórios dentro de 2 clusters ao redor do ladrilho selecionado. Ao matar o alvo, gera 1 Lâmina de Dawn no local do alvo. Cada lâmina de Dawn pego ou recuperado reduz o cooldown da habilidade em <color=#00F6FF>1</color>.",
  str_skill_desc_3432023 = "Seleciona 1 ladrilho dentro <color=#00F6FF>3 aglomerados circundantes</color> onde um inimigo está parado e lida <color=#00F6FF>650%</color> dano, mais dano adicional que é <color=#00F6FF>4%</color> deles <color=#00F6FF>máximo</color> HP (afetado por contadores de elemento). Em seguida, gera uma Lâmina de Dawn sobre <color=#00F6FF>3</color> ladrilhos atravessáveis aleatoriamente dentro de 2 clusters ao redor do ladrilho selecionado. Ao matar o alvo, gera 1 Lâmina de Dawn no local do alvo. Cada lâmina de Dawn pego ou recuperado reduz o cooldown da habilidade em <color=#00F6FF>1</color>.",
  str_skill_desc_3302022 = "Seleciona qualquer <color=#00F6FF>1</color> Lâmina de Dawn e o recupera.",
  str_skill_desc_3362022 = "Seleciona qualquer <color=#00F6FF>1</color> Lâmina de Dawn e o recupera.",
  str_skill_passive_name_410202 = "Onde a Luz Brilha",
  str_skill_passive_name_420202 = "Onde a Luz Brilha",
  str_skill_passive_name_430202 = "Onde a Luz Brilha",
  str_skill_passive_desc_410202 = "Para cada lâmina de Dawn recuperado, acumule 1 pilha de Ode to Ephemeral Night. O seguinte Ataque Normal consome 1 acúmulo de Ode à Noite Efêmera e causa dano adicional ao alvo igual a <color=#00F6FF>{1}</color> deles <color=#00F6FF>atual</color> HP (o dano adicional não será menor que <color=#00F6FF>{2}</color> e não mais do que <color=#00F6FF>{3}</color> de ATK básico).",
  str_skill_passive_desc_420202 = "Para cada lâmina de Dawn recuperado, acumule 1 pilha de Ode to Ephemeral Night. O seguinte Ataque Normal consome 1 pilha de Ode to Ephemeral Night e causa dano adicional ao alvo igual a <color=#00F6FF>{1}</color> deles <color=#00F6FF>atual</color> HP (o dano adicional não será menor que <color=#00F6FF>{2}</color> e não mais do que <color=#00F6FF>{3}</color> de ATK básico).",
  str_skill_passive_desc_430202 = "Para cada lâmina de Dawn pego ou recuperado, acumule 1 pilha de Ode to Ephemeral Night. O seguinte Ataque Normal consome 1 pilha de Ode to Ephemeral Night e causa dano adicional ao alvo igual a <color=#00F6FF>{1}</color> deles <color=#00F6FF>atual</color> HP (o dano adicional não será menor que <color=#00F6FF>{2}</color> e não mais do que <color=#00F6FF>{3}</color> de ATK básico).",
  str_skill_passive_desc_440202 = "Para cada lâmina de Dawn recuperado, acumule 1 pilha de Ode to Ephemeral Night. O seguinte Ataque Normal consome 1 pilha de Ode to Ephemeral Night e causa dano adicional ao alvo igual a <color=#00F6FF>4%</color> do <color=#00F6FF>atual</color> HP (o dano adicional não será menor que <color=#00F6FF>150%</color> e não mais do que <color=#00F6FF>600%</color> de ATK básico).",
  str_skill_upgrade_desc_16020213 = "Aprimoramento de habilidade ativa: mudanças <color=#FFFF00>dias sem fim</color> para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate.",
  str_skill_upgrade_desc_16020216 = "Aprimoramento de Habilidade Ativa: Reduz o cooldown de habilidade de <color=#FFFF00>Escuridão Despedaçada</color> por <color=#FFFF00>1</color> rodada (válido para Ascension III).",
  str_skill_upgrade_refine_desc_16020211 = "Aprimoramento de Habilidade de Equipamento: Aumenta o limite de dano adicional até <color=#00F6FF>600%</color> de ATK.",
  str_skill_upgrade_refine_desc_16020212 = "Aprimoramento de habilidade ativa: aumenta o dano a <color=#00F6FF>650%</color>.",
  str_skill_upgrade_refine_desc_16020213 = "Aprimoramento de Habilidade Ativa: Ao matar um alvo, gera 1 Lâmina de Dawn no local do alvo.",
  str_skill_upgrade_refine_desc_15007811 = "Aprimoramento de habilidade de equipamento: para cada 1 ladrilho verde aos pés do inimigo, o bônus de dano aumenta em <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_15007812 = "Aprimoramento de habilidade ativa: causa o dobro de dano ao ladrilho no centro do alcance da habilidade.",
  str_skill_upgrade_refine_desc_15007813 = "Aprimoramento de Habilidade Ativa: Se a Habilidade Ativa estiver pronta na última rodada, o intervalo de seleção torna-se <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_passive_desc_4400781 = "Aumenta o dano de Robyn contra inimigos ocupando um ladrilho Verde em <color=#00F6FF>10%</color>. Para cada ladrilho verde aos pés do inimigo, o bônus de dano aumenta em <color=#00F6FF>1%</color>. Também concede companheiros de equipe da Floresta Auroriana <color=#00F6FF>50%</color> deste bônus.",
  str_skill_name_3400782 = "Sopro Rastejante",
  str_skill_name_3420782 = "Sopro Rastejante",
  str_skill_name_3400783 = "Sopro Rastejante",
  str_skill_name_3420783 = "Sopro Rastejante",
  str_skill_desc_3400782 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho central selecionado é dobrado.",
  str_skill_desc_3420782 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho selecionado é dobrado. Converte até 1 ladrilho sob o inimigo em um <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link>.",
  str_skill_desc_3400783 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho central selecionado é dobrado. Se esta habilidade ativa estava pronta na última rodada, o intervalo de seleção torna-se <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_3420783 = "Ofertas <color=#00F6FF>250%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado em 1 ladrilho selecionado. O dano causado ao ladrilho selecionado é dobrado. Converte até 1 ladrilho sob o inimigo em um <link=\"20001\"><#FFAE07><u>ladrilho aprimorado</u></color></link>. Se esta habilidade ativa estava pronta na última rodada, o intervalo de seleção torna-se <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_upgrade_refine_desc_15007511 = "Aprimoramento de habilidade de equipamento: A chance de ataques normais infligir veneno aumenta para <color=#00F6FF>80%</color>.",
  str_skill_upgrade_refine_desc_15007512 = "Aprimoramento de habilidade ativa: o fator de dano da habilidade ativa aumenta para <color=#00F6FF>500%</color>.",
  str_skill_upgrade_refine_desc_15007513 = "Aprimoramento de habilidade ativa: o tempo de recarga da habilidade é reduzido em <color=#00F6FF>2</color> no início de cada batalha.",
  str_skill_name_340075 = "Luta Interna",
  str_skill_name_342075 = "Luta Interna",
  str_skill_name_345075 = "Luta Interna",
  str_skill_desc_340075 = "Causa 500% de dano aos inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> por 2 rodadas e 2 pilhas de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas.",
  str_skill_desc_342075 = "Causa 500% de dano aos inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> por 2 rodadas e 2 pilhas de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas.",
  str_skill_desc_345075 = "Causa 500% de dano a <color=#00F6FF>todos</color> inimigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> por 2 rodadas e 2 pilhas de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas.",
  str_skill_desc_350075 = "Causa 500% de dano aos inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> por 2 rodadas e 2 pilhas de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas. Recarga de habilidade <color=#00F6FF>-2</color> rodadas no início da batalha.",
  str_skill_desc_352075 = "Causa 500% de dano aos inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color> e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> por 2 rodadas e 2 pilhas de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas. Recarga de habilidade <color=#00F6FF>-2</color> rodadas no início da batalha.",
  str_skill_desc_355075 = "Causa 500% de dano a <color=#00F6FF>todos</color> inimigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> por 2 rodadas e 2 pilhas de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas. Recarga de habilidade <color=#00F6FF>-2</color> rodadas no início da batalha.",
  str_skill_passive_desc_440075 = "Ataques normais podem atingir inimigos em <color=#00F6FF>ladrilhos diagonais</color> e ter um <color=#00F6FF>80%</color> chance de infligir 1 pilha de <link=\"10001\"><#FFAE07><u>Tóxico</u></color></link> por 2 rodadas.",
  str_skill_desc_5220014 = "Selecione% s <color=#00F6FF>2</color> ladrilhos atravessáveis para converter em <color=#00F6FF>azulejos cromáticos</color>.",
