  str_skill_desc_5220019 = "Selecione% s <color=#00F6FF>7</color> ladrilhos atravessáveis para converter em <color=#00F6FF>azulejos cromáticos</color>.",
  str_skill_name_290540101 = "Joshua: Golpe Destruidor",
