  str_skill_name_290540102 = "Joshua: Wipeout",
  str_skill_desc_290540102 = "Move-se em direção aos aurorianos e brande uma lança para causar dano aos alvos à frente.",
  str_skill_name_290540103 = "Josué: Aniquilação",
  str_skill_desc_290540103 = "Você pode absorver energia de ladrilhos que correspondem ao elemento do Phantom Crystal, redefinir o elemento dos ladrilhos e atacar todos os alvos no campo. Quanto mais energia absorvida, mais forte será o dano.",
  str_skill_name_290540202 = "Joshua: Golpe Destruidor",
