  str_skill_upgrade_desc_16020413 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate. Aumenta o fator de dano da habilidade para <color=#00F6FF>250%</color>.",
