  str_skill_desc_2002041 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos.",
  str_skill_desc_2002042 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos.",
  str_skill_desc_2002043 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos.",
  str_skill_desc_2202041 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>50%</color>.",
  str_skill_desc_2202042 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>50%</color>.",
  str_skill_desc_2202043 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>50%</color>.",
  str_skill_desc_2302041 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos. Inflige <color=#00F6FF>30%</color> a mais de dano aos alvos dentro de 3 grupos adjacentes. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>50%</color>.",
  str_skill_desc_2302042 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos. Inflige <color=#00F6FF>30%</color> a mais de dano aos alvos dentro de 3 grupos adjacentes. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>50%</color>.",
  str_skill_desc_2302043 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 alvos mais próximos. Inflige <color=#00F6FF>30%</color> a mais de dano aos alvos dentro de 3 grupos adjacentes. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>50%</color>.",
  str_skill_desc_2502041 = "Ofertas <color=#00F6FF>140%</color> dano aos 2 alvos mais próximos. inflige <color=#00F6FF>30%</color> mais dano aos alvos dentro de 3 grupos ao redor. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>65%</color>.",
  str_skill_desc_2502042 = "Ofertas <color=#00F6FF>155%</color> dano aos 2 alvos mais próximos. inflige <color=#00F6FF>30%</color> mais dano aos alvos dentro de 3 grupos ao redor. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>65%</color>.",
  str_skill_desc_2502043 = "Ofertas <color=#00F6FF>170%</color> dano aos 2 alvos mais próximos. inflige <color=#00F6FF>30%</color> mais dano aos alvos dentro de 3 grupos ao redor. Se houver apenas 1 alvo, o dano será aumentado em <color=#00F6FF>65%</color>.",
  str_skill_desc_3002041 = "Seleciona um alvo, infligindo a <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link> e Sabedoria igual a <color=#00F6FF>200% do ATQ de Joshua</color>. Também causa <color=#00F6FF>200%</color> de dano ignorando DEF aos alvos que não têm PV Máx. Selecionar o mesmo alvo novamente aumentará ainda mais a Sabedoria deles. Quando a Sabedoria do alvo exceder seu PV atual, eles receberão dano de golpeia ignorando Escudo (a invencibilidade ainda tem efeito).",
  str_skill_desc_3032041 = "Seleciona um alvo, infligindo a <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link> e Sabedoria igual a <color=#00F6FF>250% do ATQ de Joshua</color>. Também causa <color=#00F6FF>250%</color> de dano ignorando DEF aos alvos que não têm PV Máx. Selecionar o mesmo alvo novamente aumentará ainda mais a Sabedoria deles. Quando a Sabedoria do alvo exceder seu PV atual, eles receberão dano de golpeia ignorando Escudo (a invencibilidade ainda tem efeito).",
  str_skill_desc_3062041 = "Seleciona um alvo, infligindo a <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link> e Sabedoria igual a <color=#00F6FF>250% do ATQ de Joshua + 3% do PV máximo do alvo</color> (não menos que <color=#00F6FF>120%</color> do ATQ de Joshua). Também causa <color=#00F6FF>370%</color> de dano ignorando DEF aos alvos que não têm PV máximo. Selecionar o mesmo alvo novamente aumentará ainda mais a Sabedoria deles. Quando a Sabedoria do alvo exceder seu PV atual, eles receberão dano de golpeia ignorando Escudo (a invencibilidade ainda tem efeito).",
  str_skill_passive_desc_4102041 = "Joshua causa <color=#00F6FF>{1}</color> de dano aos inimigos no estado <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link>, ignora todos os escudos e converte todo o dano causado em pontos de Sabedoria.",
  str_skill_upgrade_refine_desc_16020411 = "Aprimoramento de Habilidade de Equipamento: Aumenta todo o dano causado a alvos no estado de Sabedoria Sagrada para <color=#00F6FF>124%</color>.",
  str_skill_upgrade_refine_desc_16020412 = "Chain Combo Enhancement: Quando há apenas 1 alvo, aumenta o dano em <color=#00F6FF>65%</color>.",
  str_skill_upgrade_refine_desc_16020413 = "Aprimoramento de habilidade ativa: atualiza imediatamente o tempo de recarga da habilidade após a morte de um alvo no estado de Sabedoria Sagrada.",
  str_skill_desc_3502041 = "Seleciona um alvo, infligindo a <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link> e Sabedoria igual a <color=#00F6FF>200% do ATQ de Joshua</color>. Também causa <color=#00F6FF>200%</color> de dano ignorando DEF aos alvos que não têm PV Máx. Selecionar o mesmo alvo novamente aumentará ainda mais sua Sabedoria. Quando a Sabedoria do alvo exceder seu PV atual, ele receberá dano de golpeia ignorando Escudo (a invencibilidade ainda tem efeito). Atualiza imediatamente o tempo de recarga da Habilidade Ativa após a morte de um alvo no estado de Sabedoria Sagrada.",
  str_skill_desc_3532041 = "Seleciona um alvo, infligindo a <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link> e Sabedoria igual a <color=#00F6FF>250% do ATQ de Joshua</color>. Também causa <color=#00F6FF>250%</color> de dano ignorando DEF aos alvos que não têm PV Máx. Selecionar o mesmo alvo novamente aumentará ainda mais sua Sabedoria. Quando a Sabedoria do alvo exceder seu PV atual, ele receberá dano de golpeia ignorando Escudo (a invencibilidade ainda tem efeito). Atualiza imediatamente o tempo de recarga da Habilidade Ativa após a morte de um alvo no estado de Sabedoria Sagrada.",
  str_skill_desc_3562041 = "Seleciona um alvo, infligindo a <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link> e Sabedoria igual a <color=#00F6FF>250% do ATQ de Joshua + 3% do PV máximo do alvo</color> (não menos que <color=#00F6FF>120%</color> do ATQ de Joshua). Também causa <color=#00F6FF>370%</color> de dano ignorando DEF aos alvos que não têm PV máximo. Selecionar o mesmo alvo novamente aumentará ainda mais sua Sabedoria. Quando a Sabedoria do alvo exceder seu PV atual, eles recebem dano de golpeia ignorando Escudo (a invencibilidade ainda tem efeito). Atualiza imediatamente o tempo de recarga da Habilidade Ativa após a morte de um alvo no estado de Sabedoria Sagrada.",
  str_skill_passive_desc_4502041 = "Joshua causa <color=#00F6FF>124%</color> de dano aos inimigos sob o estado de <link=\"30083\"><#FFAE07><u>Sabedoria Sagrada</u></color></link>, ignora todos os escudos e converte todo o dano causado em pontos de Sabedoria.",
