  str_skill_desc_3002051 = "Seleciona 1 ladrilho não quebrado e o transforma em um ladrilho quebrado que dura 9 rodadas, depois converte <color=#00F6FF>4 ladrilhos em formato de cruz</color> em ladrilhos Azuis.",
  str_skill_desc_3052051 = "Seleciona 1 ladrilho não quebrado e o transforma em um ladrilho quebrado que dura 9 rodadas, depois converte <color=#00F6FF>4 ladrilhos em formato de cruz</color> em ladrilhos Azuis.",
  str_skill_passive_name_410205 = "saudação agradável",
  str_skill_passive_name_430205 = "saudação agradável",
  str_skill_passive_desc_410205 = "Blanc: Pura Cordis não realiza ataques normais quando está em uma casa Azul. Sempre que passa por 1 casa Azul, ela ganha 1 pilha de Hospitalidade se houver inimigos dentro de <color=#00F6FF>4 casas em forma de cruz</color>. Cada pilha de Hospitalidade aumenta a taxa de dano do Combo em <color=#00F6FF>{1}</color> e diminui a condição de acionamento do Combo em <color=#00F6FF>1</color>. Todas as pilhas são removidas após ela usar um Combo.",
  str_skill_passive_desc_430205 = "Blanc: Pura Cordis não realiza ataques normais quando está em uma Casa Azul. Sempre que passa por 1 Casa Azul, ela ganha 1 pilha de Hospitalidade se houver inimigos ou casas quebradas dentro de <color=#00F6FF>4 casas em forma de cruz</color>. Cada pilha de Hospitalidade aumenta a taxa de dano do Combo em <color=#00F6FF>{1}</color> e diminui a condição de acionamento do Combo em <color=#00F6FF>1</color>. Todas as pilhas são removidas após ela usar um Combo.",
  str_skill_upgrade_desc_15020512 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_15020515 = "Aprimoramento do Chain Combo: A duração dos ladrilhos quebrados dentro do alcance do Chain Combo é reduzida em <color=#FFFF00>2/3/4</color> rodadas (válido para Ascensão II).",
  str_skill_passive_desc_440097 = "Ataques normais tornam-se ataques de 2 combos que causam <color=#00F6FF>60%</color> de dano base a cada acerto. Cada ataque tem um <color=#00F6FF>20%</color> chance de lidar <color=#00F6FF>50%</color> dano extra. Cada combo aumenta a chance de ativação em <color=#00F6FF>1%</color>, até 50%.",
  str_skill_name_3400971 = "Frigid Debone Variante I",
  str_skill_name_3400972 = "Frigid Debone Variante II",
  str_skill_name_3420971 = "Frigid Debone Variante I",
  str_skill_name_3420972 = "Frigid Debone Variante II",
  str_skill_desc_3400971 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Teletransporta para qualquer local e causa dano aos inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor a área, maior o dano causado, até <color=#00F6FF>600%</color> dano.",
  str_skill_desc_3400972 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Teletransporta para qualquer local dentro <color=#FFFF00>3 aglomerados circundantes</color> e causa dano aos inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor a área, maior o dano causado, até <color=#00F6FF>360%</color> dano.",
  str_skill_desc_3420971 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Teletransporta para qualquer local e causa dano aos inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor a área, maior o dano causado, até <color=#00F6FF>720%</color> dano.",
  str_skill_desc_3420972 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Teletransporta para qualquer local dentro <color=#FFFF00>3 aglomerados circundantes</color> e causa dano aos inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor a área, maior o dano causado, até <color=#00F6FF>480%</color> dano.",
  str_skill_upgrade_refine_desc_15009711 = "<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Teletransporta para qualquer local e causa dano aos inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor a área, maior o dano causado. O dano da habilidade ativa aumenta em <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_15009712 = "Aprimoramento de habilidade de equipamento: cada combo aumenta a chance de desencadear dano adicional em <color=#00F6FF>1%</color>, até 50%.",
  str_skill_upgrade_refine_desc_15009713 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Teletransporta para qualquer local dentro <color=#FFFF00>3 aglomerados circundantes</color> e causa dano aos inimigos em forma de retângulo entre o ponto inicial e o destino. Quanto menor a área, maior o dano causado. O dano da Habilidade Ativa é reduzido em <color=#FFFF00>120%</color>.",
  str_skill_upgrade_refine_desc_16002711 = "Aprimoramento de habilidade ativa: o fator de dano da habilidade ativa aumenta para <color=#00F6FF>360%</color>.",
  str_skill_upgrade_refine_desc_16002712 = "Aprimoramento de Habilidade de Equipamento: Ganhos <color=#00F6FF>2</color> pilhas de Silent Thunder Mark ao lançar a Habilidade Ativa.",
  str_skill_upgrade_refine_desc_16002713 = "Aprimoramento de habilidade de equipamento: Ataques normais consomem 1 pilha de Silent Thunder Mark para causar dano extra igual a <color=#00F6FF>2,5%</color> de HP atual aos inimigos. Este dano não será menor do que <color=#00F6FF>50%</color> do ATK de Michael.",
  str_skill_desc_3400271 = "Traços para o local selecionado, lidando <color=#00F6FF>360%</color> dano e dano extra igual a <color=#00F6FF>5%</color> de seu HP atual para inimigos ao longo do caminho e em ladrilhos adjacentes.",
  str_skill_desc_3430271 = "Traços para o local selecionado, lidando <color=#00F6FF>360%</color> dano e dano extra igual a <color=#00F6FF>5%</color> de seu HP atual para inimigos ao longo do caminho e em ladrilhos adjacentes e, em seguida, lança instantaneamente um Chain Combo uma vez no local selecionado correspondente à distância percorrida.",
  str_skill_desc_3400272 = "Traços para o local selecionado, lidando <color=#00F6FF>360%</color> dano e dano extra igual a <color=#00F6FF>5%</color> de seu HP atual para inimigos ao longo do caminho e em ladrilhos adjacentes.",
  str_skill_desc_3430272 = "Traços para o local selecionado, lidando <color=#00F6FF>360%</color> dano e dano extra igual a <color=#00F6FF>5%</color> de seu HP atual para inimigos ao longo do caminho e em ladrilhos adjacentes e, em seguida, lança instantaneamente um Chain Combo uma vez no local selecionado correspondente à distância percorrida.",
  str_skill_desc_4400271 = "Concede 1 pilha de Silent Thunder Mark no início de cada rodada e ao usar um Chain Combo, e 2 pilhas de Silent Thunder Mark ao usar uma habilidade ativa. Ataques normais consomem 1 pilha de Silent Thunder Mark para causar dano extra igual a <color=#00F6FF>2,5%</color> de HP atual para o inimigo.",
  str_skill_desc_440027 = "Concede 1 pilha de Silent Thunder Mark no início de cada rodada e ao usar um Chain Combo, e 2 pilhas de Silent Thunder Mark ao usar uma habilidade ativa. Ataques normais consomem 1 pilha de Silent Thunder Mark para causar dano extra igual a <color=#00F6FF>2,5%</color> de HP atual para o inimigo. Este dano não será menor do que <color=#00F6FF>50%</color> do ATK de Michael.",
  str_skill_name_490250101 = "Forsaken: Fantasma da Restauração",
  str_skill_desc_490250101 = "Abandonado: Minos absorve os blocos aprimorados e enfraquecidos dentro de 2 agrupamentos próximos, e então causa dano aos alvos dentro de 1 agrupamento próximo. O dano deste ataque é aprimorado com base no número de blocos absorvidos.",
  str_skill_name_490250102 = "Forsaken: Immolation Finale",
  str_skill_desc_490250102 = "Abandonado: Minos absorve todas as casas(s) melhoradas e enfraquecidas no tabuleiro e, em seguida, causa dano aos Aurorianos. Minos causa dano 1 vez extra para cada casa(s) absorvida.",
  str_skill_name_490250103 = "Forsaken: Fantasma da Restauração+",
  str_skill_desc_490250103 = "Abandonado: Minos absorve os blocos aprimorados e enfraquecidos dentro de 2 agrupamentos próximos, e então causa dano aos alvos dentro de 1 agrupamento próximo. O dano deste ataque é aprimorado com base no número de blocos absorvidos.",
  str_skill_name_490250104 = "Forsaken: Immolation Finale +",
  str_skill_desc_490250104 = "Abandonado: Minos absorve todas as casas(s) melhoradas e enfraquecidas no tabuleiro e, em seguida, causa dano aos Aurorianos. Minos causa dano 1 vez extra para cada casa(s) absorvida.",
  str_skill_upgrade_refine_desc_16002811 = "Aprimoramento de Habilidade de Equipamento: Aumenta o fator de recuperação para <color=#00F6FF>1,8%</color>.",
  str_skill_upgrade_refine_desc_16002812 = "Aprimoramento de Habilidade Ativa: Aumenta o fator de recuperação para <color=#00F6FF>250%</color>.",
  str_skill_upgrade_refine_desc_16002813 = "Aprimoramento de habilidade ativa: quanto menor o HP da equipe, maior a eficácia da cura, até um adicional <color=#00F6FF>bônus de 100%</color>.",
  str_skill_passive_desc_450028 = "Cada azulejo azul gerado no mapa recupera o HP da equipe em <color=#00F6FF>1,8%</color> do HP de Raphael. Quanto menor o HP da equipe, maior a eficácia da cura, até um adicional <color=#00F6FF>bônus de 100%</color>.",
  str_skill_desc_350028 = "Recupera o HP da equipe por <color=#00F6FF>250%</color> do ATK de Raphael. Redefinir <color=#00F6FF>tudo não azul</color> azulejos.",
  str_skill_desc_356028 = "Recupera o HP da equipe por <color=#00F6FF>250%</color> do ATK de Raphael. Redefinir <color=#00F6FF>tudo não azul</color> telhas, e tem um <color=#00F6FF>pequena chance</color> para gerar telhas azuis.",
  str_skill_desc_360028 = "Recupera o HP da equipe por <color=#00F6FF>250%</color> do ATK de Raphael. Redefinir <color=#00F6FF>tudo não azul</color> azulejos. Quanto menor o HP da equipe, maior a eficácia da cura, até um adicional <color=#00F6FF>bônus de 100%</color>.",
  str_skill_desc_366028 = "Recupera o HP da equipe por <color=#00F6FF>250%</color> do ATK de Raphael. Redefinir <color=#00F6FF>tudo não azul</color> telhas, com um <color=#00F6FF>pequena chance</color> para gerar telhas azuis. Quanto menor o HP da equipe, maior a eficácia da cura, até um adicional <color=#00F6FF>bônus de 100%</color>.",
  str_skill_upgrade_refine_desc_15007011 = "Aprimoramento de Habilidade Ativa: Aumenta o fator de dano para <color=#00F6FF>100%</color>.",
  str_skill_upgrade_refine_desc_15007012 = "Aprimoramento de habilidade de equipamento: aumenta o fator de dano para <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_15007013 = "Aprimoramento de Habilidade Ativa: Ao causar dano, há um <color=#00F6FF>25%</color> chance de infligir 1 pilha de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link>.",
  str_skill_desc_350070 = "Ofertas <color=#00F6FF>100%</color> dano <color=#00F6FF>5</color> vezes para inimigos aleatórios no campo. Lança 1 ataque adicional para cada bloco vermelho dentro <color=#00F6FF>1 cluster circundante</color> da unidade.",
  str_skill_desc_355070 = "Ofertas <color=#00F6FF>100%</color> dano <color=#00F6FF>6</color> vezes para inimigos aleatórios no campo. Lança 1 ataque adicional para cada bloco vermelho dentro <color=#00F6FF>12 blocos adjacentes</color>.",
  str_skill_desc_360070 = "Ofertas <color=#00F6FF>100%</color> dano <color=#00F6FF>5</color> vezes para inimigos aleatórios no campo. Lança 1 ataque adicional para cada bloco vermelho dentro <color=#00F6FF>1 cluster circundante</color> da unidade. Ao causar dano, há um <color=#00F6FF>25%</color> chance de infligir 1 pilha de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link>.",
  str_skill_desc_365070 = "Ofertas <color=#00F6FF>100%</color> dano <color=#00F6FF>6</color> vezes para inimigos aleatórios no campo. Lança 1 ataque adicional para cada bloco vermelho dentro <color=#00F6FF>12 ladrilhos adjacentes</color>. Ao causar dano, há um <color=#00F6FF>25%</color> chance de infligir 1 pilha de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link>.",
  str_skill_passive_desc_450070 = "Ataques normais têm um <color=#00F6FF>75%</color> chance de ativar 1 Ataque do Dragão Vermelho que causa dano igual a <color=#00F6FF>60%</color> do dano do Ataque Normal de Leona e inflige 1 pilha de <link=\"10002\"><#FFAE07><u>Queimar</u></color></link> por 2 rodadas.",
  str_skill_desc_400140110 = "Quando os aurorianos começam a se mover, Tentaclaw se enrola para evitar ataques e restaura HP para Mirren Gautier.",
  str_skill_upgrade_desc_16020713 = "Melhoria de Habilidade de Equipamento: Reduz o número de pilhas de Ondulação necessárias para acionar o efeito para 5. Reduz o número de pilhas de Ondulação consumidas para um múltiplo de 5 pilhas. (Válido para Ascensão I)",
  str_skill_upgrade_desc_16020716 = "Aprimoramento de habilidade ativa: Converte a casa selecionada para azul.",
  str_skill_name_2002071 = "Agridoce",
  str_skill_name_2002072 = "Agridoce",
  str_skill_name_2002073 = "Agridoce",
  str_skill_desc_2002071 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_2002072 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2002073 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_name_3002071 = "Dança dos Sonhos Despertos",
  str_skill_name_3062071 = "Dança dos Sonhos Despertos",
  str_skill_name_3202071 = "Dança dos Sonhos Despertos",
  str_skill_name_3262071 = "Dança dos Sonhos Despertos",
  str_skill_name_3302071 = "Dança dos Sonhos Despertos",
  str_skill_name_3362071 = "Dança dos Sonhos Despertos",
  str_skill_desc_3002071 = "Seleciona 1 casa e faz todas as casas azuis na mesma coluna <link=\"30084\"><#FFAE07><u>convergir</u></color></link> em direção à casa selecionada.",
  str_skill_desc_3062071 = "Seleciona 1 casa e converte esta casa para azul, depois faz todas as casas azuis na mesma coluna <link=\"30084\"><#FFAE07><u>convergir</u></color></link> em direção à casa selecionada.",
  str_skill_desc_3202071 = "Seleciona 1 casa e faz todas as casas azuis na mesma coluna <link=\"30084\"><#FFAE07><u>convergir</u></color></link> em direção à casa selecionada. Tocar novamente fará o efeito alternar entre <color=#00F6FF>linha/coluna</color>.",
  str_skill_desc_3262071 = "Seleciona 1 casa e converte esta casa para azul, depois faz todas as casas azuis na mesma coluna <link=\"30084\"><#FFAE07><u>convergir</u></color></link> em direção à casa selecionada. Tocar novamente fará com que o efeito alterne entre <color=#00F6FF>linha/coluna</color>.",
  str_skill_desc_3302071 = "Seleciona 1 casa e faz com que todas as casas azuis na mesma coluna <link=\"30084\"><#FFAE07><u>converjam</u></color></link> em direção à casa selecionada. Tocar novamente fará com que o efeito alterne entre <color=#00F6FF>linha/coluna</color>. Ganha 1 pilha de Ondulação para cada 1 casa azul dentro do alcance da Habilidade Ativa.",
  str_skill_desc_3362071 = "Seleciona 1 casa e converte esta casa para azul, em seguida, faz todas as casas azuis na mesma coluna <link=\"30084\"><#FFAE07><u>convergir</u></color></link> em direção à casa selecionada. Tocar novamente fará o efeito alternar entre <color=#00F6FF>linha/coluna</color>. Ganha 1 pilha de Ondulação para cada 1 casa azul dentro do alcance da Habilidade Ativa.",
  str_skill_passive_name_410207 = "De Dawn Até o Anoitecer",
  str_skill_passive_desc_410207 = "Cena ganha 1 pilha de <link=\"30085\"><#FFAE07><u>Ripple</u></color></link> quando os aurorianos da equipe lançam uma habilidade ativa pela primeira vez na rodada. Se Cena já tiver 7 ou mais pilhas de Ripple ao ganhar uma pilha, elas serão consumidas para recuperar HP igual a <color=#00F6FF>{1}</color> do HP máximo de Cena.",
  str_skill_passive_name_416207 = "De Dawn Até o Anoitecer",
  str_skill_passive_desc_416207 = "Cena ganha 1 pilha de <link=\"30086\"><#FFAE07><u>Ondulação</u></color></link> quando os Aurorianos da equipe usam uma Habilidade Ativa pela primeira vez na rodada. Se Cena já tiver 5 ou mais pilhas de Ondulação ao ganhar uma pilha, uma parte é consumida para recuperar PV igual a <color=#00F6FF>{1}</color> do PV Máx. de Cena.",
  str_skill_desc_350025 = "Causa <color=#00F6FF>300%</color> de dano em <color=#00F6FF>3 colunas selecionadas</color> ou <color=#00F6FF>3 linhas selecionadas</color> e empurra os inimigos para trás. O dano causado à linha ou coluna do meio será 1,7 vezes maior que o dano causado aos dois lados. Reinicia todas as peças <color=#00F6FF>não-Vermelhas</color> na área de ataque.",
  str_skill_desc_356025 = "Causa <color=#00F6FF>300%</color> de dano em <color=#00F6FF>3 colunas selecionadas</color> ou <color=#00F6FF>3 linhas selecionadas</color> e empurra os inimigos para trás. O dano causado à linha ou coluna do meio será 1,7 vezes maior que o dano causado aos dois lados. Reinicia todas as peças <color=#00F6FF>não-Vermelhas</color> na área de ataque e tem uma <color=#00F6FF>pequena chance</color> de gerar peças Vermelhas.",
  str_skill_desc_360025 = "Causa <color=#00F6FF>340%</color> de dano em <color=#00F6FF>3 colunas selecionadas</color> ou <color=#00F6FF>3 linhas selecionadas</color> e empurra os inimigos para trás. O dano causado à linha ou coluna do meio será 1,7 vezes maior que o dano causado aos dois lados. Redefine todas as peças <color=#00F6FF>não-Vermelhas</color> na área de ataque.",
  str_skill_desc_366025 = "Causa <color=#00F6FF>340%</color> de dano em <color=#00F6FF>3 colunas selecionadas</color> ou <color=#00F6FF>3 linhas selecionadas</color> e empurra os inimigos para trás. O dano causado à linha ou coluna do meio será 1,7 vezes maior que o dano causado aos dois lados. Reinicia todas as peças <color=#00F6FF>não-Vermelhas</color> na área de ataque e tem uma <color=#00F6FF>pequena chance</color> de gerar peças Vermelhas.",
  str_skill_passive_desc_440025 = "Ataques normais <color=#00F6FF>agora podem atacar na diagonal</color>. Ataques normais causam dano adicional que ignora DEF, equivalente a <color=#00F6FF>12%</color> do ATQ.",
  str_skill_upgrade_refine_desc_16002511 = "Melhoria de Habilidade de Equip.: Aumenta o fator de dano para <color=#00F6FF>12%</color>.",
  str_skill_upgrade_refine_desc_16002512 = "Aprimoramento de Habilidade Ativa: Causa <color=#00F6FF>1,7 vezes</color> mais dano às linhas ou colunas do meio.",
  str_skill_upgrade_refine_desc_16002513 = "Aprimoramento de habilidade ativa: Aumenta o fator de dano para <color=#00F6FF>340%</color>.",
