  str_skill_desc_2002062 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 grupo ao redor</color> e blocos Vermelhos <color=#00F6FF>se estendendo para fora em forma de cruz</color>.",
