  str_skill_upgrade_refine_desc_15002413 = "Aprimoramento de Combinação de Cadeia: Nas rodadas em que a Habilidade Ativa é lançada, reduz a contagem de casas que acionam o COMBO em <color=#00F6FF>1</color>.",
  str_skill_passive_desc_440024 = "Ataques normais causam um dano extra de <color=#00F6FF>65%</color> aos inimigos que ocupam as casas Vermelhas.",
  str_skill_desc_340024 = "Marca 1 casa. Quando o número de casas conectadas atinge <color=#00F6FF>1,5</color> vezes o número de casas necessárias para acionar um Combo, lança o Combo na localização marcada também (aumenta o dano final de ambos os Combos em <color=#00F6FF>35%</color>).",
  str_skill_desc_342024 = "Marca 1 casa. Quando o número de casas conectadas atinge <color=#00F6FF>1,5</color> vezes o número de casas necessárias para acionar um Combo, lança o Combo na localização marcada também (aumenta o dano final de ambos os Combos em <color=#00F6FF>35%</color>).",
  str_skill_desc_345024 = "Marca 1 casa. Quando o número de casas conectadas atinge <color=#00F6FF>1,5</color> vezes o número de casas necessárias para acionar um Combo, lança o Combo na localização marcada também (aumenta o dano final de ambos os Combos em <color=#00F6FF>35%</color>).",
  str_skill_desc_240241 = "Causa <color=#00F6FF>140%</color> de dano a <color=#00F6FF>1 grupo adjacente</color>. Nas rodadas em que a Habilidade Ativa é lançada, reduz a contagem de casas que ativam o COMBO em <color=#00F6FF>1</color>.",
  str_skill_desc_240242 = "Causa <color=#00F6FF>145%</color> de dano a <color=#00F6FF>12 casas em formato de diamante</color>. Nas rodadas em que a Habilidade Ativa é lançada, reduz a contagem de casas que ativam o COMBO em <color=#00F6FF>1</color>.",
  str_skill_desc_240243 = "Causa <color=#00F6FF>155%</color> de dano em <color=#00F6FF>16 casas em formato radial</color>. Nas rodadas em que a Habilidade Ativa é lançada, reduz a contagem de casas que ativam o COMBO em <color=#00F6FF>1</color>.",
  str_skill_name_290560101 = "Deusa Denuo - Espinho de Vinha",
  str_skill_desc_290560101 = "Move-se em direção aos Aurorianos e cause dano aos alvos em uma linha ou coluna à frente.",
  str_skill_name_290560102 = "Deusa Denuo - Polinização",
  str_skill_desc_290560102 = "Move-se em direção aos Aurorianos e cause dano a todos os alvos em 12 tiles ao redor, em formato de diamante, enquanto inflige veneno e catalisa o crescimento das plantas na área.",
  str_skill_name_290560103 = "Deusa Denuo - Explosão",
  str_skill_desc_290560103 = "Mira em um Auroriano e causa dano a todos os alvos dentro de 12 tiles em forma de diamante ao redor do Auroriano, enquanto inflige veneno e catalisa o crescimento de plantas dentro do alcance (não pode errar).",
  str_skill_name_200260101 = "Erva Encantada Sadesiana - Adormecida",
  str_skill_desc_200260101 = "Em sua forma juvenil, a Erva Encantada Sadesiana é imune a ataques de Aurorianos.",
  str_skill_name_200260201 = "Erva Encantada Sadesiana - Expansão",
  str_skill_desc_200260201 = "Em seu estágio metamórfico, a Erva Encantada Sadesiana pode ser atacada por Aurorianos, mas não possui a habilidade de contra-atacar.",
  str_skill_name_200260301 = "Erva Encantada Sadesiana - Aguilhão",
  str_skill_desc_200260301 = "Mira nos Aurorianos e causa dano enquanto inflige veneno.",
  str_skill_name_53310002 = "Deusa Denuo - Polinização",
  str_skill_desc_53310002 = "Catalisa o crescimento de plantas em 12 ladrilhos adjacentes em formato de diamante.",
  str_skill_desc_3300051 = "<color=#FFFF00>Tempo de recarga da habilidade +1 após conjurar</color>. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos. Quanto menor a porcentagem de PV do inimigo, maior o dano (dano aumentado até 100%). Aumenta o dano de impacto causado por cada pilha de Alma para 130%.",
  str_skill_desc_3300052 = "<color=#FFFF00>Redução de 1 no tempo de recarga da habilidade após lançamento</color>. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor a porcentagem de PV do inimigo, maior o dano (dano aumentado até 100%). Não ganha Alma para inimigos derrotados por Aurorianos no campo com suas Habilidades Ativas.",
  str_skill_desc_3360051 = "<color=#FFFF00>Tempo de recarga da habilidade +1 após conjurar</color>. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos. Quanto menor a porcentagem de PV do inimigo, maior o dano (dano aumentado até 100%). Aumenta o dano de impacto causado por cada pilha de Alma para 130%.",
  str_skill_desc_3360052 = "<color=#FFFF00>Redução de 1 no tempo de recarga da habilidade após lançamento</color>. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos na tela. Quanto menor a porcentagem de PV do inimigo, maior o dano (dano aumentado até 100%). Não ganha Alma para inimigos derrotados por Aurorianos no campo com suas Habilidades Ativas.",
  str_skill_passive_desc_443005 = "Mia ganha 1 acúmulo de Alma para cada inimigo derrotado por <color=#00F6FF>aurorianos</color> no campo com suas Habilidades Ativas, até <color=#00F6FF>8</color> pilhas. Cada pilha desencadeia uma explosão que causa <color=#00F6FF>100%</color> Dano de ATK a um único alvo, aumentando adicionalmente o Ataque Normal de Mia em <color=#00F6FF>3%</color>, e dano de combo em cadeia por <color=#00F6FF>5%</color>.",
  str_skill_upgrade_refine_desc_16000511 = "<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Tempo de recarga da habilidade +1 após conjurar</color>. Aumenta o dano de impacto causado por cada pilha de Alma para 130%.",
  str_skill_upgrade_refine_desc_16000512 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Redução de 1 no tempo de recarga da habilidade após lançamento</color>. Não ganha Alma por inimigos derrotados por Aurorianos no campo com suas Habilidades Ativas.",
  str_skill_upgrade_refine_desc_16000513 = "Melhoria de Habilidade de Equipamento: Aumenta o limite máximo de pilhas de Alma para <color=#00F6FF>8</color>.",
  str_skill_desc_8001201 = "Invoca um Alma Sombria instantaneamente em uma casa próxima.",
  str_skill_desc_8001441 = "Invoca um enorme enxame de Dretchers no campo e concede a si mesmo 30 Marcas de Energia que aumentam o ATQ.",
