  str_skill_name_3062093 = "Variante de Patrulha do Trovão I",
  str_skill_desc_3002091 = "Selecione 1 casa para causar <color=#00F6FF>200%</color> de dano em 25 casas em forma de quadrado. Se o lançador estiver dentro do alcance da habilidade, o dano final é aumentado em <color=#00F6FF>30%</color>.",
  str_skill_desc_3002092 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Selecione 1 ladrilho para causar <color=#00F6FF>100%</color> de dano em 9 ladrilhos em formato quadrado. Se o lançador estiver dentro do alcance da habilidade, o dano final é aumentado em <color=#00F6FF>30%</color>.",
  str_skill_desc_3002093 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa 300% de dano a todos os ladrilhos e o dano final aumenta em <color=#00F6FF>30%</color>.",
  str_skill_desc_3062091 = "Selecione 1 casa para causar <color=#00F6FF>200%</color> de dano em 25 casas em forma de quadrado. Se o lançador estiver dentro do alcance da habilidade, o dano final é aumentado em <color=#00F6FF>30%</color>.",
  str_skill_desc_3062092 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Selecione 1 ladrilho para causar <color=#00F6FF>100%</color> de dano em 9 ladrilhos em formato quadrado. Se o lançador estiver dentro do alcance da habilidade, o dano final é aumentado em <color=#00F6FF>30%</color>.",
  str_skill_desc_3062093 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa <color=#00F6FF>300%</color> de dano a todos os blocos e o dano final aumenta em <color=#00F6FF>30%</color>.",
  str_skill_passive_name_410209 = "Fúria do Trovão",
  str_skill_passive_name_420209 = "Fúria do Trovão",
  str_skill_passive_name_430209 = "Fúria do Trovão",
  str_skill_passive_desc_410209 = "Inimigos atacados pela Habilidade Ativa entrarão no status de Eco Trovejante por <color=#00F6FF>2 rodadas</color>. Causa <color=#00F6FF>{1}</color> de dano aos alvos sob o status de Eco Trovejante dentro de <color=#00F6FF>12 peças em forma de diamante</color> para cada peça que a equipe atravessa.",
  str_skill_passive_desc_420209 = "Inimigos atacados pela Habilidade Ativa entrarão no status de Eco Trovejante por <color=#00F6FF>2 rodadas</color>. Causa <color=#00F6FF>{1}</color> de dano aos alvos sob o status de Eco Trovejante dentro de <color=#00F6FF>12 peças em forma de diamante</color> para cada peça que a equipe atravessa.",
  str_skill_passive_desc_430209 = "Ataques normais podem atingir inimigos dentro de <color=#00F6FF>8 peças em forma de cruz</color>. Inimigos atacados pela Habilidade Ativa entrarão no status de Eco Trovejante por <color=#00F6FF>2 rodadas</color>. Causa <color=#00F6FF>{1}</color> de dano aos alvos sob o status de Eco Trovejante dentro de <color=#00F6FF>12 peças em forma de diamante</color> para cada peça que a equipe atravessa.",
  str_skill_passive_desc_440209 = "Ataques normais podem atingir inimigos dentro de <color=#00F6FF>8 peças em forma de cruz</color>. Inimigos atacados pela Habilidade Ativa entrarão no status de Eco Trovejante por <color=#00F6FF>2 rodadas</color>. Causa <color=#00F6FF>50%</color> de dano aos alvos sob o status de Eco Trovejante dentro de <color=#00F6FF>12 peças em forma de diamante</color> para cada peça que a equipe atravessa.",
  str_skill_upgrade_refine_desc_16020911 = "Aprimoramento de Habilidade de Equipamento: Aumenta o fator de dano para <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16020912 = "<color=#00F6FF>Nova Variante de Habilidade Ativa I</color>: <color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Causa <color=#00F6FF>300%</color> de dano a todos os ladrilhos e o dano final aumenta em <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16020913 = "<color=#00F6FF>Nova Variante de Habilidade Ativa II</color>: <color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Selecione 1 ladrilho para causar <color=#00F6FF>100%</color> de dano em 9 ladrilhos em formato quadrado. Se o lançador estiver posicionado dentro do alcance da habilidade, o dano final aumenta em 30%.",
  str_skill_desc_320116 = "Fleur causa <color=#00F6FF>{1}%</color> de dano a um inimigo selecionado e marca o alvo. Fleur causa dano a alvos marcados mais 1 vez ao usar Combos nesta rodada. Se a Habilidade Ativa estiver pronta na rodada anterior, o dano final nesta rodada aumenta em <color=#00F6FF>35%</color>.",
  str_skill_desc_323116 = "Fleur causa <color=#00F6FF>{1}%</color> de dano a um inimigo selecionado e marca o alvo. Fleur causa dano a alvos marcados mais 1 vez ao usar Combos nesta rodada. Se a Habilidade Ativa estiver pronta na rodada anterior, o dano final nesta rodada aumenta em <color=#00F6FF>35%</color>.",
  str_skill_upgrade_desc_16011113 = "Aprimoramento de Habilidade de Equipamento: O alcance de geração de cristais aumenta para 1/2/3 <color=#00F6FF>aglomerados circundantes</color>.",
  str_skill_upgrade_desc_16011116 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_desc_300111 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos. Quanto menos inimigos, maior o dano causado, até 2 vezes o original.",
  str_skill_desc_303111 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos. Quanto menos inimigos, maior o dano causado, até 2 vezes o original.",
  str_skill_desc_320111 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos. Quanto menos inimigos, maior o dano causado, até 2 vezes o original. Marca a posição atual <color=#00F6FF>após usar Habilidades Ativas</color> e ao <color=#00F6FF>entrar na Hora da Aurora</color>. Se a Habilidade de Equipamento gerar cristais nesta rodada, ela será ativada uma vez na posição marcada.",
  str_skill_desc_323111 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>todos</color> os inimigos. Quanto menos inimigos, maior o dano causado, até 2 vezes o original. Marca a posição atual <color=#00F6FF>após usar Habilidades Ativas</color> e ao <color=#00F6FF>entrar na Hora da Aurora</color>. Se a Habilidade de Equipamento gerar cristais nesta rodada, ela será ativada uma vez na posição marcada.",
  str_skill_passive_name_416111 = "Toque de Cristal",
  str_skill_passive_name_436111 = "Toque de Cristal",
  str_skill_passive_desc_410111 = "Antes do inimigo agir, se Beryl lançou um Combo nesta rodada, cristais são gerados dentro do <color=#00F6FF>alcance do Combo</color> dela e permanecerão lá por 1 rodada. Quando os inimigos <link=\"30091\"><#FFAE07><u>tocam</u></color></link> nos cristais dela, eles recebem dano ignorando DEF de <color=#00F6FF>{1}</color> (afetado pelos contadores de elementos).",
  str_skill_passive_desc_430111 = "Antes do inimigo agir, se Beryl lançou um Combo de Corrente nesta rodada, cristais são gerados dentro do <color=#00F6FF>alcance do Combo de Corrente</color> dela e permanecerão lá por 1 rodada. Quando os inimigos <link=\"30091\"><#FFAE07><u>tocam</u></color></link> nos cristais dela, eles sofrem dano <color=#00F6FF>{1}</color> que ignora DEF (afetado pelos contadores de elementos). Esse dano aumenta em <color=#00F6FF>10%</color> para cada peça conectada, até um máximo de 20 peças.",
  str_skill_passive_desc_416111 = "Antes do inimigo agir, se Beryl lançou um Combo nesta rodada, cristais são gerados em <color=#00F6FF>1/2/3 círculos ao redor</color> e permanecerão lá por 1 rodada. Quando os inimigos <link=\"30091\"><#FFAE07><u>tocam</u></color></link> nos cristais dela, eles recebem dano <color=#00F6FF>{1}</color> que ignora DEF (afetado pelos contadores de elementos).",
  str_skill_passive_desc_436111 = "Antes do inimigo agir, se Beryl lançou um Combo nesta rodada, cristais são gerados dentro de <color=#00F6FF>1/2/3 aglomerados circundantes</color> e permanecerão lá por 1 rodada. Quando os inimigos <link=\"30091\"><#FFAE07><u>tocam</u></color></link> nos cristais dela, eles sofrem dano <color=#00F6FF>{1}</color> que ignora DEF (afetado pelos contadores de elementos). Esse dano aumenta em <color=#00F6FF>10%</color> para cada peça conectada, até um máximo de 20 peças.",
  str_skill_desc_2001161 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de dano a <color=#00F6FF>4 casas em forma de cruz</color> <link=\"30015\"><#FFAE07><u>ao redor</u></color></link>.",
  str_skill_desc_2001162 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de dano a <color=#00F6FF>4 casas em forma de cruz</color> <link=\"30015\"><#FFAE07><u>ao redor</u></color></link>.",
  str_skill_desc_2001163 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de dano a <color=#00F6FF>4 casas em forma de cruz</color> <link=\"30015\"><#FFAE07><u>ao redor</u></color></link>.",
  str_skill_desc_2061161 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de <link=\"30015\"><#FFAE07><u>dano em área</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor deles. Este ataque ignora toda a DEF se o alvo estiver marcado.",
  str_skill_desc_2061162 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de <link=\"30015\"><#FFAE07><u>dano em área</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor deles. Este ataque ignora toda a DEF se o alvo estiver marcado.",
  str_skill_desc_2061163 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de <link=\"30015\"><#FFAE07><u>dano em área</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor deles. Este ataque ignora toda a DEF se o alvo estiver marcado.",
  str_skill_desc_2201161 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de <link=\"30015\"><#FFAE07><u>dano em área</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor deles. Este ataque ignora 40% da DEF se o alvo estiver marcado.",
  str_skill_desc_2201162 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de <link=\"30015\"><#FFAE07><u>dano em área</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor deles. Este ataque ignora 40% da DEF se o alvo estiver marcado.",
  str_skill_desc_2201163 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e <color=#00F6FF>30%</color> de <link=\"30015\"><#FFAE07><u>dano em área</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor deles. Este ataque ignora 40% da DEF se o alvo estiver marcado.",
  str_skill_name_2201161 = "Punho de Ferro",
  str_skill_name_2201162 = "Punho de Ferro",
  str_skill_name_2201163 = "Punho de Ferro",
  str_skill_desc_300116 = "Seleciona 1 inimigo e causa <color=#00F6FF>{1}%</color> de dano, deixando uma marca. Os Combos em Cadeia de Fleur causam dano aos alvos marcados 1 vez adicional nesta rodada.",
  str_skill_desc_303116 = "Seleciona 1 inimigo e causa <color=#00F6FF>{1}%</color> de dano, deixando uma marca. Os Combos de Corrente do Fleur causam dano aos alvos marcados 1 vez adicional nesta rodada. Fleur pode lançar sua Habilidade Ativa novamente após <color=#00F6FF>entrar na Hora da Aurora</color> ou quando <color=#00F6FF>um alvo marcado é derrotado</color>.",
  str_skill_passive_name_400116 = "Quebra-Galho",
  str_skill_passive_name_410116 = "Quebra-Galho",
  str_skill_passive_name_430116 = "Quebra-Galho",
  str_skill_passive_desc_410116 = "Todo o dano que Fleur causa a inimigos com menos de 50% de seu PV Máx. é aumentado em <color=#00F6FF>{1}</color> (se o alvo não tiver um valor de PV Máx., este aumento de dano entra em vigor imediatamente).",
  str_skill_passive_desc_430116 = "Todo o dano que Fleur causa a inimigos com menos de 50% de seu PV Máx. é aumentado em <color=#00F6FF>{1}</color> (se o alvo não tiver um valor de PV Máx., este aumento de dano entra em vigor imediatamente). Concede um bônus adicional de <color=#00F6FF>{2}</color> ao atacar alvos marcados.",
  str_skill_upgrade_desc_16011613 = "Aprimoramento de Combo de Cadeia: Ao atacar alvos marcados, os ataques do Combo de Cadeia ignoram completamente a DEF. (Válido para Ascensão II.)",
  str_skill_upgrade_desc_16011616 = "Aprimoramento de Habilidade Ativa: Pode ser lançado novamente após entrar na Hora da Aurora ou quando um alvo marcado é derrotado.",
  str_skill_name_20021011 = "Destruição Pentagramática",
  str_skill_name_2002102 = "Destruição Pentagramática",
  str_skill_name_2002103 = "Destruição Pentagramática",
  str_skill_name_3002101 = "Blitz Sagrado",
  str_skill_name_3102101 = "Blitz Sagrado",
  str_skill_name_3202101 = "Blitz Sagrado",
  str_skill_name_3302101 = "Blitz Sagrado",
  str_skill_name_3022101 = "Blitz Sagrado",
  str_skill_name_3122101 = "Blitz Sagrado",
  str_skill_name_3222101 = "Blitz Sagrado",
  str_skill_name_3322101 = "Blitz Sagrado",
  str_skill_name_3152101 = "Blitz Sagrado",
  str_skill_name_3252101 = "Blitz Sagrado",
  str_skill_name_3352101 = "Blitz Sagrado",
  str_skill_passive_name_410210 = "Arrependimentos dos Moribundos",
  str_skill_passive_name_415210 = "Arrependimentos dos Moribundos",
  str_skill_desc_20021011 = "Causa <color=#00F6FF>130%</color> de dano 2 vezes aleatoriamente a inimigos em <color=#00F6FF>3 círculos ao redor</color> desta unidade. O dano é dividido pela metade a partir da segunda vez que o inimigo toma dano.",
  str_skill_desc_2002102 = "Causa <color=#00F6FF>135%</color> de dano 3 vezes, atribuindo aleatoriamente a inimigos em <color=#00F6FF>3 círculos ao redor</color> desta unidade. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2002103 = "Ofertas <color=#00F6FF>140%</color> dano 4 vezes, atribuído aleatoriamente aos inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Quando um alvo recebe dano mais de uma vez, o dano da segunda vez é reduzido pela metade.",
  str_skill_desc_3002101 = "Seleciona 1 de <color=#00F6FF>4</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>.",
  str_skill_desc_3102101 = "Seleciona 1 de <color=#00F6FF>4</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>.",
  str_skill_desc_3202101 = "Seleciona 1 de <color=#00F6FF>4</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. A cada 4 pilhas de Vontade Persistente no alvo, causa <color=#00F6FF>120%</color> de dano adicional uma vez a todos os inimigos dentro de <color=#00F6FF>12 casas em formato de diamante</color> centrado na posição da equipe.",
  str_skill_desc_3302101 = "Seleciona 1 de <color=#00F6FF>4</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 casa, causando <color=#00F6FF>metade do dano</color> na casa atravessada. A cada 4 pilhas de Vontade Persistente no alvo, causa adicionalmente <color=#00F6FF>120%</color> de dano uma vez a todos os inimigos dentro de <color=#00F6FF>12 casas em forma de diamante</color> centradas na posição da equipe.",
  str_skill_desc_3022101 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>.",
  str_skill_desc_3122101 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>.",
  str_skill_desc_3222101 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. A cada 4 pilhas de Vontade Persistente no alvo, causa <color=#00F6FF>120%</color> de dano adicional uma vez a todos os inimigos dentro de <color=#00F6FF>12 casas em formato de diamante</color> a partir da posição da equipe.",
  str_skill_desc_3322101 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 bloco à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 bloco, causando <color=#00F6FF>metade do dano</color> no bloco atravessado. A cada 4 pilhas de Vontade Persistente no alvo, causa <color=#00F6FF>120%</color> de dano adicional uma vez a todos os inimigos dentro de <color=#00F6FF>12 blocos em forma de diamante</color> centrados na posição da equipe.",
  str_skill_desc_3152101 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>.",
  str_skill_desc_3252101 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. A cada 4 pilhas de Vontade Persistente no alvo, causa <color=#00F6FF>120%</color> de dano adicional uma vez a todos os inimigos dentro de <color=#00F6FF>12 casas em formato de diamante</color> a partir da posição da equipe.",
  str_skill_desc_3352101 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>{1}%</color> de dano uma vez ao inimigo <color=#00F6FF>1 bloco à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 bloco, causando <color=#00F6FF>metade do dano</color> no bloco atravessado. A cada 4 pilhas de Vontade Persistente no alvo, causa <color=#00F6FF>120%</color> de dano adicional uma vez a todos os inimigos dentro de <color=#00F6FF>12 blocos em forma de diamante</color> centrados na posição da equipe.",
  str_skill_passive_desc_410210 = "Cada Ataque Normal e Chain Combo de Joselyne inflige 1 acúmulo de Vontade Persistente nos inimigos atingidos, até <color=#00F6FF>6</color> acúmulos. Sua Habilidade Ativa também causa <color=#00F6FF>{1}</color> de dano de ATQ ao inimigo <color=#00F6FF>1 bloco à frente</color> várias vezes, de acordo com o número de acúmulos de Vontade Persistente no alvo. Os acúmulos são reiniciados após isso.",
  str_skill_passive_desc_415210 = "Cada Ataque Normal e Chain Combo de Joselyne inflige 1 acúmulo de Vontade Persistente nos inimigos atingidos, até <color=#00F6FF>8</color> acúmulos. Sua Habilidade Ativa também causa <color=#00F6FF>{1}</color> de dano de ATQ ao inimigo <color=#00F6FF>1 bloco à frente</color> várias vezes, de acordo com o número de acúmulos de Vontade Persistente no alvo. Os acúmulos são reiniciados após isso.",
  str_skill_upgrade_desc_15021012 = "Aprimoramento de Habilidade Ativa: Seleciona qualquer uma das <color=#FFFF00>8</color> direções e avança em direção a ela.",
  str_skill_upgrade_desc_15021015 = "Aprimoramento de Habilidade de Equipamento: Aumenta o limite máximo de pilhas de Lingering Will para <color=#FFFF00>8</color>.",
  str_skill_name_200330110 = "Manipulação Psíônica",
  str_skill_desc_200330110 = "Dreadweaver se distancia da localização da equipe do jogador. Assim que o movimento da equipe terminar, Dreadweaver imediatamente mudará a localização da equipe, afetando a posição dos Combos em Cadeia lançados por sua equipe.",
  str_skill_name_200330121 = "Sacrifício de Sangue",
  str_skill_desc_200330121 = "Dreadweaver queima seu HP restante até 1 ponto, causando dano verdadeiro que ignora defesa ao jogador. A quantidade de HP queimado determina diretamente o DMG final. Esta habilidade só pode ser lançada uma vez.",
  str_skill_upgrade_refine_desc_15021011 = "Aprimoramento de Habilidade de Equipamento: Aumenta o fator de dano para <color=#00F6FF>36%</color>.",
  str_skill_upgrade_refine_desc_15021012 = "Aprimoramento de Habilidade Ativa: Para cada 4 pilhas de Vontade Persistente no alvo, causa 120% de dano uma vez a todos os inimigos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_upgrade_refine_desc_15021013 = "Aprimoramento de Habilidade Ativa: Habilidades Ativas e Habilidades de Equipamento causam dano total nos ladrilhos pelos quais atravessam.",
  str_skill_passive_desc_440210 = "Cada Ataque Normal e Chain Combo de Joselyne inflige 1 acúmulo de Vontade Persistente nos inimigos atingidos, até <color=#00F6FF>8</color> acúmulos. Sua Habilidade Ativa também causa <color=#00F6FF>36%</color> de dano de ATQ ao inimigo <color=#00F6FF>1 bloco à frente</color> várias vezes, de acordo com o número de acúmulos de Vontade Persistente no alvo. Os acúmulos são reiniciados após isso.",
  str_skill_passive_desc_445210 = "Cada Ataque Normal e Chain Combo de Joselyne inflige 1 acúmulo de Vontade Persistente nos inimigos atingidos, até <color=#00F6FF>8</color> acúmulos. Sua Habilidade Ativa também causa <color=#00F6FF>36%</color> de dano de ATQ ao inimigo <color=#00F6FF>1 bloco à frente</color> várias vezes, de acordo com o número de acúmulos de Vontade Persistente no alvo. Os acúmulos são reiniciados após isso.",
  str_skill_desc_34021011 = "Seleciona 1 de <color=#00F6FF>4</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>80%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 casa, causando <color=#00F6FF>metade do dano</color> na casa atravessada. A cada 4 pilhas de Vontade Persistente no alvo, causa <color=#00F6FF>120%</color> de dano adicional uma vez a todos os inimigos dentro de <color=#00F6FF>2 grupos adjacentes</color>.",
  str_skill_desc_34221011 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>80%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 casa, causando <color=#00F6FF>metade do dano</color> na casa atravessada. Para cada 4 pilhas de Vontade Persistente no alvo, causa adicionalmente <color=#00F6FF>120%</color> de dano uma vez a todos os inimigos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_34521011 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>80%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 casa, causando <color=#00F6FF>metade do dano</color> na casa atravessada. Para cada 4 pilhas de Vontade Persistente no alvo, causa adicionalmente <color=#00F6FF>120%</color> de dano uma vez a todos os inimigos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_34021012 = "Seleciona 1 de <color=#00F6FF>4</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>80%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 casa, causando <color=#00F6FF>dano total</color> na casa atravessada. A cada 4 pilhas de Vontade Persistente no alvo, causa adicionalmente <color=#00F6FF>120%</color> de dano uma vez a todos os inimigos dentro de <color=#00F6FF>2 grupos adjacentes</color>.",
  str_skill_desc_34221012 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>80%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 casa, causando <color=#00F6FF>dano total</color> à casa atravessada. A cada 4 pilhas de Vontade Persistente no alvo, causa adicionalmente <color=#00F6FF>120%</color> de dano uma vez a todos os inimigos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_34521012 = "Seleciona 1 de <color=#00F6FF>8</color> direções e avança, parando ao encontrar obstáculos. Causa <color=#00F6FF>80%</color> de dano uma vez ao inimigo <color=#00F6FF>1 casa à frente</color>. Esse dano, juntamente com o acionado pela Habilidade do Equipamento, pode atravessar 1 casa, causando <color=#00F6FF>dano total</color> à casa atravessada. A cada 4 pilhas de Vontade Persistente no alvo, causa adicionalmente <color=#00F6FF>120%</color> de dano uma vez a todos os inimigos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_name_70010981 = "Forsaken: Colossus Perspicácia",
  str_skill_name_70010982 = "Abandonado: Força do Relâmpago",
  str_skill_name_70010983 = "Abandonado: Grito do Colosso",
  str_skill_desc_70010981 = "Abandonada: Schummer a Aviduz causa dano aos alvos em uma área em forma de cruz centrada nela mesma.",
  str_skill_desc_70010982 = "Abandonado: Schummer o Aviduz invoca a Força do Relâmpago para causar dano em várias áreas do campo e inflige Paralisia.",
  str_skill_desc_70010983 = "Forsaken: Schummer o Aviduz controla a Colossus para liberar um Sonic Blast, causando dano a todos os alvos e atraindo Aurorians em sua direção.",
  str_skill_name_290610101 = "Avanço Desenfreado",
  str_skill_desc_290610101 = "Avança lentamente e desfere golpes pesados nos inimigos à frente.",
  str_skill_name_290610102 = "Aceleração Potente",
  str_skill_desc_290610102 = "Avança rapidamente se não houver inimigo à frente.",
  str_skill_name_290610103 = "Bombardeio Total",
  str_skill_desc_290610103 = "Causa dano aos Aurorianos ao redor do mecha e os repele. A habilidade também inflige dano nas paredes.",
  str_skill_name_290610104 = "Jatos de Chama",
  str_skill_desc_290610104 = "Lança um ataque formidável, causando dano massivo aos aurorianos à frente e às paredes.",
  str_skill_name_290610105 = "Mecânico Corrompido",
  str_skill_desc_290610105 = "Repara seus componentes quando paralisado e, após a conclusão do reparo, será reposicionado para o cerco.",
  str_skill_name_280240101 = "Impulso Dissipador",
  str_skill_desc_280240101 = "Desfere golpes pesados nos inimigos à frente do Portão da Fortaleza e os paralisa.",
  str_skill_name_290570101 = "Mudbundle: Esborrifando",
  str_skill_name_290570102 = "Mudbundle: Jorrando",
  str_skill_name_290570103 = "Mudbundle: Sifonando",
  str_skill_desc_290570101 = "Mudbundle afunda na lama e emerge na localização mais próxima dos Aurorianos, causando dano às unidades dentro de 2 aglomerados ao redor e gerando atoleiros no campo.",
  str_skill_desc_290570102 = "Mudbundle afunda na lama e emerge na localização mais próxima dos Aurorianos, causando dano às unidades dentro de 2 colunas à frente e gerando atoleiros no campo.",
  str_skill_desc_290570103 = "Absorve todos os ladrilhos no campo e os reinicia, causando dano aos Aurorianos e movendo-os para um atoleiro aleatório.",
  str_skill_desc_290570104 = "Mara Sol invoca 2 Tecelões do Medo ao campo de batalha.",
  str_skill_upgrade_desc_16021213 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate.\nConverte 2 ladrilhos não verdes aleatórios dentro da área retangular determinada da Habilidade Ativa em ladrilhos verdes.",
  str_skill_upgrade_desc_16021216 = "Aprimoramento de Habilidade Ativa: O alcance de seleção do segundo ladrilho se expande para <color=#00F6FF>4 aglomerados circundantes</color>.",
  str_skill_desc_3002121 = "Seleciona qualquer ladrilho, em seguida, seleciona outro ladrilho dentro de <color=#00F6FF>3 aglomerados circundantes</color> para determinar uma área retangular. Os 2 ladrilhos selecionados são convertidos em ladrilhos verdes e, se a equipe estiver dentro da área determinada, restaura o HP igual a <color=#00F6FF>250%</color> do ATQ de Antony.",
  str_skill_desc_3032121 = "Seleciona qualquer ladrilho, depois seleciona outro ladrilho dentro de <color=#00F6FF>3 aglomerados circundantes</color> para determinar uma área retangular. As 2 telhas selecionadas são convertidas em telhas verdes, depois converte 2 telhas não verdes aleatórias dentro da área determinada em telhas verdes. Se a equipe estiver dentro da área determinada, restaura o PV igual a <color=#00F6FF>250%</color> do ATQ de Antony.",
  str_skill_desc_3062121 = "Seleciona qualquer ladrilho, depois seleciona outro ladrilho dentro de <color=#00F6FF>4 aglomerados circundantes</color> para determinar uma área retangular. As 2 telhas selecionadas são convertidas em telhas verdes, depois converte 2 telhas não verdes aleatórias dentro da área determinada em telhas verdes. Se a equipe estiver dentro da área determinada, restaura o PV igual a <color=#00F6FF>250%</color> do ATQ de Antony.",
  str_skill_desc_3202121 = "Seleciona qualquer 1 ladrilho, depois seleciona outro 1 ladrilho dentro de <color=#00F6FF>3 aglomerados circundantes</color> para determinar uma área retangular. Os 2 ladrilhos selecionados são convertidos em <link=\"20001\"><#FFAE07><u>ladrilhos verdes aprimorados</u></color></link>, e se a equipe estiver dentro da área determinada, restaura HP igual a <color=#00F6FF>250%</color> do ATK de Antony.",
  str_skill_desc_3232121 = "Seleciona qualquer ladrilho, depois seleciona outro ladrilho dentro de <color=#00F6FF>3 aglomerados circundantes</color> para determinar uma área retangular. Os 2 ladrilhos selecionados são convertidos em <link=\"20001\"><#FFAE07><u>ladrilhos verdes aprimorados</u></color></link>, depois converte 2 ladrilhos não-verdes aleatórios dentro da área determinada em ladrilhos verdes. Se a equipe estiver dentro da área determinada, restaura HP igual a <color=#00F6FF>250%</color> do ATK de Antony.",
  str_skill_desc_3262121 = "Seleciona qualquer ladrilho, depois seleciona outro ladrilho dentro de <color=#00F6FF>4 aglomerados circundantes</color> para determinar uma área retangular. Os 2 ladrilhos selecionados são convertidos em <link=\"20001\"><#FFAE07><u>ladrilhos verdes aprimorados</u></color></link>, depois converte 2 ladrilhos não-verdes aleatórios dentro da área determinada em ladrilhos verdes. Se a equipe estiver dentro da área determinada, restaura HP igual a <color=#00F6FF>250%</color> do ATK de Antony.",
  str_skill_desc_2002121 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>1 coluna</color>.",
  str_skill_desc_2002122 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>3 colunas</color>.",
  str_skill_desc_2002123 = "Causa <color=#00F6FF>{1}%</color> de dano em <color=#00F6FF>3 colunas</color>.",
  str_skill_passive_desc_410212 = "Quando membros da equipe atravessam 1 casa em ladrilhos Verdes conectados ou <link=\"30092\"><#FFAE07><u>movem</u></color></link> 1 casa por qualquer meio, eles restauram PV igual a <color=#00F6FF>{1}</color> do ATQ de Antony.",
  str_skill_passive_desc_430212 = "Quando os membros da equipe atravessam 1 casa conectada a casas Verdes ou <link=\"30092\"><#FFAE07><u>se movem</u></color></link> 1 casa por qualquer meio, eles restauram PV igual a <color=#00F6FF>{1}</color> do ATQ de Antony. Quanto menor a saúde da equipe, maior o efeito de recuperação, até <color=#00F6FF>100%</color>.",
