  str_skill_name_8002002 = "Sonho Fulgor: Terremoto",
  str_skill_name_8002003 = "Sonho Fulgor: Relâmpago Rápido",
  str_skill_name_8002004 = "Sonho Fulgor: Impulso Voltaico",
  str_skill_name_8002005 = "Fulgor dos Sonhos: Salto Crescente",
  str_skill_desc_8002001 = "Seleciona 1 ladrilho e seleciona outro ladrilho para formar um campo de 2×2 ou 1×4 e converte os ladrilhos em azulejos cromáticos, gerando também ladrilhos aprimorados.",
  str_skill_desc_8002002 = "Seleciona 1 ladrilho e converte aleatoriamente 5 dos 9 ladrilhos em forma de quadrado em azulejos cromáticos, e gera 5 ladrilhos aprimorados aleatoriamente.",
  str_skill_desc_8002003 = "Seleciona 1 ladrilho e converte os 6 ladrilhos não cromáticos mais próximos em 6 <color=#00F6FF>azulejos cromáticos</color>, e gera ladrilhos aprimorados.",
  str_skill_desc_8002004 = "Seleciona 1 ladrilho e converte 4 ladrilhos adjacentes em <color=#00F6FF>azulejos cromáticos</color>, gerando também azulejos aprimorados.",
  str_skill_desc_8002005 = "Converte qualquer 5 ladrilhos selecionados em <color=#00F6FF>azulejos cromáticos</color> e gera ladrilhos aprimorados.",
  str_skill_name_8002006 = "Silenciar",
  str_skill_desc_8002006 = "Há muito silenciado, não responde mais a nada. Suporta os danos recebidos por todos os Eclipsitas e Soldados de Lumopolis.",
  str_skill_name_80020042 = "Ameaça",
  str_skill_desc_80020042 = "Quando um Auroriano está dentro de um alcance em forma radial, move-se para adjacente a ele, causa dano e o repele. Este ataque pode ser bloqueado por obstáculos.",
  str_skill_name_80020052 = "Hesitar",
  str_skill_desc_80020052 = "Situado fora do campo, só pode ser atingido por ataques de alvo único não direcionais, é imune a Detonadores e danos de ataques normais. O dano causado aos inimigos no campo também será transferido para Irridon.",
