  str_skill_name_30021105 = "Tempestade de Granizo Invernal",
  str_skill_name_30021106 = "Branco Eterno Sempre Verde",
  str_skill_name_30621103 = "Tempestade de Granizo Invernal",
  str_skill_name_30621104 = "Branco Eterno Sempre Verde",
  str_skill_name_30321101 = "Tempestade de Granizo Invernal",
  str_skill_name_30321102 = "Branco Eterno Sempre Verde",
  str_skill_desc_2002111 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2002112 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2002113 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_30021101 = "Converte as <color=#00F6FF>2</color> casas Amarelas mais próximas em Azuis. Após lançar Granizo Invernal, o tempo de recarga do Apagão Perene aumenta em 1.",
  str_skill_desc_30021102 = "Converte as <color=#00F6FF>2</color> casas Verdes mais próximas em Azuis. Após lançar Evergreen Whiteout, o tempo de recarga de Wintry Hailstorm aumenta em 1.",
  str_skill_desc_30021103 = "Converte as <color=#00F6FF>3</color> casas Amarelas mais próximas em Azuis. Após lançar a Tempestade de Inverno, o tempo de recarga do Apagão Sempre Verde aumenta em 1.",
  str_skill_desc_30021104 = "Converte as <color=#00F6FF>3</color> casas Verdes mais próximas em Azuis. Após lançar Evergreen Whiteout, o tempo de recarga do Wintry Hailstorm aumenta em 1.",
  str_skill_desc_30021105 = "Converte as <color=#00F6FF>4</color> casas Amarelas mais próximas em Azuis. Após lançar Granizo Invernal, o tempo de recarga do Apagão Sempre-verde aumenta em 1.",
  str_skill_desc_30021106 = "Converte as <color=#00F6FF>4</color> casas Verdes mais próximas em Azuis. Após lançar Evergreen Whiteout, o tempo de recarga do Wintry Hailstorm aumenta em 1.",
  str_skill_desc_30321101 = "Converte as <color=#00F6FF>2</color> casas Amarelas mais próximas em Azuis. Após a execução, a próxima Habilidade Ativa poderá converter <color=#00F6FF>3</color> casas, e o tempo de espera do Evergreen Whiteout aumenta em 1.",
  str_skill_desc_30321102 = "Converte as <color=#00F6FF>2</color> casas Verdes mais próximas em Azuis. Após a ativação, a próxima Habil. Ativa poderá converter <color=#00F6FF>3</color> casas, e o tempo de recarga da Tempestade de Granizo Invernal aumenta em 1.",
  str_skill_desc_30621103 = "Converte as <color=#00F6FF>3</color> casas Amarelas mais próximas em Azuis. Após usar a habilidade, o tempo de recarga do Evergreen Whiteout aumenta em +1. Se essas 2 Habil. Ativas não estiverem prontas quando a rodada começar, converte <color=#00F6FF>1</color> casa não-azul mais próxima da equipe em uma <link=\"30093\"><#FFAE07><u>Casa Escura</u></color></link> azul.",
  str_skill_desc_30621104 = "Converte as <color=#00F6FF>3</color> casas verdes mais próximas em azuis. Após lançar a habilidade, o tempo de recarga da Tempestade de Granizo Invernal aumenta em +1. Se essas 2 Habilidades Ativas não estiverem prontas quando a rodada começar, converte <color=#00F6FF>1</color> casa não-azul mais próxima da equipe em uma <color=#00F6FF>Azul</color> <link=\"30093\"><#FFAE07><u>Casa Escura</u></color></link>.",
  str_skill_passive_name_410211 = "Remediação Nevosa",
  str_skill_passive_name_420211 = "Remediação Nevosa",
  str_skill_passive_name_430211 = "Remediação Nevosa",
  str_skill_passive_desc_410211 = "Ataques normais tornam-se ataques de 2 combos que causam <color=#00F6FF>50%</color> de dano básico por acerto. A cada <color=#00F6FF>7</color> ataques normais, Zarya restaura HP igual a <color=#00F6FF>{1}</color> do seu ATK para a equipe.",
  str_skill_passive_desc_420211 = "Ataques normais tornam-se ataques de 2 combos que causam <color=#00F6FF>50%</color> de dano básico por acerto. A cada <color=#00F6FF>7</color> ataques normais, Zarya restaura HP igual a <color=#00F6FF>{1}</color> de seu ATQ para a equipe. Ao entrar na Hora da Aurora, ela restaura instantaneamente HP igual a <color=#00F6FF>100%</color> de seu ATQ para a equipe.",
  str_skill_passive_desc_430211 = "Ataques normais podem ser lançados na diagonal. Ataques normais contra inimigos em forma de cruz tornam-se ataques de 2 combos que causam <color=#00F6FF>50%</color> do dano básico por acerto. A cada <color=#00F6FF>7</color> ataques normais, Zarya restaura HP igual a <color=#00F6FF>{1}</color> de seu ATK para a equipe. Ao entrar no Aurora Time, ela restaura instantaneamente HP igual a <color=#00F6FF>100%</color> de seu ATK para a equipe.",
  str_skill_upgrade_desc_16021113 = "Melhoria de Habilidade Ativa: Aumenta as casas convertidas para <color=#FFFF00>3</color>.",
  str_skill_upgrade_desc_16021116 = "Melhoria de Habilidade Ativa: Se essas 2 Habilidades Ativas <color=#00F6FF>não estiverem prontas</color> quando a rodada começar, converte 1 casa não-azul mais próxima da equipe em uma Casa Azul Escura.",
  str_skill_name_200350101 = "Terremoto",
  str_skill_name_200350102 = "Golpe Doloroso",
  str_skill_name_200350103 = "Esmaga-crânio",
  str_skill_name_200350104 = "Lambe-sangue",
  str_skill_desc_200350101 = "Rimebeast bate no chão, causando múltiplas instâncias de dano aos inimigos em forma de cruz até o alcance máximo e os empurrando para a maior distância possível.",
  str_skill_desc_200350102 = "Quando os inimigos estão posicionados dentro de 1 aglomerado ao redor, Rimebeast causa dano a eles e os repele um quadrado.",
  str_skill_desc_200350103 = "Se os inimigos estiverem dentro de um alcance específico ao redor do Rimebeast e não houver obstáculos na área em forma de cruz, o Rimebeast se aproxima rapidamente deles e desfere um golpe poderoso, causando dano. Inimigos na área central sofrerão mais dano e ficarão atordoados.",
  str_skill_desc_200350104 = "Rimebeast recuperará seu HP quando não houver inimigos por perto.",
  str_skill_name_200360102 = "Espectro Carmesim - Perseguição",
  str_skill_desc_200360102 = "Teletransporta-se para a equipe, desferindo múltiplos golpes prejudiciais às unidades dentro de 1 casa à frente e empurrando-as para trás. Quanto maior a distância do teletransporte, menos ataques são lançados.",
  str_skill_name_290213101 = "Ruínas Eternas",
  str_skill_name_290213102 = "Juízo do Guardião",
  str_skill_name_290213103 = "Ameaça Detectada",
  str_skill_desc_290213101 = "Teletransporta 1 vez, causando dano ao mesmo tempo. Depois disso, converte 3 peças aleatórias dentro de 1 círculo ao redor do time em peças Verdes.",
  str_skill_desc_290213102 = "Teletransporta 1 vez, causando dano também. Depois disso, converte 3 casas aleatórias dentro de 1 círculo ao redor do time em casas Amarelas.",
  str_skill_desc_290213103 = "Absorve energia dos ladrilhos azuis em 2 aglomerados ao redor antes de atacar (quanto mais ladrilhos absorvidos, maior o dano).",
  str_skill_desc_200270201 = "Restaura HP para o Sinalizador Illumina e converte uma parte da Contusão acumulada em HP.",
  str_skill_desc_200280201 = "Convoca 2 Soldados Illumina para o campo de batalha.",
  str_skill_desc_200280202 = "Convoca 1 Soldado Illumina e 1 Sargento Illumina para o campo de batalha.",
  str_skill_desc_200280301 = "Invoca 2 Lança-chamas Illumina no campo de batalha.",
  str_skill_desc_200280302 = "Invoca 1 Lança-chamas Illumina e 1 Sargento Illumina para o campo de batalha.",
  str_skill_name_290280111 = "Sanki - Corte Cruzado",
  str_skill_desc_290280111 = "Sanki se move em direção ao alvo, desferindo um golpe amplo com a Lâmina Sakae para causar dano.",
  str_skill_name_290280121 = "Sanki - Frenesi da Lâmina",
  str_skill_desc_290280121 = "Libera um furacão frenético de golpes de lâmina no local, causando dano aos alvos dentro do alcance.",
