  str_skill_name_290280122 = "Frenesi",
  str_skill_desc_290280122 = "Avança em direção a um enxame de Eclipsitas e lança um turbilhão frenético de lâminas, causando dano a todos os Eclipsitas dentro de um determinado alcance.",
