  str_skill_name_111807212 = "Invocador de Pergaminho",
  str_skill_desc_111807212 = "Convoca 5 Pergaminhos em posições aleatórias no campo de batalha.",
  str_skill_name_2002131 = "Ameaça Detectada",
  str_skill_name_2102131 = "Ameaça Detectada",
  str_skill_desc_2002131 = "Causa <color=#00F6FF>{1}%</color> de dano ao inimigo mais próximo, que ganha um bônus de dano adicional com base na contagem de Chain Combo.",
  str_skill_desc_2102131 = "Causa 3 instâncias de dano ao inimigo mais próximo, cada uma igual a 30% do dano original. O dano recebe um bônus com base no número de ataques normais lançados pelo lançador nesta rodada.",
  str_skill_name_300213 = "Controle de Área",
  str_skill_desc_300213 = "Seleciona 1 ladrilho, desativa temporariamente seu elemento e cria <color=#00F6FF>um domínio quadrado de 25 ladrilhos</color> centralizado no ladrilho selecionado. Pelos próximos <color=#00F6FF>15 segundos</color>, você pode tocar continuamente para trocar os elementos dos ladrilhos adjacentes. O ladrilho selecionado será convertido em <color=#00F6FF>Amarelo</color> quando a contagem regressiva terminar. Só pode ser lançado 1 vez durante toda a batalha.",
  str_skill_name_302213 = "Controle de Área",
  str_skill_desc_302213 = "Seleciona 1 ladrilho, desativa temporariamente seu elemento e cria <color=#00F6FF>um domínio quadrado de 25 ladrilhos</color> centrado no ladrilho selecionado. Pelos próximos <color=#00F6FF>15 segundos</color>, você pode tocar continuamente para trocar os elementos dos ladrilhos adjacentes. O ladrilho selecionado será convertido em <color=#00F6FF>Amarelo</color> quando a contagem regressiva terminar. Concede uma utilização ao entrar na batalha/na 2ª onda.",
  str_skill_name_305213 = "Controle de Área",
  str_skill_desc_305213 = "Seleciona 1 ladrilho, desativa temporariamente seu elemento e cria <color=#00F6FF>um domínio quadrado de 25 ladrilhos</color> centrado no ladrilho selecionado. Pelos próximos <color=#00F6FF>15 segundos</color>, você pode tocar continuamente para trocar os elementos dos ladrilhos adjacentes. O ladrilho selecionado será convertido em <color=#00F6FF>Amarelo</color> quando a contagem regressiva terminar. Concede uma utilização ao entrar na batalha/na 2ª onda/na 7ª rodada.",
  str_skill_passive_name_410213 = "Hora da Erupção",
  str_skill_passive_desc_410213 = "Quando a contagem de combos atinge <color=#00F6FF>{1}</color>, o Chain Combo atual lança 3 instâncias de dano, cada uma igual a 30% do dano original. O dano recebe um bônus com base no número de ataques normais realizados pelo lançador nesta rodada.",
  str_skill_passive_name_420213 = "Hora da Erupção",
  str_skill_passive_desc_420213 = "Quando a contagem de combos atinge <color=#00F6FF>{1}</color>, o Chain Combo atual lança 3 instâncias de dano, cada uma igual a 30% do dano original. O dano ganha um bônus com base no número de ataques normais realizados pelo lançador nesta rodada e pode ser desencadeado <color=#00F6FF>independentemente do elemento das peças conectadas</color>.",
  str_skill_passive_name_430213 = "Hora da Erupção",
  str_skill_passive_desc_430213 = "Quando a contagem de combos atinge <color=#00F6FF>{1}</color>, o Chain Combo atual lança 3 instâncias de dano, cada uma igual a 30% do dano original. O dano ganha um bônus com base no número de ataques normais realizados pelo lançador nesta rodada e pode ser desencadeado <color=#00F6FF>independentemente do elemento das peças conectadas</color>. Quando novas peças são adicionadas à corrente, a N-ésima peça desta corrente será convertida em Amarela, com N representando as rodadas restantes.",
  str_skill_upgrade_desc_15021312 = "Melhoria de Habilidade Ativa: Concede uma utilização ao entrar na 2ª onda.",
  str_skill_upgrade_desc_15021315 = "Melhoria de Habilidade Ativa: Concede uma utilização ao entrar na 7ª rodada.",
  str_skill_name_53520212 = "Invocação",
  str_skill_desc_53520212 = "Ataca os Aurorianos primeiro se estiverem presentes em sua proximidade; se não, convoca mais Lumopolis Pikers para auxiliar no combate.",
  str_skill_name_53520213 = "Encorajar",
  str_skill_desc_53520213 = "Ataca os aurorianos primeiro se estiverem presentes em sua proximidade; se não, inspira os Soldados de Lumopolis próximos, aumentando seu ATK.",
  str_skill_name_53520411 = "Ameaça Detectada",
  str_skill_desc_53520411 = "Absorve energia dos ladrilhos azuis em 2 aglomerados ao redor antes de causar dano aos inimigos. Quanto mais ladrilhos absorvidos, maior o dano.",
  str_skill_name_53520412 = "Ameaça Detectada",
  str_skill_desc_53520412 = "Absorve energia dos ladrilhos vermelhos em 2 aglomerados circundantes antes de causar dano aos inimigos. Quanto mais ladrilhos absorvidos, maior o dano.",
  str_skill_name_53520413 = "Ameaça Detectada",
  str_skill_desc_53520413 = "Absorve energia dos ladrilhos verdes em 2 aglomerados ao redor antes de causar dano aos inimigos. Quanto mais ladrilhos absorvidos, maior o dano.",
  str_skill_name_5352031 = "Explosão Fatal",
  str_skill_desc_5352031 = "Explode sempre que um certo tempo passar, causando dano a todas as unidades no campo de batalha.",
  str_skill_name_29089011 = "Martelo do Juiz Chefe",
