  str_skill_desc_3051871 = "Causa aleatoriamente <color=#00F6FF>90%</color> de dano <color=#00F6FF>8</color> vezes aos inimigos dentro de <color=#00F6FF>13 peças em forma de diamante</color> centradas em 1 ladrilho selecionado.",
  str_skill_passive_desc_410187 = "Se não houver inimigos em <color=#00F6FF>1 círculo ao redor</color>, cada instância do Combo em Cadeia tem <color=#00F6FF>25%</color> de chance de causar <color=#00F6FF>{1}×</color> de dano.",
  str_skill_passive_desc_420187 = "Se não houver inimigos dentro de <color=#00F6FF>1 cluster circundante</color>, cada instância da Habilidade Ativa e Combo em Cadeia tem <color=#00F6FF>25%</color> de chance de causar <color=#00F6FF>{1}×</color> de dano.",
  str_skill_passive_desc_430187 = "Se não houver inimigos dentro de <color=#00F6FF>1 cluster circundante</color>, cada instância da Habilidade Ativa e Combo em Cadeia tem <color=#00F6FF>25%</color> de chance de causar <color=#00F6FF>{1}×</color> de dano. Se não houver inimigos dentro de <color=#00F6FF>2 clusters circundantes</color>, a chance aumenta para <color=#00F6FF>50%</color>.",
