  str_skill_desc_2001883 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_300188 = "Seleciona quaisquer <color=#00F6FF>2</color> casas para converter em casas Vermelhas, causando <color=#00F6FF>{1}%</color> de dano às casas no caminho e às casas adjacentes.",
  str_skill_desc_306188 = "Seleciona qualquer <color=#00F6FF>2</color> casas para converter em casas Vermelhas, causando <color=#00F6FF>{1}%</color> de dano às casas ao longo do caminho e casas adjacentes. Elimina inimigos não-chefes no alcance com HP menor que <color=#00F6FF>15%</color>.",
  str_skill_passive_desc_410188 = "Durante esta rodada, o primeiro ataque normal lançado em cada direção acertará um golpe crítico, causando <color=#00F6FF>{1}</color> de dano.",
  str_skill_passive_desc_420188 = "Durante esta rodada, o primeiro ataque normal lançado em cada direção causará um acerto crítico, causando <color=#00F6FF>{1}</color> de dano. Ao entrar na Hora da Aurora, a contagem de acertos críticos para todas as direções de ataque normal é reiniciada.",
  str_skill_passive_desc_430188 = "Ataques normais <color=#00F6FF>podem ser lançados diagonalmente</color>. Durante esta rodada, o primeiro ataque normal lançado em cada direção será um acerto crítico, causando <color=#00F6FF>{1}</color> de dano. Ao entrar no Aurora Time, a contagem de acertos críticos para todas as direções de ataque normal é reiniciada.",
  str_skill_upgrade_desc_16018813 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16018816 = "Melhoria de Habilidade Ativa: Multiplicador de dano aumenta para <color=#FFFF00>360%</color>. Elimina inimigos não-chefes no alcance com HP inferior a 15%.",
  str_skill_desc_1501301061 = "Após se mover, causa dano ao inimigo mais próximo.",
