  str_skill_passive_name_435215 = "Um Momento de Alegria",
  str_skill_passive_desc_410215 = "Quando Isa desencadeia Ataques Normais em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>, eles causam <color=#00F6FF>{1}</color> de dano 3 vezes.",
  str_skill_passive_desc_420215 = "Quando Isa desfere Ataques Normais em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>, eles causam <color=#00F6FF>{1}</color> de dano 3 vezes. Após Isa causar dano ao mesmo inimigo <color=#00F6FF>7 vezes</color> com seu Ataque Normal, ela causa dano adicional igual a <color=#00F6FF>100%</color> de seu ATK.",
  str_skill_passive_desc_430215 = "Quando Isa desencadeia Ataques Normais em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>, eles causam <color=#00F6FF>{1}</color> de dano 3 vezes. Após Isa causar dano ao mesmo inimigo <color=#00F6FF>7 vezes</color> com seu Ataque Normal e/ou Combo em Cadeia, ela causa dano adicional igual a <color=#00F6FF>100%</color> de seu ATK. Acertar um alvo com sua Habilidade Ativa também acionará dano adicional 1 vez.",
  str_skill_passive_desc_425215 = "Quando Isa desencadeia Ataques Normais em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>, eles causam <color=#00F6FF>{1}</color> de dano 3 vezes. Após Isa causar dano ao mesmo inimigo <color=#00F6FF>7 vezes</color> com seu Ataque Normal, ela causa dano adicional igual a <color=#00F6FF>150%</color> de seu ATK.",
  str_skill_passive_desc_435215 = "Quando Isa desencadeia Ataques Normais em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>, eles causam <color=#00F6FF>{1}</color> de dano 3 vezes. Após Isa causar dano ao mesmo inimigo <color=#00F6FF>7 vezes</color> com seu Ataque Normal e/ou Combo em Cadeia, ela causa dano adicional igual a <color=#00F6FF>150%</color> de seu ATK. Acertar um alvo com sua Habilidade Ativa também acionará dano adicional 1 vez.",
