  str_skill_desc_2002153 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>24 telhas em forma radial</color>.",
  str_skill_name_300215 = "Sobre Cobrança de Dívidas",
  str_skill_desc_300215 = "Seleciona uma casa onde um inimigo está posicionado e escolhe 1 das 4 direções ao redor da casa. Se o inimigo não for um chefe, força-o a se mover 1 casa na direção selecionada, causa {1}% de dano a ele e gera um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link> na casa selecionada.",
  str_skill_upgrade_refine_desc_15021511 = "Aprimoramento de Habilidade de Equipamento: Ataques normais causam dano 3 vezes aos inimigos em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link> e o fator de dano aumenta para <color=#00F6FF>65%</color>.",
