  str_skill_desc_2402141 = "Causa <color=#00F6FF>145%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>. Aplica <color=#00F6FF>2</color> acúmulos de Imersão em todos os alvos dentro do alcance.",
  str_skill_desc_2402142 = "Causa <color=#00F6FF>160%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>. Aplica <color=#00F6FF>2</color> acúmulos de Imersão em todos os alvos dentro do alcance.",
  str_skill_desc_2402143 = "Causa <color=#00F6FF>165%</color> de dano <color=#00F6FF>em formato radial até o alcance máximo</color>. Inflige <color=#00F6FF>2</color> acúmulos de Imersão em todos os alvos dentro do alcance.",
  str_skill_desc_3002141 = "Converte 1 azulejo selecionado em um <link=\"30093\"><#FFAE07><u>Azulejo Escuro Azul</u></color></link> e converte as <color=#00F6FF>3</color> casas Azuis mais próximas a este azulejo em Azulejos Escuros Azuis.",
  str_skill_desc_3062141 = "Converte 1 casa selecionada em uma <link=\"30093\"><#FFAE07><u>Casa Azul Escura</u></color></link> e converte as <color=#00F6FF>5</color> casas Azuis mais próximas desta casa em Casas Azuis Escuras.",
  str_skill_passive_name_410214 = "Metástase Venenosa",
  str_skill_passive_desc_410214 = "Sempre que passar por um Ladrilho Escuro, inflige <link=\"30094\"><#FFAE07><u>Imersão</u></color></link> em <color=#00F6FF>12 peças em forma de diamante</color>. No início da rodada inimiga, cada pilha de Imersão causa dano igual a <color=#00F6FF>{1}</color> do ATK ao alvo.",
  str_skill_passive_name_430214 = "Metástase Venenosa",
  str_skill_passive_desc_430214 = "Sempre que passar por um Ladrilho Escuro, inflige <link=\"30094\"><#FFAE07><u>Imersão</u></color></link> em <color=#00F6FF>12 peças em forma de diamante</color>. No início da rodada do inimigo, cada pilha de Imersão causa dano igual a <color=#00F6FF>{1}</color> do ATK ao alvo. A Imersão causa dano ignorando DEF aos inimigos atingidos por um Combo em Cadeia nesta rodada.",
  str_skill_upgrade_desc_16021413 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16021416 = "Aprimoramento de Habil. Ativa: Converte as <color=#FFFF00>5</color> casas Azuis mais próximas da casa selecionada em Casas Azuis Escuras.",
  str_skill_upgrade_refine_desc_16021411 = "Aprimoramento de Habilidade de Equipamento: Cada pilha de Imersão causa dano igual a <color=#00F6FF>40%</color> do ATK de Rebecca ao alvo.",
  str_skill_upgrade_refine_desc_16021412 = "Aprimoramento do Combo de Cadeia: O Combo de Cadeia inflige <color=#00F6FF>2</color> acúmulos de Imersão em todos os alvos dentro do alcance.",
  str_skill_upgrade_refine_desc_16021413 = "Aprimoramento de Habilidade Ativa: Ao lançar a Habilidade Ativa, causa dano 1 vez em todos os alvos com Imersão, causando o dobro de dano.",
  str_skill_passive_desc_440214 = "Sempre que passar por um Ladrilho Escuro, inflige <link=\"30094\"><#FFAE07><u>Imersão</u></color></link> em <color=#00F6FF>12 peças em forma de diamante</color>. No início da rodada do inimigo, cada pilha de Imersão causa dano igual a <color=#00F6FF>40%</color> do ATK ao alvo. A Imersão causa dano ignorando DEF aos inimigos atingidos por um Combo em Cadeia nesta rodada.",
  str_skill_desc_3402141 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>ladrilho Azul Escuro</u></color></link> e converte os <color=#00F6FF>3</color> ladrilhos Azuis mais próximos a este em ladrilhos Azuis Escuros, em seguida, causa dano 1 vez em todos os alvos no campo com Imersão, causando dano dobrado.",
  str_skill_desc_3462141 = "Converte 1 casa selecionada em um Azul <link=\"30093\"><#FFAE07><u>Casa Escura</u></color></link> e converte as <color=#00F6FF>5</color> casas Azuis mais próximas desta casa em Casas Escuras Azuis, em seguida, causa dano 1 vez em todos os alvos no campo com Imersão, causando dano dobrado.",
