  str_skill_desc_8003001 = "Seleciona 1 casa e seleciona outra casa para formar um campo 2x2 ou 1x4, e converte as casas dentro para casas cromáticas.",
  str_skill_desc_8003002 = "Seleciona 1 casa e converte aleatoriamente 5 das 9 casas em formato quadrado em casas cromáticas.",
  str_skill_desc_8003003 = "Seleciona 1 casa e converte as 6 casas não cromáticas mais próximas em 6 casas cromáticas.",
  str_skill_desc_8003004 = "Seleciona 1 casa e converte 4 casas adjacentes em casas cromáticas.",
  str_skill_desc_8003005 = "Converte 5 peças selecionadas em peças cromáticas.",
  str_skill_name_290900113 = "Mantendo Distância",
  str_skill_desc_290900113 = "Afaste-se dos aurorianos.",
  str_skill_name_1003431 = "Abraço Enfraquecedor",
  str_skill_desc_1003431 = "Aderir aos Aurorianos dentro de 1 aglomerado ao redor, causando dano a eles e reduzindo seu ATK.",
  str_skill_name_200380101 = "Tiro Rápido",
  str_skill_desc_200380101 = "Move-se o mais longe possível do alvo e cause dano ao alvo 2 vezes.",
  str_skill_name_200370101 = "Flecha Distante",
  str_skill_desc_200370101 = "Causa dano aos alvos em forma de cruz até o alcance máximo.",
  str_skill_name_290910102 = "Névoa Venenosa",
  str_skill_name_290910103 = "Borboleta Venenosa",
  str_skill_name_290910104 = "Ataque das Borboletas",
  str_skill_desc_290910102 = "Move e depois ataca inimigos dentro de 2 casas em forma de cruz, infligindo-lhes 2 pilhas de Fusão. No início de cada rodada, cada pilha de Fusão causa dano com base em uma porcentagem do ATK de Rebecca Venomswamp.",
  str_skill_desc_290910103 = "Se afasta do alvo, causa dano e aplica 1 acúmulo de Fusão. No início de cada rodada, cada acúmulo de Fusão causa dano com base em uma porcentagem do ATK de Rebecca Venomswamp.",
  str_skill_desc_290910104 = "Após se mover, causa dano dentro de um alcance fixo, inflige 3 acúmulos de Fusão e invoca aleatoriamente várias Marcas de Veneno dentro do alcance.",
  str_skill_name_200390101 = "Golpe Mecânico",
  str_skill_desc_200390101 = "Ataca o inimigo mais próximo. Se estiver com menos de 40% de HP, recupera uma certa porcentagem de HP após se afastar.",
  str_skill_name_200390102 = "Ataque de Cura",
  str_skill_desc_200390102 = "Recupera uma certa porcentagem de HP.",
  str_skill_name_200410101 = "Assassinato",
  str_skill_desc_200410101 = "Ataca o alvo 2 vezes após se mover e recua até 2 casas. Se não houver alvos no alcance, aumenta o ACT na próxima rodada.",
  str_skill_name_9997042 = "Abrasador Voante",
  str_skill_name_9997041 = "Gelador Voante",
  str_skill_name_9997043 = "Florestalma Voante",
  str_skill_name_9997044 = "Trovão Voante",
  str_skill_name_9997045 = "Prato do Amanhecer",
  str_skill_name_200140111 = "Tentaclaw - Prevenção de Danos",
  str_skill_desc_200140111 = "O dano sustentado de Tentaclaw é passado para Kittypus. Mas antes de um Auroriano liberar o Chain Combo, o tentaclaw se enrola para evitar ataques.",
  str_skill_name_5000591 = "Repelindo Goldor",
  str_skill_desc_5000591 = "Causa dano e empurra todos os alvos uma vez.",
  str_skill_name_5000592 = "Goldor Purificador",
  str_skill_desc_5000592 = "Causa dano a todos os alvos à sua frente uma vez.",
  str_skill_name_5000593 = "Frenesi de Fuga",
  str_skill_desc_5000593 = "Após um auroriano lançar uma Habilidade Ativa, ladrilhos amarelos aleatórios serão convertidos em ladrilhos vermelhos enquanto se movem.",
  str_skill_name_5000594 = "Calor Compartilhado",
  str_skill_desc_5000594 = "Você sempre se aproximará de Goldor, não importa onde esteja.",
  str_skill_name_29092001 = "Pinça Rasgadora",
  str_skill_desc_29092001 = "Stinger causa dano aos alvos dentro de 1 aglomerado ao redor de si 2 vezes e inflige efeitos de Sangramento neles.",
  str_skill_desc_290920011 = "Stinger causa dano aos alvos em 1 aglomerado ao redor de si 2 vezes e inflige neles os efeitos de Sangramento e Sem Cura.",
  str_skill_name_29092002 = "Confronto Montanhoso",
  str_skill_desc_29092002 = "O Stinger seleciona 1 direção onde um jogador está em uma área em forma de cruz, avança até a borda do campo ou o obstáculo mais próximo e, em seguida, empurra todos os alvos ao longo de seu caminho, causando dano adicional aos alvos dentro de 1 casa em ambos os lados de seu trajeto e infligindo Sangramento neles.",
  str_skill_name_29092003 = "Imolar",
  str_skill_desc_29092003 = "Stinger dispara um raio de Energia de sua cauda, causando um enorme dano ao alvo 1 vez.",
  str_skill_name_29092004 = "Impulso Carregado",
  str_skill_desc_29092004 = "Stinger pula para trás em 1 ladrilho, causando dano aos alvos à sua frente e infligindo efeitos de Sangramento e Veneno.",
  str_skill_name_29092005 = "Investida Desenfreada",
  str_skill_desc_29092005 = "O Stinger avança horizontal e verticalmente em sucessão, causando dano aos alvos à sua frente e infligindo efeitos de Sangramento e Veneno.",
  str_skill_name_29092006 = "Reflexo no Espelho",
  str_skill_desc_29092006 = "Stinger dispara raios nos borboletas espelho, formando um caminho triangular com a luz que refletem e causando dano a tudo em seu caminho.",
  str_skill_name_2002161 = "Puxar Guarda-sol",
  str_skill_name_2002162 = "Puxar Guarda-sol",
  str_skill_name_2002163 = "Puxar Guarda-sol",
  str_skill_name_2202161 = "Puxar Guarda-sol",
  str_skill_name_2202162 = "Puxar Guarda-sol",
  str_skill_name_2202163 = "Puxar Guarda-sol",
  str_skill_name_300216 = "Flash Relâmpago",
  str_skill_name_303216 = "Flash Relâmpago",
  str_skill_passive_name_410216 = "Perímetro da Libélula",
  str_skill_passive_name_430216 = "Perímetro da Libélula",
  str_skill_desc_2002161 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2002162 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próx.",
  str_skill_desc_2002163 = "Causa <color=#00F6FF>{1}%</color> de dano aos 4 inimigos mais próx.",
  str_skill_desc_2202161 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e, em seguida, causa dano mais uma vez a 1 inimigo aleatório dentro de uma Matriz Quadrada de Trovão.",
  str_skill_desc_2202162 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próximos e, em seguida, causa dano novamente a 1 inimigo aleatório dentro de uma Matriz Quadrada de Trovão.",
  str_skill_desc_2202163 = "Causa <color=#00F6FF>{1}%</color> de dano aos 4 inimigos mais próximos e, em seguida, causa dano novamente a 1 inimigo aleatório dentro de uma Matriz Quadrada de Trovão.",
  str_skill_desc_300216 = "Consome 3 <link=\"30095\"><#FFAE07><u>Peças Sobressalentes</u></color></link> para selecionar qualquer ladrilho e gerar um Array de Trovão Quadrado dentro de <color=#00F6FF>9 ladrilhos em forma quadrada</color> que dura <color=#00F6FF>2</color> rodadas. O ataque normal de Xuan Ji <color=#00F6FF>pode ser lançado na diagonal</color> dentro de um Array de Trovão Quadrado.",
  str_skill_desc_303216 = "Consome 3 <link=\"30095\"><#FFAE07><u>Peças Sobressalentes</u></color></link> para selecionar qualquer 1 bloco e gerar uma Matriz de Trovão Quadrada dentro de <color=#00F6FF>25 blocos em forma de quadrado</color> que dura <color=#00F6FF>3</color> rodadas. O ataque normal de Xuan Ji <color=#00F6FF>pode ser lançado na diagonal</color> dentro de uma Matriz de Trovão Quadrada.",
  str_skill_passive_desc_410216 = "Aumenta o dano de Xuan Ji em uma Matriz Quadrada de Trovão em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_416216 = "Aumenta o dano de Xuan Ji em uma Matriz de Trovão Quadrada em <color=#00F6FF>{1}</color>. Seu dano aumenta ainda mais em <color=#00F6FF>5%</color> para cada Matriz de Trovão Quadrada adicional no campo. Se Xuan Ji estiver dentro de uma Matriz de Trovão Quadrada quando a rodada terminar, ela ganha 1 Peça Sobressalente.",
  str_skill_passive_desc_430216 = "Aumenta o dano de Xuan Ji em uma Matriz de Trovão Quadrada em <color=#00F6FF>{1}</color>. Sempre que Xuan Ji estiver dentro de uma Matriz de Trovão Quadrada após lançar seu Combo em Cadeia, seu ATQ básico é aumentado em <color=#00F6FF>4%</color>, acumulando até 5 vezes. Se ela não estiver dentro de uma Matriz de Trovão Quadrada quando a rodada terminar, as pilhas deste efeito serão reduzidas pela metade.",
  str_skill_passive_desc_436216 = "Aumenta o dano de Xuan Ji em uma Matriz de Trovão Quadrada em <color=#00F6FF>{1}</color>. Seu dano é aumentado em <color=#00F6FF>5%</color> para cada Matriz de Trovão Quadrada adicional no campo. Se Xuan Ji estiver dentro de uma Matriz de Trovão Quadrada quando a rodada terminar, ela ganha 1 Peça Sobressalente. Sempre que Xuan Ji estiver dentro de uma Matriz de Trovão Quadrada após lançar seu Chain Combo, seu ATQ básico é aumentado em <color=#00F6FF>4%</color>, acumulando até 5 vezes. Se ela não estiver dentro de uma Matriz de Trovão Quadrada quando a rodada terminar, as pilhas deste efeito são reduzidas pela metade.",
  str_skill_upgrade_desc_16021613 = "Aprimoramento de Habilidade Ativa: Expande a área do Arranjo Quadrado de Trovão para <color=#00F6FF>25 ladrilhos em forma de quadrado</color>. Dura por <color=#00F6FF>3</color> rodadas.",
  str_skill_upgrade_desc_16021616 = "Aprimoramento de Habilidade de Equipamento: O dano de Xuan Ji é aumentado em <color=#00F6FF>5%</color> para cada Array de Trovão Quadrado adicional no campo. Se Xuan Ji estiver dentro de um Array de Trovão Quadrado quando a rodada terminar, ela ganha 1 Peça Sobressalente.",
  str_skill_name_53820323 = "Explode quando os Aurorianos se aproximam. Se deixado sozinho, ele explodirá após um certo número de rodadas e gerará várias chamas ao seu redor.",
  str_skill_name_200400103 = "Fogo na Barriga",
  str_skill_name_200400104 = "Fogo na Barriga",
  str_skill_desc_200400103 = "Move-se lateralmente e cospe chamas, causando dano aos inimigos à sua frente. Ele para de se mover quando encontra obstáculos.",
  str_skill_desc_200400104 = "Move-se lateralmente e cospe chamas, causando dano aos inimigos à sua frente. Ele para de se mover quando encontra obstáculos.",
  str_skill_name_290570123 = "Mudbundle: Devorador",
  str_skill_desc_290570123 = "Mudbundle emerge do centro do grande pântano, devorando tudo e causando dano aos Aurorianos.",
  str_skill_name_290620102 = "Cortador Espacial: Latitude",
  str_skill_desc_290620102 = "Vilanor corre e ataca, causando dano e lançando uma Parede Proibida de 3 ladrilhos horizontalmente ao lado dos Aurorianos e se teletransporta para um novo local.",
  str_skill_name_290620104 = "Cortador Espacial: Longitude",
  str_skill_desc_290620104 = "Vilanor corre e ataca, causando dano e lançando uma Parede Proibida de 3 ladrilhos verticalmente ao lado dos Aurorianos e se teletransporta para um novo local.",
  str_skill_name_290620106 = "Mantenha Distância",
  str_skill_desc_290620106 = "Vilanor causa dano aos inimigos dentro de 1 aglomerado ao redor e os repele para o local mais distante possível, em seguida, lança uma Parede Proibida na borda externa dos ladrilhos dentro de 1 aglomerado ao redor.",
  str_skill_name_800400011 = "Armadilha de Exorcismo",
  str_skill_desc_800400011 = "Ao pisar em uma Armadilha de Exorcismo, todas as Paredes Proibidas no campo serão removidas.",
  str_skill_desc_2900273 = "Causa dano aos Aurorianos em qualquer lugar do campo de batalha e convoca Goldor.",
  str_skill_desc_2000303 = "Paga Ouro para recuperar o HP do Goldor Amaldiçoado quando dentro de 1 cluster ao redor dele.",
  str_skill_desc_2000304 = "Quando dentro de 1 aglomerado ao redor de Istvan, pague Ouro para recuperar seu HP.",
  str_skill_desc_200381101 = "Aumenta o alcance de movimento, em seguida, move-se perto do alvo e causa dano 2 vezes. Este movimento não é obstruído por obstáculos.",
  str_skill_desc_200411101 = "Ataca o alvo 2 vezes após se mover, empurrando o alvo e deixando uma bomba, depois recua até 3 casas. Se não houver alvos dentro do alcance, aumenta o ACT na próxima rodada.",
  str_skill_desc_200371101 = "Causa dano aos inimigos dentro de um alcance de 3 peças em uma forma de cruz, os repele e deixa uma bomba onde eles estavam antes de serem repelidos.",
  str_skill_upgrade_desc_16021913 = "Aprimoramento de Habilidade Ativa: Ganhe <color=#00F6FF>5</color> Dotações de Sombra ao entrar na batalha.\nAprimoramento da Habilidade do Equipamento: Expande o alcance de seleção do Movimento de Xadrez para 2 aglomerados circundantes.",
  str_skill_upgrade_desc_16021916 = "Ganhe Nova Habilidade Ativa: Seleciona quaisquer <color=#00F6FF>2</color> ladrilhos e troca os Ladrilhos Escuros nestes 2 ladrilhos. Se houver uma Peça Sombra em um ladrilho selecionado, a Peça Sombra também será trocada para o outro ladrilho.",
  str_skill_name_2002191 = "Garras Ardentes",
  str_skill_name_2002192 = "Garras Ardentes",
  str_skill_name_2002193 = "Garras Ardentes",
  str_skill_desc_2002191 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos dentro <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2002192 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos dentro <color=#00F6FF>3 aglomerados circundantes</color>.",
  str_skill_desc_2002193 = "Ofertas <color=#00F6FF>{1}%</color> dano aos 4 inimigos mais próximos dentro <color=#00F6FF>4 círculos ao redor</color>.",
  str_skill_name_3002191 = "Roque Sombrio",
  str_skill_name_3302191 = "Roque Sombra",
  str_skill_name_3032191 = "Roque Sombra",
  str_skill_name_3332191 = "Roque Sombra",
  str_skill_name_3062191 = "Transferência de Sombra",
  str_skill_desc_3002191 = "Consome <color=#00F6FF>2</color> <link=\"30096\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que ele possa <color=#00F6FF>lançar seu Combo em Cadeia mais 1 vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo em Cadeia adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo em Cadeia nesta rodada. Sempre que a Habilidade Ativa for lançada no mesmo aliado nesta batalha, +1 custo de Dotacão de Sombra.",
  str_skill_desc_3302191 = "Consome <color=#00F6FF>2</color> <link=\"30096\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que possa <color=#00F6FF>lançar seu Combo mais uma vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo nesta rodada. Alternativamente, consome <color=#00F6FF>2</color> Dotações de Sombra para selecionar uma Peça de Sombra no campo e lançar a Habilidade Ativa, que faz a Peça de Sombra lançar um Combo em Cadeia em vez de Istvan: Scarred Pith nesta rodada, e o dano final será aumentado em <color=#00F6FF>50%</color>. O custo da Dotação de Sombra será sempre 2 quando isso for lançado na Peça de Sombra. Sempre que a Habilidade Ativa é lançada no mesmo aliado nesta batalha, +1 custo de Dotação de Sombra.",
  str_skill_desc_3032191 = "Consome <color=#00F6FF>2</color> <link=\"30097\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que ele possa <color=#00F6FF>lançar seu Combo em Cadeia mais uma vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo em Cadeia adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo em Cadeia nesta rodada. Sempre que a Habilidade Ativa for lançada no mesmo aliado nesta batalha, +1 custo de Dotacão de Sombra.",
  str_skill_desc_3332191 = "Consome <color=#00F6FF>2</color> <link=\"30097\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que possam <color=#00F6FF>lançar seu Combo mais 1 vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo nesta rodada. Alternativamente, consome <color=#00F6FF>2</color> Dotações de Sombra para selecionar uma Peça de Sombra no campo e lançar a Habilidade Ativa, que faz a Peça de Sombra lançar um Combo em Cadeia em vez de Istvan: Medula Cicatrizada nesta rodada, e o dano final será aumentado em <color=#00F6FF>50%</color>. O custo da Dotação de Sombra será sempre 2 quando isso for lançado na Peça de Sombra. Sempre que a Habilidade Ativa é lançada no mesmo aliado nesta batalha, +1 custo de Dotação de Sombra.",
  str_skill_desc_3062191 = "Seleciona quaisquer <color=#00F6FF>2</color> ladrilhos e troca os Ladrilhos Escuros nestes 2 ladrilhos. Se houver uma Peça Sombra em um ladrilho selecionado, a Peça Sombra também será trocada para o outro ladrilho.",
  str_skill_passive_name_410219 = "Promoção de Sombra",
  str_skill_passive_name_420219 = "Promoção de Sombra",
  str_skill_passive_name_403219 = "Promoção de Sombra",
  str_skill_passive_name_423219 = "Promoção de Sombra",
  str_skill_passive_desc_410219 = "Ao entrar na batalha, Istvan: Scarred Pith invoca 1 Peça Sombria perto dos Aurorianos que podem lançar habilidades.\nMovimento de Xadrez: Teletransporta-se para uma casa percorrida dentro de <color=#00F6FF>12 casas em forma de diamante</color> e causa <color=#00F6FF>{1}</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_passive_desc_420219 = "Ao entrar na batalha, Istvan: Scarred Pith invoca 1 Peça Sombria perto dos Aurorianos que podem lançar habilidades. Quando a rodada termina, a Peça Sombria gera um <link=\"30093\"><#FFAE07><u>Tile Escuro</u></color></link> abaixo dela.\nMovimento do Xadrez: Teletransporta para um ladrilho transponível dentro de <color=#00F6FF>12 ladrilhos em forma de diamante</color> e causa <color=#00F6FF>{1}</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados ao redor</color>.",
  str_skill_passive_desc_403219 = "Ao entrar na batalha, Istvan: Scarred Pith invoca 1 Peça Sombria perto dos Aurorianos que podem lançar habilidades.\nMovimento de Xadrez: Teletransporta para um ladrilho transponível dentro de <color=#00F6FF>2 aglomerados ao redor</color> e causa <color=#00F6FF>{1}</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados ao redor</color>.",
  str_skill_passive_desc_423219 = "Ao entrar na batalha, Istvan: Scarred Pith invoca 1 Peça Sombria perto dos Aurorianos que podem lançar habilidades. Quando a rodada termina, a Peça Sombria gera um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link> abaixo dela.\nMovimento de Xadrez: Teletransporta para um ladrilho transponível dentro de <color=#00F6FF>2 círculos ao redor</color> e causa <color=#00F6FF>{1}</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_name_160219111 = "Movimento de Xadrez",
  str_skill_name_160219112 = "Movimento de Xadrez",
  str_skill_name_160219114 = "Movimento de Xadrez",
  str_skill_name_160219115 = "Movimento de Xadrez",
  str_skill_name_160219116 = "Movimento de Xadrez",
  str_skill_name_160219117 = "Movimento de Xadrez",
  str_skill_name_160219118 = "Movimento de Xadrez",
  str_skill_name_160219119 = "Movimento de Xadrez",
  str_skill_name_160219120 = "Movimento de Xadrez",
  str_skill_name_160219121 = "Movimento de Xadrez",
  str_skill_desc_160219111 = "Teletransporta para qualquer ladrilho transponível dentro de <color=#00F6FF>12 ladrilhos em forma de diamante</color> e causa <color=#00F6FF>40%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_160219112 = "Teletransporta para qualquer ladrilho transponível dentro de <color=#00F6FF>2 aglomerados circundantes</color> e causa <color=#00F6FF>40%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_160219114 = "Teletransporta para qualquer casa transponível dentro de <color=#00F6FF>12 casas em forma de diamante</color> e causa <color=#00F6FF>60%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_160219115 = "Teletransporta para qualquer ladrilho transponível dentro de <color=#00F6FF>2 aglomerados circundantes</color> e causa <color=#00F6FF>60%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_160219116 = "Teletransporta para qualquer ladrilho transponível dentro de <color=#00F6FF>12 ladrilhos em forma de diamante</color> e causa <color=#00F6FF>80%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_160219117 = "Teletransporta para qualquer ladrilho transponível dentro de <color=#00F6FF>2 aglomerados circundantes</color> e causa <color=#00F6FF>80%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_160219118 = "Teletransporta para qualquer casa transponível dentro de <color=#00F6FF>12 casas em forma de diamante</color> e causa <color=#00F6FF>100%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_160219119 = "Teletransporta para qualquer ladrilho transponível dentro de <color=#00F6FF>2 aglomerados circundantes</color> e causa <color=#00F6FF>100%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_160219120 = "Teletransporta para qualquer casa transponível dentro de <color=#00F6FF>12 casas em forma de diamante</color> e causa <color=#00F6FF>110%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_160219121 = "Teletransporta para qualquer ladrilho transponível dentro de <color=#00F6FF>2 aglomerados circundantes</color> e causa <color=#00F6FF>110%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_upgrade_refine_desc_16021911 = "Aprimoramento de Habilidade de Equipamento: Aumenta o dano da habilidade Movimento de Xadrez para <color=#00F6FF>110%</color>.",
  str_skill_upgrade_refine_desc_16021912 = "Melhoria de Habilidade Ativa: Se lançar a Habilidade Ativa na Peça Sombra, o dano final do Combo em Cadeia da Peça Sombra nesta rodada será aumentado em <color=#00F6FF>60%</color>.",
  str_skill_upgrade_refine_desc_16021913 = "Aprimoramento de Habilidade Ativa: Dotacão de Sombra <color=#00F6FF>+2</color> no início de cada onda.",
  str_skill_passive_desc_450219 = "Ao entrar na batalha, Istvan: Scarred Pith convoca 1 Peça Sombria perto dos Aurorianos que podem lançar habilidades. Quando a rodada termina, a Peça Sombria gera um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link> abaixo dela.\nMovimento de Xadrez: Teletransporta para uma casa percorrida dentro de <color=#00F6FF>12 casas em forma de diamante</color> e causa <color=#00F6FF>110%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_passive_desc_453219 = "Ao entrar na batalha, Istvan: Scarred Pith invoca 1 Peça Sombria perto dos Aurorianos que podem lançar habilidades. Quando a rodada termina, a Peça Sombria gera um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link> abaixo dela.\nMovimento de Xadrez: Teletransporta para um ladrilho transponível dentro de <color=#00F6FF>2 círculos ao redor</color> e causa <color=#00F6FF>110%</color> de dano aos 4 inimigos mais próximos dentro de <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_3602191 = "Consome <color=#00F6FF>2</color> <link=\"30096\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que ele possa <color=#00F6FF>lançar seu Combo mais uma vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo nesta rodada. Alternativamente, consome <color=#00F6FF>2</color> Dotações de Sombra para selecionar uma Peça de Sombra no campo e lançar a Habilidade Ativa, que faz a Peça de Sombra lançar um Combo em Cadeia em vez de Istvan: Medula Cicatrizada nesta rodada, e o dano final será aumentado em <color=#00F6FF>60%</color>. O custo da Dotação de Sombra será sempre 2 quando isso for lançado na Peça de Sombra. Sempre que uma Habilidade Ativa é lançada no mesmo aliado nesta batalha, +1 custo de Dotação de Sombra.",
  str_skill_desc_3632191 = "Consome <color=#00F6FF>2</color><link=\"30097\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que possam <color=#00F6FF>lançar seu Combo mais 1 vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo nesta rodada. Alternativamente, consome <color=#00F6FF>2</color> Dotações de Sombra para selecionar uma Peça de Sombra no campo e lançar a Habilidade Ativa, que faz a Peça de Sombra lançar um Combo em Cadeia em vez de Istvan: Medula Cicatrizada nesta rodada, e o dano final será aumentado em <color=#00F6FF>60%</color>. O custo da Dotação de Sombra será sempre 2 quando isso for lançado na Peça de Sombra. Sempre que uma Habilidade Ativa é lançada no mesmo aliado nesta batalha, +1 custo de Dotação de Sombra.",
  str_skill_desc_3702191 = "Consome <color=#00F6FF>2</color> <link=\"30099\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que possam <color=#00F6FF>lançar seu Combo mais uma vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo nesta rodada. Alternativamente, consome <color=#00F6FF>2</color> Dotações de Sombra para selecionar uma Peça de Sombra no campo e lançar a Habilidade Ativa, que faz a Peça de Sombra lançar um Combo em Cadeia em vez de Istvan: Medula Cicatrizada nesta rodada, e o dano final será aumentado em <color=#00F6FF>60%</color>. O custo da Dotação de Sombra será sempre 2 quando isso for lançado na Peça de Sombra. Sempre que uma Habilidade Ativa é lançada no mesmo aliado nesta batalha, +1 custo de Dotação de Sombra.",
  str_skill_desc_3732191 = "Consome <color=#00F6FF>2</color><link=\"30098\"><#FFAE07><u>Dotacões de Sombra</u></color></link> e seleciona <color=#00F6FF>um aliado</color> para que possam <color=#00F6FF>lançar seu Combo de Corrente mais uma vez</color> nesta rodada (este efeito não se acumula). Ao lançar o Combo de Corrente adicional, o ATQ do aliado será igual a <color=#00F6FF>100%</color> do ATQ de Istvan: Scarred Pith. Istvan: Scarred Pith não lançará um Combo de Corrente nesta rodada. Alternativamente, consome <color=#00F6FF>2</color> Dotações de Sombra para selecionar uma Peça de Sombra no campo e lançar a Habilidade Ativa, que faz a Peça de Sombra lançar um Combo em Cadeia em vez de Istvan: Medula Cicatrizada nesta rodada, e o dano final será aumentado em <color=#00F6FF>60%</color>. O custo da Dotação de Sombra será sempre 2 quando isso for lançado na Peça de Sombra. Sempre que uma Habilidade Ativa é lançada no mesmo aliado nesta batalha, +1 custo de Dotação de Sombra.",
