  str_skill_name_3052202 = "Exposição Total",
  str_skill_name_3022201 = "Exposição Total",
  str_skill_desc_20022011 = "Causa <color=#00F6FF>125%</color> de dano 2 vezes, atribuindo aleatoriamente a inimigos em <color=#00F6FF>3 círculos ao redor</color> desta unidade. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2002202 = "Ofertas <color=#00F6FF>130%</color> dano 3 vezes, atribuído aleatoriamente aos inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color> desta unidade. Quando um alvo sofre dano mais de uma vez, o dano da segunda vez em diante é reduzido pela metade.",
  str_skill_desc_2002203 = "Causa <color=#00F6FF>135%</color> de dano 4 vezes, atribuindo aleatoriamente a inimigos em <color=#00F6FF>3 círculos ao redor</color>. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_3002201 = "Conv. as <color=#00F6FF>2</color> casas Amarelas mais próx. em Casas Azuis Escuras.",
  str_skill_desc_3002202 = "Converte as <color=#00F6FF>2</color> casas Amarelas mais próximas em Azuis Escuras. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3052201 = "Converte as <color=#00F6FF>3</color> casas Amarelas mais próximas em Azuis Escuras. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_desc_3052202 = "Converte as <color=#00F6FF>3</color> casas Amarelas mais próximas em Azuis Escuras. Se a Habil. Ativa já estava pronta na rodada anterior, aumenta as casas convertidas em <color=#00F6FF>+1</color> nessa rodada.",
  str_skill_passive_name_410220 = "Refrações Caleidoscópicas",
  str_skill_passive_name_420220 = "Refrações Caleidoscópicas",
  str_skill_passive_name_430220 = "Refrações Caleidoscópicas",
  str_skill_passive_desc_410220 = "No início de cada rodada, inflige <color=#00F6FF>Avaliação</color> no alvo mais distante no campo por 1 rodada. Sempre que um alvo com Avaliação é atingido por 1 habilidade de Combo de alvo único, 1 ataque extra é lançado no alvo, causando dano igual a <color=#00F6FF>{1}</color> do ATK de Vergil.",
  str_skill_passive_desc_420220 = "No início de cada rodada, inflige <color=#00F6FF>Avaliação</color> no alvo mais distante no campo por 1 rodada. Ao entrar na Hora da Aurora, ele tem efeito 1 vez adicional. Sempre que um alvo com Avaliação é atingido por 1 habilidade de Combo de Cadeia de alvo único, 1 ataque extra é lançado no alvo, causando dano igual a <color=#00F6FF>{1}</color> do ATQ de Vergil.",
  str_skill_passive_desc_430220 = "No início de cada rodada, inflige <color=#00F6FF>Avaliação</color> no alvo mais distante no campo por 1 rodada. Ao entrar na Hora da Aurora, tem efeito 1 vez adicional. Sempre que um alvo com Avaliação é atingido por 1 habilidade de Combo de alvo único, 1 ataque extra é lançado no alvo, causando dano igual a <color=#00F6FF>{1}</color> do ATQ de Vergil. Quando o alvo é atingido pelo Combo de Vergil, esse dano adicional é dobrado.",
  str_skill_upgrade_desc_15022012 = "Melhoria de Habilidade Ativa: Se a Habil. Ativa já estava pronta na última rodada, converte 1 casa Amarela adicional em uma Casa Azul Escura nesta rodada.",
  str_skill_upgrade_desc_15022015 = "Melhoria de Habilidade Ativa: Aumenta o número de casas convertidas em Casas Azuis Escuras em 1.",
  str_skill_desc_290910114 = "Após se mover, causa dano dentro de um alcance fixo e inflige 3 pilhas de Fusão.",
  str_skill_desc_290910124 = "Após se mover, causa dano dentro de um alcance fixo, inflige 3 acúmulos de Fusão e invoca várias Marcas de Veneno.",
  str_skill_name_16021911 = "Ataque Normal",
  str_skill_desc_16021911 = "Lança um Ataque Normal após o movimento, matando o alvo com um único golpe.",
  str_skill_desc_16021912 = "Após se mover, lança o Chain Combo, causando dano igual a 40% do HP máximo do alvo a cada alvo.",
