  str_skill_passive_name_436218 = "Sobre o Capital",
  str_skill_desc_2002181 = "Causa <color=#00F6FF>150%</color> de dano aos inimigos em <color=#00F6FF>2 círculos ao redor</color> 3 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2002182 = "Causa <color=#00F6FF>155%</color> de dano a inimigos em <color=#00F6FF>3 círculos ao redor</color> 4 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2002183 = "Causa <color=#00F6FF>165%</color> de dano aos inimigos em <color=#00F6FF>3 círculos ao redor</color> 5 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2002184 = "Causa <color=#00F6FF>150%</color> de dano aos inimigos dentro de <color=#00F6FF>2 aglomerados circundantes</color> 3 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano da segunda vez em diante é reduzido pela metade. Causa dano 1 vez adicional ao alvo mais distante.",
  str_skill_desc_2002185 = "Causa <color=#00F6FF>155%</color> de dano aos inimigos em <color=#00F6FF>3 círculos ao redor</color> 4 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez. Causa dano 1 vez adicional ao alvo mais distante.",
  str_skill_desc_2002186 = "Causa <color=#00F6FF>165%</color> de dano aos inimigos em <color=#00F6FF>3 círculos ao redor</color> 5 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez. Causa dano 1 vez adicional ao alvo mais distante.",
  str_skill_desc_2202181 = "Causa <color=#00F6FF>150%</color> de dano aos inimigos dentro de <color=#00F6FF>2 aglomerados circundantes</color> 3 vezes em uma ordem fixa. Quando um alvo sofre dano mais de uma vez, o dano da segunda vez em diante é reduzido pela metade. Para cada Ladrilho Escuro passado ao conectar ladrilhos desta vez, o alcance do Chain Combo se expande em 1 aglomerado circundante.",
  str_skill_desc_2202182 = "Causa <color=#00F6FF>155%</color> de dano aos inimigos dentro de <color=#00F6FF>3 aglomerados circundantes</color> 4 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano da segunda vez em diante é reduzido pela metade. Para cada Ladrilho Escuro passado ao conectar ladrilhos desta vez, o alcance do Chain Combo se expande em 1 aglomerado circundante.",
  str_skill_desc_2202183 = "Causa <color=#00F6FF>165%</color> de dano aos inimigos dentro de <color=#00F6FF>3 aglomerados circundantes</color> 5 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano da segunda vez em diante é reduzido pela metade. Para cada Ladrilho Escuro passado ao conectar ladrilhos desta vez, o alcance do Combo em Cadeia se expande em 1 aglomerado circundante.",
  str_skill_desc_2202184 = "Causa <color=#00F6FF>150%</color> de dano aos inimigos em <color=#00F6FF>2 círculos ao redor</color> 3 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez. Causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo. Para cada Ladrilho Escuro passado ao conectar ladrilhos desta vez, o alcance do Chain Combo se expande em 1 círculo ao redor.",
  str_skill_desc_2202185 = "Causa <color=#00F6FF>155%</color> de dano aos inimigos dentro de <color=#00F6FF>3 aglomerados circundantes</color> 4 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano a partir da segunda vez é reduzido pela metade. Causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo. Para cada Ladrilho Escuro passado ao conectar ladrilhos desta vez, o alcance do Chain Combo se expande por 1 aglomerado circundante.",
  str_skill_desc_2202186 = "Causa <color=#00F6FF>165%</color> de dano aos inimigos em <color=#00F6FF>3 círculos ao redor</color> 5 vezes em uma ordem fixa. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez. Causa dano 1 vez adicional ao alvo mais distante. Este dano adicional não será reduzido pela metade ao causar dano ao mesmo alvo. Para cada Ladrilho Escuro passado ao conectar ladrilhos desta vez, o alcance do Chain Combo se expande em 1 círculo ao redor.",
  str_skill_desc_3002181 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Azul e causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma de cruz</color>.",
  str_skill_desc_30021811 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Azul e causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>13 ladrilhos em forma de diamante</color>.",
  str_skill_desc_3402181 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 casas em forma de cruz</color> centradas em 1 casa selecionada.",
  str_skill_desc_3412181 = "<color=#FFFF00>Redução de 1 no tempo de recarga da habilidade após a conjuração</color>. Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>13 casas em forma de diamante</color> centradas na casa selecionada.",
  str_skill_desc_3402182 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> Azul e causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>5 ladrilhos em forma de cruz</color>. Para cada 5 pontos de Capital, ganhe 1 Capital adicional como dividendo.",
  str_skill_desc_3412182 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link> Azul e causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>13 ladrilhos em forma de diamante</color>. Para cada 5 pontos de Capital, ganhe 1 Capital adicional como dividendo.",
  str_skill_desc_30021812 = "Converte 1 ladrilho selecionado em um Azul <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link> e causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>5 ladrilhos em forma de cruz</color>.",
  str_skill_desc_300218112 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>ladrilho escuro</u></color></link> Azul e causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>13 peças em forma de diamante</color>.",
  str_skill_desc_34021812 = "<color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>5 ladrilhos em forma de cruz</color> centrados em 1 ladrilho selecionado.",
  str_skill_desc_34121812 = "<color=#FFFF00>Cooldown da habilidade -1 após a conjuração</color>. Causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>13 ladrilhos em forma de diamante</color> centrados em 1 ladrilho selecionado.",
  str_skill_desc_34021822 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>ladrilho Azul Escuro</u></color></link> e causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>5 ladrilhos em forma de cruz</color>. Para cada 5 pontos de Capital, ganhe 1 Capital adicional como dividendo.",
  str_skill_desc_34121822 = "Converte 1 ladrilho selecionado em um <link=\"30093\"><#FFAE07><u>ladrilho escuro</u></color></link> Azul e causa <color=#00F6FF>150%</color> de dano a <color=#00F6FF>13 peças em forma de diamante</color>. Para cada 5 pontos de Capital, ganhe 1 Capital adicional como dividendo.",
  str_skill_passive_desc_410218 = "Sheol inicia a batalha com <link=\"510218\"><#FFAE07><u>Estratégia de Investimento</u></color></link> e pode acumular Capital para selecionar estratégias de investimento e ganhar habilidades de combate correspondentes. (Alcance o Nível de Equipamento Lv. 3/6/10 para desbloquear as estratégias de investimento \"Impulsionado pela Névoa\", \"Riqueza Esmagadora\" e \"Ataque de Capital.\")",
  str_skill_passive_desc_413218 = "Sheol inicia a batalha com <link=\"513218\"><#FFAE07><u>Estratégia de Investimento</u></color></link> e pode acumular Capital para selecionar estratégias de investimento e ganhar habilidades de combate correspondentes. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos. (Alcance o Nível de Equipamento Lv. 3/6/10 para desbloquear as estratégias de investimento \"Impulsionado pela Névoa\", \"Riqueza Esmagadora\" e \"Ataque Capital\").",
  str_skill_passive_desc_416218 = "Sheol começa a batalha com <link=\"516218\"><#FFAE07><u>Estratégia de Investimento</u></color></link> e pode acumular Capital para selecionar estratégias de investimento e ganhar habilidades de combate correspondentes. Sheol começa a batalha com 5 de Capital. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos. (Alcance o Nível de Equipamento Lv. 3/6/10 para desbloquear as estratégias de investimento \"Impulsionado pela Névoa\", \"Riqueza Esmagadora\" e \"Ataque de Capital\").",
  str_skill_passive_desc_430218 = "Sheol inicia a batalha com <link=\"530218\"><#FFAE07><u>Estratégia de Investimento</u></color></link> e pode acumular Capital para selecionar estratégias de investimento e ganhar habilidades de combate correspondentes. Após completar a primeira rodada de investimento, ela pode fazer uma segunda rodada de investimento para obter habilidades de combate que não tinha na primeira rodada de investimento. (Alcance o Nível de Equipamento Lv. 3/6/10 para desbloquear as estratégias de investimento \"Impulsionado pela Névoa\", \"Riqueza Esmagadora\" e \"Ataque de Capital\").",
  str_skill_passive_desc_433218 = "Sheol inicia a batalha com <link=\"533218\"><#FFAE07><u>Estratégia de Investimento</u></color></link> e pode acumular Capital para selecionar estratégias de investimento e ganhar habilidades de combate correspondentes. Após completar a primeira rodada de investimento, ela pode fazer uma segunda rodada de investimento para obter habilidades de combate que não tinha na primeira rodada de investimento. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos. (Alcance o Nível de Equipamento Nv. 3/6/10 para desbloquear as estratégias de investimento \"Impulsionado pela Névoa\", \"Riqueza Esmagadora\" e \"Golpe de Capital\".)",
  str_skill_passive_desc_436218 = "Sheol começa a batalha com <link=\"536218\"><#FFAE07><u>Estratégia de Investimento</u></color></link> e pode acumular Capital para selecionar estratégias de investimento e ganhar habilidades de combate correspondentes. Após completar a primeira rodada de investimento, ela pode fazer uma segunda rodada de investimento para obter habilidades de combate que não tinha na primeira rodada de investimento. Sheol começa a batalha com 5 Capital. Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos. (Alcance o Nível de Equipamento Nv. 3/6/10 para desbloquear as estratégias de investimento \"Impulsionado pela Névoa\", \"Riqueza Esmagadora\" e \"Golpe de Capital\".)",
  str_skill_upgrade_desc_16021813 = "Aprimoramento de Habilidade de Equipamento: Cada ponto de Capital ganho após completar a segunda rodada de investimento aumenta o ATK de Sheol em 1%, até 40 pontos. (desbloqueia na Ascensão III)",
  str_skill_upgrade_desc_16021816 = "Sheol começa a batalha com 5 Capital. Para cada 5 pontos de Capital que ela tem ao lançar sua Habilidade Ativa, ela ganha 1 Capital adicional como dividendo.",
  str_skill_name_53920111 = "Ataque Normal",
  str_skill_desc_53920111 = "Ataca os inimigos com um Ataque Normal após o movimento, causando muito dano a eles.",
  str_skill_desc_53920112 = "Causa dano aos inimigos dentro de 2 aglomerados ao redor após se mover.",
  str_skill_desc_53920214 = "Após a equipe passar por um Ladrilho Escuro, Sheol causa dano aos inimigos dentro de 2 aglomerados ao redor 2 vezes.",
  str_skill_upgrade_refine_desc_16021811 = "<color=#00F6FF>Nova Variante de Habilidade Ativa</color>: <color=#FFFF00>Tempo de recarga da habilidade -1 após a conjuração</color>. A Habilidade Ativa apenas causa dano e não gera nenhum Azulejo Escuro Azul.",
  str_skill_upgrade_refine_desc_16021812 = "Melhoria de Habilidade Ativa: Aumenta o dano da Habil. Ativa em <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16021813 = "Aprimoramento de Habilidade de Equipamento: Reduz o custo do ponto de capital da segunda rodada de investimento em 1 ponto.",
  str_skill_name_70011191 = "Forsaken: Devorar - Saudável",
  str_skill_desc_70011191 = "Quando os alvos estão dentro do alcance, Aurorianos e fantasmas dentro de dois aglomerados na direção à frente são devorados. Os Aurorianos sofrem danos e são então cuspidos para a borda do tabuleiro.",
  str_skill_name_70011192 = "Forsaken: Devorar - Obliterar",
  str_skill_desc_70011192 = "Causa uma enorme quantidade de dano aos alvos quando estão ao alcance, e quaisquer fantasmas ao redor dos alvos são eliminados instantaneamente.",
  str_skill_name_70011193 = "Esquecidos: Devorar - Exército Fantasma",
  str_skill_desc_70011193 = "Quando o alvo está dentro do alcance, um grande número de fantasmas é convocado e todos os fantasmas no campo de batalha são aprimorados.",
  str_skill_name_70011195 = "Forsaken: Devorar - Saudável",
  str_skill_desc_70011195 = "Quando os alvos estão dentro do alcance, Aurorianos e fantasmas dentro de dois grupos à frente são devorados, causando dano verdadeiro aos Aurorianos. Quanto mais fantasmas são devorados, maior o dano causado. Os Aurorianos são então cuspidos para a borda do tabuleiro.",
  str_skill_name_200440103 = "Golpe Esmagador",
  str_skill_name_200450103 = "Barragem de Explosão",
  str_skill_name_200460103 = "Ataque Armado",
  str_skill_name_200460104 = "Aniquilação Total",
  str_skill_desc_200440103 = "Balança a arma para causar dano aos Aurorians.",
  str_skill_desc_200450103 = "Causa dano aos aurorianos em uma forma de cruz até o alcance máximo.",
  str_skill_desc_200460103 = "Causa dano aos Aurorianos após o movimento.",
  str_skill_desc_200460104 = "Lança um ataque penetrante na direção dos aurorianos após se mover, causando dano tanto a inimigos quanto a aliados, e então perde uma certa quantidade de HP.",
  str_skill_name_8004003 = "Explode quando os Aurorianos se aproximam. Se deixado sozinho, ele explodirá após um certo número de rodadas e gerará uma Parede Proibida de 1 ladrilho ao redor dele.",
  str_skill_desc_8004039 = "Aumento de dano nesta rodada: Dreadblades usa lâminas para atacar alvos dentro do alcance 2 vezes, causando danos extremamente altos.",
  str_skill_name_8004039 = "Corte Duplo+",
  str_skill_desc_8004055 = "Vilanor corre e ataca, causando dano e lançando uma Parede Proibida de 5 ladrilhos horizontalmente ao lado dos aurorianos. Em seguida, se teletransporta para um novo local.",
  str_skill_desc_8004057 = "Vilanor corre e ataca, causando dano e lançando uma Parede Proibida de 5 ladrilhos verticalmente ao lado dos Aurorianos, depois se teletransporta para um novo local.",
  str_skill_desc_8004051 = "Vilanor corre e desfere um golpe, causando dano e lançando uma Parede Proibida de 3 ladrilhos horizontalmente ao lado dos aurorianos, depois se teleporta para sua localização original.",
  str_skill_desc_8004053 = "Vilanor corre e ataca, causando dano e lançando uma Parede Proibida de 3 ladrilhos verticalmente ao lado dos aurorianos, depois se teletransporta para sua localização original.",
  str_skill_name_8004012 = "Invocar Atrivespa Marcavinha+",
  str_skill_desc_8004012 = "Invoca 1 Atrivespa e 1 Marca de Vinha para a batalha a cada rodada.",
  str_skill_desc_8004022 = "Após pisar em uma Armadilha de Exorcismo, a partir da próxima rodada, as Paredes Proibidas ao redor dos Aurorianos se expandem para 3 aglomerados circundantes novamente.",
  str_skill_desc_8004040 = "Ao pisar em uma Armadilha de Exorcismo, Muros Proibidos serão invocados ao redor dos inimigos.",
  str_skill_desc_8004050 = "Ao pisar em uma Armadilha de Exorcismo, todas as Paredes Proibidas dentro de 2 aglomerados ao redor serão removidas.",
  str_skill_name_290640101 = "Pisoteio",
  str_skill_name_290640102 = "Saída Eficiente",
  str_skill_name_290640103 = "Substituição de Componentes",
  str_skill_desc_290640101 = "Consome uma certa porcentagem de seu próprio HP e todas as pilhas de Armadura Mecânica após se mover para atacar alvos dentro de 2 quadrados à sua frente. Se o alvo estiver ao lado de Blaugm, ele repele o alvo em 1 quadrado. Após o ataque, restaura seu próprio HP com base no número de pilhas de Armadura Mecânica consumidas.",
  str_skill_desc_290640102 = "Causa dano a todos os alvos dentro de uma forma de leque. Quanto mais próximo o alvo, maior o dano causado.",
  str_skill_desc_290640103 = "Blaugm se fortalece, aumentando permanentemente seu ATK, DEF e Max HP, e ganha um certo número de pilhas de Armadura Mecânica.",
  str_skill_name_29063011 = "Velocidade do Vento Opressiva",
  str_skill_name_29063012 = "Mira na localização dos aurorianos e avança para a borda do tabuleiro, causando dano a todos os inimigos dentro do alcance ao longo do caminho.",
  str_skill_name_29063013 = "Modificação Corporal",
  str_skill_desc_29063011 = "Move-se em direção aos aurorianos e causa dano aos inimigos dentro de 2 blocos à sua frente.",
  str_skill_desc_29063012 = "Ataque de Dados",
  str_skill_desc_29063013 = "Ulysses usa o Protótipo Guardião para causar dano aos Aurorianos em qualquer lugar do campo de batalha.",
  str_skill_name_2002211 = "Erupção Binária",
  str_skill_name_2002212 = "Erupção Binária",
  str_skill_name_2002213 = "Erupção Binária",
  str_skill_desc_2002211 = "Bool causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2002212 = "Bool causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em formato radial</color>.",
  str_skill_desc_2002213 = "Bool causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>24 casas em formato radial</color>.",
  str_skill_name_300221 = "Tarifa da Morte",
  str_skill_name_306221 = "Tarifa da Morte",
  str_skill_name_320221 = "Tarifa da Morte",
  str_skill_name_326221 = "Tarifa da Morte",
  str_skill_name_340221 = "Tarifa da Morte",
  str_skill_name_346221 = "Tarifa da Morte",
  str_skill_desc_300221 = "Escolhe qualquer 1 ladrilho, em seguida, seleciona 3 ladrilhos dentro de <color=#00F6FF>1 aglomerado circundante</color> ao redor para transformá-los em <link=\"30093\"><#FFAE07><u>Azulejos Escuros</u></color></link>. Bool causa <color=#00F6FF>{1}%</color> de dano a esta área.",
  str_skill_desc_306221 = "Escolhe qualquer 1 ladrilho, em seguida, seleciona 4 ladrilhos dentro de <color=#00F6FF>12 ladrilhos em forma de diamante</color> ao redor para transformá-los em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>. Bool causa <color=#00F6FF>{1}%</color> de dano a esta área.",
  str_skill_desc_320221 = "Escolhe qualquer 1 ladrilho, em seguida, seleciona 3 ladrilhos dentro de <color=#00F6FF>1 aglomerado circundante</color> ao redor para transformá-los em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>. Bool causa <color=#00F6FF>{1}%</color> de dano a esta área. Ganha 1 ponto de cálculo cada vez que o dano é causado.",
  str_skill_desc_326221 = "Escolhe qualquer 1 ladrilho, em seguida, seleciona 4 ladrilhos dentro de <color=#00F6FF>12 ladrilhos em forma de diamante</color> ao redor para transformá-los em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>. Bool causa <color=#00F6FF>{1}%</color> de dano a esta área. Ganha 1 ponto de cálculo cada vez que o dano é causado.",
  str_skill_desc_340221 = "Escolhe qualquer 1 ladrilho, em seguida, seleciona 3 ladrilhos dentro de <color=#00F6FF>1 aglomerado circundante</color> ao redor para transformá-los em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>. Bool causa <color=#00F6FF>250%</color> de dano a esta área. Ganha 1 ponto de cálculo cada vez que o dano é causado.",
  str_skill_desc_346221 = "Escolhe qualquer 1 ladrilho, depois seleciona 4 ladrilhos dentro de <color=#00F6FF>12 ladrilhos em forma de diamante</color> ao redor para transformá-los em <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link>. Bool causa <color=#00F6FF>250%</color> de dano a esta área. Ganha 1 ponto de cálculo cada vez que o dano é causado.",
  str_skill_passive_name_410221 = "Números Mágicos Nanométricos",
  str_skill_passive_name_430221 = "Números Mágicos Nanométricos",
  str_skill_passive_name_440221 = "Números Mágicos Nanométricos",
  str_skill_passive_name_443221 = "Números Mágicos Nanométricos",
  str_skill_passive_desc_410221 = "Ganha 1 ponto de cálculo cada vez que passa por um <link=\"30093\"><#FFAE07><u>Casa Escura</u></color></link>. Cada ponto de cálculo aumenta o dano do Bool em <color=#00F6FF>{1}</color>, e metade dos pontos de cálculo será retida no final da rodada.",
  str_skill_passive_desc_430221 = "Ganha 1 ponto de cálculo cada vez que passa por um <link=\"30093\"><#FFAE07><u>Tile Escuro</u></color></link>. Cada ponto de cálculo aumenta o dano de Bool em <color=#00F6FF>{1}</color>, e metade dos pontos de cálculo serão retidos no final do turno. Se houver não menos que <color=#00F6FF>3</color> pontos de cálculo após o fim da ação de Bool, Bool causa um dano adicional de <color=#00F6FF>100%</color> ao inimigo que recebeu mais vezes dano dele.",
  str_skill_passive_desc_440221 = "Ganha 1 ponto de cálculo cada vez que passa por um <link=\"30093\"><#FFAE07><u>Tile Escuro</u></color></link>. Cada ponto de cálculo aumenta o dano de Bool em <color=#00F6FF>6%</color>, e metade dos pontos de cálculo serão retidos no final do turno. Se houver não menos que <color=#00F6FF>3</color> pontos de cálculo após o fim da ação de Bool, Bool causa um dano adicional de <color=#00F6FF>100%</color> ao inimigo que mais vezes recebeu dano dele.",
  str_skill_passive_desc_443221 = "Ganha 1 ponto de cálculo cada vez que passa por um <link=\"30093\"><#FFAE07><u>Tile Escuro</u></color></link>. Cada ponto de cálculo aumenta o dano de Bool em <color=#00F6FF>6%</color>, e metade dos pontos de cálculo serão retidos no final do turno. Se houver não menos que <color=#00F6FF>3</color> pontos de cálculo após o fim da ação de Bool, Bool causa um dano adicional de <color=#00F6FF>120%</color> ao inimigo que recebeu mais dano dele.",
  str_skill_upgrade_refine_desc_16022111 = "Aprimoramento de Habilidade de Equipamento: Cada ponto de cálculo aumenta o dano de Bool em <color=#00F6FF>6%</color>.",
  str_skill_upgrade_refine_desc_16022112 = "Melhoria de Habilidade Ativa: Aumenta o fator de dano em <color=#00F6FF>30%</color>.",
  str_skill_upgrade_refine_desc_16022113 = "Aprimoramento de Habilidade de Equipamento: Aumenta o dano adicional causado por Bool para <color=#00F6FF>120%</color>.",
  str_skill_upgrade_desc_16022113 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16022116 = "Melhoria de Habilidade Ativa: O alcance expande para 13 peças em forma de diamante, e o número de peças que podem ser selecionadas aumenta para 4.",
  str_skill_name_802401 = "Talento: Quebra-Céus",
  str_skill_name_802402 = "Habilidade: Apagar",
  str_skill_name_802403 = "Talento: Vitalização",
  str_skill_name_802404 = "Knack: Terremoto",
  str_skill_name_802405 = "Habilidade: Desorientar",
  str_skill_desc_802401 = "Este pedaço de metal pode dobrar o tecido do espaço e transportar os Aurorianos para qualquer casa que possa ser atravessada.",
  str_skill_desc_802402 = "Os restos de um deslizamento de terra que destruiu uma cidade. Pode remover Rochas ou Paredes Proibidas de qualquer ladrilho.",
  str_skill_desc_802403 = "Uma gota de orvalho deixada pelas estrelas em movimento. Usar isso aumenta os pontos de força dos aurorianos em 7.",
  str_skill_desc_802404 = "Uma arma de pólvora do misterioso oriente. Repelir todos os inimigos dentro de 1 aglomerado ao redor para a maior distância e causa dano a eles.",
  str_skill_desc_802405 = "As ervas podem ser usadas para salvar pessoas ou para envenená-las. Atordoa o alvo por 1 rodada.",
  str_skill_desc_80240131 = "Invoca 3 Runas de Alma Sombria de uma vez, cada uma se transforma em uma Alma Sombria com habil. de cura após 3 rodadas.",
  str_skill_desc_8024441 = "Murkmite ataca alvos dentro do alcance e reduz os pontos de força dos alvos em 2.",
  str_skill_name_802431111 = "Vontade do Mal: O Chamado",
  str_skill_desc_802431111 = "Convoca alguns inimigos para a área próxima para apoiá-lo.",
  str_skill_desc_8024150 = "O Coletor causa dano igual a 30% do PV máx. a inimigos adjacentes. Custa 5 pontos de força.",
  str_skill_desc_8024151 = "O Coletor se autorrepara para regenerar 25% do PV máx. Custa 3 pontos de força.",
  str_skill_desc_8024152 = "O Coletor irradia partículas de energia, formando 3 camadas de Escudo que podem suportar danos. Custa 1 ponto de força.",
  str_skill_name_80242801 = "Armadilha de Gaiola",
  str_skill_desc_80242801 = "Uma gaiola robusta, aparentemente inquebrável. O inimigo dentro pode transferir uma proporção do dano que sofre para o inimigo central. Consome 3 pontos de força para libertar o inimigo da gaiola.",
  str_skill_upgrade_desc_16022313 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16022316 = "Aprimoramento de Habilidade Ativa: Reduz a recarga de habilidade em <color=#FFFF00>1</color> rodada. Aumenta o número de Ladrilhos Escuros gerados para 5.",
  str_skill_name_2002231 = "Dança do Dragão Abençoada",
  str_skill_name_2002232 = "Dança do Dragão Abençoada",
  str_skill_name_2002233 = "Dança do Dragão Abençoada",
  str_skill_name_3002231 = "Graça Divina do Trovão",
  str_skill_name_3062231 = "Graça do Trovão Divino",
  str_skill_passive_name_410223 = "Sinos de Escamas de Dragão",
  str_skill_passive_name_420223 = "Sinos de Escamas de Dragão",
  str_skill_passive_name_430223 = "Sinos de Escamas de Dragão",
  str_skill_desc_2002231 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_2002232 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2002233 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>24 casas em forma de diamante</color>.",
  str_skill_desc_3002231 = "Seleciona 1 das 8 direções e converte <color=#00F6FF>todos os ladrilhos</color> naquela linha para Amarelo, priorizando a criação de <color=#00F6FF>3</color> <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link> na direção escolhida.",
  str_skill_desc_3062231 = "Seleciona 1 das 8 direções e converte <color=#00F6FF>todos os ladrilhos</color> naquela linha para Amarelo, priorizando a criação de <color=#00F6FF>5</color> <link=\"30093\"><#FFAE07><u>Ladrilhos Escuros</u></color></link> na direção escolhida.",
  str_skill_passive_desc_410223 = "Os ataques normais de Chen'ni visam o inimigo com a maior diferença de porcentagem de PV em relação à equipe, causando dano igual a <color=#00F6FF>{1}</color> do ATQ médio da equipe.",
  str_skill_passive_desc_420223 = "Os ataques normais de Chen'ni visam o inimigo com a maior diferença na porcentagem de HP em relação à equipe, causando dano igual a <color=#00F6FF>{1}</color> do ATQ médio da equipe. Aciona <color=#00F6FF>1.5×</color> de dano toda vez que passa por um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link>.",
  str_skill_passive_desc_430223 = "Os ataques normais de Chen'ni visam o inimigo com a maior diferença de porcentagem de HP em relação à equipe, causando dano igual a <color=#00F6FF>{1}</color> do ATQ médio da equipe. Aciona <color=#00F6FF>1.5×</color> de dano toda vez que passa por um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link>. Quanto maior a diferença de porcentagem de HP entre o alvo e a equipe, maior o dano, com um aumento máximo de <color=#00F6FF>50%</color>.",
  str_skill_name_70011211 = "Abandonado: Força Dominante",
  str_skill_name_70011212 = "Desamparado: Ondas Furiosas",
  str_skill_upgrade_desc_15022412 = "Muda a Habilidade Ativa para <color=#FFFF00>Ataque Preventivo</color>, disponível ao entrar em combate. Obtenha 10 Chamas do Guardião Fiendling no início da batalha.",
  str_skill_upgrade_desc_15022415 = "Aprimoramento de Habilidade de Equipamento: Ganha uma Chama Guardiã Fiendling sempre que passa por ladrilhos de qualquer elemento.",
