  str_skill_passive_name_415224 = "Empreendimento Conjunto",
  str_skill_desc_2002241 = "Lança Ah Ding, causando <color=#00F6FF>{1}%</color> de dano ao quadrado mais próximo do inimigo mais próximo.",
  str_skill_desc_2002242 = "Lança Ah Ding, causando <color=#00F6FF>{1}%</color> de dano ao bloco mais próximo do inimigo mais próximo e 30% de dano a <color=#00F6FF>4 casas ao redor em forma de cruz</color>.",
  str_skill_desc_2002243 = "Lança Ah Ding, causando <color=#00F6FF>{1}%</color> de dano ao ladrilho mais próximo do inimigo mais próximo e 30% de dano a <color=#00F6FF>1 aglomerado ao redor</color>.",
  str_skill_desc_300224 = "Seleciona uma casa para o Combo ser centrado e reduz a exigência de ativação do Combo em 3, aplicável apenas a esta rodada.",
  str_skill_desc_3002241 = "<color=#FFFF00>Após a conjuração, reduz a recarga da habilidade em 1</color>, e se nenhum Combo em Cadeia for desencadeado nesta rodada, ataques normais podem ser lançados na diagonal. Ganha 2 Chamas do Guardião Diabrete a cada ataque normal.",
  str_skill_desc_3002242 = "<color=#FFFF00>Após a conjuração, aumenta a recarga da habilidade em 1</color>. Seleciona um ladrilho para ser o centro do Chain Combo nesta rodada, e então causa <color=#00F6FF>100%</color> de dano. Cada Chama Guardiã Fiendling aumenta o dano em 10%. Reduz o requisito de ativação do Chain Combo em 3 para esta rodada e ganha um efeito de repulsão adicional.",
  str_skill_passive_desc_410224 = "Ganha 1 Chama do Guardião Diabrete para cada ladrilho Vermelho percorrido. Cada Chama aumenta o dano do próximo Combo em Cadeia em <color=#00F6FF>{1}</color>, que é reiniciado após o Combo em Cadeia ser liberado.",
  str_skill_passive_desc_412224 = "Ganha 1 Chama do Guardião Diabrete para cada ladrilho Vermelho percorrido. Cada Chama aumenta o dano do próximo Combo em Cadeia em <color=#00F6FF>{1}</color>, que é reiniciado após o Combo em Cadeia ser liberado. Obtenha 10 Chamas do Guardião Diabrete no início da batalha.",
  str_skill_passive_desc_415224 = "Ganha 1 Chama do Guardião Fiendling para cada ladrilho percorrido. Cada Chama aumenta o dano do próximo Combo em Cadeia em <color=#00F6FF>{1}</color>, que é reiniciado após o Combo em Cadeia ser liberado. Obtenha 10 Chamas do Guardião Fiendling no início da batalha.",
  str_skill_desc_9997040 = "Converte quaisquer 2 peças selecionadas em peças cromáticas, ganhando 1 energia para cada peça removida. Obtém 1 chance de uso após acumular 60 energias; até 2 chances podem ser armazenadas.",
  str_skill_desc_9997041 = "Seleciona uma área de 3x3 e remove todos os ladrilhos azuis dentro dela, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 50 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_9997042 = "Seleciona uma área de 3x3 e remove todos os ladrilhos vermelhos dentro dela, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 50 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_9997043 = "Seleciona uma área de 3x3 e remove todos os ladrilhos verdes dentro dela, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 50 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_9997044 = "Seleciona uma área de 3x3 e remove todos os ladrilhos amarelos dentro dela, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 50 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_9997045 = "Redefine todos os ladrilhos no campo, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 80 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_9997046 = "Seleciona 1 cor e redefine todas as peças desta cor no campo, ganhando 1 energia para cada peça removida. Obtém 1 chance de uso após acumular 80 energias; até 2 chances podem ser armazenadas.",
  str_skill_desc_9997047 = "Seleciona 1 ladrilho e remove os 4 ladrilhos mais próximos da mesma cor. Ganha 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 60 energias; até 3 chances podem ser armazenadas.",
  str_skill_name_5066101 = "Caleidojoia",
  str_skill_desc_5066101 = "Converte todos os ladrilhos no campo em ladrilhos cromáticos.",
  str_skill_name_5060801 = "Quebra-Muro",
  str_skill_desc_5060801 = "Consome 2 rodadas para lançar instantaneamente uma habilidade de suporte de facção Lv.2. Só pode ser usado uma vez a cada rodada.",
  str_skill_name_20047011 = "Ataque de Transporte",
  str_skill_desc_20047011 = "Após se mover, ataca um alvo em 4 ladrilhos ao redor em forma de cruz, depois passa pelo alvo para um ladrilho ao redor, priorizando o ladrilho diretamente atrás do alvo.",
  str_skill_name_5412015 = "Invocação: Carniceiro",
  str_skill_desc_5412015 = "Invoca Gloom Ghouls para a batalha a cada rodada.",
  str_skill_name_9997040 = "Espada do Esplendor",
  str_skill_name_9997046 = "Escudo de Esplendor",
  str_skill_name_9997047 = "Lança do Esplendor",
  str_skill_desc_5064701 = "Seleciona uma área de 5x5 e remove todos os ladrilhos Azuis dentro dela, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 40 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_5064702 = "Seleciona uma área de 5x5 e remove todos os ladrilhos Vermelhos dentro dela, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 40 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_5064703 = "Seleciona uma área de 5x5 e remove todas as casas Verdes dentro dela, ganhando 1 energia para cada casa removida. Obtém 1 chance de uso após acumular 40 energias; até 3 chances podem ser armazenadas.",
  str_skill_desc_5064704 = "Seleciona uma área de 5x5 e remove todos os ladrilhos Amarelos dentro dela, ganhando 1 energia para cada ladrilho removido. Obtém 1 chance de uso após acumular 40 energias; até 3 chances podem ser armazenadas.",
  str_skill_name_5411002 = "Dança do Dragão Abençoada",
  str_skill_desc_5411002 = "Causa dano a 24 peças em forma de diamante.",
  str_skill_name_5411003 = "Invocação: Diabrete",
  str_skill_desc_5411003 = "Invoca 2 Fiendling: Ratos para o campo de batalha.",
  str_skill_desc_5411012 = "Nozard reúne forças para a iminente Maré Crescente, convocando vários Gloom Ghouls à sua frente.",
  str_skill_desc_5411020 = "Gertzurde invoca 4 Servos de Gertzurde imóveis aleatoriamente no campo.",
  str_skill_desc_5411021 = "Gertzurde ataca alvos dentro da área de efeito e aplica 1 Marca de Penetrabilidade. Quanto mais marcas houver, menor será a DEF do alvo. Também convoca 2 Servos de Gertzurde.",
  str_skill_desc_5411022 = "Gertzurde ruge e aplica 2 Marcas de Penetrabilidade aos alvos dentro da área de efeito. Quanto mais marcas houver, menor será a DEF do alvo. Também convoca 2 Servos de Gertzurde.",
  str_skill_desc_5411023 = "Gertzurde detona as Marcas de Penetrabilidade nos alvos para causar um dano massivo. Quanto mais marcas um alvo tem, mais dano ele recebe. Também convoca 2 Servos de Gertzurde.",
  str_skill_desc_5411025 = "Gertzurde invoca 4 Servos de Gertzurde imóveis aleatoriamente no campo.",
  str_skill_desc_5411026 = "Gertzurde ataca freneticamente os alvos dentro da área de efeito 2 vezes e aplica 2 Marcas de Penetrabilidade. Quanto mais marcas houver, menor será a DEF do alvo. Também convoca 2 Servos de Gertzurde.",
  str_skill_desc_5411027 = "Gertzurde solta seu rugido final e aplica 3 Marcas de Penetrabilidade aos alvos dentro da área de efeito. Quanto mais marcas houver, menor será a DEF do alvo. Também convoca 2 Servos de Gertzurde.",
  str_skill_desc_5411004 = "Invoca uma Armadilha de Gaiola.",
  str_skill_name_5411031 = "Ligar",
  str_skill_desc_5411031 = "A linha entre a realidade e a fantasia se confunde neste reino ilusório...",
  str_skill_name_5064701 = "Gelador Voante",
  str_skill_name_5064702 = "Abrasador Voante",
  str_skill_name_5064703 = "Florestalma Voante",
  str_skill_name_5064704 = "Trovão Voante",
  str_skill_name_5065501 = "Armadilha de Aumento de Dano",
  str_skill_name_5065601 = "Jarra de Doces Energéticos",
  str_skill_name_5065801 = "Energizador Móvel",
  str_skill_desc_5065501 = "Após a remoção, o dano do Chain Combo aumenta em 35% nesta rodada.",
  str_skill_desc_5065601 = "Após a remoção, concede 1 chance de uso para um Equipamento Caelestite Especial aleatório.",
  str_skill_desc_5065801 = "Após a remoção, concede 3 rodadas extras.",
  str_skill_name_29093013 = "Passada de Ano Novo",
  str_skill_desc_29093013 = "Nian salta para frente 3 casas, causando dano a 1 aglomerado ao redor da casa de aterrissagem e repelindo os inimigos dentro do alcance para ambos os lados. Se Nian chegar ao portão, o portão será destruído, permitindo que Nian entre.",
  str_skill_name_7001125103 = "Abandonado: Uivo Irritado",
  str_skill_desc_7001125103 = "Forsaken: Cerritus causa dano a todos os Aurorianos no campo, aumenta seu próprio ACT e convoca seixos.",
  str_skill_name_7001125104 = "Forsaken: Esmagamento Destruidor",
  str_skill_desc_7001125104 = "Abandonado: Cerritus gera ladrilhos enfraquecidos e ataca os aurorianos, derrubando-os e destruindo seixos em seu caminho.",
  str_skill_name_7001125105 = "Forsaken: Terremoto Devastador",
  str_skill_desc_7001125105 = "Abandonado: Cerritus ataca os 2 ladrilhos à sua frente depois de se mover, causando dano massivo e gerando ladrilhos enfraquecidos.",
  str_skill_name_7001126103 = "Abandonado: Liberar Negatividade",
  str_skill_desc_7001126103 = "Forsaken: Chandra se afasta dos Aurorianos e então causa dano aos Aurorianos dentro de 2 aglomerados ao redor.",
  str_skill_name_7001126104 = "Abandonado: Projeto Emoção Negativa",
  str_skill_desc_7001126104 = "Forsaken: Chandra causa dano a todos os Aurorianos no campo.",
  str_skill_name_80150311 = "Rocha",
  str_skill_desc_80150311 = "A Rocha obstruiu o caminho aqui por tempo suficiente. Consuma 2 Pontos de Força para removê-la.",
  str_skill_name_290940103 = "Lança Sombra de Fogo",
  str_skill_desc_290940103 = "Ira causa dano aos Aurorianos e gera Shadowfire nas peças mais externas do campo até o alcance máximo na área em forma de cruz centrada nos Aurorianos.",
  str_skill_name_290940104 = "Explosão Ardente",
  str_skill_desc_290940104 = "Ira causa dano aos Aurorianos dentro de 2 aglomerados ao redor dele mesmo.",
  str_skill_name_290940105 = "Meteoro Irado",
  str_skill_desc_290940105 = "Ira convoca meteoritos para atingir a posição onde os Aurorianos estavam na rodada anterior, causando dano letal e destruindo o ladrilho, deixando para trás 4 ladrilhos quebrados em forma de cruz.",
  str_skill_name_200480103 = "Sombra de Fogo do Inferno",
  str_skill_desc_200480103 = "Shadowfire causa dano aos Aurorianos dentro do alcance e se teleporta para o lado oposto do campo. Se não puder atacar os jogadores, ele se teleporta no sentido horário ao longo do aglomerado mais externo do campo, movendo 2 blocos.",
  str_skill_name_300226 = "É um Mundo de Sapo",
  str_skill_name_200226 = "Todos saúdam o Sapo",
  str_skill_passive_name_400226 = "Uma Sinfonia Ribbitante",
  str_skill_desc_300226 = "Dentro dos sonhos, o Príncipe Lilypad tem o poder de acalmar vulcões em erupção e reparar fendas negras no céu. No mundo real, ele aspira a curar companheiros com sua ternura... O que ele realmente faz, você pergunta? Enche você de fofura!",
  str_skill_desc_200226 = "O coaxar resoluto do Príncipe Lilypad ecoa por toda Astra! O que ele realmente faz, você pergunta? Enche você de fofura!",
  str_skill_passive_desc_400226 = "O coaxar de um sapo é o batimento cardíaco da natureza, o sopro de Astra, um feixe de luz na escuridão infinita. Você consegue ouvi-lo? Ele está convidando todos para se juntarem a esta grande celebração cantando um hino juntos! O que isso realmente faz, você pergunta? Faz com que todos coaxem, é claro!",
  str_skill_name_54350081 = "Guardião do Atirador de Salva",
  str_skill_desc_54350081 = "É dever de uma arma de salva proteger o rei! Eles deixarão o campo de batalha após o Combo dos Aurorianos.",
  str_skill_upgrade_desc_16022513 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate. Inflige 1 ponto fraco extra aos inimigos dentro do alcance.",
  str_skill_upgrade_desc_16022516 = "Aprimoramento de habilidade de equipamento: Ao passar por um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link>, há uma chance de 50% de infligir 1 ponto fraco extra.",
  str_skill_name_2002251 = "Céus Despedaçados",
  str_skill_name_2002252 = "Céus Despedaçados",
  str_skill_name_2002253 = "Céus Despedaçados",
