  str_skill_name_340225 = "Acrimônia Gelada",
  str_skill_name_343225 = "Acrimônia Gelada",
  str_skill_passive_name_410225 = "Trovão & Céu, Como Um Só",
  str_skill_passive_name_430225 = "Trovão & Céu, Como Um Só",
  str_skill_passive_name_416225 = "Trovão & Céu, Como Um Só",
  str_skill_passive_name_436225 = "Trovão & Céu, Como Um Só",
  str_skill_passive_name_440225 = "Trovão & Céu, Como Um Só",
  str_skill_passive_name_446225 = "Trovão & Céu, Como Um Só",
  str_skill_passive_name_4402253 = "Trovão & Céu, Como Um Só",
  str_skill_passive_name_4462253 = "Trovão & Céu, Como Um Só",
  str_skill_desc_2002251 = "Causa <color=#00F6FF>{1}%</color> de dano em uma coluna ao longo do caminho em direção ao inimigo mais próximo.",
  str_skill_desc_2002252 = "Causa <color=#00F6FF>{1}%</color> de dano em uma coluna e nos azulejos adjacentes ao longo do caminho em direção ao inimigo mais próximo.",
  str_skill_desc_2002253 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy.",
  str_skill_desc_2102251 = "Causa <color=#00F6FF>{1}%</color> de dano em uma coluna ao longo do caminho em direção ao inimigo mais próximo. Também quebra 1 ponto fraco nessa direção.",
  str_skill_desc_2102252 = "Causa <color=#00F6FF>{1}%</color> de dano em uma coluna e nos blocos adjacentes ao longo do caminho em direção ao inimigo mais próximo. Também quebra 1 ponto fraco nessa direção.",
  str_skill_desc_2102253 = "Causa <color=#00F6FF>{1}%</color> de dano em uma coluna e nos blocos adjacentes ao longo do caminho em direção ao inimigo mais próximo. Também quebra até 2 pontos fracos nessa direção.",
  str_skill_desc_2302251 = "Deals <color=#00F6FF>{1}%</color> damage in a column along the path towards the nearest enemy. Also breaks 1 weak spot in that direction.",
  str_skill_desc_2302252 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy. Also breaks 1 weak spot in that direction.",
  str_skill_desc_2302253 = "Deals <color=#00F6FF>{1}%</color> damage in a column and to adjacent tiles along the path towards the nearest enemy. Also breaks up to 2 weak spots in that direction.",
  str_skill_desc_300225 = "Mira em 1 casa e causa <color=#00F6FF>{1}%</color> de dano em forma de cone nessa direção.",
  str_skill_desc_303225 = "Targets 1 tile and deals <color=#00F6FF>{1}%</color> damage in a cone shape in that direction.",
  str_skill_desc_320225 = "Mira em 1 casa e causa <color=#00F6FF>{1}%</color> de dano em forma de cone nessa direção. Também inflige 1 ponto fraco em todos os inimigos dentro do alcance do ataque.",
  str_skill_desc_323225 = "Mira em 1 casa e causa <color=#00F6FF>{1}%</color> de dano em forma de cone nessa direção. Também inflige 2 pontos fracos em todos os inimigos dentro do alcance do ataque.",
  str_skill_desc_340225 = "Mira 1 casa e causa <color=#00F6FF>250%</color> de dano em forma de cone nessa direção. Também inflige 1 ponto fraco em todos os inimigos dentro do alcance do ataque.",
  str_skill_desc_343225 = "Mira 1 ladrilho e causa <color=#00F6FF>250%</color> de dano em forma de cone nessa direção. Também inflige 2 pontos fracos em todos os inimigos dentro do alcance do ataque.",
  str_skill_passive_desc_410225 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link>, Tiare infligirá 1 ponto fraco no inimigo com o maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo em Cadeia de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>{1}</color> de dano. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, uma metade adicional do dano de quebra será infligida.",
  str_skill_passive_desc_416225 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link>, Tiare irá infligir 1 ponto fraco (com 50% de chance para 1 ponto fraco extra) no inimigo com o maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo em Cadeia de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>{1}</color> de dano. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, uma metade adicional do dano de quebra será infligida.",
  str_skill_passive_desc_430225 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link>, Tiare irá infligir 1 ponto fraco no inimigo com maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo de Corrente de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>Dano de Respingo</u></color></link> e <color=#00F6FF>{2}</color> de dano ao alcance do respingo. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, uma metade adicional do dano de quebra será infligida.",
  str_skill_passive_desc_436225 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link>, Tiare infligirá 1 ponto fraco (com 50% de chance de 1 ponto fraco extra) no inimigo com maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo de Corrente de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>{1}</color> <link=\"30015\"><#FFAE07><u>Dano em Área</u></color></link> e <color=#00F6FF>{2}</color> de dano ao alcance do dano em área. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, uma metade adicional do dano de quebra será infligida.",
  str_skill_passive_desc_440225 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link>, Tiare irá infligir 1 ponto fraco no inimigo com maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo de Corrente de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>230%</color> de <link=\"30015\"><#FFAE07><u>Dano em Área</u></color></link> e <color=#00F6FF>100%</color> de dano no alcance do dano em área. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, uma metade adicional do dano de quebra será infligida.",
  str_skill_passive_desc_446225 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link>, Tiare irá infligir 1 ponto fraco (com 50% de chance de 1 ponto fraco extra) no inimigo com maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo de Corrente de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>230%</color> de <link=\"30015\"><#FFAE07><u>Dano em Área</u></color></link> e <color=#00F6FF>100%</color> de dano no alcance do dano em área. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, uma metade adicional do dano de quebra será infligida.",
  str_skill_passive_desc_4402253 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link> ou entrar na Hora da Aurora, Tiare irá infligir 1 ponto fraco no inimigo com o maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo em Cadeia de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>230%</color> de <link=\"30015\"><#FFAE07><u>Dano em Área</u></color></link> e <color=#00F6FF>100%</color> de dano na área de impacto. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, uma metade adicional do dano de quebra será infligida.",
  str_skill_passive_desc_4462253 = "Ao passar por <link=\"30093\"><#FFAE07><u>Peças Escuras</u></color></link> ou entrar na Hora da Aurora, Tiare irá infligir 1 ponto fraco (com 50% de chance para 1 ponto fraco extra) no inimigo com o maior HP no campo na direção mais próxima dela. Sempre que o Ataque Normal ou Combo em Cadeia de Tiare atingir nessa direção, os pontos fracos serão quebrados, resultando em <color=#00F6FF>230%</color> <link=\"30015\"><#FFAE07><u>Dano Splash</u></color></link> e <color=#00F6FF>100%</color> de dano ao alcance do splash. Quando um inimigo morre, seu ponto fraco é transferido para o inimigo mais próximo. Quando um inimigo está cercado por pontos fracos, um adicional de metade do dano de quebra será infligido.",
  str_skill_upgrade_refine_desc_16022511 = "Aprimoramento de Habilidade de Equipamento: Aumenta o dano causado ao quebrar pontos fracos em <color=#00F6FF>230%</color>.",
  str_skill_upgrade_refine_desc_16022512 = "Aprimoramento de habilidade ativa: aumenta o fator de dano da habilidade em <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16022513 = "Aprimoramento de Habilidade de Equipamento: Ao entrar na Hora da Aurora, inflige 1 ponto fraco no inimigo com o maior PV na direção mais próxima.",
  str_skill_desc_70011272 = "A energia do Caracalune transborda, causando dano a 4 colunas e linhas.",
  str_skill_desc_70011273 = "O Caracalune torna-se um Plenalune, causando dano a alvos dentro da área de ataque e movendo para o outro lado do campo. Após mover, bloqueia casas dentro de 1 círculo ao redor. Casas bloqueadas não podem ser convertidas.",
  str_skill_name_290501142 = "Desamparado: Presa",
  str_skill_name_290501143 = "Desamparado: Caçar",
  str_skill_name_290501144 = "Abandonado: Rally",
  str_skill_desc_290501142 = "A Rainha Aranha Queen desce sobre sua presa, lança uma teia para bloquear os ladrilhos e danifica os aurorianos. As peças bloqueadas retornam ao seu estado original após 1 rodada.",
  str_skill_desc_290501143 = "Rainha Aranha tece uma teia para prender os ladrilhos ao redor dos aurorianos, então convoca seus filhotes para atacá-los e causar dano. As peças bloqueadas retornam ao seu estado original após 1 rodada.",
  str_skill_desc_290501144 = "A Rainha Aranha convoca seus filhotes para atacar. Eles vão tecer teias de aranha, bloqueando um grande número de peças. As peças bloqueadas retornam ao seu estado original após 1 rodada.",
  str_skill_desc_9011062 = "-1 rodadas de habilidade para o Auroriano com o maior tempo de espera atual.",
  str_skill_name_290420209 = "Foice",
  str_skill_desc_290420209 = "O Fantasma Dreamwalker se move e causa dano aos alvos à frente.",
  str_skill_desc_510233 = "-2 para todas as Rodadas de Habil. dos Aur. Lançados",
  str_skill_desc_520233 = "Encerra a recarga de habilidade para um Aurorian aleatório.",
  str_skill_desc_530233 = "Encerra o tempo de espera da habilidade para todos os Aurorianos implantados.",
  str_skill_desc_292600105 = "A Eve em luto ganha um número substancial de pilhas de Fluxo Escuro, obtendo o efeito de Assalto com base no número de pilhas. Cada vez que ela é atacada, as pilhas de Fluxo Escuro diminuem.",
  str_skill_desc_292600106 = "O luto Eve trava no alvo e causa dano.",
  str_skill_desc_20060012 = "Concede um bônus de DEF para Grieving Eve.",
  str_skill_name_200490101 = "Neblina",
  str_skill_desc_200490101 = "Haze se move em direção aos Aurorians.",
  str_skill_name_290950105 = "Granizo da Praga",
  str_skill_name_290950106 = "Tempestade de Praga",
  str_skill_name_290950107 = "Granizo da Praga",
  str_skill_name_290950108 = "Tempestade de Praga",
  str_skill_name_290950109 = "Esmagamento Devastador",
  str_skill_desc_290950105 = "Cenoura: A Praga causa múltiplas instâncias de dano aos Aurorianos. Quanto menor o HP dos Aurorianos, maior será o dano causado.",
  str_skill_desc_290950106 = "Cenoura: Blight gira em alta velocidade, causando múltiplos danos aos alvos ao seu redor. Toda vez que causa dano, há uma chance de repelir os Aurorianos em 1 ladrilho na direção anti-horária ou para fora. Cada acerto bem-sucedido reduz o dano do próximo golpe.",
  str_skill_desc_290950107 = "Cenoura: A Praga causa múltiplas instâncias de dano aos Aurorianos. Quanto menor o HP dos Aurorianos, maior será o dano causado.",
  str_skill_desc_290950108 = "Se os Aurorianos não estiverem dentro do alcance de Blight Crush, Carrot: Blight gira em alta velocidade, causando múltiplos danos aos alvos ao seu redor. Toda vez que causa dano, há uma chance de repelir os Aurorianos em 1 ladrilho na direção anti-horária ou para fora. Cada acerto bem-sucedido reduz o dano do próximo golpe.",
  str_skill_desc_290950109 = "Se os Aurorianos estiverem dentro do alcance de Blight Crush, Carrot: Blight os esmaga com uma cenoura gigante, causando dano a eles e os repelindo por 2 ladrilhos.",
  str_skill_name_80060401 = "Espigas de Contradição",
  str_skill_desc_80060401 = "Causa dano considerável ao final de cada rodada a qualquer monstro preso nos espinhos e inflige 1 acúmulo de Sangramento. Esses espinhos parecem familiares, mas não vão te machucar desta vez.",
  str_skill_name_80060501 = "Evocar Slasher",
  str_skill_name_80060502 = "Invocar Sonda",
  str_skill_name_80060503 = "Invocar: Siforbe",
  str_skill_desc_80060501 = "Convoca um Cortador para o campo de batalha!",
  str_skill_desc_80060502 = "Invoca uma Sonda para o campo de batalha!",
  str_skill_desc_80060503 = "Convoca um Siforbe para o campo de batalha!",
  str_skill_desc_800637101 = "Libera tiros precisos, furtivos e habilidosos que causam dano em forma de cruz ao alcance máximo.",
  str_skill_desc_800638101 = "Causa dano ao seu alvo duas vezes após usar sua incrível agilidade para se distanciar do inimigo.",
  str_skill_desc_80062201 = "Recuperação de Ponto de Força da equipe por rodada +1.",
