  str_skill_name_2202272 = "Eagleeye Lock-On",
  str_skill_name_2202273 = "Eagleeye Lock-On",
  str_skill_name_3002271 = "Reconhecimento Mortal",
  str_skill_name_3032271 = "Death Recon",
  str_skill_name_3002272 = "Reconhecimento Mortal: Exausto",
  str_skill_name_3032272 = "Death Recon: Exhausted",
  str_skill_name_3062272 = "Death Recon: Exhausted",
  str_skill_name_3062271 = "Death Recon",
  str_skill_desc_2002271 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2002272 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2002273 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_20022712 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos. Isso pode ser lançado enquanto estiver Esgotado, mas infligirá 1 pilha de Garra de Águia em vez de causar dano.",
  str_skill_desc_20022722 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos. Isso pode ser lançado enquanto estiver Exausto, mas infligirá 2 pilhas de Garra de Águia em vez de causar dano.",
  str_skill_desc_20022732 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos. Isso pode ser lançado enquanto Exausto, mas infligirá 3 pilhas de Garra de Águia em vez de causar dano.",
  str_skill_desc_2202271 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos. Isso pode ser lançado enquanto estiver Esgotado, mas infligirá 1 pilha de Garra de Águia em vez de causar dano.",
  str_skill_desc_2202272 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos. Isso pode ser lançado enquanto estiver Exausto, mas infligirá 2 pilhas de Garra de Águia em vez de causar dano.",
  str_skill_desc_2202273 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos. Isso pode ser lançado enquanto Exausto, mas infligirá 3 pilhas de Garra de Águia em vez de causar dano.",
  str_skill_desc_3002271 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera uma Casa Escura em <color=#00F6FF>1</color> dessas casas aleatoriamente.\nA Habil. Ativa pode ser lançada novamente antes de estar pronta. Após o lançamento, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. Exausta é removido quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3032271 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera uma Casa Escura em <color=#00F6FF>1</color> dessas casas aleatoriamente.\nA Habil. Ativa pode ser lançada novamente antes de estar pronta. Aumenta a contagem de casas convertidas em <color=#00F6FF>2</color> e gera <color=#00F6FF>1</color> Casa Escura adicional. Após o lançamento, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. Exausta é removido quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3062271 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera Casas Escuras em <color=#00F6FF>2</color> dessas casas aleatoriamente.\nA Habil. Ativa pode ser lançada novamente antes de estar pronta. Aumenta a contagem de conversão de casas em <color=#00F6FF>2</color> e gera <color=#00F6FF>1</color> Casa Escura adicional. Após o lançamento, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. Exausta é removida quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3002272 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera uma Casa Escura em <color=#00F6FF>1</color> dessas casas aleatoriamente.\nApós a conjuração, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. Exausto é removido quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3032272 = "Converte as <color=#00F6FF>5</color> casas não-Amarelas mais próximas em Amarelas, e gera Casas Escuras em <color=#00F6FF>2</color> dessas casas aleatoriamente.\nApós a conjuração, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Esgotada</color>, o que a impede de realizar Ataques Normais ou Combos em Cadeia. O Esgotamento é removido quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3062272 = "Converte as <color=#00F6FF>5</color> casas não-Amarelas mais próximas em Amarelas, e gera Casas Escuras em <color=#00F6FF>3</color> dessas casas aleatoriamente.\nApós a conjuração, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Esgotada</color>, o que a impede de realizar Ataques Normais ou Combos em Cadeia. O estado de Esgotada é removido quando a Habil. Ativa está pronta novamente.",
  str_skill_passive_name_410227 = "Formação Holográfica",
  str_skill_passive_name_420227 = "Holographic Formation",
  str_skill_passive_name_430227 = "Holographic Formation",
  str_skill_passive_desc_410227 = "Inflige <color=#00F6FF>3</color> pilhas de Garra de Águia no alvo mais próximo ao passar por um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link>. No início do turno do inimigo, causa dano igual a <color=#00F6FF>{1}</color> do ATK atual de Rachel uma vez para cada pilha de Garra de Águia. O número de pilhas é reduzido pela metade quando a rodada termina. Se o alvo for morto, metade das pilhas de Garra de Águia será transferida para o inimigo mais próximo.",
  str_skill_passive_desc_420227 = "Inflicts <color=#00F6FF>3</color> Eagle Talon stacks on the nearest target when passing through a <link=\"30093\"><#FFAE07><u>Dark Tile</u></color></link>. At the start of the enemy's round, deals damage equal to <color=#00F6FF>{1}</color> of Rachel's current ATK once for each Eagle Talon stack. The number of stacks is halved when the round ends. If the target is killed, half the Eagle Talon stacks will transfer to the nearest enemy.",
  str_skill_passive_desc_430227 = "Inflige <color=#00F6FF>3</color> pilhas de Garra de Águia no alvo mais próximo ao passar por um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link>. No início do turno do inimigo, causa dano igual a <color=#00F6FF>{1}</color> do ATK atual de Rachel uma vez para cada pilha de Garra de Águia. O número de pilhas é reduzido pela metade quando a rodada termina. Se o alvo for morto, metade das pilhas de Garra de Águia será transferida para o inimigo mais próximo. Se Rachel estiver <color=#00F6FF>Exausta</color>, seu ATK aumenta em <color=#00F6FF>3%</color> para cada ladrilho percorrido em uma conexão.",
  str_skill_passive_desc_440227 = "Inflige <color=#00F6FF>3</color> pilhas de Garra de Águia no alvo mais próximo ao passar por um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link>. No início do turno do inimigo, causa dano igual a <color=#00F6FF>80%</color> do ATK atual de Rachel uma vez para cada pilha de Garra de Águia. O número de pilhas é reduzido pela metade quando a rodada termina. Se o alvo for morto, metade das pilhas de Garra de Águia será transferida para o inimigo mais próximo. Se Rachel estiver <color=#00F6FF>Exausta</color>, seu ATK aumenta em <color=#00F6FF>3%</color> para cada ladrilho percorrido em uma conexão.",
  str_skill_passive_desc_460227 = "Inflige <color=#00F6FF>3</color> pilhas de Garra de Águia no alvo mais próximo ao passar por um <link=\"30093\"><#FFAE07><u>Ladrilho Escuro</u></color></link>. No início do turno do inimigo, causa dano igual a <color=#00F6FF>80%</color> do ATK atual de Rachel uma vez para cada pilha de Garra de Águia. O número de pilhas é reduzido pela metade quando a rodada termina. Se o alvo for morto, metade das pilhas de Garra de Águia será transferida para o inimigo mais próximo. Se Rachel estiver <color=#00F6FF>Exausta</color>, seu ATK aumenta em <color=#00F6FF>4%</color> para cada ladrilho percorrido em uma conexão.",
  str_skill_desc_3502271 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera uma Casa Escura em <color=#00F6FF>1</color> dessas casas aleatoriamente, então inflige <color=#00F6FF>2</color> pilhas de Garra de Águia no alvo mais próximo.\nA Habil. Ativa pode ser lançada novamente antes de estar pronta. Após o lançamento, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. Exausta é removida quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3532271 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera uma Casa Escura em <color=#00F6FF>1</color> dessas casas aleatoriamente, então inflige <color=#00F6FF>2</color> pilhas de Garra de Águia no alvo mais próximo.\nA Habil. Ativa pode ser lançada novamente antes de estar pronta. Aumenta a contagem de casas convertidas em <color=#00F6FF>2</color> e gera <color=#00F6FF>1</color> Casa Escura adicional. Após o lançamento, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. A exaustão é removida quando a Habilidade Ativa está pronta novamente.",
  str_skill_desc_3562271 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera Casas Escuras em <color=#00F6FF>2</color> dessas casas aleatoriamente, então inflige <color=#00F6FF>2</color> pilhas de Garra de Águia no alvo mais próximo.\nA Habil. Ativa pode ser lançada novamente antes de estar pronta. Aumenta a contagem de casas convertidas em <color=#00F6FF>2</color> e gera <color=#00F6FF>1</color> Casa Escura adicional. Após o lançamento, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. A exaustão é removida quando a Habilidade Ativa está pronta novamente.",
  str_skill_desc_3502272 = "Converte as <color=#00F6FF>3</color> casas não-Amarelas mais próximas em Amarelas, e gera uma Casa Escura em <color=#00F6FF>1</color> dessas casas aleatoriamente, depois inflige <color=#00F6FF>2</color> pilhas de Garra de Águia no alvo mais próximo.\nApós a conjuração, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. Exausto é removido quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3532272 = "Converte as <color=#00F6FF>5</color> casas não-Amarelas mais próximas em Amarelas, e gera Casas Escuras em <color=#00F6FF>2</color> dessas casas aleatoriamente, em seguida, inflige <color=#00F6FF>2</color> pilhas de Garra de Águia no alvo mais próximo.\nApós a conjuração, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos de Corrente. Exausto é removido quando a Habil. Ativa está pronta novamente.",
  str_skill_desc_3562272 = "Converte as <color=#00F6FF>5</color> casas não-Amarelas mais próximas em Amarelas, e gera Casas Escuras em <color=#00F6FF>3</color> dessas casas aleatoriamente, depois inflige <color=#00F6FF>2</color> pilhas de Garra de Águia no alvo mais próximo.\nApós a conjuração, o tempo de recarga da Habil. Ativa aumenta em 1 rodada, e Rachel se torna <color=#00F6FF>Exausta</color>, o que a impede de lançar Ataques Normais ou Combos em Cadeia. Exausta é removida quando a Habil. Ativa está pronta novamente.",
  str_skill_upgrade_desc_16022713 = "Melhoria de Habilidade Ativa: A Habilidade Ativa pode ser lançada novamente antes de estar pronta. Aumenta as casas convertidas em <color=#FFFF00>2</color> e gera <color=#FFFF00>1</color> Casa Escura adicional.",
  str_skill_upgrade_desc_16022716 = "Melhoria de Habilidade Ativa: Aumenta a contagem de geração de Casas Escuras em <color=#FFFF00>1</color>.",
  str_skill_upgrade_refine_desc_16022711 = "Aprimoramento de Habilidade de Equipamento: No início da rodada do inimigo, causa dano igual a <color=#00F6FF>80%</color> do ATK atual de Rachel uma vez para cada pilha de Garra de Águia.",
  str_skill_upgrade_refine_desc_16022712 = "Aprimoramento de Habilidade Ativa: Após a conjuração, inflige <color=#00F6FF>2</color> pilhas de Garra de Águia no alvo mais próximo.",
  str_skill_upgrade_refine_desc_16022713 = "Aprimoramento de habilidade de equipamento: Se Rachel estiver Esgotado, seu ATK aumenta em <color=#00F6FF>4%</color> para cada ladrilho percorrido em uma conexão.",
  str_skill_upgrade_desc_15022812 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.\nO Segredo Razzle Dazzle <color=#FFFF00>Ataque Preventivo</color> é válido para Ascensão I.",
  str_skill_upgrade_desc_15022815 = "Melhoria de Habilidade Ativa do Blitz Variado: Aumenta o número de casas que você pode selecionar em <color=#FFFF00>1</color>.",
  str_skill_desc_10071120 = "Lança um raio impactante em direção ao local do alvo na última rodada, causando dano aos alvos no caminho do raio e no local do alvo.",
  str_skill_desc_10071130 = "Empurra alvos ao alcance para o meio do campo de batalha.",
  str_skill_name_54550920 = "Tentaclaw - Prevenção de Danos",
  str_skill_desc_54550920 = "Quando um Auroriano desencadeia um combo em cadeia, Tentaclaw enrola seus tentáculos para evitar ataques e absorve o Ladrilho Aprimorado em sua localização.",
  str_skill_name_29097013 = "Ataque Normal",
  str_skill_desc_29097013 = "Causa dano aos aurorianos à sua frente após o movimento.",
  str_skill_name_29097014 = "Corrida de Lava",
  str_skill_desc_29097014 = "Causa dano a uma grande área em forma de leque na direção dos aurorianos e gera Seixos.",
  str_skill_name_29097015 = "Urro Abrasador",
  str_skill_desc_29097015 = "Causa dano em tela cheia 3 vezes, empurrando os alvos para trás em 1 quadrado a cada golpe. O alvo sofre ainda mais dano se não puder ser empurrado para trás.",
  str_skill_name_2002281 = "Doce Emboscada",
  str_skill_name_2002282 = "Doce Emboscada",
  str_skill_name_2002283 = "Doce Emboscada",
  str_skill_desc_2002281 = "Zeta libera Conan, que procura o inimigo mais próximo dentro de 12 peças em forma de diamante. Ele explode ao atingir o alvo, causando <color=#00F6FF>150%</color> de dano a 5 ladrilhos em forma de cruz.",
  str_skill_desc_2002282 = "Zeta libera Conan, que procura o inimigo mais próximo dentro de 24 peças em forma de diamante. Ele explode ao atingir o alvo, causando <color=#00F6FF>160%</color> de dano a 5 ladrilhos em forma de cruz.",
  str_skill_desc_2002283 = "Zeta libera Conan, que procura pelo inimigo mais próximo dentro de 24 peças em forma de diamante. Ele explode ao alcançar o alvo, causando <color=#00F6FF>160%</color> de dano a 5 peças em forma de cruz.\nQuando Zeta lança sua Combinação de Corrente de nível 3, o alcance do dano de Conan, invocado por sua Habilidade Ativa Secreta Razzle Dazzle, é expandido para 1 aglomerado circundante.",
  str_skill_name_3002281 = "Blitz Variado",
  str_skill_name_3052281 = "Blitz Variado",
  str_skill_name_3102281 = "Blitz Variado",
  str_skill_name_3152281 = "Blitz Variado",
  str_skill_desc_3002281 = "Seleciona quaisquer 3 ladrilhos, em seguida, redefine suas cores e os purifica. Os ladrilhos Azuis serão mantidos ao redefinir os ladrilhos.",
  str_skill_desc_3052281 = "Seleciona quaisquer 4 ladrilhos, em seguida, redefine suas cores e os purifica. Os ladrilhos Azuis serão mantidos ao redefinir os ladrilhos.",
  str_skill_desc_3102281 = "Seleciona quaisquer 3 casas, registra suas cores no <link=\"30100\"><#FFAE07><u>Quadro de Cores</u></color></link>, depois redefine suas cores e as purifica. As casas Azuis serão mantidas ao redefinir as casas.",
  str_skill_desc_3152281 = "Seleciona qualquer 4 casas, registra suas cores no <link=\"30100\"><#FFAE07><u>Quadro de Cores</u></color></link>, depois reinicia suas cores e as purifica. As casas Azuis serão mantidas ao reiniciar as casas.",
  str_skill_name_3002282 = "Segredo Deslumbrante",
  str_skill_desc_3002282 = "Usa todas as cores no <link=\"30100\"><#FFAE07><u>Tabuleiro de Cores</u></color></link> preenchido para invocar Conan em 1 ladrilho atravessável. Quando Zeta lança sua Combinação em Cadeia pela primeira vez nesta rodada, Conan também procurará inimigos e os atacará.",
  str_skill_passive_name_410228 = "Rainbow Dinamite",
  str_skill_passive_name_420228 = "Rainbow Dinamite",
  str_skill_passive_name_430228 = "Rainbow Dinamite",
  str_skill_passive_desc_410228 = "Zeta ganha a Habilidade Ativa Secreta Razzle Dazzle e o <link=\"30100\"><#FFAE07><u>Tabuleiro de Cores</u></color></link>. Conan, que é convocado pelo Razzle Dazzle Secreto, vai <color=#00F6FF>procurar inimigos ao seu redor e atacá-los</color> quando Zeta lança seu Chain Combo. Seu raio de busca é o <color=#00F6FF>mesmo</color> que o alcance do Chain Combo lançado por Zeta, e ele causa dano igual a <color=#00F6FF>{1}</color> do dano causado pelo Chain Combo de Zeta.",
  str_skill_passive_desc_420228 = "Zeta ganha a Habilidade Ativa Secreta Razzle Dazzle e o <link=\"30100\"><#FFAE07><u>Tabuleiro de Cores</u></color></link>. Conan, que é convocado pelo Razzle Dazzle Secreto, vai <color=#00F6FF>procurar inimigos ao seu redor e atacá-los</color> quando Zeta lança seu Combo de Cadeia. Seu raio de busca é o <color=#00F6FF>mesmo</color> que o alcance do Combo de Cadeia lançado por Zeta, e ele causa dano igual a <color=#00F6FF>{1}</color> do dano causado pelo Combo de Cadeia de Zeta. Quando Zeta lança seu Combo de Cadeia de nível 3, o alcance de dano de Conan se expande <color=#00F6FF>1 aglomerado circundante</color>.",
  str_skill_passive_desc_430228 = "Zeta ganha a Habilidade Ativa Secret Razzle Dazzle e o <link=\"30100\"><#FFAE07><u>Tabuleiro de Cores</u></color></link>. Conan, que é invocado pelo Secret Razzle Dazzle, vai <color=#00F6FF>procurar inimigos ao seu redor e atacá-los</color> quando Zeta lança seu Combo de Cadeia. Seu raio de busca é o <color=#00F6FF>mesmo</color> que o alcance do Combo de Cadeia lançado por Zeta, e ele causa dano igual a <color=#00F6FF>{1}</color> do dano causado pelo Combo de Cadeia de Zeta. Quando Zeta lança seu Combo de Cadeia de nível 3, o alcance de dano de Conan se expande <color=#00F6FF>1 aglomerado circundante</color>. Sempre que o Quadro de Cores estiver preenchido, ele restaura o PV igual a <color=#00F6FF>12%</color> do Max PV de Zeta para a equipe.",
  str_skill_name_2002291 = "Saída Encontrada!",
  str_skill_name_2002292 = "Exit Found!",
  str_skill_name_2002293 = "Exit Found!",
  str_skill_name_3002291 = "Tudo Limpo!",
  str_skill_name_3202291 = "All Clear!",
  str_skill_name_3302291 = "All Clear!",
  str_skill_name_3232291 = "All Clear!",
  str_skill_name_3262291 = "All Clear!",
  str_skill_name_3332291 = "All Clear!",
  str_skill_name_3362291 = "All Clear!",
  str_skill_passive_name_4002291 = "Não Fique Sem Bateria!",
  str_skill_desc_2002291 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próx.",
  str_skill_desc_2002292 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próx.",
  str_skill_desc_2002293 = "Causa <color=#00F6FF>{1}%</color> de dano aos 4 inimigos mais próx.",
  str_skill_desc_2202291 = "Causa <color=#00F6FF>{1}%</color> de dano aos 2 inimigos mais próximos e aplica 1 acúmulo de Queimar.",
  str_skill_desc_2202292 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próximos e aplica 1 acúmulo de Queimadura.",
  str_skill_desc_2202293 = "Causa <color=#00F6FF>{1}%</color> de dano aos 4 inimigos mais próximos e inflige 1 pilha de Queimadura.",
  str_skill_desc_3002291 = "Batia começa a batalha com <link=\"30110\"><#FFAE07><u>Próxima Fila</u></color></link>. Selecione 1 casa, e a área correspondente ao bloco mostrado na Próxima Fila será convertida em casas Vermelhas.",
  str_skill_desc_3202291 = "Batia começa a batalha com <link=\"30111\"><#FFAE07><u>Próxima Fila</u></color></link>. Selecione 1 casa, e a área correspondente ao bloco mostrado na Próxima Fila será convertida em casas Vermelhas. Cada casa Vermelha percorrida concede <color=#00F6FF>1</color> Energia. Consuma <color=#00F6FF>5</color> Energia para randomizar o bloco. Cada tentativa de randomização custará mais <color=#00F6FF>5</color> Energia até o próximo uso de sua Habil. Ativa.",
  str_skill_desc_3232291 = "Batia começa a batalha com <link=\"30112\"><#FFAE07><u>Próxima Fila</u></color></link>. Selecione 1 casa, e a área correspondente ao bloco mostrado na Próxima Fila será convertida em casas Vermelhas. Próxima Fila começa com <color=#00F6FF>10</color> de Energia, e cada casa Vermelha percorrida concede-lhe <color=#00F6FF>1</color> de Energia. Consuma <color=#00F6FF>5</color> de Energia para randomizar o bloco. Cada tentativa de randomização custará um adicional de <color=#00F6FF>5</color> de Energia até o próximo uso de sua Habil. Ativa.",
  str_skill_desc_3262291 = "Batia começa a batalha com <link=\"30113\"><#FFAE07><u>Próxima Fila</u></color></link>. Selecione 1 casa, e a área correspondente ao bloco mostrado na Próxima Fila será convertida em casas Vermelhas. Próxima Fila começa com <color=#00F6FF>10</color> de Energia, e cada casa Vermelha percorrida concede-lhe <color=#00F6FF>1</color> de Energia. Consuma <color=#00F6FF>5</color> de Energia para randomizar o bloco.",
  str_skill_desc_3302291 = "Batia começa a batalha com <link=\"30114\"><#FFAE07><u>Próxima Fila</u></color></link>. Selecione 1 casa, e a área correspondente ao bloco mostrado na Próxima Fila será convertida em casas Vermelhas. Cada casa Vermelha atravessada concede <color=#00F6FF>1</color> Energia. Consuma <color=#00F6FF>5</color> Energia para randomizar o bloco. Cada tentativa de randomização custará um adicional de <color=#00F6FF>5</color> Energia até o próximo uso de sua Habilidade Ativa. Bloqueie o bloco na Próxima Fila para evitar que ele seja randomizado. Enquanto bloqueado, cada randomização aprimora o bloco atual. Para cada aprimoramento, a Habilidade Ativa também gerará um Ladrilho Escuro em uma localização aleatória.",
  str_skill_desc_3332291 = "Batia começa a batalha com <link=\"30115\"><#FFAE07><u>Próxima Fila</u></color></link>. Selecione 1 casa, e a área correspondente ao bloco mostrado na Próxima Fila será convertida em casas Vermelhas. Próxima Fila começa com <color=#00F6FF>10</color> Energia, e cada casa Vermelha atravessada concede-lhe <color=#00F6FF>1</color> Energia. Consome <color=#00F6FF>5</color> Energia para randomizar o bloco. Cada tentativa de randomização custará um adicional de <color=#00F6FF>5</color> Energia até o próximo uso de sua Habilidade Ativa. Bloqueie o bloco na Próxima Fila para evitar que ele seja randomizado. Enquanto bloqueado, cada randomização aprimora o bloco atual. Para cada aprimoramento, a Habilidade Ativa também gerará um Bloco Escuro em um local aleatório.",
  str_skill_desc_3362291 = "Batia começa a batalha com <link=\"30116\"><#FFAE07><u>Próxima Fila</u></color></link>. Selecione 1 casa, e a área correspondente ao bloco mostrado na Próxima Fila será convertida em casas Vermelhas. Próxima Fila começa com <color=#00F6FF>10</color> de Energia, e cada casa Vermelha atravessada concede-lhe <color=#00F6FF>1</color> de Energia. Consome <color=#00F6FF>5</color> Energia para randomizar o bloco. Bloqueie o bloco na Próxima Fila para impedir que ele seja randomizado. Enquanto bloqueado, cada randomização aprimora o bloco atual. Para cada aprimoramento, a Habilidade Ativa também gerará um Ladrilho Escuro em uma localização aleatória.",
  str_skill_passive_desc_4002291 = "A equipe inflige <color=#00F6FF>Chama</color> nos alvos em vez de Queimar. Cada acúmulo causa <color=#00F6FF>{1}</color> do ATK médio da equipe aos alvos. Quanto maior o HP do alvo, maior o dano, até um bônus de 100%. Acumula até 5 vezes e dura 2 rodadas. Inflige <color=#00F6FF>1</color> acúmulo de Chama no alvo mais próximo para cada <link=\"30093\"><#FFAE07><u>Casa Escura</u></color></link> percorrida.",
  str_skill_upgrade_desc_16022913 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate. Próxima fila começa com 10 de Energia (válido para Ascensão II).",
  str_skill_upgrade_desc_16022916 = "Aprimoramento de Habilidade Ativa: O custo de energia não aumenta mais ao randomizar a Próxima Fila (válido para Ascensão II).",
  str_skill_name_28002414 = "Opressão",
  str_skill_desc_28002414 = "Forsakin lança um feitiço poderoso e empurra os Aurorianos para trás.",
  str_skill_name_28002415 = "Invocação",
  str_skill_desc_28002415 = "Forsakin convoca Eclipsitas em locais aleatórios no campo.",
  str_skill_name_1003003 = "Tranca",
  str_skill_desc_1003003 = "Shadowgeist converte 1 peça aleatória dentro de 1 aglomerado ao redor em uma Peça Bloqueada a cada rodada.",
  str_skill_name_29102421 = "Queimar",
  str_skill_desc_29102421 = "Causa dano aos Aurorianos dentro de 4 colunas à frente e convoca chamas em locais aleatórios.",
  str_skill_name_29102422 = "Reino de Fogo",
  str_skill_desc_29102422 = "Libera chamas escaldantes, causando dano a todo o campo. Causa dano adicional aumentado 1 vez a alvos dentro de 3 linhas de cada lado do campo.",
  str_skill_name_15017611 = "Tempestade Australis",
  str_skill_desc_15017611 = "Causa dano várias vezes aos Aurorianos dentro de 3 aglomerados circundantes com base em suas pilhas de Lanças Australis. Cada instância de dano inflige 1 Lança Australis adicional no alvo. Se o alvo não puder ser atacado, inflige 3 pilhas de Lanças Australis em si mesma.",
  str_skill_name_15017612 = "resplendor boreal",
  str_skill_desc_15017612 = "Remove Lanças Australis de alvos dentro de 2 aglomerados circundantes. Cada Lança Australis causa 20% de dano. Se o alvo não pode ser atacado, inflige 3 pilhas de Lanças Australis em si mesma.",
  str_skill_name_15020011 = "A Escuridão Vem",
  str_skill_desc_15020011 = "Causa dano a unidades inimigas dentro de 3 aglomerados ao redor.",
  str_skill_name_15020012 = "Ode às Profundezas",
  str_skill_desc_15020012 = "Reúne os Aurorianos e o soldado Illumina em direção ao centro em relação a ambas as suas posições.",
  str_skill_name_547100101 = "Reinhardt Ataque Normal",
  str_skill_desc_547100101 = "Reinhardt se aproxima dos inimigos e lança ataques.",
  str_skill_name_547100102 = "Explosão de Iluminação",
  str_skill_desc_547100102 = "Reinhardt causa grande dano aos inimigos.",
  str_skill_name_290980101 = "Maldade Penetrante",
  str_skill_name_290980102 = "Juízo Desprezado pela Alma",
  str_skill_name_290980103 = "Berro da Maré de Blitz",
  str_skill_name_290980104 = "Sopro de Dragão Convergente",
  str_skill_desc_290980101 = "Se houver inimigos dentro de uma área em forma de X, causa dano a eles e convoca unidades periféricas. Caso contrário, convoca unidades periféricas ao seu redor.",
  str_skill_desc_290980102 = "Se houver inimigos dentro de uma área em forma de cruz, causa dano a eles e convoca unidades periféricas. Caso contrário, convoca unidades periféricas ao seu redor.",
  str_skill_desc_290980103 = "Convoca unidades periféricas ao seu redor.",
  str_skill_desc_290980104 = "Causa dano a todos os inimigos no campo, repelindo-os e convocando unidades periféricas ao redor deles.",
  str_skill_name_200510101 = "Olhar Provocativo",
  str_skill_desc_200510101 = "Provocantes da Periferia se aproximam dos inimigos e lançam ataques.",
  str_skill_name_290520111 = "Forsaken: Blitz Feroz",
  str_skill_desc_290520111 = "Figerald move-se em direção aos aurorianos e causa muito dano, depois se retira.",
  str_skill_name_290520112 = "Forsaken: Figerald's Assaulto",
  str_skill_desc_290520112 = "Figerald se move, depois causa dano a todos os Aurorianos ao alcance.",
  str_skill_name_290940113 = "Forsaken: Lança do Fogo Sombrio",
  str_skill_desc_290940113 = "Ira causa dano igual a 40% do HP atual dos Aurorianos, aumenta o HP máximo da equipe com base no dano causado e gera Shadowfires nas peças mais externas do tabuleiro dentro de um alcance máximo na área em forma de cruz centrada ao redor do Auroriano.",
  str_skill_name_290940114 = "Forsaken: Explosão Ardente",
  str_skill_desc_290940114 = "Ira causa dano aos Aurorianos dentro de 2 aglomerados ao redor dele mesmo.",
  str_skill_name_290940115 = "Forsaken: Meteoro Irado",
  str_skill_desc_290940115 = "Ira convoca meteoritos para atingir a posição onde os Aurorianos estavam na rodada anterior, causando dano letal e destruindo o ladrilho, deixando para trás 4 ladrilhos quebrados em forma de cruz.",
  str_skill_upgrade_refine_desc_17010711 = "Aprimoramento de Habilidade Ativa: Aumenta o dano do Combo em Cadeia em <color=#00F6FF>25%</color> quando Aumentado.",
  str_skill_upgrade_refine_desc_17010712 = "Melhoria de Habilidade de Equip.: No início de cada rodada, ganha 1 Vis para cada inimigo dentro de <color=#00F6FF>1 aglomerado circundante</color>.",
  str_skill_upgrade_refine_desc_17010713 = "Melhoria de Habilidade de Equip.: Ganha 5 Vis no <color=#00F6FF>final da rodada</color> (ganha 1 Vis extra para cada <color=#00F6FF>15%</color> de PV perdido).",
  str_skill_desc_346107 = "Usa <color=#00F6FF>10</color> Vis para entrar em um estado aumentado nesta rodada: ataques normais podem ser lançados diagonalmente. Aumenta o dano do Ataque Normal/Combo em Cadeia em <color=#00F6FF>20%/25%</color> respectivamente (pode ser acumulado). Ganha 2 Vis para cada inimigo derrotado enquanto aumentado.",
  str_skill_passive_desc_456107 = "Ganhe 10 Vis no começo da batalha. No início de cada rodada, ganhe <color=#00F6FF>1</color> Vis para cada inimigo dentro de <color=#00F6FF>1 cluster circundante</color>. Ganhe <color=#00F6FF>5</color> Vis ao terminar a rodada em um estado não aumentado e 1 Vis extra para cada 20% de PV perdido.",
  str_skill_passive_desc_466107 = "Ganhe 10 Vis no começo da batalha. No começo de cada rodada, ganhe <color=#00F6FF>1</color> Vis para cada inimigo dentro de <color=#00F6FF>1 cluster circundante</color>. Ganhe <color=#00F6FF>5</color> Vis no final da rodada e 1 Vis extra para cada 15% de PV perdido.",
  str_skill_upgrade_refine_desc_17010811 = "<color=#00F6FF>Habilidade Ativa Variante I</color>: Usa <color=#00F6FF>15</color> Vis para causar <color=#00F6FF>480%</color> de dano a uma casa selecionada. Cada lançamento aumenta o ATK básico em <color=#00F6FF>3%</color>. Pode ser lançado várias vezes a cada rodada.",
  str_skill_upgrade_refine_desc_17010812 = "Aprimoramento de Habilidade Ativa: Cada lançamento aumenta o dano final da Habil. Ativa em <color=#00F6FF>3%</color>.",
  str_skill_upgrade_refine_desc_17010813 = "Aprimoramento de Habilidade Ativa: Causa <color=#00F6FF>300%</color> de dano a alvos com menos de <color=#00F6FF>10%</color> de HP.",
  str_skill_name_366108 = "Chuva de Meteoros",
  str_skill_name_33610801 = "Variante I da Chuva de Meteoros",
  str_skill_name_36610801 = "Variante I da Chuva de Meteoros",
  str_skill_desc_33610801 = "Usa <color=#00F6FF>15</color> Vis para causar <color=#00F6FF>480%</color> de dano a uma casa selecionada. Cada lançamento aumenta o ATK básico em <color=#00F6FF>3%</color>. Pode ser lançado várias vezes a cada rodada.",
  str_skill_desc_356108 = "Usa <color=#00F6FF>10</color> Vis para causar <color=#00F6FF>240%</color> de dano a 1 casa selecionada e causa 50% de dano <link=\"30015\"><#FFAE07><u>de sobra</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor. Cada lançamento aumenta o ATK básico e o dano final da Habilidade Ativa em <color=#00F6FF>3%</color>. Pode ser lançada múltiplas vezes por rodada.",
  str_skill_desc_35610801 = "Usa <color=#00F6FF>15</color> Vis para causar <color=#00F6FF>480%</color> de dano a uma casa selecionada. Cada lançamento aumenta o ATK básico e o dano final da Habilidade Ativa em <color=#00F6FF>3%</color>. Pode ser lançado várias vezes a cada rodada.",
  str_skill_desc_366108 = "Usa <color=#00F6FF>10</color> Vis para causar <color=#00F6FF>240%</color> de dano a 1 casa selecionada e causa 50% de dano <link=\"30015\"><#FFAE07><u>de sobra</u></color></link> a <color=#00F6FF>4 casas em forma de cruz</color> ao redor. Cada lançamento aumenta o ATK básico e o dano final da Habilidade Ativa em <color=#00F6FF>3%</color>. Pode ser lançada múltiplas vezes por rodada. Causa <color=#00F6FF>300%</color> de dano a alvos com menos de <color=#00F6FF>10%</color> de HP.",
  str_skill_desc_36610801 = "Usa <color=#00F6FF>15</color> Vis para causar <color=#00F6FF>480%</color> de dano a uma casa selecionada. Cada lançamento aumenta o ATK básico e o dano final da Habilidade Ativa em <color=#00F6FF>3%</color>. Pode ser lançado várias vezes a cada rodada. Causa <color=#00F6FF>300%</color> de dano a alvos com menos de <color=#00F6FF>10%</color> de HP.",
  str_skill_upgrade_refine_desc_17010911 = "Aprimoramento de Habilidade Ativa: <color=#00F6FF>Seleciona 1 casa no campo</color> e os ataques podem alcançar <color=#00F6FF>alvos atrás da equipe</color>.",
  str_skill_upgrade_refine_desc_17010912 = "Melhoria de Habilidade de Equip.: Ganha <color=#00F6FF>1</color> Vis para os <color=#00F6FF>primeiros 2</color> Ataques Normais lançados a cada rodada e aumenta o dano causado por esses ataques em <color=#00F6FF>100%</color>.",
  str_skill_upgrade_refine_desc_17010913 = "Nova Habilidade Ativa: Usa <color=#00F6FF>10</color> Vis para aumentar os alvos do Combo em Cadeia nesta rodada em <color=#00F6FF>1</color> (pode ser acumulado).",
  str_skill_name_340109 = "Caça ao Luar",
  str_skill_desc_340109 = "Custa <color=#00F6FF>10</color> Vis e limpa o Vis restante para selecionar 1 casa e causar <color=#00F6FF><color=#00F6FF>150%</color></color> de dano a todos os inimigos no caminho entre o Auroriano e a casa selecionada, estendendo-se em ambas as direções, bem como aos inimigos nas casas adjacentes. O dano final aumenta em <color=#00F6FF>8%</color> para cada 1 Vis limpo.",
  str_skill_passive_desc_453109 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada. Ganhe <color=#00F6FF>1</color> Vis para os <color=#00F6FF>primeiros 2</color> Ataques Normais a cada rodada e aumente o dano deles em <color=#00F6FF>100%</color>.",
  str_skill_name_360109 = "Perseguindo Sombras Entre Árvores",
  str_skill_desc_360109 = "Usa <color=#00F6FF>10</color> Vis para aumentar o número de alvos para o Combo em cadeia nesta rodada em <color=#00F6FF>1</color> (pode ser acumulado).",
  str_skill_upgrade_refine_desc_17011011 = "Aprimoramento de Habilidade de Equipamento: Ataques Normais têm uma chance de <color=#00F6FF>35%</color> de atingir o inimigo mais distante com um relâmpago.",
  str_skill_upgrade_refine_desc_17011012 = "Melhoria de Habilidade de Equip.: Ganha 1 Vis para cada relâmpago quando possui menos de 5 Vis.",
  str_skill_upgrade_refine_desc_17011013 = "Aprimoramento de Habilidade Ativa: Ganha 1 acúmulo de Marca Requiem para cada golpe de relâmpago liberado, e todas as marcas serão limpas quando a habilidade ativa for liberada. Aumenta o fator de dano para habilidade ativa em 10% para cada acúmulo de Marcas Requiem limpas.",
  str_skill_passive_desc_443110 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada. Ganha <color=#00F6FF>2</color> Vis extras ao derrotar um alvo com uma Habil. Ativa. Ataques normais têm uma chance de <color=#00F6FF>35%</color> de atingir o inimigo mais distante com um relâmpago.",
  str_skill_passive_desc_453110 = "Ganhe <color=#00F6FF>5</color> Vis no início de cada rodada. Ganha <color=#00F6FF>2</color> Vis extras ao derrotar um alvo com uma Habil. Ativa. Ataques normais têm uma chance de <color=#00F6FF>35%</color> de atingir o inimigo mais distante com um relâmpago. Ganha 1 Vis para cada relâmpago quando possui menos de 5 Vis.",
  str_skill_desc_366110 = "Custa <color=#00F6FF>10</color> Vis. Limpa o Vis restante e <link=\"30117\"><#FFAE07><u>Marcas de Requiem</u></color></link> para causar <color=#00F6FF>150%</color> de dano a todos os inimigos. Para cada 1 Vis limpo, o dano aumenta em <color=#00F6FF>15%</color> e ignora <color=#00F6FF>1%</color> da DEF. Aumenta o fator de dano da Habilidade Ativa em <color=#00F6FF>10%</color> para cada pilha de Marca de Requiem limpa.",
  str_skill_upgrade_desc_16023013 = "Aprimoramento de habilidade de equipamento: Sempre que a sanidade fica abaixo ou acima de 50, o ladrilho não vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Vermelho Escuro</color>.",
  str_skill_upgrade_desc_16023014 = "Aprimoramento de Habilidade Ativa e de Equipamento: Ao causar dano, inclui uma perda adicional de <color=#00F6FF>4,000</color> de HP da equipe.",
  str_skill_upgrade_desc_16023015 = "Aprimoramento de Habilidade de Equipamento: Victoria: O dano da Elegia aos inimigos com o Pacto do Senhor aumenta à medida que o HP da equipe diminui, atingindo o máximo de <color=#00F6FF>15%</color> quando o HP da equipe está em 50%.",
