  str_skill_passive_name_4362301 = "Onisciência Benevolente",
  str_skill_desc_2002301 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próximos e o <color=#00F6FF>mesmo dano</color> uma vez aos inimigos com a Aliança do Senhor.",
  str_skill_desc_2002302 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próximos e o <color=#00F6FF>mesmo dano</color> uma vez aos inimigos com a Aliança do Senhor.",
  str_skill_desc_2002303 = "Causa <color=#00F6FF>{1}%</color> de dano aos 3 inimigos mais próximos e o <color=#00F6FF>mesmo dano</color> uma vez aos inimigos com a Aliança do Senhor.",
  str_skill_desc_3002301 = "Victoria: Elegy junta-se à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ela consome 10 Sanidade para aplicar o <link=\"30118\"><#FFAE07><u>Pacto do Senhor</u></color></link> a 1 alvo e causar dano ignorando DEF igual a <color=#00F6FF>200%</color> do HP perdido da equipe.",
  str_skill_desc_3042301 = "Victoria: Elegy junta-se à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Ela consome 10 Sanidade para aplicar o <link=\"30118\"><#FFAE07><u>Pacto do Senhor</u></color></link> a 1 alvo e causar dano ignorando DEF igual a <color=#00F6FF>200%</color> do HP perdido da equipe, com um extra de 4.000 pontos de HP perdido da equipe considerado.",
  str_skill_desc_3002302 = "Troca as porcentagens atuais de HP e Sanidade da equipe. Não pode ser lançado se a Sanidade for 0. Ganha 1 lançamento ao entrar na batalha.",
  str_skill_passive_desc_4102301 = "No início de cada rodada ou ao passar por uma Casa Escura, causa uma vez dano ignorando a DEF igual a <color=#00F6FF>{1}</color> do PV perdido da equipe aos inimigos com o Pacto do Senhor.",
  str_skill_passive_desc_4302301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa uma vez dano que ignora DEF igual a <color=#00F6FF>{1}</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que ela danifica um inimigo assim (pelo menos 1 ponto).",
  str_skill_passive_desc_4132301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa uma vez dano ignorando a DEF igual a <color=#00F6FF>{1}</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Sempre que a Sanidade muda de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, o ladrilho não-Vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Escuro Vermelho</color>.",
  str_skill_passive_desc_4332301 = "No início de cada rodada ou ao passar por uma Telha Escura, causa dano ignorando DEF igual a <color=#00F6FF>{1}</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que danifica tal inimigo (pelo menos 1 ponto). Sempre que a Sanidade muda de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, a telha não-Vermelha mais próxima da equipe é convertida em uma <color=#00F6FF>Telha Escura Vermelha</color>.",
  str_skill_passive_desc_4142301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa dano ignorando a DEF uma vez igual a <color=#00F6FF>{1}</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor, com um extra de <color=#00F6FF>4.000</color> pontos de HP perdido da equipe considerados. Sempre que a Sanidade muda de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, o ladrilho não-vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Escuro Vermelho</color>.",
  str_skill_passive_desc_4342301 = "No início de cada rodada ou ao passar por uma Telha Escura, causa dano ignorando DEF igual a <color=#00F6FF>{1}</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que danifica tal inimigo (pelo menos 1 ponto). Sempre que a Sanidade muda de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, a telha não-Vermelha mais próxima da equipe é convertida em uma <color=#00F6FF>Telha Escura Vermelha</color>.",
  str_skill_passive_desc_4162301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa uma vez dano que ignora DEF igual a <color=#00F6FF>{1}</color> do PV perdido da equipe aos inimigos com o Pacto do Senhor, com um extra de <color=#00F6FF>4.000</color> pontos de PV perdido da equipe considerados. Sempre que a Sanidade mudar de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, o ladrilho não-Vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Escuro Vermelho</color>. Victoria: O dano da Elegia aos inimigos com o Pacto do Senhor aumenta à medida que o HP da equipe diminui, atingindo o máximo de <color=#00F6FF>15%</color> quando o HP da equipe está em 50%.",
  str_skill_passive_desc_4362301 = "No início de cada rodada ou ao passar por uma Peça Escura, causa dano que ignora DEF uma vez igual a <color=#00F6FF>{1}</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que ela danifica um inimigo assim (pelo menos 1 ponto). Sempre que a Sanidade mudar de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, o ladrilho não-vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Escuro Vermelho</color>. Victoria: O dano da Elegia aos inimigos com o Pacto do Senhor aumenta à medida que o HP da equipe diminui, atingindo o máximo de <color=#00F6FF>15%</color> quando o HP da equipe está em 50%.",
  str_skill_upgrade_refine_desc_16023011 = "Aprimoramento de habilidade de equipamento: aumenta o fator de dano para <color=#00F6FF>35%</color>.",
  str_skill_upgrade_refine_desc_16023012 = "Aprimoramento do Chain Combo: Causa um dano adicional de <color=#00F6FF>110%</color> contra inimigos com a Aliança do Senhor.",
  str_skill_upgrade_refine_desc_16023013 = "Aprimoramento de Habilidade Ativa: Ganha <color=#00F6FF>1</color> lançamento adicional.",
