  str_skill_name_2502302 = "Prisão Escarlate",
  str_skill_name_2502303 = "Prisão Escarlate",
  str_skill_passive_desc_4402301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa uma vez dano que ignora DEF igual a <color=#00F6FF>35%</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que ela danifica um inimigo assim (pelo menos 1 ponto).",
  str_skill_passive_desc_4432301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa dano ignorando DEF uma vez igual a <color=#00F6FF>35%</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que danifica tal inimigo (pelo menos 1 ponto). Sempre que a Sanidade muda de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, o ladrilho não-Vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Escuro Vermelho</color>.",
  str_skill_passive_desc_4442301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa dano ignorando DEF uma vez igual a <color=#00F6FF>35%</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que danifica tal inimigo (pelo menos 1 ponto). Sempre que a Sanidade muda de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, o ladrilho não-Vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Escuro Vermelho</color>.",
  str_skill_passive_desc_4462301 = "No início de cada rodada ou ao passar por um Ladrilho Escuro, causa uma vez dano que ignora DEF igual a <color=#00F6FF>35%</color> do HP perdido da equipe aos inimigos com o Pacto do Senhor. Victoria: Elegy restaura <color=#00F6FF>3%</color> da Sanidade perdida sempre que danifica um inimigo assim (pelo menos 1 ponto). Sempre que a Sanidade mudar de 50 ou mais para menos de 50, ou de menos de 50 para 50 ou mais, o ladrilho não-Vermelho mais próximo da equipe é convertido em um <color=#00F6FF>Ladrilho Escuro Vermelho</color>. Victoria: O dano da Elegia aos inimigos com o Pacto do Senhor aumenta à medida que o HP da equipe diminui, atingindo o máximo de <color=#00F6FF>15%</color> quando o HP da equipe está em 50%.",
  str_skill_desc_2502301 = "Causa <color=#00F6FF>135%</color> de dano aos 3 inimigos mais próximos e causa <color=#00F6FF>110%</color> do dano anterior uma vez ao inimigo com a Aliança do Senhor.",
  str_skill_desc_2502302 = "Causa <color=#00F6FF>150%</color> de dano aos 3 inimigos mais próximos e causa <color=#00F6FF>110%</color> do dano anterior uma vez ao inimigo com a Aliança do Senhor.",
  str_skill_desc_2502303 = "Ofertas <color=#00F6FF>165%</color> dano aos 3 inimigos mais próximos e causa <color=#00F6FF>110%</color> do dano anterior uma vez ao inimigo com a Aliança do Senhor.",
  str_skill_desc_3602302 = "Troca as porcentagens atuais de HP e Sanidade da equipe. Não pode ser lançado se a Sanidade for 0. Ganha 2 lançamentos ao entrar na batalha.",
  str_skill_name_2002311 = "Clarão Carmesim",
  str_skill_name_2002312 = "Clarão Carmesim",
  str_skill_name_2002313 = "Clarão Carmesim",
  str_skill_name_3002311 = "Erudição Malfeitora",
  str_skill_name_3032311 = "Erudição Malfeitora",
  str_skill_name_3202311 = "Erudição Malfeitora",
  str_skill_name_3232311 = "Erudição Malfeitora",
  str_skill_name_3302312 = "Selo de Ardor",
  str_skill_desc_2002311 = "Causa <color=#00F6FF>130%</color> de dano 3 vezes, atribuindo aleatoriamente a inimigos em <color=#00F6FF>2 círculos ao redor</color> desta unidade. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2002312 = "Causa <color=#00F6FF>140%</color> de dano 4 vezes, atribuindo aleatoriamente a inimigos em <color=#00F6FF>2 círculos ao redor</color> desta unidade. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_2002313 = "Causa <color=#00F6FF>150%</color> de dano 5 vezes, atribuindo aleatoriamente a inimigos em <color=#00F6FF>3 círculos ao redor</color> desta unidade. Quando um alvo recebe dano mais de uma vez, o dano é dividido pela metade a partir da segunda vez.",
  str_skill_desc_3002311 = "Wilhelm se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Escolha qualquer ladrilho e, em seguida, selecione outro ladrilho dentro <color=#00F6FF>2 aglomerados circundantes</color> para gerar uma área retangular. Converte os ladrilhos selecionados em Ladrilhos Azuis Escuros. Cada ladrilho na área usa <color=#00F6FF>2</color> Sanidade.",
  str_skill_desc_3032311 = "Wilhelm se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Escolha qualquer ladrilho e, em seguida, selecione outro ladrilho dentro de <color=#00F6FF>3 aglomerados circundantes</color> para gerar uma área retangular. Converte os ladrilhos selecionados em Ladrilhos Azuis Escuros. Cada ladrilho na área usa <color=#00F6FF>2</color> de Sanidade.",
  str_skill_desc_3202311 = "Wilhelm se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Escolha qualquer peça e depois selecione outra peça dentro de <color=#00F6FF>2 grupos circundantes</color> para gerar uma área retangular. Converte as peças selecionadas em Peças Azuis Escuras. Cada peça na área usa <color=#00F6FF>2</color> de Sanidade, e <color=#00F6FF>1</color> pilha de Vertigem de Sangue é infligida a todos os inimigos na área. Uma pilha adicional é infligida se a Sanidade cair abaixo de <color=#00F6FF>50</color> após a conjuração.",
  str_skill_desc_3232311 = "Wilhelm se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Escolha qualquer peça e depois selecione outra peça dentro de <color=#00F6FF>3 grupos circundantes</color> para gerar uma área retangular. Converte as peças selecionadas em Peças Azuis Escuras. Cada peça na área usa <color=#00F6FF>2</color> de Sanidade, e <color=#00F6FF>1</color> pilha de Vertigem de Sangue é infligida a todos os inimigos na área. Uma pilha adicional é infligida se a Sanidade cair abaixo de <color=#00F6FF>50</color> após a conjuração.",
  str_skill_desc_3302312 = "Restaura 20 de Sanidade, mas reduz a Max Sanity em 20 após a conjuração. Pode ser lançado em sucessão até que a Max Sanity caia para 0.",
  str_skill_passive_name_4002311 = "Enterro Noturno",
  str_skill_passive_name_4062311 = "Enterro Noturno",
  str_skill_passive_desc_4002311 = "Substitui o debuff de Medo infligido pela equipe no alvo por <color=#00F6FF>Tontura de Sangue</color>. Cada pilha reduz a DEF do alvo em <color=#00F6FF>{1}</color>, até 3 pilhas, durando 2 rodadas. Cada vez que uma pilha é removida (incluindo quando o alvo morre) ou excede o limite, restaura 1 Sanidade. O Combo em Cadeia de Wilhelm aplica 1 pilha de <color=#00F6FF>Tontura de Sangue</color> sempre que causa dano.",
  str_skill_passive_desc_4062311 = "Substitui o debuff de Medo infligido pela equipe no alvo por <color=#00F6FF>Tontura de Sangue</color>. Cada acúmulo reduz a DEF do alvo em <color=#00F6FF>{1}</color>, até 3 acúmulos, durando 2 rodadas. Cada vez que um acúmulo é removido (incluindo quando o alvo morre) ou excede o limite, restaura 2 de Sanidade. O Combo em Cadeia de Wilhelm aplica 1 acúmulo de <color=#00F6FF>Tontura de Sangue</color> sempre que causa dano.",
  str_skill_upgrade_desc_16023113 = "Aprimoramento de Habilidade Ativa: Muda a Habilidade Ativa para <color=#FFFF00>Ataque preventivo</color>. Disponível ao entrar em combate. Expande o alcance de seleção do segundo ladrilho para 3 clusters circundantes.",
  str_skill_upgrade_desc_16023116 = "Aprimoramento de Habilidade de Equipamento: Restaura 2 de Sanidade para cada pilha de Vertigem de Sangue que desaparece ou excede o limite.",
  str_skill_name_2002321 = "Batismo Sangrento",
  str_skill_name_2002322 = "Batismo Sangrento",
  str_skill_name_2002323 = "Batismo Sangrento",
  str_skill_name_3002321 = "Salvação Sangrenta",
  str_skill_name_3202322 = "Variante de Salvação Sangrenta",
  str_skill_name_3022321 = "Salvação Sangrenta",
  str_skill_name_3222322 = "Variante de Salvação Sangrenta",
  str_skill_name_3302321 = "Salvação Sangrenta",
  str_skill_name_3302322 = "Variante de Salvação Sangrenta",
  str_skill_name_3322321 = "Salvação Sangrenta",
  str_skill_name_3322322 = "Variante de Salvação Sangrenta",
  str_skill_passive_name_4002321 = "Perdão Inebriante",
  str_skill_passive_name_4052321 = "Perdão Inebriante",
  str_skill_desc_2002321 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color> e aplica 1 acúmulo de <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> por 2 rodadas.",
  str_skill_desc_2002322 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>16 casas em forma radial</color> e aplica 1 acúmulo de <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> por 2 rodadas.",
  str_skill_desc_2002323 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color> e aplica 1 acúmulo de <link=\"10000\"><#FFAE07><u>Sangrar</u></color></link> por 2 rodadas.",
  str_skill_desc_3002321 = "Consome <color=#00F6FF>10%</color> do HP máximo da equipe para converter <color=#00F6FF>1</color> azulejo selecionado em azulejos escuros. Não pode ser lançado se o HP for insuficiente.",
  str_skill_desc_3202322 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Consome <color=#00F6FF>25%</color> do HP máximo da equipe para converter <color=#00F6FF>2</color> peças selecionadas em peças escuras. Não pode ser lançado se o HP for insuficiente.",
  str_skill_desc_3022321 = "Consome <color=#00F6FF>10%</color> do HP máximo da equipe para converter <color=#00F6FF>1</color> azulejo selecionado em azulejos escuros. Não pode ser lançado se o HP for insuficiente.",
  str_skill_desc_3222322 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Consome <color=#00F6FF>25%</color> do HP máximo da equipe para converter <color=#00F6FF>2</color> peças selecionadas em peças escuras. Não pode ser lançado se o HP for insuficiente.",
  str_skill_desc_3302321 = "Consome <color=#00F6FF>10%</color> do HP máximo da equipe para converter <color=#00F6FF>1</color> azulejo selecionado em azulejos escuros. Não pode ser lançado se o HP for insuficiente. Se o HP da equipe estiver abaixo de <color=#00F6FF>30%</color> após o lançamento, converte o primeiro azulejo selecionado em um azulejo escuro vermelho.",
  str_skill_desc_3302322 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Consome <color=#00F6FF>25%</color> do HP máximo da equipe para converter <color=#00F6FF>2</color> peças selecionadas em peças escuras. Não pode ser lançado se o HP for insuficiente. Se o HP da equipe estiver abaixo de <color=#00F6FF>30%</color> após a conjuração, converte a primeira peça selecionada em uma peça escura vermelha.",
  str_skill_desc_3322321 = "Consome <color=#00F6FF>10%</color> do HP máximo da equipe para converter <color=#00F6FF>1</color> azulejo selecionado em azulejos escuros. Não pode ser lançado se o HP for insuficiente. Se o HP da equipe estiver abaixo de <color=#00F6FF>30%</color> após o lançamento, converte o primeiro azulejo selecionado em um azulejo escuro vermelho.",
  str_skill_desc_3322322 = "<color=#FFFF00>Recarga de habilidade +1 após conjuração</color>. Consome <color=#00F6FF>25%</color> do HP máximo da equipe para converter <color=#00F6FF>2</color> peças selecionadas em peças escuras. Não pode ser lançado se o HP for insuficiente. Se o HP da equipe estiver abaixo de <color=#00F6FF>30%</color> após a conjuração, converte a primeira peça selecionada em uma peça escura vermelha.",
  str_skill_passive_desc_4002321 = "Quando a porcentagem atual de PV cai abaixo de <color=#00F6FF>50%</color>, gera uma Bênção Carmesim na casa vermelha mais próxima que pode ser atravessada. Ao passar por ela, restaura PV igual a <color=#00F6FF>{1}</color> do ATQ de Nails: Rito Sagrado.",
  str_skill_passive_desc_4052321 = "Quando a porcentagem do PV atual cai abaixo de <color=#00F6FF>50%</color>, gera uma Bênção Carmesim na casa vermelha percorrida mais próxima. Ao passar por ela, restaura PV igual a <color=#00F6FF>{1}</color> do ATQ de Nails: Rito Sagrado. Considera a Bênção Carmesim como uma casa escura ao passar por ela.",
