  str_skill_name_2302343 = "Infinity Arrow",
  str_skill_passive_name_410234 = "Marca-passo",
  str_skill_passive_desc_410234 = "Personagens de colaboração do Atelier Ryza 2 lutam com o <link=\"30122\"><#FFAE07><u>Sistema Tático</u></color></link>. Klaudia ganha <color=#00F6FF>{1}</color> Pontos Táticos cada vez que ela lança uma Habilidade Ativa.",
  str_skill_passive_desc_440234 = "Personagens de colaboração do Atelier Ryza 2 lutam com o <link=\"30122\"><#FFAE07><u>Sistema de Táticas</u></color></link>. Klaudia ganha <color=#00F6FF>20</color> Pontos Táticos cada vez que ela lança uma Habilidade Ativa.",
  str_skill_upgrade_refine_desc_16023411 = "Melhoria de Habilidade de Equipamento: Klaudia ganha <color=#00F6FF>20</color> Pontos Táticos cada vez que ela usa uma Habilidade Ativa.",
  str_skill_upgrade_refine_desc_16023412 = "Melhoria de Habilidade Ativa: Aumenta o bônus de dano contra inimigos que ocupam várias casas em <color=#00F6FF>50%</color>.",
  str_skill_upgrade_refine_desc_16023413 = "Aprimoramento do Chain Combo: O fator de dano do Chain Combo aumenta em <color=#00F6FF>5%</color> para cada Ladrilho Escuro percorrido na rodada atual.",
  str_skill_desc_240461 = "Ofertas <color=#00F6FF>120%</color> danos a <color=#00F6FF>3</color> inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color> e inflige 1 acúmulo de Riso, até 8 acúmulos. Cada pilha aumenta o dano do Chain Combo em <color=#00F6FF>7%</color>.",
  str_skill_desc_240462 = "Ofertas <color=#00F6FF>140%</color> danos a <color=#00F6FF>3</color> inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color> e inflige 2 acúmulos de Riso, até 8 acúmulos. Cada pilha aumenta o dano do Chain Combo em <color=#00F6FF>7%</color>.",
  str_skill_desc_240463 = "Ofertas <color=#00F6FF>155%</color> danos a <color=#00F6FF>3</color> inimigos dentro <color=#00F6FF>4 aglomerados circundantes</color> e inflige 3 acúmulos de Riso, até 8 acúmulos. Cada pilha aumenta o dano do Chain Combo em <color=#00F6FF>7%</color>.",
  str_skill_upgrade_refine_desc_13004612 = "Aprimoramento do Chain Combo: Cada acúmulo de Riso aumenta o dano do Chain Combo em <color=#00F6FF>7%</color>.",
  str_skill_desc_300046 = "Coloca Clucky em um ladrilho selecionado, depois puxa <color=#00F6FF>todos</color> os inimigos e inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> nos inimigos com 5 pilhas de Riso por 2 rodadas.",
  str_skill_desc_302046 = "Coloca Clucky em um ladrilho selecionado, depois puxa <color=#00F6FF>todos</color> os inimigos. Inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> em inimigos com 4 acúmulos de Riso por 2 rodadas e <link=\"10004\"><#FFAE07><u>Paralisado</u></color></link> em inimigos com 6 acúmulos de Riso por 1 rodada.",
  str_skill_desc_305046 = "Coloca Clucky em um ladrilho selecionado, depois puxa <color=#00F6FF>todos</color> os inimigos. Inflige <link=\"10006\"><#FFAE07><u>Lento</u></color></link> em inimigos com 4 acúmulos de Riso por 2 rodadas e <link=\"10004\"><#FFAE07><u>Paralisado</u></color></link> em inimigos com 6 acúmulos de Riso por <color=#00F6FF>1</color> rodada.",
  str_skill_name_29099011 = "Ataques Normais",
  str_skill_desc_29099011 = "Após se mover, causa dano aos alvos até 4 casas à frente.",
  str_skill_name_29099012 = "Ataques Normais",
  str_skill_desc_29099012 = "Após se mover, causa dano aos alvos até 2 casas à frente.",
  str_skill_name_29099013 = "Ataque em Queda",
  str_skill_desc_29099013 = "Salta e pousa ao lado de um Auroriano em qualquer local, causando dano e derrubando materiais de alquimia nas proximidades.",
  str_skill_name_29099023 = "Forsaken: Ataque Prumo",
  str_skill_desc_29099023 = "Salta e aterrissa ao lado de um Auroriano em qualquer local, causando dano.",
