  str_skill_desc_700201701 = "Move-se e depois causa dano a todos os alvos no campo.",
  str_skill_desc_700201702 = "Após o movimento, causa dano a 17 ladrilhos em uma forma radial centrada na localização dos Aurorianos no início da rodada.",
  str_skill_desc_700201901 = "Causa dano a alvos dentro de 5 colunas.",
  str_skill_desc_700201902 = "Causa dano a todos os alvos no campo e os repele 3 peças de si mesmo.",
  str_skill_name_590028203 = "Forsaken: Cruz da Escuridão",
  str_skill_desc_590028203 = "O Invocador Escuro causa dano a alvos em uma forma de cruz até o alcance máximo.",
  str_skill_name_590028204 = "Abandonado: Invocar Baliza",
  str_skill_desc_590028204 = "O Invocador Escuro invoca uma baliza para um local fixo.",
  str_skill_name_590028205 = "Abandonado: Invocar Baliza",
  str_skill_desc_590028205 = "O Invocador Escuro invoca 4 balizas no campo de batalha.",
  str_skill_name_590028206 = "Forsaken: Guardar Energia I",
  str_skill_desc_590028206 = "O Invocador Escuro reúne energia para liberar um ataque em uma área ampla. Quanto mais balizas houver, maior será a área de ataque.",
  str_skill_name_590028207 = "Forsaken: Guardar Energia II",
  str_skill_desc_590028207 = "O Invocador Escuro se teletransporta para o alvo e reúne energia para liberar um ataque em uma área ampla. Quanto mais balizas houver, maior será a área de ataque.",
  str_skill_name_590028208 = "Desamparado: Calar",
