  str_skill_name_3232371 = "Cascata Dreamwave",
  str_skill_desc_2002371 = "Ofertas <color=#00F6FF>160%</color> danos a <color=#00F6FF>12 peças em forma de diamante</color>.",
  str_skill_desc_2002372 = "Ofertas <color=#00F6FF>170%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado no inimigo mais próximo dentro de <color=#00F6FF>12 peças em forma de diamante</color>.",
  str_skill_desc_2002373 = "Ofertas <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado no inimigo mais próximo dentro de <color=#00F6FF>2 aglomerados circundantes</color>.",
  str_skill_desc_2302371 = "Ofertas <color=#00F6FF>160%</color> danos a <color=#00F6FF>12 peças em forma de diamante</color>.",
  str_skill_desc_2302372 = "Ofertas <color=#00F6FF>170%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado no inimigo mais próximo dentro de <color=#00F6FF>12 peças em forma de diamante</color>. Convoca uma Bolha Radiante na localização do alvo.",
  str_skill_desc_2302373 = "Ofertas <color=#00F6FF>180%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color> centralizado no inimigo mais próximo dentro de <color=#00F6FF>2 aglomerados circundantes</color>. Convoca uma Bolha Radiante na localização do alvo.",
  str_skill_desc_3002371 = "Selecione um ladrilho transponível de <color=#00F6FF>12 peças em forma de diamante</color> como ponto de partida, depois conecte qualquer número de <color=#00F6FF>Peças Azuis</color> ignorando todos os obstáculos. Teletransporta instantaneamente para o final da conexão. Se houver um inimigo no último ladrilho, causa <color=#00F6FF>200%</color> de dano ao alvo antes de se mover para um ladrilho adjacente.",
  str_skill_desc_3032371 = "Selecione um ladrilho transponível de <color=#00F6FF>12 peças em forma de diamante</color> como ponto de partida, depois conecte qualquer número de <color=#00F6FF>Peças Azuis</color> ignorando todos os obstáculos. Teletransporta instantaneamente para o final da conexão. Se houver um inimigo no último ladrilho, causa <color=#00F6FF>300%</color> de dano ao alvo antes de se mover para um ladrilho adjacente.",
  str_skill_desc_3202371 = "Selecione um ladrilho transponível de <color=#00F6FF>12 peças em forma de diamante</color> como ponto de partida, depois conecte qualquer número de <color=#00F6FF>Peças Azuis, Peças Escuras ou Peças de Bolha Radiante</color> ignorando todos os obstáculos. Teletransporta para o final da conexão. Se houver um inimigo no último ladrilho, causa <color=#00F6FF>200%</color> de dano ao alvo antes de se mover para um ladrilho adjacente.",
  str_skill_desc_3232371 = "Selecione um ladrilho transponível de <color=#00F6FF>12 peças em forma de diamante</color> como ponto de partida, depois conecte qualquer número de <color=#00F6FF>Peças Azuis, Peças Escuras ou Peças de Bolha Radiante</color> ignorando todos os obstáculos. Teletransporta para o final da conexão. Se houver um inimigo no último ladrilho, causa <color=#00F6FF>300%</color> de dano ao alvo antes de se mover para um ladrilho adjacente.",
  str_skill_passive_name_4102371 = "Irreal",
  str_skill_passive_desc_4102371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>2</color> casas aleatórias que podem ser atravessadas e que duram por 3 rodadas. Ao passar por uma Bolha Radiante através de casas conectadas ou Habilidades Ativas, causa <color=#00F6FF>{1}</color> de dano a 3 inimigos dentro de <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_passive_name_4402371 = "Irreal",
  str_skill_passive_desc_4402371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>2</color> casas aleatórias que podem ser atravessadas e que duram por 3 rodadas. Ao passar por uma Bolha Radiante através de casas conectadas ou Habilidades Ativas, causa <color=#00F6FF>140%</color> de dano a 3 inimigos dentro de <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_passive_name_4502371 = "Irreal",
  str_skill_passive_desc_4502371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>2</color> casas aleatórias que podem ser atravessadas e que duram por 3 rodadas. Ao passar por uma Bolha Radiante através de casas conectadas ou Habilidades Ativas, causa <color=#00F6FF>140%</color> de dano a 4 inimigos dentro de <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_passive_name_4602371 = "Irreal",
  str_skill_passive_desc_4602371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>2</color> ladrilhos percorríveis aleatórios que duram por 3 rodadas. Ao passar por uma Bolha Radiante através de ladrilhos conectados ou Habilidades Ativas, causa <color=#00F6FF>140%</color> de dano a 4 inimigos dentro de <color=#00F6FF>3 aglomerados circundantes</color>. Ganha 1 Fonte de Ilusão ao passar por Ladrilhos Escuros ou Bolhas Radiantes. Cada ponto de Fonte de Ilusão aumenta o dano do Combo em Cadeia em <color=#00F6FF>1%</color>.",
  str_skill_passive_name_4162371 = "Irreal",
  str_skill_passive_desc_4162371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>3</color> casas aleatórias que podem ser atravessadas e que duram por 5 rodadas. Ao passar por uma Bolha Radiante através de casas conectadas ou Habilidades Ativas, causa <color=#00F6FF>{1}</color> de dano a 3 inimigos dentro de <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_passive_name_4462371 = "Irreal",
  str_skill_passive_desc_4462371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>3</color> casas aleatórias que podem ser atravessadas e que duram por 5 rodadas. Ao passar por uma Bolha Radiante através de casas conectadas ou Habilidades Ativas, causa <color=#00F6FF>140%</color> de dano a 3 inimigos dentro de <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_passive_name_4562371 = "Irreal",
  str_skill_passive_desc_4562371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>3</color> casas aleatórias que podem ser atravessadas e que duram por 5 rodadas. Ao passar por uma Bolha Radiante através de casas conectadas ou Habilidades Ativas, causa <color=#00F6FF>140%</color> de dano a 4 inimigos dentro de <color=#00F6FF>3 círculos ao redor</color>.",
  str_skill_passive_name_4662371 = "Irreal",
  str_skill_passive_desc_4662371 = "No início de cada rodada, gera Bolhas Radiantes em <color=#00F6FF>3</color> ladrilhos aleatórios que duram por 3 rodadas. Ao passar por uma Bolha Radiante através de ladrilhos conectados ou Habilidades Ativas, causa <color=#00F6FF>140%</color> de dano a 4 inimigos dentro de <color=#00F6FF>3 círculos ao redor</color>. Ganhe 1 Fonte de Ilusão ao passar por Ladrilhos Escuros ou Bolhas Radiantes. Cada ponto de Fonte de Ilusão aumenta o dano do Combo em Cadeia em <color=#00F6FF>1%</color>.",
  str_skill_upgrade_refine_desc_16023711 = "Aprimoramento de Habilidade de Equipamento: Aumenta o dano da Bolha Radiante para <color=#00F6FF>140%</color>.",
  str_skill_upgrade_refine_desc_16023712 = "Aprimoramento de Habilidade de Equipamento: Bolhas Radiantes causam dano a <color=#00F6FF>4</color> inimigos dentro do alcance.",
  str_skill_upgrade_refine_desc_16023713 = "Aprimoramento de Habilidade de Equipamento: Ganhe 1 Fonte de Ilusão ao passar por Ladrilhos Escuros ou Bolhas Radiantes. Cada ponto de Fonte de Ilusão aumenta o dano do Combo de Cadeia em <color=#00F6FF>1%</color>.",
  str_skill_upgrade_desc_16023713 = "Aprimoramento de Habilidade Ativa: Reduz o tempo de recarga da habilidade em <color=#FFFF00>1</color> rodada. Se houver um inimigo no último bloco, causa <color=#FFFF00>300%</color> de dano.",
  str_skill_upgrade_desc_16023716 = "Aprimoramento de Habilidade de Equipamento: Bolhas Radiantes duram por 5 rodadas e geram 1 Bolha Radiante adicional no início de cada rodada.",
  str_skill_name_291020103 = "Perseguição Encalhada",
  str_skill_name_291020104 = "Amor Desesperado",
  str_skill_name_291020105 = "Lamento da Sirene",
  str_skill_desc_291020103 = "Causa dano aos Aurorianos e convoca Salvo Guns ao redor deles. Quando o HP cai abaixo de 70%/40%, o número de Salvo Guns convocados aumenta em 1 respectivamente.",
  str_skill_desc_291020104 = "Convoca um Pedido no ladrilho mais distante dos aurorianos dentro de 1 cluster ao redor. Quando o HP cai abaixo de 50%, o número de Pedidos convocados aumenta em 1.",
  str_skill_desc_291020105 = "Causa dano crescente aos Aurorianos 3 vezes e os empurra para a borda do campo.",
  str_skill_desc_291020113 = "Causa dano aos Aurorianos e invoca Salvo Guns ao redor deles.",
  str_skill_passive_desc_443173 = "Causa imediatamente <color=#00F6FF>85%</color> de dano a <color=#00F6FF>1</color> alvo aleatório no campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>ladrilhos aprimorados</u></color></link> (incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> pilhas de Marcas Mortais e reduz <color=#00F6FF>1</color> pilha para cada ladrilho aprimorado obtido. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>25%</color>, permitindo que seus ataques normais atinjam peças diagonais, aumentando o dano da Habilidade de Equipamento para <color=#00F6FF>2.5</color> vezes, e permitindo que seu Combo em Cadeia cause dano normal ao atingir o mesmo alvo novamente.",
  str_skill_passive_desc_453173 = "Causa imediatamente <color=#00F6FF>85%</color> de dano a <color=#00F6FF>1</color> alvo aleatório no campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>peças aprimoradas</u></color></link> (incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> Marcas Mortais e reduz <color=#00F6FF>1</color> pilha para cada peça aprimorada obtida. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>25%</color>, permitindo que seus ataques normais atinjam peças diagonais e aumentando o dano da Habilidade de Equipamento para <color=#00F6FF>2.5</color> vezes. Reduz a exigência de ativação do Chain Combo em <color=#00F6FF>1/2/3</color> e seu dano não diminui mais ao atingir o mesmo alvo.",
  str_skill_passive_desc_463173 = "Causa imediatamente <color=#00F6FF>85%</color> de dano a <color=#00F6FF>1</color> alvo aleatório no campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>peças aprimoradas</u></color></link> (incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> Marcas Mortais e reduz <color=#00F6FF>1</color> pilha para cada peça aprimorada obtida. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>25%</color>, permitindo que seus ataques normais atinjam peças diagonais e aumentando o dano da Habilidade de Equipamento para <color=#00F6FF>2.5</color> vezes. Reduz o requisito de gatilho do Chain Combo em <color=#00F6FF>1/2/3</color> e seu dano não diminui mais ao atingir o mesmo alvo. Aumenta o fator de dano da Habil. Ativa para <color=#00F6FF>200%</color>.",
  str_skill_passive_desc_440173 = "Causa imediatamente <color=#00F6FF>85%</color> de dano a <color=#00F6FF>1</color> alvo aleatório no campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>peças aprimoradas</u></color></link> (incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> pilhas de Marcas Mortais e reduz <color=#00F6FF>1</color> pilha para cada peça aprimorada obtida. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>20%</color>, permitindo que seus ataques normais atinjam peças diagonais, aumentando o dano da Habilidade de Equipamento para <color=#00F6FF>2.5</color> vezes, e o dano do Combo em Cadeia não diminui mais ao atingir o mesmo alvo.",
  str_skill_passive_desc_450173 = "Causa imediatamente <color=#00F6FF>85%</color> de dano a <color=#00F6FF>1</color> alvo aleatório no campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>peças aprimoradas</u></color></link> (incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> Marcas Mortais e reduz <color=#00F6FF>1</color> pilha para cada peça aprimorada obtida. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>20%</color>, permitindo que seus ataques normais atinjam peças diagonais e aumentando o dano da Habilidade de Equipamento para <color=#00F6FF>2.5</color> vezes. Reduz a exigência de ativação do Chain Combo em <color=#00F6FF>1/2/3</color> e seu dano não diminui mais ao atingir o mesmo alvo.",
  str_skill_passive_desc_460173 = "Causa imediatamente <color=#00F6FF>85%</color> de dano a <color=#00F6FF>1</color> alvo aleatório no campo sempre que a equipe obtém <link=\"20001\"><#FFAE07><u>peças aprimoradas</u></color></link> (incluindo <link=\"30065\"><#FFAE07><u>absorção</u></color></link>). Começa a batalha com <color=#00F6FF>33</color> Marcas Mortais e reduz <color=#00F6FF>1</color> pilha para cada peça aprimorada obtida. Minos entra no Estado Minotauro quando todas as Marcas foram removidas, aumentando seu ATK básico em <color=#00F6FF>20%</color>, permitindo que seus ataques normais atinjam peças diagonais e aumentando o dano da Habilidade de Equipamento para <color=#00F6FF>2.5</color> vezes. Reduz o requisito de gatilho do Chain Combo em <color=#00F6FF>1/2/3</color> e seu dano não diminui mais ao atingir o mesmo alvo. Aumenta o fator de dano da Habil. Ativa para <color=#00F6FF>200%</color>.",
  str_skill_upgrade_refine_desc_16017311 = "Aprimoramento de Habilidade de Equipamento: Aumenta o fator de dano para 85%.",
  str_skill_upgrade_refine_desc_16017312 = "Melhoria de Habilidade de Equipamento: Reduz o requisito de acionamento do Chain Combo em 1/2/3 no Estado Minotauro.",
  str_skill_upgrade_refine_desc_16017313 = "Aprimoramento de habilidade de equipamento: Aumenta o fator de dano da Habilidade Ativa para 200% no Estado de Minotauro.",
  str_skill_upgrade_refine_desc_14016911 = "Melhoria de Habilidade de Equipamento: Aumenta o ATK básico de Sadie em <color=#00F6FF>33%</color>. Cada Ponto de Falha aumenta o fator de dano da Habilidade Ativa em <color=#00F6FF>22%</color>.",
  str_skill_upgrade_refine_desc_14016912 = "Aprimoramento de Habilidade de Equipamento: Ganhe 1 <color=#00F6FF>Ponto de falha</color> ao passar por um ladrilho escuro.",
  str_skill_upgrade_refine_desc_14016913 = "Aprimoramento de Habilidade Ativa: Expande o alcance de peças selecionáveis para <color=#00F6FF>1 aglomerado circundante</color>.",
  str_skill_passive_desc_440169 = "Aumenta o ATK básico de Sadie em <color=#00F6FF>33%</color>. Sadie negocia até <color=#00F6FF>3</color> ataques normais ao conectar peças, e o terceiro ataque normal causa o dobro de dano. Após 3 ataques, ganhe 1 <color=#00F6FF>Ponto de falha</color> com o próximo ataque normal. Cada Crash Point aumenta o fator de dano da Habilidade Ativa em <color=#00F6FF>22%</color>. Todos os Crash Points são limpos após usar a Active Skill.",
  str_skill_passive_desc_450169 = "Aumenta o ATK básico de Sadie em <color=#00F6FF>33%</color>. Sadie negocia até <color=#00F6FF>3</color> ataques normais ao conectar peças, e o terceiro ataque normal causa o dobro de dano. Após 3 ataques, ganhe 1 <color=#00F6FF>Ponto de falha</color> com o próximo ataque normal. Cada Crash Point aumenta o fator de dano da Habilidade Ativa em <color=#00F6FF>22%</color>. Todos os Crash Points são limpos após usar a Active Skill. Ganhe 1 <color=#00F6FF>Ponto de falha</color> adicional para cada ladrilho escuro percorrido.",
  str_skill_name_360169 = "Bola aérea",
  str_skill_name_365169 = "Bola aérea",
  str_skill_desc_360169 = "Ofertas <color=#00F6FF>300%</color> dano a 1 inimigo dentro de <color=#00F6FF>1 cluster circundante</color> e os repele por 2 peças. Inimigos bloqueados por <color=#00F6FF>obstáculos</color> ao serem empurrados para trás recebem um adicional <color=#00F6FF>200%</color> danos e são <color=#00F6FF>atordoado</color> para 1 rodada. Se bloqueado por outro inimigo, ambos sofrem dano e ficam atordoados.",
  str_skill_desc_365169 = "Ofertas <color=#00F6FF>300%</color> dano a 1 inimigo dentro de <color=#00F6FF>1 cluster circundante</color> e os empurra para trás 3 peças. Inimigos bloqueados por <color=#00F6FF>obstáculos</color> enquanto são empurrados para trás recebem um adicional <color=#00F6FF>200%</color> danos e são <color=#00F6FF>atordoado</color> para 1 rodada. Se bloqueado por outro inimigo, ambos sofrem dano e ficam atordoados.",
  str_skill_name_20053011 = "Sussurros do Mar Profundo",
  str_skill_desc_20053011 = "Causa dano a unidades inimigas dentro de 1 aglomerado ao redor.",
  str_skill_name_20054011 = "Toque",
  str_skill_desc_20054011 = "Quando há um Auroriano dentro de 2 aglomerados de si mesmo, ele convoca um Eclipsite perto do alvo para se auxiliar.",
  str_skill_upgrade_desc_17023613 = "Melhoria de Habil. Ativa: Ganhe 5 Vis no início de cada rodada.",
  str_skill_upgrade_desc_17023616 = "Nova Habilidade Ativa: Pode ser lançada para retornar à equipe enquanto estiver fora da equipe, causando <color=#00F6FF>550%</color> de dano nas casas ao longo do caminho.",
  str_skill_passive_name_4102361 = "Agitado",
  str_skill_name_2002361 = "Milagre de Czerny",
  str_skill_name_2002362 = "Milagre de Czerny",
  str_skill_name_2002363 = "Milagre de Czerny",
  str_skill_name_2002364 = "Milagre de Czerny",
  str_skill_name_3302361 = "Com Brio",
  str_skill_name_3302362 = "Estrelas de Retorno",
  str_skill_desc_3302361 = "Ganha <link=\"30125\"><#FFAE07><u>Vis</u></color></link> durante o combate. Ao ativar a habilidade, Claymore entra em um modo de combate único, permitindo <link=\"30127\"><#FFAE07><u>conexões de ladrilhos</u></color></link> independentes. Após a conexão, Claymore entra no <link=\"30128\"><#FFAE07><u>estado fora da equipe</u></color></link>, deixando uma <link=\"30129\"><#FFAE07><u>imagem residual</u></color></link> no último ladrilho conectado, que servirá como ponto de partida para a próxima Habilidade Ativa.",
  str_skill_desc_3332361 = "Ganha <link=\"30126\"><#FFAE07><u>Vis</u></color></link> durante o combate. Ao ativar a habilidade, Claymore entra em um modo de combate único, permitindo <link=\"30127\"><#FFAE07><u>conexões de ladrilhos</u></color></link> independentes. Após a conexão, Claymore entra no <link=\"30128\"><#FFAE07><u>estado fora da equipe</u></color></link>, deixando uma <link=\"30129\"><#FFAE07><u>imagem residual</u></color></link> no último ladrilho conectado, que servirá como ponto de partida para a próxima Habilidade Ativa.",
  str_skill_desc_3302362 = "Pode ser lançado para retornar ao time enquanto estiver no estado fora do time, causando <color=#00F6FF>550%</color> de dano aos ladrilhos ao longo do caminho.",
  str_skill_desc_2002361 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>4 telhas ao redor</color>.",
  str_skill_desc_2002362 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>. Ganha 3 Vis se não estiver no estado de equipe reserva.",
  str_skill_desc_2002363 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>. Ganha 4 Vis se não estiver no estado de equipe reserva.",
  str_skill_desc_2002364 = "Causa <color=#00F6FF>175%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>. Ganha 5 Vis se não estiver no estado de equipe reserva.",
  str_skill_passive_desc_4102361 = "Claymore é um Auroriano <color=#00F6FF>não-elemental</color> e tem um Contra-ataque Elemental de <color=#00F6FF>100%</color> ao atacar ou ser atacado. <color=#00F6FF>Claymore entra em ação durante a batalha quando é Capitão, mas só participa como membro da equipe quando todas as casas conectadas são casas cromáticas.</color> Cada uso de uma Habilidade Ativa consome 1 Vis, concedendo a Claymore 1 pilha de Poder Estelar. O Poder Estelar aumenta o dano em <color=#00F6FF>{1}</color>, até 99 pilhas.",
  str_skill_passive_desc_4402361 = "Claymore é um Auroriano <color=#00F6FF>não-elemental</color> e tem um Contra-ataque Elemental de <color=#00F6FF>100%</color> ao atacar ou ser atacado. <color=#00F6FF>Claymore entra em ação durante a batalha quando é Capitão, mas só participa como membro da equipe quando todas as casas conectadas são casas cromáticas.</color> Cada uso de uma Habilidade Ativa consome 1 Vis, concedendo a Claymore 1 pilha de Poder Estelar. O Poder Estelar aumenta o dano em <color=#00F6FF>1.1%</color>, até 99 pilhas.",
  str_skill_passive_desc_4602361 = "Claymore é um Auroriano <color=#00F6FF>não-elemental</color> e tem um Contra-ataque Elemental de <color=#00F6FF>100%</color> ao atacar ou ser atacado. <color=#00F6FF>Claymore entra em ação durante a batalha quando é Capitão, mas só participa como membro da equipe quando todas as casas conectadas são casas cromáticas.</color> Cada uso de uma Habilidade Ativa consome 1 Vis, concedendo a Claymore 2 pilhas de Poder Estelar. O Poder Estelar aumenta o dano em <color=#00F6FF>1.1%</color>, até 99 pilhas.",
  str_skill_upgrade_refine_desc_17023611 = "Melhoria de Habilidade de Equipamento: Aumenta o fator para <color=#00F6FF>1.1%</color>.",
  str_skill_upgrade_refine_desc_17023612 = "Novo Tier <color=#00F6FF>4</color> Chain Combo: Requer 12 blocos conectados. Ofertas 175% de dano a 2 aglomerados ao redor. Ganha 5 Vis se não estiver no estado de equipe reserva.",
  str_skill_upgrade_refine_desc_17023613 = "Aprimoramento de Habilidade de Equipamento: <color=#00F6FF>Dobra</color> as pilhas de Poder Estelar ganhas.",
  str_skill_upgrade_desc_16023813 = "Melhoria de Habilidade Ativa: Torna a Habil. Ativa um <color=#FFFF00>Ataque Preventivo</color>. Disp. no início do combate.",
  str_skill_upgrade_desc_16023816 = "Aprimoramento de habilidade ativa: aumenta o número de peças que você pode selecionar <color=#00F6FF>1</color>.",
  str_skill_name_2002381 = "Borda Celestial",
  str_skill_desc_2002381 = "Lança uma lâmina de pena no <color=#00F6FF>inimigo mais próximo</color>, causando 170% de dano, que então salta para o próximo <color=#00F6FF>inimigo mais próximo</color>. Para cada cluster entre os alvos, o dano final aumenta em 10%, até 50%. O dano é ainda mais aumentado com base na contagem de Combos em Cadeia.",
  str_skill_name_3002381 = "Mensagem Reveladora",
  str_skill_name_3062381 = "Mensagem Reveladora",
  str_skill_name_3302381 = "Mensagem Revelatória Variante I",
  str_skill_name_3362381 = "Revelatory Message Variant I",
  str_skill_desc_3002381 = "Converte qualquer <color=#00F6FF>5</color> casas selecionadas em casas melhoradas.",
  str_skill_desc_3062381 = "Converte qualquer <color=#00F6FF>6</color> ladrilhos selecionados em ladrilhos aprimorados.",
  str_skill_desc_3302381 = "<color=#FFFF00>Cooldown de habilidade -1 após lançamento</color>. Converte quaisquer <color=#00F6FF>3</color> casas selecionadas em casas melhoradas.",
  str_skill_desc_3362381 = "<color=#FFFF00>Redução de -1 no cooldown da habilidade após lançamento</color>. Converte quaisquer <color=#00F6FF>4</color> casas selecionadas em casas melhoradas.",
  str_skill_passive_name_4102381 = "Herança Estelar",
  str_skill_passive_name_4162381 = "Luz Estelar Herdada",
  str_skill_passive_desc_4102381 = "Ganhe <color=#00F6FF>1 Marca de Luz Estelar</color> para <color=#00F6FF>cada ladrilho aprimorado</color> obtido. Combos em cadeia consomem <color=#00F6FF>um terço</color> das Marcas de Luz Estelar, adicionando <color=#00F6FF>{1}%</color> do ATQ médio da equipe como dano extra por pilha.",
  str_skill_passive_desc_4162381 = "Ganhe <color=#00F6FF>1 Marca de Luz Estelar</color> para <color=#00F6FF>cada casa aprimorada</color> obtida. Combos em cadeia consomem <color=#00F6FF>um terço</color> das Marcas de Luz Estelar, adicionando <color=#00F6FF>{1}</color> do ATQ médio da equipe como dano extra por acúmulo. Cada casa aprimorada obtida em uma única rodada reduz o requisito de ativação do Combo em cadeia em 1.",
  str_skill_upgrade_refine_desc_15017611 = "Aprimoramento de Habilidade de Equipamento: A cada <color=#00F6FF>4</color> ataques normais, Beretta perfura seu alvo atual com 1 Lança Australis.",
  str_skill_upgrade_refine_desc_15017612 = "Aprimoramento de Habilidade Ativa: Cada Lança Australis causa <color=#00F6FF>100%</color> de dano ao alvo.",
  str_skill_upgrade_refine_desc_15017613 = "Aprimoramento de Habilidade Ativa: Cada Lança Australis recupera <color=#00F6FF>15%–22.5%</color> do dano causado como HP quando causa dano ao alvo.",
  str_skill_passive_desc_4401761 = "A cada <color=#00F6FF>4</color> ataques normais, Beretta perfura seu alvo atual com <color=#00F6FF>1</color> <color=#00F6FF>Lança Australis</color>.",
  str_skill_passive_desc_4451761 = "Every <color=#00F6FF>4</color> normal attacks, Beretta pierces her current target with <color=#00F6FF>1</color> <color=#00F6FF>Australis Spear</color>.",
  str_skill_desc_3501761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Ofertas <color=#00F6FF>100%</color> dano e recupera HP por <color=#00F6FF>10%–15%</color> do dano causado desta forma para cada Lança Australis puxada. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_desc_3521761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>100%</color> dano e recupera HP por <color=#00F6FF>10%–15%</color> do dano causado desta forma para cada Lança Australis puxada. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_desc_3551761 = "Retira <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>100%–120%</color> dano e recupera HP por <color=#00F6FF>10%–15% de</color> o dano causado desta forma para cada <color=#00F6FF>Lança Australis</color> puxado. Quanto menor o HP atual do alvo, maior o fator de dano. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_desc_3601761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>2 aglomerados circundantes</color>. Ofertas <color=#00F6FF>100%</color> dano e recupera HP por <color=#00F6FF>15%–22.5%</color> do dano causado desta forma para cada Lança Australis puxada. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_desc_3621761 = "puxa para fora <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>100%</color> dano e recupera HP por <color=#00F6FF>15%–22.5%</color> do dano causado desta forma para cada Lança Australis puxada. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_desc_3651761 = "Retira <color=#00F6FF>Lanças Australis</color> de todos os inimigos dentro <color=#00F6FF>3 aglomerados circundantes</color>. Ofertas <color=#00F6FF>100%–120%</color> dano e recupera HP por <color=#00F6FF>15%–22.5% de</color> o dano causado desta forma para cada <color=#00F6FF>Lança Australis</color> puxado. Quanto menor o HP atual do alvo, maior o fator de dano. Quanto menor o HP da equipe, maior o fator de recuperação.",
  str_skill_name_3501821 = "Variante da Constrição da Serpente I",
  str_skill_name_3601821 = "Variante da Constrição da Serpente II",
  str_skill_desc_3501821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Selects 1 tile and deals <color=#00F6FF>400%</color> damage to <color=#00F6FF>13 tiles in a diamond shape</color>. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_desc_3601821 = "Active Skill can be unleashed when <color=#00F6FF>2</color> <link=\"30074\"><#FFAE07><u>Serpent Flares</u></color></link> are lit, and <color=#FFFF00>2 Serpent Flares will be extinguished upon its cast</color>. Triggers the Equipment Skill: Moonglow Relict Arts, dealing <color=#00F6FF>300%</color> damage to <color=#00F6FF>all</color> enemies.",
  str_skill_upgrade_refine_desc_16018211 = "Aprimoramento de habilidade ativa: aumenta o fator de dano para 400%.",
  str_skill_upgrade_refine_desc_16018212 = "<color=#00F6FF>New Active Skill Variant I</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Selects 1 tile and deals 400% damage to 13 tiles in a diamond shape. This does not trigger the Equipment Skill: Moonglow Relict Arts.",
  str_skill_upgrade_refine_desc_16018213 = "<color=#00F6FF>New Active Skill Variant II</color>: Active Skill can be unleashed when 2 Serpent Flares are lit, and 2 Serpent Flares will be extinguished upon its cast. Triggers the Equipment Skill: Moonglow Relict Arts, dealing 300% damage to all enemies.",
  str_skill_desc_3401821 = "A Habilidade Ativa pode ser liberada quando <color=#00F6FF>3</color> <link=\"30074\"><#FFAE07><u>Sinalizadores de Serpente</u></color></link> estão acesos. Seleciona 1 ladrilho e negocia <color=#00F6FF>400%</color> danos a <color=#00F6FF>13 peças em forma de diamante</color>. Todos os Serpent Flares serão extintos após o uso da Habilidade Ativa.",
  str_skill_upgrade_desc_16024113 = "Melhoria de Habilidade Ativa: Reduz a recarga da Habilidade Ativa em <color=#00F6FF>1</color> rodada e aumenta o fator de dano em <color=#00F6FF>50%</color>.",
  str_skill_upgrade_desc_16024116 = "Nova Variante de Habilidade Ativa: <color=#00F6FF>Dobra</color> o consumo de Sanidade e o dano causado. Gera até <color=#00F6FF>3</color> Azulejos Escuros.",
  str_skill_name_2002411 = "Explosão Desenfreada",
  str_skill_name_2002412 = "Explosão Desenfreada",
  str_skill_name_2002413 = "Explosão Desenfreada",
  str_skill_name_2302411 = "Explosão Desenfreada",
  str_skill_name_2302412 = "Explosão Desenfreada",
  str_skill_name_2302413 = "Explosão Desenfreada",
  str_skill_name_3002411 = "Dança Frenética",
  str_skill_name_3032411 = "Dança Frenética",
  str_skill_name_3062411 = "Variante de Dança Frenética I",
  str_skill_desc_2002411 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 círculo ao redor</color>.",
  str_skill_desc_2002412 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>.",
  str_skill_desc_2002413 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>2 círculos ao redor</color>.",
  str_skill_desc_2302411 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>1 aglomerado ao redor</color>. <link=\"30124\"><#FFAE07><u>Absorve</u></color></link> as peças escuras dentro das 4 peças ao redor.",
  str_skill_desc_2302412 = "Causa <color=#00F6FF>{1}%</color> de dano a <color=#00F6FF>12 casas em forma de diamante</color>. <link=\"30124\"><#FFAE07><u>Absorve</u></color></link> as casas escuras dentro de 1 círculo ao redor.",
  str_skill_desc_2302413 = "Ofertas <color=#00F6FF>{1}%</color> danos a <color=#00F6FF>2 aglomerados circundantes</color>. <link=\"30124\"><#FFAE07><u>Absorve</u></color></link> as peças escuras dentro das 12 peças circundantes em forma de diamante.",
  str_skill_desc_3002411 = "Pepita se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Consome <color=#00F6FF>15</color> pontos de sanidade para causar 150% de DMG a um inimigo selecionado, gerando 1 azulejo escuro abaixo do alvo.",
  str_skill_desc_3032411 = "Pepita se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Consome <color=#00F6FF>15</color> pontos de sanidade para causar 200% DMG a um inimigo selecionado, gerando 1 azulejo escuro abaixo do alvo.",
  str_skill_desc_3062411 = "Pepita se junta à batalha com o <link=\"30039\"><#FFAE07><u>Sistema de Sanidade</u></color></link>. Consome <color=#00F6FF>30</color> pontos de sanidade para causar 400% de DMG a um inimigo selecionado, gerando até 3 peças escuras aleatoriamente abaixo do alvo.",
  str_skill_passive_name_4102411 = "Chamas em Chamas",
  str_skill_passive_name_4202411 = "Chamas em Chamas",
  str_skill_passive_desc_4102411 = "Cada vez que Pepita adquire um ladrilho escuro, ela ganha <color=#00F6FF>1</color> acúmulo de Chama do Coração, até <color=#00F6FF>7</color> acúmulos. O Capitão atual consome 1 acúmulo de Chama do Coração com cada ataque normal, aumentando seu dano final em <color=#00F6FF>{1}</color>.",
  str_skill_passive_desc_4202411 = "Cada vez que Pepita adquire um Ladrilho Escuro, ela ganha <color=#00F6FF>1</color> Chama do Coração, até <color=#00F6FF>7</color>. O Capitão atual consome 1 Chama do Coração com cada ataque normal, aumentando seu dano final em <color=#00F6FF>{1}</color>. No início de cada rodada, <color=#00F6FF>2</color> Ladrilhos Escuros são gerados aleatoriamente sob os inimigos no campo.",
